/* FittForma AI v48 — traducciones de los textos nuevos (fichas de ejercicios; ver i18n-v48 en docs). */
(window.FittFormaI18nExtra = window.FittFormaI18nExtra || []).push(
  ["Cuádriceps y glúteo mayor","Quadriceps and gluteus maximus","Quadríceps e glúteo máximo","Quadriceps et grand fessier","Quadricipiti e grande gluteo","Quadrizeps und großer Gesäßmuskel"],
  ["Aductores, pantorrillas y tronco estabilizador","Adductors, calves and stabilizing trunk","Adutores, panturrilhas e tronco estabilizador","Adducteurs, mollets et tronc stabilisateur","Adduttori, polpacci e tronco stabilizzatore","Adduktoren, Waden und stabilisierender Rumpf"],
  ["Banco firme de altura estable; opcionalmente una mancuerna sostenida al pecho","Sturdy bench of stable height; optionally a dumbbell held at the chest","Banco firme de altura estável; opcionalmente um halter segurado junto ao peito","Banc solide de hauteur stable ; éventuellement un haltère tenu contre la poitrine","Panca stabile di altezza fissa; facoltativamente un manubrio tenuto al petto","Stabile Bank mit fester Höhe; optional eine Kurzhantel vor der Brust"],
  ["Principiante; útil para aprender la sentadilla con una referencia de profundidad","Beginner; useful for learning the squat with a depth reference","Iniciante; útil para aprender o agachamento com uma referência de profundidade","Débutant ; utile pour apprendre le squat avec un repère de profondeur","Principiante; utile per imparare lo squat con un riferimento di profondità","Anfänger; hilfreich, um die Kniebeuge mit einer Tiefenreferenz zu lernen"],
  ["Parate de espaldas a un banco firme, a un paso corto de distancia, con los pies al ancho de hombros.","Stand with your back to a sturdy bench, a short step away, feet shoulder-width apart.","Fique de costas para um banco firme, a um passo curto de distância, com os pés na largura dos ombros.","Tiens-toi dos à un banc solide, à un petit pas de distance, pieds écartés à la largeur des épaules.","Mettiti di spalle a una panca stabile, a un piccolo passo di distanza, con i piedi alla larghezza delle spalle.","Stell dich mit dem Rücken zu einer stabilen Bank, einen kleinen Schritt entfernt, Füße schulterbreit."],
  ["Inhalá al bajar hacia el banco y exhalá al levantarte.","Inhale as you lower toward the bench and exhale as you stand up.","Inspire ao descer em direção ao banco e expire ao se levantar.","Inspire en descendant vers le banc et expire en te relevant.","Inspira mentre scendi verso la panca ed espira mentre ti rialzi.","Atme beim Absenken zur Bank ein und beim Aufstehen aus."],
  ["60–90 segundos","60–90 seconds","60–90 segundos","60–90 secondes","60–90 secondi","60–90 Sekunden"],
  ["Colocá el banco sobre piso antideslizante y verificá que no se mueva; si usás carga, sostené la mancuerna pegada al pecho.","Place the bench on a non-slip floor and check that it does not move; if you use a load, hold the dumbbell close to your chest.","Coloque o banco sobre piso antiderrapante e verifique que ele não se mova; se usar carga, segure o halter junto ao peito.","Pose le banc sur un sol antidérapant et vérifie qu’il ne bouge pas ; si tu utilises une charge, tiens l’haltère contre ta poitrine.","Posiziona la panca su un pavimento antiscivolo e verifica che non si muova; se usi un carico, tieni il manubrio vicino al petto.","Stell die Bank auf einen rutschfesten Boden und prüfe, dass sie nicht wackelt; mit Gewicht hältst du die Kurzhantel eng an der Brust."],
  ["Llevá la cadera atrás y abajo flexionando las rodillas hasta sentarte suavemente en el borde del banco, sin dejarte caer.","Push your hips back and down, bending your knees until you sit gently on the edge of the bench, without dropping.","Leve o quadril para trás e para baixo flexionando os joelhos até sentar suavemente na borda do banco, sem se deixar cair.","Recule et abaisse les hanches en fléchissant les genoux jusqu’à t’asseoir doucement au bord du banc, sans te laisser tomber.","Porta le anche indietro e in basso piegando le ginocchia fino a sederti dolcemente sul bordo della panca, senza lasciarti cadere.","Schieb die Hüfte nach hinten unten und beuge die Knie, bis du dich sanft auf die Bankkante setzt, ohne dich fallen zu lassen."],
  ["Con el peso en toda la planta, inclinate apenas hacia adelante y empujá el suelo para pararte.","With your weight over your whole foot, lean slightly forward and push the floor away to stand up.","Com o peso em toda a planta do pé, incline-se levemente para frente e empurre o chão para se levantar.","Avec le poids réparti sur tout le pied, penche-toi légèrement en avant et pousse dans le sol pour te lever.","Con il peso su tutta la pianta del piede, inclinati leggermente in avanti e spingi il pavimento per alzarti.","Mit dem Gewicht auf dem ganzen Fuß lehnst du dich leicht nach vorn und drückst dich vom Boden hoch."],
  ["Terminá de pie con rodillas y cadera extendidas, sin bloquear las rodillas de golpe.","Finish standing with knees and hips extended, without snapping your knees into lockout.","Termine em pé com joelhos e quadril estendidos, sem travar os joelhos de forma brusca.","Termine debout, genoux et hanches tendus, sans verrouiller brusquement les genoux.","Termina in piedi con ginocchia e anche estese, senza bloccare di colpo le ginocchia.","Beende die Bewegung im Stand mit gestreckten Knien und Hüften, ohne die Knie ruckartig durchzudrücken."],
  ["Desplomarse sobre el banco y perder la tensión de las piernas.","Collapsing onto the bench and losing tension in the legs.","Desabar sobre o banco e perder a tensão nas pernas.","S’affaler sur le banc et perdre la tension dans les jambes.","Crollare sulla panca e perdere la tensione nelle gambe.","Auf die Bank plumpsen und die Spannung in den Beinen verlieren."],
  ["Usar un balanceo fuerte del tronco para despegar.","Using a strong torso swing to get up.","Usar um balanço forte do tronco para sair do banco.","Utiliser un fort élan du buste pour se relever.","Usare un forte slancio del busto per staccarsi.","Mit starkem Oberkörperschwung hochkommen."],
  ["Dejar que las rodillas se cierren hacia adentro al subir.","Letting the knees cave inward on the way up.","Deixar os joelhos se fecharem para dentro ao subir.","Laisser les genoux rentrer vers l’intérieur en montant.","Lasciare che le ginocchia si chiudano verso l’interno in salita.","Die Knie beim Hochkommen nach innen fallen lassen."],
  ["Un banco más alto reduce el rango y facilita el movimiento; bajalo a medida que ganes control.","A higher bench reduces the range and makes the movement easier; lower it as you gain control.","Um banco mais alto reduz a amplitude e facilita o movimento; abaixe-o conforme ganhar controle.","Un banc plus haut réduit l’amplitude et facilite le mouvement ; abaisse-le à mesure que tu gagnes en contrôle.","Una panca più alta riduce l’ampiezza e facilita il movimento; abbassala man mano che acquisisci controllo.","Eine höhere Bank verkürzt den Bewegungsumfang und erleichtert die Übung; senke sie, sobald du mehr Kontrolle hast."],
  ["Tocá el banco apenas, como si fuera frágil, para mantener el control.","Barely touch the bench, as if it were fragile, to stay in control.","Toque o banco de leve, como se fosse frágil, para manter o controle.","Touche à peine le banc, comme s’il était fragile, pour garder le contrôle.","Tocca appena la panca, come se fosse fragile, per mantenere il controllo.","Berühre die Bank nur leicht, als wäre sie zerbrechlich, um die Kontrolle zu behalten."],
  ["Mantené las rodillas apuntando en la misma dirección que los pies.","Keep your knees pointing in the same direction as your feet.","Mantenha os joelhos apontando na mesma direção dos pés.","Garde les genoux orientés dans la même direction que les pieds.","Mantieni le ginocchia rivolte nella stessa direzione dei piedi.","Halte die Knie in dieselbe Richtung wie die Füße ausgerichtet."],
  ["Cuádriceps","Quadriceps","Quadríceps","Quadriceps","Quadricipiti","Quadrizeps"],
  ["Glúteo mayor y aductores","Gluteus maximus and adductors","Glúteo máximo e adutores","Grand fessier et adducteurs","Grande gluteo e adduttori","Großer Gesäßmuskel und Adduktoren"],
  ["Máquina de sentadilla hack con respaldo y hombreras","Hack squat machine with back pad and shoulder pads","Máquina de agachamento hack com encosto e ombreiras","Machine à hack squat avec dossier et épaulières","Macchina hack squat con schienale e spallacci","Hackenschmidt-Maschine mit Rückenpolster und Schulterpolstern"],
  ["Principiante-intermedio tras aprender los seguros de la máquina","Beginner–intermediate after learning the machine’s safety catches","Iniciante-intermediário após aprender as travas da máquina","Débutant-intermédiaire après avoir appris les sécurités de la machine","Principiante-intermedio dopo aver imparato le sicure della macchina","Anfänger bis Fortgeschrittene, nachdem du die Sicherungen der Maschine kennst"],
  ["Ubicate con la espalda contra el respaldo, hombros bajo las almohadillas y pies al ancho de hombros en el centro de la plataforma.","Position yourself with your back against the pad, shoulders under the pads and feet shoulder-width apart in the center of the platform.","Posicione-se com as costas contra o encosto, ombros sob as almofadas e pés na largura dos ombros no centro da plataforma.","Place-toi dos contre le dossier, épaules sous les coussins et pieds à la largeur des épaules au centre de la plateforme.","Posizionati con la schiena contro lo schienale, spalle sotto i cuscinetti e piedi alla larghezza delle spalle al centro della pedana.","Lehn dich mit dem Rücken ans Polster, Schultern unter die Polster, Füße schulterbreit in der Mitte der Plattform."],
  ["Inhalá al bajar y exhalá al empujar hacia arriba.","Inhale on the way down and exhale as you push up.","Inspire ao descer e expire ao empurrar para cima.","Inspire en descendant et expire en poussant vers le haut.","Inspira scendendo ed espira spingendo verso l’alto.","Atme beim Absenken ein und beim Hochdrücken aus."],
  ["90–120 segundos","90–120 seconds","90–120 segundos","90–120 secondes","90–120 secondi","90–120 Sekunden"],
  ["Apoyá espalda y cadera contra el respaldo, colocá los pies en la plataforma y liberá los seguros con las manijas.","Rest your back and hips against the pad, place your feet on the platform and release the safety catches with the handles.","Apoie costas e quadril no encosto, coloque os pés na plataforma e solte as travas com as alças.","Plaque le dos et les hanches contre le dossier, pose les pieds sur la plateforme et libère les sécurités avec les poignées.","Appoggia schiena e anche allo schienale, metti i piedi sulla pedana e sblocca le sicure con le maniglie.","Lehn Rücken und Hüfte ans Polster, stell die Füße auf die Plattform und löse die Sicherungen mit den Griffen."],
  ["Bajá flexionando rodillas y cadera de forma controlada hasta un rango cómodo, con los talones apoyados.","Lower by bending your knees and hips in a controlled way to a comfortable range, heels down.","Desça flexionando joelhos e quadril de forma controlada até uma amplitude confortável, com os calcanhares apoiados.","Descends en fléchissant genoux et hanches de façon contrôlée jusqu’à une amplitude confortable, talons au sol.","Scendi piegando ginocchia e anche in modo controllato fino a un’ampiezza comoda, con i talloni appoggiati.","Senke dich kontrolliert durch Beugen von Knien und Hüfte bis zu einem angenehmen Bewegungsumfang, Fersen bleiben unten."],
  ["Empujá la plataforma con toda la planta para subir sin despegar la espalda del respaldo.","Push the platform with your whole foot to rise without lifting your back off the pad.","Empurre a plataforma com toda a planta do pé para subir sem descolar as costas do encosto.","Pousse la plateforme avec tout le pied pour remonter sans décoller le dos du dossier.","Spingi la pedana con tutta la pianta del piede per salire senza staccare la schiena dallo schienale.","Drück die Plattform mit dem ganzen Fuß weg, ohne den Rücken vom Polster zu lösen."],
  ["Al terminar la serie, volvé a colocar los seguros antes de salir de la máquina.","When you finish the set, re-engage the safety catches before getting out of the machine.","Ao terminar a série, recoloque as travas antes de sair da máquina.","À la fin de la série, remets les sécurités avant de sortir de la machine.","Alla fine della serie, reinserisci le sicure prima di uscire dalla macchina.","Setz nach dem Satz die Sicherungen wieder ein, bevor du aus der Maschine steigst."],
  ["Despegar la cadera o la zona lumbar del respaldo en la parte baja.","Lifting your hips or lower back off the pad at the bottom.","Descolar o quadril ou a lombar do encosto na parte baixa.","Décoller les hanches ou le bas du dos du dossier en bas du mouvement.","Staccare le anche o la zona lombare dallo schienale nella parte bassa.","Hüfte oder unteren Rücken unten vom Polster lösen."],
  ["Levantar los talones de la plataforma.","Lifting your heels off the platform.","Levantar os calcanhares da plataforma.","Décoller les talons de la plateforme.","Sollevare i talloni dalla pedana.","Die Fersen von der Plattform abheben."],
  ["Bloquear las rodillas con fuerza arriba o rebotar abajo.","Forcefully locking your knees at the top or bouncing at the bottom.","Travar os joelhos com força em cima ou quicar embaixo.","Verrouiller les genoux en force en haut ou rebondir en bas.","Bloccare le ginocchia con forza in alto o rimbalzare in basso.","Die Knie oben kräftig durchdrücken oder unten federn."],
  ["Pies más adelante en la plataforma reparten más trabajo hacia el glúteo; más atrás, más cuádriceps.","Feet higher on the platform shift more work to the glutes; lower, more to the quadriceps.","Pés mais à frente na plataforma levam mais trabalho para o glúteo; mais atrás, mais quadríceps.","Les pieds plus en avant sur la plateforme sollicitent davantage les fessiers ; plus en arrière, davantage les quadriceps.","I piedi più avanti sulla pedana spostano il lavoro sui glutei; più indietro, sui quadricipiti.","Weiter vorn auf der Plattform arbeiten die Gesäßmuskeln mehr, weiter hinten der Quadrizeps."],
  ["Practicá el uso de los seguros sin carga antes de empezar.","Practice using the safety catches without load before you start.","Pratique o uso das travas sem carga antes de começar.","Entraîne-toi à utiliser les sécurités sans charge avant de commencer.","Esercitati a usare le sicure senza carico prima di iniziare.","Übe den Umgang mit den Sicherungen ohne Gewicht, bevor du startest."],
  ["Mantené las rodillas alineadas con la punta de los pies.","Keep your knees aligned with your toes.","Mantenha os joelhos alinhados com a ponta dos pés.","Garde les genoux alignés avec la pointe des pieds.","Mantieni le ginocchia allineate con la punta dei piedi.","Halte die Knie in einer Linie mit den Fußspitzen."],
  ["Aductores, isquiotibiales y tronco estabilizador","Adductors, hamstrings and stabilizing trunk","Adutores, isquiotibiais e tronco estabilizador","Adducteurs, ischio-jambiers et tronc stabilisateur","Adduttori, ischiocrurali e tronco stabilizzatore","Adduktoren, hintere Oberschenkel und stabilisierender Rumpf"],
  ["Máquina multipower (Smith) con topes de seguridad regulados","Smith machine with safety stops set","Máquina Smith com batentes de segurança ajustados","Smith machine avec butées de sécurité réglées","Multipower (Smith machine) con fermi di sicurezza regolati","Multipresse (Smith Machine) mit eingestellten Sicherheitsanschlägen"],
  ["Principiante-intermedio","Beginner–intermediate","Iniciante-intermediário","Débutant-intermédiaire","Principiante-intermedio","Anfänger bis Fortgeschrittene"],
  ["Parate bajo la barra guiada con la barra apoyada sobre la parte alta de la espalda y los pies apenas adelantados respecto de la barra.","Stand under the guided bar with it resting on your upper back and your feet slightly in front of the bar.","Fique sob a barra guiada com ela apoiada na parte alta das costas e os pés levemente à frente da barra.","Place-toi sous la barre guidée, posée sur le haut du dos, les pieds légèrement en avant de la barre.","Mettiti sotto il bilanciere guidato appoggiato sulla parte alta della schiena, con i piedi leggermente avanti rispetto al bilanciere.","Stell dich unter die geführte Stange, sie liegt auf dem oberen Rücken, die Füße leicht vor der Stange."],
  ["Inhalá antes de bajar y exhalá al subir, sin contener el aire de forma prolongada.","Inhale before lowering and exhale on the way up, without holding your breath for long.","Inspire antes de descer e expire ao subir, sem prender o ar por muito tempo.","Inspire avant de descendre et expire en remontant, sans retenir ta respiration longtemps.","Inspira prima di scendere ed espira salendo, senza trattenere il respiro a lungo.","Atme vor dem Absenken ein und beim Hochkommen aus, ohne lange die Luft anzuhalten."],
  ["90–150 segundos","90–150 seconds","90–150 segundos","90–150 secondes","90–150 secondi","90–150 Sekunden"],
  ["Regulá los topes de seguridad un poco por debajo de tu profundidad más baja y apoyá la barra sobre los trapecios, no sobre el cuello.","Set the safety stops slightly below your lowest depth and rest the bar on your traps, not on your neck.","Ajuste os batentes de segurança um pouco abaixo da sua profundidade mais baixa e apoie a barra sobre os trapézios, não sobre o pescoço.","Règle les butées de sécurité un peu en dessous de ta profondeur la plus basse et pose la barre sur les trapèzes, pas sur la nuque.","Regola i fermi di sicurezza poco sotto la tua profondità massima e appoggia il bilanciere sui trapezi, non sul collo.","Stell die Sicherheitsanschläge etwas unter deine tiefste Position und leg die Stange auf den Trapezmuskel, nicht auf den Nacken."],
  ["Girá la barra para destrabarla y, con el tronco firme, bajá flexionando cadera y rodillas.","Rotate the bar to unhook it and, with a braced trunk, lower by bending your hips and knees.","Gire a barra para destravá-la e, com o tronco firme, desça flexionando quadril e joelhos.","Fais pivoter la barre pour la décrocher et, le tronc gainé, descends en fléchissant hanches et genoux.","Ruota il bilanciere per sganciarlo e, con il tronco stabile, scendi piegando anche e ginocchia.","Dreh die Stange zum Entriegeln und senke dich mit festem Rumpf durch Beugen von Hüfte und Knien."],
  ["Llegá hasta el rango que controlás con los talones apoyados y empujá el suelo para subir.","Go down to the range you control with your heels down and push the floor away to rise.","Desça até a amplitude que você controla com os calcanhares apoiados e empurre o chão para subir.","Descends jusqu’à l’amplitude que tu contrôles, talons au sol, et pousse dans le sol pour remonter.","Scendi fino all’ampiezza che controlli con i talloni appoggiati e spingi il pavimento per salire.","Geh so tief, wie du es kontrollierst, Fersen unten, und drück dich vom Boden hoch."],
  ["Al terminar, girá la barra para trabarla en el gancho antes de soltarla.","When you finish, rotate the bar to lock it on the hook before letting go.","Ao terminar, gire a barra para travá-la no gancho antes de soltá-la.","À la fin, fais pivoter la barre pour la bloquer sur le crochet avant de la lâcher.","Alla fine, ruota il bilanciere per agganciarlo prima di lasciarlo.","Dreh die Stange am Ende in den Haken, bevor du loslässt."],
  ["Colocar los pies justo debajo de la barra y cargar en exceso las rodillas o la espalda.","Placing your feet directly under the bar and overloading your knees or back.","Colocar os pés logo abaixo da barra e sobrecarregar os joelhos ou as costas.","Placer les pieds juste sous la barre et surcharger les genoux ou le dos.","Mettere i piedi proprio sotto il bilanciere e sovraccaricare ginocchia o schiena.","Die Füße direkt unter die Stange stellen und Knie oder Rücken überlasten."],
  ["Apoyar la barra sobre las vértebras del cuello.","Resting the bar on the vertebrae of your neck.","Apoiar a barra sobre as vértebras do pescoço.","Poser la barre sur les vertèbres de la nuque.","Appoggiare il bilanciere sulle vertebre del collo.","Die Stange auf die Halswirbel legen."],
  ["Olvidar regular los topes de seguridad.","Forgetting to set the safety stops.","Esquecer de ajustar os batentes de segurança.","Oublier de régler les butées de sécurité.","Dimenticare di regolare i fermi di sicurezza.","Vergessen, die Sicherheitsanschläge einzustellen."],
  ["La barra guiada sigue una línea fija: buscá una posición de pies donde el movimiento se sienta natural.","The guided bar follows a fixed path: find a foot position where the movement feels natural.","A barra guiada segue uma linha fixa: encontre uma posição dos pés em que o movimento pareça natural.","La barre guidée suit une trajectoire fixe : trouve une position des pieds où le mouvement te semble naturel.","Il bilanciere guidato segue una linea fissa: trova una posizione dei piedi in cui il movimento risulti naturale.","Die geführte Stange läuft auf einer festen Bahn: Finde eine Fußposition, in der sich die Bewegung natürlich anfühlt."],
  ["Probá el gancho de trabado con la barra vacía.","Test the locking hook with the empty bar.","Teste o gancho de trava com a barra vazia.","Teste le crochet de verrouillage avec la barre à vide.","Prova il gancio di blocco con il bilanciere scarico.","Teste den Verriegelungshaken mit der leeren Stange."],
  ["No uses la guía para bajar más de lo que permite tu movilidad.","Don’t use the guide to go lower than your mobility allows.","Não use a guia para descer mais do que sua mobilidade permite.","N’utilise pas le guidage pour descendre plus bas que ta mobilité ne le permet.","Non usare la guida per scendere più di quanto consenta la tua mobilità.","Nutze die Führung nicht, um tiefer zu gehen, als deine Beweglichkeit erlaubt."],
  ["Aductores, erectores espinales, abdominales y parte alta de la espalda","Adductors, spinal erectors, abdominals and upper back","Adutores, eretores da espinha, abdominais e parte alta das costas","Adducteurs, érecteurs du rachis, abdominaux et haut du dos","Adduttori, erettori spinali, addominali e parte alta della schiena","Adduktoren, Rückenstrecker, Bauchmuskeln und oberer Rücken"],
  ["Barra, discos y rack con soportes y barras de seguridad","Barbell, plates and rack with supports and safety bars","Barra, anilhas e rack com suportes e barras de segurança","Barre, disques et rack avec supports et barres de sécurité","Bilanciere, dischi e rack con supporti e barre di sicurezza","Langhantel, Scheiben und Rack mit Ablagen und Sicherheitsstangen"],
  ["Intermedio-avanzado; requiere movilidad de muñeca, hombro y tobillo","Intermediate–advanced; requires wrist, shoulder and ankle mobility","Intermediário-avançado; exige mobilidade de punho, ombro e tornozelo","Intermédiaire-avancé ; demande de la mobilité des poignets, des épaules et des chevilles","Intermedio-avanzato; richiede mobilità di polso, spalla e caviglia","Fortgeschritten; erfordert Beweglichkeit in Handgelenk, Schulter und Sprunggelenk"],
  ["Parate con la barra apoyada sobre los deltoides frontales, cerca del cuello, codos altos y pies al ancho de hombros.","Stand with the bar resting on your front delts, close to your neck, elbows high and feet shoulder-width apart.","Fique com a barra apoiada sobre os deltoides anteriores, perto do pescoço, cotovelos altos e pés na largura dos ombros.","Tiens-toi avec la barre posée sur les deltoïdes antérieurs, près du cou, coudes hauts et pieds à la largeur des épaules.","Mettiti in piedi con il bilanciere appoggiato sui deltoidi anteriori, vicino al collo, gomiti alti e piedi alla larghezza delle spalle.","Stell dich hin, die Stange liegt auf den vorderen Schultern nahe am Hals, Ellbogen hoch, Füße schulterbreit."],
  ["Tomá aire y afirmá el tronco antes de bajar; exhalá al completar la subida.","Take a breath and brace your trunk before lowering; exhale as you complete the ascent.","Respire e firme o tronco antes de descer; expire ao completar a subida.","Prends ton souffle et gaine le tronc avant de descendre ; expire en terminant la montée.","Prendi fiato e stabilizza il tronco prima di scendere; espira completando la salita.","Atme ein und spann den Rumpf an, bevor du absenkst; atme aus, wenn du oben ankommst."],
  ["120–180 segundos","120–180 seconds","120–180 segundos","120–180 secondes","120–180 secondi","120–180 Sekunden"],
  ["Sacá la barra del rack con los codos al frente y elevados; podés usar agarre limpio o brazos cruzados.","Unrack the bar with your elbows forward and high; you can use a clean grip or crossed arms.","Tire a barra do rack com os cotovelos à frente e elevados; você pode usar pegada limpa ou braços cruzados.","Sors la barre du rack, coudes devant et levés ; tu peux utiliser une prise d’épaulé ou les bras croisés.","Togli il bilanciere dal rack con i gomiti avanti e alti; puoi usare la presa da girata o le braccia incrociate.","Heb die Stange mit hohen, nach vorn zeigenden Ellbogen aus dem Rack; nutze den Clean-Griff oder verschränkte Arme."],
  ["Bajá con el tronco lo más vertical posible, llevando las rodillas hacia adelante sobre los pies.","Lower with your torso as upright as possible, bringing your knees forward over your feet.","Desça com o tronco o mais vertical possível, levando os joelhos para frente sobre os pés.","Descends le buste le plus vertical possible, en avançant les genoux au-dessus des pieds.","Scendi con il busto il più verticale possibile, portando le ginocchia in avanti sopra i piedi.","Senke dich mit möglichst aufrechtem Oberkörper und schieb die Knie über die Füße nach vorn."],
  ["Mantené los codos altos en la parte baja para que la barra no ruede hacia adelante.","Keep your elbows high at the bottom so the bar doesn’t roll forward.","Mantenha os cotovelos altos na parte baixa para a barra não rolar para frente.","Garde les coudes hauts en bas pour que la barre ne roule pas vers l’avant.","Mantieni i gomiti alti in basso perché il bilanciere non rotoli in avanti.","Halte die Ellbogen unten hoch, damit die Stange nicht nach vorn rollt."],
  ["Empujá el suelo para subir y devolvé la barra al rack al terminar.","Push the floor away to rise and return the bar to the rack when you finish.","Empurre o chão para subir e devolva a barra ao rack ao terminar.","Pousse dans le sol pour remonter et repose la barre dans le rack à la fin.","Spingi il pavimento per salire e riponi il bilanciere sul rack alla fine.","Drück dich vom Boden hoch und leg die Stange am Ende zurück ins Rack."],
  ["Dejar caer los codos y redondear la parte alta de la espalda.","Dropping your elbows and rounding your upper back.","Deixar os cotovelos caírem e arredondar a parte alta das costas.","Laisser tomber les coudes et arrondir le haut du dos.","Lasciar cadere i gomiti e arrotondare la parte alta della schiena.","Die Ellbogen sinken lassen und den oberen Rücken runden."],
  ["Despegar los talones del suelo.","Lifting your heels off the floor.","Tirar os calcanhares do chão.","Décoller les talons du sol.","Sollevare i talloni da terra.","Die Fersen vom Boden abheben."],
  ["Sostener la barra con las manos en lugar de apoyarla en los hombros.","Holding the bar with your hands instead of resting it on your shoulders.","Segurar a barra com as mãos em vez de apoiá-la nos ombros.","Tenir la barre avec les mains au lieu de la poser sur les épaules.","Tenere il bilanciere con le mani invece di appoggiarlo sulle spalle.","Die Stange mit den Händen halten, statt sie auf den Schultern abzulegen."],
  ["Regulá las barras de seguridad del rack para poder soltar la barra hacia adelante si fallás.","Set the rack’s safety bars so you can dump the bar forward if you fail.","Ajuste as barras de segurança do rack para poder soltar a barra para frente se falhar.","Règle les barres de sécurité du rack pour pouvoir lâcher la barre vers l’avant en cas d’échec.","Regola le barre di sicurezza del rack per poter lasciar andare il bilanciere in avanti se non chiudi la ripetizione.","Stell die Sicherheitsstangen des Racks so ein, dass du die Stange bei einem Fehlversuch nach vorn ablegen kannst."],
  ["Si las muñecas no llegan, usá agarre con brazos cruzados o abrí más las manos.","If your wrists can’t get there, use a crossed-arm grip or widen your hands.","Se os punhos não alcançarem, use pegada com braços cruzados ou abra mais as mãos.","Si tes poignets ne suivent pas, utilise la prise bras croisés ou écarte davantage les mains.","Se i polsi non ci arrivano, usa la presa a braccia incrociate o allarga le mani.","Wenn deine Handgelenke nicht mitmachen, nutze verschränkte Arme oder greif breiter."],
  ["Empezá con la barra sola hasta que la posición de rack te resulte cómoda.","Start with just the bar until the rack position feels comfortable.","Comece só com a barra até a posição de rack ficar confortável.","Commence avec la barre seule jusqu’à ce que la position de rack te soit confortable.","Inizia con il solo bilanciere finché la posizione di rack non ti risulta comoda.","Beginne mit der leeren Stange, bis sich die Frontposition bequem anfühlt."],
  ["Aductores, isquiotibiales y estabilizadores de cadera","Adductors, hamstrings and hip stabilizers","Adutores, isquiotibiais e estabilizadores do quadril","Adducteurs, ischio-jambiers et stabilisateurs de hanche","Adduttori, ischiocrurali e stabilizzatori dell’anca","Adduktoren, hintere Oberschenkel und Hüftstabilisatoren"],
  ["Dos mancuernas","Two dumbbells","Dois halteres","Deux haltères","Due manubri","Zwei Kurzhanteln"],
  ["Parate en posición de paso largo, un pie adelante y otro atrás apoyado sobre la punta, con una mancuerna en cada mano a los costados.","Stand in a long split stance, one foot forward and the other back on the ball of the foot, with a dumbbell in each hand at your sides.","Fique em posição de passada longa, um pé à frente e outro atrás apoiado na ponta, com um halter em cada mão ao lado do corpo.","Place-toi en grande fente, un pied devant et l’autre derrière sur la pointe, un haltère dans chaque main le long du corps.","Mettiti in posizione di affondo lungo, un piede avanti e l’altro dietro sulla punta, con un manubrio per mano lungo i fianchi.","Stell dich in eine lange Schrittstellung, ein Fuß vorn, der andere hinten auf dem Fußballen, je eine Kurzhantel seitlich in der Hand."],
  ["Inhalá al bajar y exhalá al subir.","Inhale on the way down and exhale on the way up.","Inspire ao descer e expire ao subir.","Inspire en descendant et expire en remontant.","Inspira scendendo ed espira salendo.","Atme beim Absenken ein und beim Hochkommen aus."],
  ["60–90 segundos entre lados o series","60–90 seconds between sides or sets","60–90 segundos entre lados ou séries","60–90 secondes entre les côtés ou les séries","60–90 secondi tra i lati o le serie","60–90 Sekunden zwischen den Seiten oder Sätzen"],
  ["Separá los pies a lo ancho de cadera, como sobre dos rieles, para tener una base estable.","Set your feet hip-width apart, as if on two rails, for a stable base.","Separe os pés na largura do quadril, como sobre dois trilhos, para ter uma base estável.","Écarte les pieds à la largeur des hanches, comme sur deux rails, pour une base stable.","Separa i piedi alla larghezza delle anche, come su due binari, per avere una base stabile.","Stell die Füße hüftbreit wie auf zwei Schienen, damit du eine stabile Basis hast."],
  ["Bajá en vertical flexionando ambas rodillas hasta que la rodilla trasera quede cerca del suelo.","Lower straight down by bending both knees until the back knee is close to the floor.","Desça na vertical flexionando os dois joelhos até o joelho de trás ficar perto do chão.","Descends à la verticale en fléchissant les deux genoux jusqu’à ce que le genou arrière soit près du sol.","Scendi in verticale piegando entrambe le ginocchia finché il ginocchio posteriore è vicino a terra.","Senke dich senkrecht ab, indem du beide Knie beugst, bis das hintere Knie nah am Boden ist."],
  ["Empujá con el pie de adelante para subir, sin mover los pies de lugar.","Push through your front foot to rise, without moving your feet.","Empurre com o pé da frente para subir, sem mudar os pés de lugar.","Pousse sur le pied avant pour remonter, sans déplacer les pieds.","Spingi con il piede anteriore per salire, senza spostare i piedi.","Drück dich über den vorderen Fuß hoch, ohne die Füße zu versetzen."],
  ["Completá todas las repeticiones de un lado y después cambiá de pierna.","Complete all the reps on one side, then switch legs.","Complete todas as repetições de um lado e depois troque de perna.","Fais toutes les répétitions d’un côté, puis change de jambe.","Completa tutte le ripetizioni da un lato e poi cambia gamba.","Mach alle Wiederholungen auf einer Seite und wechsle dann das Bein."],
  ["Poner los pies en una misma línea y perder el equilibrio.","Placing your feet in a single line and losing balance.","Colocar os pés na mesma linha e perder o equilíbrio.","Placer les pieds sur une même ligne et perdre l’équilibre.","Mettere i piedi sulla stessa linea e perdere l’equilibrio.","Die Füße auf eine Linie stellen und das Gleichgewicht verlieren."],
  ["Dejar que la rodilla de adelante se cierre hacia adentro.","Letting the front knee cave inward.","Deixar o joelho da frente se fechar para dentro.","Laisser le genou avant rentrer vers l’intérieur.","Lasciare che il ginocchio anteriore si chiuda verso l’interno.","Das vordere Knie nach innen fallen lassen."],
  ["Golpear la rodilla trasera contra el suelo.","Banging the back knee on the floor.","Bater o joelho de trás no chão.","Cogner le genou arrière contre le sol.","Sbattere il ginocchio posteriore a terra.","Das hintere Knie auf den Boden schlagen."],
  ["El peso va principalmente sobre el pie de adelante.","Most of the weight goes on the front foot.","O peso fica principalmente sobre o pé da frente.","Le poids repose surtout sur le pied avant.","Il peso va principalmente sul piede anteriore.","Das Gewicht liegt hauptsächlich auf dem vorderen Fuß."],
  ["Mantené el tronco erguido y las mancuernas quietas a los costados.","Keep your torso upright and the dumbbells still at your sides.","Mantenha o tronco ereto e os halteres parados ao lado do corpo.","Garde le buste droit et les haltères immobiles le long du corps.","Mantieni il busto eretto e i manubri fermi lungo i fianchi.","Halte den Oberkörper aufrecht und die Kurzhanteln ruhig an den Seiten."],
  ["Si te cuesta el equilibrio, empezá sin peso o con un apoyo al costado.","If balance is hard, start without weight or with support at your side.","Se o equilíbrio for difícil, comece sem peso ou com um apoio ao lado.","Si l’équilibre est difficile, commence sans poids ou avec un appui sur le côté.","Se fai fatica con l’equilibrio, inizia senza peso o con un appoggio di lato.","Wenn das Gleichgewicht schwerfällt, beginne ohne Gewicht oder mit einer seitlichen Stütze."],
  ["Glúteo mayor, cuádriceps e isquiotibiales","Gluteus maximus, quadriceps and hamstrings","Glúteo máximo, quadríceps e isquiotibiais","Grand fessier, quadriceps et ischio-jambiers","Grande gluteo, quadricipiti e ischiocrurali","Großer Gesäßmuskel, Quadrizeps und hintere Oberschenkel"],
  ["Erectores espinales, trapecio, dorsales y agarre","Spinal erectors, trapezius, lats and grip","Eretores da espinha, trapézio, dorsais e pegada","Érecteurs du rachis, trapèzes, dorsaux et préhension","Erettori spinali, trapezio, dorsali e presa","Rückenstrecker, Trapezmuskel, Latissimus und Griffkraft"],
  ["Barra hexagonal (trap bar) y discos","Hex bar (trap bar) and plates","Barra hexagonal (trap bar) e anilhas","Barre hexagonale (trap bar) et disques","Bilanciere esagonale (trap bar) e dischi","Hexbar (Trap Bar) und Scheiben"],
  ["Principiante-intermedio; suele ser más fácil de aprender que el peso muerto con barra recta","Beginner–intermediate; usually easier to learn than the straight-bar deadlift","Iniciante-intermediário; costuma ser mais fácil de aprender que o levantamento terra com barra reta","Débutant-intermédiaire ; généralement plus facile à apprendre que le soulevé de terre à la barre droite","Principiante-intermedio; di solito più facile da imparare dello stacco con bilanciere dritto","Anfänger bis Fortgeschrittene; meist leichter zu lernen als das Kreuzheben mit gerader Stange"],
  ["Parate en el centro de la barra hexagonal con los pies al ancho de cadera y las manijas a los costados.","Stand in the center of the hex bar with your feet hip-width apart and the handles at your sides.","Fique no centro da barra hexagonal com os pés na largura do quadril e as alças ao lado do corpo.","Place-toi au centre de la barre hexagonale, pieds à la largeur des hanches et poignées sur les côtés.","Mettiti al centro del bilanciere esagonale con i piedi alla larghezza delle anche e le maniglie ai lati.","Stell dich in die Mitte der Hexbar, Füße hüftbreit, die Griffe seitlich neben dir."],
  ["Tomá aire y afirmá el tronco antes de levantar; exhalá al llegar arriba.","Take a breath and brace your trunk before lifting; exhale at the top.","Respire e firme o tronco antes de levantar; expire ao chegar em cima.","Prends ton souffle et gaine le tronc avant de soulever ; expire en haut.","Prendi fiato e stabilizza il tronco prima di sollevare; espira arrivato in alto.","Atme ein und spann den Rumpf an, bevor du hebst; atme oben aus."],
  ["Flexioná cadera y rodillas y tomá las manijas por el centro, con la espalda estable y la mirada al frente.","Bend your hips and knees and grab the handles in the middle, with a stable back and eyes forward.","Flexione quadril e joelhos e segure as alças pelo centro, com as costas estáveis e o olhar à frente.","Fléchis hanches et genoux et saisis les poignées au milieu, le dos stable et le regard devant.","Piega anche e ginocchia e afferra le maniglie al centro, con la schiena stabile e lo sguardo avanti.","Beuge Hüfte und Knie und greif die Griffe mittig, Rücken stabil, Blick nach vorn."],
  ["Afirmá el tronco y empujá el suelo para levantarte, extendiendo cadera y rodillas a la vez.","Brace your trunk and push the floor away to stand up, extending hips and knees at the same time.","Firme o tronco e empurre o chão para se levantar, estendendo quadril e joelhos ao mesmo tempo.","Gaine le tronc et pousse dans le sol pour te relever, en tendant hanches et genoux en même temps.","Stabilizza il tronco e spingi il pavimento per alzarti, estendendo anche e ginocchia insieme.","Spann den Rumpf an und drück dich vom Boden hoch, Hüfte und Knie strecken sich gleichzeitig."],
  ["Terminá de pie con los hombros sobre la cadera, sin inclinarte hacia atrás.","Finish standing with your shoulders over your hips, without leaning back.","Termine em pé com os ombros sobre o quadril, sem inclinar para trás.","Termine debout, épaules au-dessus des hanches, sans te pencher en arrière.","Termina in piedi con le spalle sopra le anche, senza inclinarti indietro.","Beende die Bewegung im Stand, Schultern über der Hüfte, ohne dich nach hinten zu lehnen."],
  ["Bajá con control llevando la cadera atrás y flexionando las rodillas hasta apoyar los discos.","Lower under control by pushing your hips back and bending your knees until the plates touch down.","Desça com controle levando o quadril para trás e flexionando os joelhos até apoiar as anilhas.","Redescends en contrôle en reculant les hanches et en fléchissant les genoux jusqu’à poser les disques.","Scendi con controllo portando le anche indietro e piegando le ginocchia fino ad appoggiare i dischi.","Senke kontrolliert ab, Hüfte nach hinten, Knie beugen, bis die Scheiben aufsetzen."],
  ["Redondear la espalda al despegar la barra del suelo.","Rounding your back as the bar leaves the floor.","Arredondar as costas ao tirar a barra do chão.","Arrondir le dos au décollage de la barre.","Arrotondare la schiena quando stacchi il bilanciere da terra.","Den Rücken beim Abheben der Stange runden."],
  ["Tomar las manijas descentradas y que la barra se incline.","Gripping the handles off-center so the bar tilts.","Segurar as alças fora do centro e deixar a barra inclinar.","Saisir les poignées décentrées et laisser la barre pencher.","Afferrare le maniglie decentrate e far inclinare il bilanciere.","Die Griffe außermittig fassen, sodass die Stange kippt."],
  ["Echar el tronco hacia atrás al terminar.","Leaning your torso back at the top.","Jogar o tronco para trás ao terminar.","Basculer le buste en arrière à la fin.","Buttare il busto indietro alla fine.","Den Oberkörper am Ende nach hinten werfen."],
  ["Al estar la carga a los costados, el tronco puede quedar más vertical que con barra recta.","With the load at your sides, your torso can stay more upright than with a straight bar.","Como a carga fica ao lado do corpo, o tronco pode ficar mais vertical do que com barra reta.","La charge étant sur les côtés, le buste peut rester plus vertical qu’avec une barre droite.","Con il carico ai lati, il busto può restare più verticale che con il bilanciere dritto.","Da die Last seitlich ist, kann der Oberkörper aufrechter bleiben als mit gerader Stange."],
  ["Si la barra tiene manijas altas, usalas para reducir el rango al principio.","If the bar has high handles, use them to reduce the range at first.","Se a barra tiver alças altas, use-as para reduzir a amplitude no começo.","Si la barre a des poignées hautes, utilise-les pour réduire l’amplitude au début.","Se il bilanciere ha maniglie alte, usale per ridurre l’ampiezza all’inizio.","Hat die Stange hohe Griffe, nutze sie anfangs, um den Bewegungsumfang zu verkürzen."],
  ["Apoyá los discos en cada repetición si perdés la posición.","Set the plates down on each rep if you lose position.","Apoie as anilhas em cada repetição se perder a posição.","Pose les disques à chaque répétition si tu perds la position.","Appoggia i dischi a ogni ripetizione se perdi la posizione.","Setz die Scheiben bei jeder Wiederholung ab, wenn du die Position verlierst."],
  ["Isquiotibiales y glúteo mayor","Hamstrings and gluteus maximus","Isquiotibiais e glúteo máximo","Ischio-jambiers et grand fessier","Ischiocrurali e grande gluteo","Hintere Oberschenkel und großer Gesäßmuskel"],
  ["Erectores espinales y tronco estabilizador","Spinal erectors and stabilizing trunk","Eretores da espinha e tronco estabilizador","Érecteurs du rachis et tronc stabilisateur","Erettori spinali e tronco stabilizzatore","Rückenstrecker und stabilisierender Rumpf"],
  ["Barra liviana apoyada sobre la parte alta de la espalda; rack para tomarla","Light barbell resting on the upper back; rack to pick it up","Barra leve apoiada na parte alta das costas; rack para pegá-la","Barre légère posée sur le haut du dos ; rack pour la prendre","Bilanciere leggero appoggiato sulla parte alta della schiena; rack per prenderlo","Leichte Langhantel auf dem oberen Rücken; Rack zum Aufnehmen"],
  ["Intermedio; usar carga ligera y aprender antes la versión sin peso","Intermediate; use a light load and learn the unloaded version first","Intermediário; use carga leve e aprenda antes a versão sem peso","Intermédiaire ; utilise une charge légère et apprends d’abord la version sans poids","Intermedio; usa un carico leggero e impara prima la versione senza peso","Fortgeschritten; leichtes Gewicht nutzen und vorher die Variante ohne Gewicht lernen"],
  ["Parate con la barra sobre los trapecios, pies al ancho de cadera y rodillas apenas flexionadas.","Stand with the bar on your traps, feet hip-width apart and knees slightly bent.","Fique com a barra sobre os trapézios, pés na largura do quadril e joelhos levemente flexionados.","Tiens-toi avec la barre sur les trapèzes, pieds à la largeur des hanches et genoux légèrement fléchis.","Mettiti con il bilanciere sui trapezi, piedi alla larghezza delle anche e ginocchia leggermente piegate.","Stell dich mit der Stange auf dem Trapezmuskel hin, Füße hüftbreit, Knie leicht gebeugt."],
  ["Inhalá al inclinarte y exhalá al volver a la posición erguida.","Inhale as you hinge forward and exhale as you return upright.","Inspire ao inclinar e expire ao voltar à posição ereta.","Inspire en te penchant et expire en revenant à la position droite.","Inspira mentre ti inclini ed espira tornando in posizione eretta.","Atme beim Vorbeugen ein und beim Aufrichten aus."],
  ["Sacá la barra del rack y afirmá el tronco con la espalda neutra.","Unrack the bar and brace your trunk with a neutral spine.","Tire a barra do rack e firme o tronco com a coluna neutra.","Sors la barre du rack et gaine le tronc, le dos neutre.","Togli il bilanciere dal rack e stabilizza il tronco con la schiena neutra.","Heb die Stange aus dem Rack und spann den Rumpf mit neutralem Rücken an."],
  ["Llevá la cadera hacia atrás inclinando el torso hacia adelante, sin redondear la espalda.","Push your hips back, tilting your torso forward without rounding your back.","Leve o quadril para trás inclinando o tronco para frente, sem arredondar as costas.","Recule les hanches en inclinant le buste vers l’avant, sans arrondir le dos.","Porta le anche indietro inclinando il busto in avanti, senza arrotondare la schiena.","Schieb die Hüfte nach hinten und neige den Oberkörper nach vorn, ohne den Rücken zu runden."],
  ["Bajá hasta sentir estiramiento en la parte posterior del muslo o hasta donde mantengas la espalda estable.","Lower until you feel a stretch in the back of your thighs or as far as you can keep your back stable.","Desça até sentir alongamento na parte de trás da coxa ou até onde mantiver as costas estáveis.","Descends jusqu’à sentir un étirement à l’arrière des cuisses ou tant que ton dos reste stable.","Scendi finché senti allungamento nella parte posteriore della coscia o fin dove mantieni la schiena stabile.","Geh so weit runter, bis du eine Dehnung hinten im Oberschenkel spürst oder solange dein Rücken stabil bleibt."],
  ["Empujá la cadera hacia adelante para volver a quedar erguido.","Drive your hips forward to return to standing.","Empurre o quadril para frente para voltar à posição ereta.","Pousse les hanches vers l’avant pour revenir debout.","Spingi le anche in avanti per tornare in posizione eretta.","Schieb die Hüfte nach vorn, um dich wieder aufzurichten."],
  ["Redondear la zona lumbar para bajar más.","Rounding your lower back to go lower.","Arredondar a lombar para descer mais.","Arrondir le bas du dos pour descendre plus bas.","Arrotondare la zona lombare per scendere di più.","Den unteren Rücken runden, um tiefer zu kommen."],
  ["Flexionar mucho las rodillas y convertirlo en sentadilla.","Bending your knees a lot and turning it into a squat.","Flexionar muito os joelhos e transformar em agachamento.","Trop fléchir les genoux et en faire un squat.","Piegare molto le ginocchia e trasformarlo in uno squat.","Die Knie stark beugen und eine Kniebeuge daraus machen."],
  ["Usar una carga que obliga a perder la posición.","Using a load that forces you to lose position.","Usar uma carga que obriga a perder a posição.","Utiliser une charge qui te fait perdre la position.","Usare un carico che ti costringe a perdere la posizione.","Ein Gewicht nutzen, bei dem du die Position verlierst."],
  ["Pensá en empujar la cadera hacia una pared detrás tuyo.","Think about pushing your hips toward a wall behind you.","Pense em empurrar o quadril em direção a uma parede atrás de você.","Pense à pousser les hanches vers un mur derrière toi.","Pensa di spingere le anche verso una parete dietro di te.","Stell dir vor, du schiebst die Hüfte zu einer Wand hinter dir."],
  ["El rango típico termina con el torso cerca de paralelo al suelo o antes.","The typical range ends with the torso close to parallel to the floor, or earlier.","A amplitude típica termina com o tronco perto de paralelo ao chão, ou antes.","L’amplitude typique s’arrête avec le buste presque parallèle au sol, ou avant.","L’ampiezza tipica termina con il busto quasi parallelo al pavimento, o prima.","Der typische Bewegungsumfang endet mit dem Oberkörper etwa parallel zum Boden oder früher."],
  ["Mantené la barra fija sobre la espalda durante todo el movimiento.","Keep the bar fixed on your back throughout the movement.","Mantenha a barra fixa sobre as costas durante todo o movimento.","Garde la barre fixe sur le dos pendant tout le mouvement.","Mantieni il bilanciere fermo sulla schiena per tutto il movimento.","Halte die Stange während der ganzen Bewegung fest auf dem Rücken."],
  ["Glúteo mayor e isquiotibiales","Gluteus maximus and hamstrings","Glúteo máximo e isquiotibiais","Grand fessier et ischio-jambiers","Grande gluteo e ischiocrurali","Großer Gesäßmuskel und hintere Oberschenkel"],
  ["Erectores espinales y aductores","Spinal erectors and adductors","Eretores da espinha e adutores","Érecteurs du rachis et adducteurs","Erettori spinali e adduttori","Rückenstrecker und Adduktoren"],
  ["Polea baja con cuerda","Low cable with rope","Polia baixa com corda","Poulie basse avec corde","Cavo basso con corda","Tiefer Kabelzug mit Seil"],
  ["Principiante; buena opción para aprender la bisagra de cadera","Beginner; a good option for learning the hip hinge","Iniciante; boa opção para aprender a dobradiça de quadril","Débutant ; une bonne option pour apprendre la charnière de hanche","Principiante; buona opzione per imparare il movimento a cerniera dell’anca","Anfänger; gute Option, um das Hüftbeugen (Hip Hinge) zu lernen"],
  ["Parate de espaldas a la polea baja, con la cuerda entre las piernas tomada con ambas manos y pies algo más abiertos que la cadera.","Stand with your back to the low cable, the rope between your legs held with both hands and feet slightly wider than hip-width.","Fique de costas para a polia baixa, com a corda entre as pernas segura com as duas mãos e os pés um pouco mais abertos que o quadril.","Tiens-toi dos à la poulie basse, la corde entre les jambes tenue à deux mains, pieds un peu plus écartés que les hanches.","Mettiti di spalle al cavo basso, con la corda tra le gambe tenuta con entrambe le mani e i piedi poco più larghi delle anche.","Stell dich mit dem Rücken zum tiefen Kabelzug, das Seil zwischen den Beinen mit beiden Händen gefasst, Füße etwas breiter als hüftbreit."],
  ["Inhalá al llevar la cadera atrás y exhalá al extenderla.","Inhale as you push your hips back and exhale as you extend them.","Inspire ao levar o quadril para trás e expire ao estendê-lo.","Inspire en reculant les hanches et expire en les tendant.","Inspira portando le anche indietro ed espira estendendole.","Atme ein, wenn die Hüfte nach hinten geht, und aus, wenn du sie streckst."],
  ["Alejate uno o dos pasos de la polea para que el cable quede tenso.","Step one or two paces away from the cable so it stays taut.","Afaste-se um ou dois passos da polia para o cabo ficar tenso.","Éloigne-toi d’un ou deux pas de la poulie pour que le câble reste tendu.","Allontanati di uno o due passi dal cavo perché resti teso.","Geh ein, zwei Schritte vom Kabelzug weg, damit das Seil gespannt bleibt."],
  ["Llevá la cadera hacia atrás con rodillas apenas flexionadas, dejando que las manos pasen entre las piernas.","Push your hips back with your knees slightly bent, letting your hands pass between your legs.","Leve o quadril para trás com os joelhos levemente flexionados, deixando as mãos passarem entre as pernas.","Recule les hanches, genoux légèrement fléchis, en laissant les mains passer entre les jambes.","Porta le anche indietro con le ginocchia leggermente piegate, lasciando passare le mani tra le gambe.","Schieb die Hüfte mit leicht gebeugten Knien nach hinten und lass die Hände zwischen den Beinen durchgehen."],
  ["Empujá la cadera hacia adelante para pararte, apretando los glúteos.","Drive your hips forward to stand up, squeezing your glutes.","Empurre o quadril para frente para ficar em pé, contraindo os glúteos.","Pousse les hanches vers l’avant pour te redresser en serrant les fessiers.","Spingi le anche in avanti per alzarti, contraendo i glutei.","Schieb die Hüfte nach vorn, um dich aufzurichten, und spann das Gesäß an."],
  ["Terminá erguido, sin tirar con los brazos ni arquear la espalda.","Finish upright, without pulling with your arms or arching your back.","Termine ereto, sem puxar com os braços nem arquear as costas.","Termine droit, sans tirer avec les bras ni cambrer le dos.","Termina in posizione eretta, senza tirare con le braccia né inarcare la schiena.","Beende die Bewegung aufrecht, ohne mit den Armen zu ziehen oder ins Hohlkreuz zu gehen."],
  ["Tirar de la cuerda con los brazos o los hombros.","Pulling the rope with your arms or shoulders.","Puxar a corda com os braços ou os ombros.","Tirer la corde avec les bras ou les épaules.","Tirare la corda con le braccia o le spalle.","Mit Armen oder Schultern am Seil ziehen."],
  ["Agacharse en sentadilla en lugar de bisagra de cadera.","Squatting down instead of hinging at the hips.","Agachar em vez de fazer a dobradiça de quadril.","S’accroupir en squat au lieu de faire une charnière de hanche.","Accovacciarsi in squat invece di fare la cerniera d’anca.","In die Hocke gehen statt aus der Hüfte zu beugen."],
  ["Hiperextender la zona lumbar al final.","Hyperextending your lower back at the end.","Hiperestender a lombar no final.","Hyperétendre le bas du dos à la fin.","Iperestendere la zona lombare alla fine.","Den unteren Rücken am Ende überstrecken."],
  ["Los brazos solo sostienen la cuerda: el movimiento sale de la cadera.","Your arms only hold the rope: the movement comes from the hips.","Os braços só seguram a corda: o movimento sai do quadril.","Les bras ne font que tenir la corde : le mouvement vient des hanches.","Le braccia tengono solo la corda: il movimento parte dalle anche.","Die Arme halten nur das Seil: Die Bewegung kommt aus der Hüfte."],
  ["Mantené la espalda neutra durante toda la repetición.","Keep your back neutral throughout the rep.","Mantenha as costas neutras durante toda a repetição.","Garde le dos neutre pendant toute la répétition.","Mantieni la schiena neutra per tutta la ripetizione.","Halte den Rücken während der ganzen Wiederholung neutral."],
  ["Una pausa breve arriba ayuda a sentir el glúteo.","A brief pause at the top helps you feel your glutes.","Uma pausa breve em cima ajuda a sentir o glúteo.","Une courte pause en haut aide à sentir les fessiers.","Una breve pausa in alto aiuta a sentire i glutei.","Eine kurze Pause oben hilft dir, das Gesäß zu spüren."],
  ["Glúteo mayor","Gluteus maximus","Glúteo máximo","Grand fessier","Grande gluteo","Großer Gesäßmuskel"],
  ["Isquiotibiales y estabilizadores del tronco","Hamstrings and trunk stabilizers","Isquiotibiais e estabilizadores do tronco","Ischio-jambiers et stabilisateurs du tronc","Ischiocrurali e stabilizzatori del tronco","Hintere Oberschenkel und Rumpfstabilisatoren"],
  ["Polea baja con tobillera","Low cable with ankle strap","Polia baixa com tornozeleira","Poulie basse avec sangle de cheville","Cavo basso con cavigliera","Tiefer Kabelzug mit Fußmanschette"],
  ["Parate frente a la polea baja con la tobillera puesta en un pie, manos apoyadas en la máquina y tronco levemente inclinado.","Stand facing the low cable with the ankle strap on one foot, hands on the machine and torso slightly leaning forward.","Fique de frente para a polia baixa com a tornozeleira em um pé, mãos apoiadas na máquina e tronco levemente inclinado.","Tiens-toi face à la poulie basse, la sangle à une cheville, les mains sur la machine et le buste légèrement penché.","Mettiti di fronte al cavo basso con la cavigliera su un piede, mani appoggiate alla macchina e busto leggermente inclinato.","Stell dich mit der Fußmanschette an einem Fuß vor den tiefen Kabelzug, Hände an der Maschine, Oberkörper leicht nach vorn geneigt."],
  ["Exhalá al llevar la pierna atrás e inhalá al volver.","Exhale as you move your leg back and inhale as you return.","Expire ao levar a perna para trás e inspire ao voltar.","Expire en amenant la jambe vers l’arrière et inspire en revenant.","Espira portando la gamba indietro e inspira tornando.","Atme aus, wenn das Bein nach hinten geht, und ein, wenn es zurückkommt."],
  ["45–75 segundos","45–75 seconds","45–75 segundos","45–75 secondes","45–75 secondi","45–75 Sekunden"],
  ["Colocá la tobillera, tomá la máquina para estabilizarte y apoyá firme la pierna de base con la rodilla suave.","Put on the ankle strap, hold the machine to steady yourself and plant your standing leg firmly with a soft knee.","Coloque a tornozeleira, segure a máquina para se estabilizar e apoie firme a perna de base com o joelho levemente flexionado.","Mets la sangle, tiens la machine pour te stabiliser et ancre bien la jambe d’appui, genou souple.","Metti la cavigliera, afferra la macchina per stabilizzarti e appoggia bene la gamba d’appoggio con il ginocchio morbido.","Leg die Fußmanschette an, halt dich an der Maschine fest und stell das Standbein mit weichem Knie sicher auf."],
  ["Llevá la pierna con tobillera hacia atrás extendiendo la cadera, sin girar la pelvis.","Move the strapped leg back by extending your hip, without rotating your pelvis.","Leve a perna com a tornozeleira para trás estendendo o quadril, sem girar a pelve.","Amène la jambe avec la sangle vers l’arrière en tendant la hanche, sans faire pivoter le bassin.","Porta indietro la gamba con la cavigliera estendendo l’anca, senza ruotare il bacino.","Führ das Bein mit der Manschette durch Hüftstreckung nach hinten, ohne das Becken zu drehen."],
  ["Pausá un instante con el glúteo contraído y volvé despacio adelante.","Pause for a moment with your glute squeezed and return slowly forward.","Pause um instante com o glúteo contraído e volte devagar para frente.","Marque une courte pause, fessier contracté, puis reviens lentement vers l’avant.","Fai una breve pausa con il gluteo contratto e torna lentamente in avanti.","Halte kurz mit angespanntem Gesäß und bring das Bein langsam wieder nach vorn."],
  ["Arquear la zona lumbar para levantar más la pierna.","Arching your lower back to lift your leg higher.","Arquear a lombar para levantar mais a perna.","Cambrer le bas du dos pour monter la jambe plus haut.","Inarcare la zona lombare per sollevare di più la gamba.","Ins Hohlkreuz gehen, um das Bein höher zu heben."],
  ["Rotar la cadera hacia afuera durante la patada.","Rotating your hip outward during the kick.","Girar o quadril para fora durante o chute.","Faire pivoter la hanche vers l’extérieur pendant le mouvement.","Ruotare l’anca verso l’esterno durante il calcio.","Die Hüfte beim Kick nach außen drehen."],
  ["Balancear la pierna con impulso.","Swinging your leg with momentum.","Balançar a perna com impulso.","Balancer la jambe avec de l’élan.","Far oscillare la gamba con lo slancio.","Das Bein mit Schwung schleudern."],
  ["El recorrido termina cuando la cadera deja de extenderse, no cuando la espalda se arquea.","The range ends when your hip stops extending, not when your back arches.","O movimento termina quando o quadril deixa de estender, não quando as costas arqueiam.","L’amplitude s’arrête quand la hanche ne s’étend plus, pas quand le dos se cambre.","L’ampiezza finisce quando l’anca smette di estendersi, non quando la schiena si inarca.","Die Bewegung endet, wenn die Hüfte nicht weiter streckt, nicht wenn der Rücken ins Hohlkreuz geht."],
  ["Mantené el abdomen firme y la pelvis mirando al frente.","Keep your abs tight and your pelvis facing forward.","Mantenha o abdômen firme e a pelve voltada para frente.","Garde les abdos gainés et le bassin face à l’avant.","Mantieni l’addome contratto e il bacino rivolto in avanti.","Halte den Bauch fest und das Becken nach vorn ausgerichtet."],
  ["Usá poca carga para controlar todo el rango.","Use a light load to control the full range.","Use pouca carga para controlar toda a amplitude.","Utilise une charge légère pour contrôler toute l’amplitude.","Usa poco carico per controllare tutta l’ampiezza.","Nimm wenig Gewicht, um den ganzen Bewegungsumfang zu kontrollieren."],
  ["Gastrocnemio","Gastrocnemius","Gastrocnêmio","Gastrocnémien","Gastrocnemio","Gastrocnemius (Zwillingswadenmuskel)"],
  ["Sóleo","Soleus","Sóleo","Soléaire","Soleo","Schollenmuskel (Soleus)"],
  ["Máquina de pantorrillas de pie con hombreras y escalón","Standing calf raise machine with shoulder pads and step","Máquina de panturrilha em pé com ombreiras e degrau","Machine à mollets debout avec épaulières et marche","Macchina per polpacci in piedi con spallacci e gradino","Wadenmaschine im Stehen mit Schulterpolstern und Stufe"],
  ["Ubicate bajo las hombreras con la parte delantera de los pies sobre el borde del escalón y las rodillas extendidas sin bloquear.","Position yourself under the shoulder pads with the balls of your feet on the edge of the step and knees straight but not locked.","Posicione-se sob as ombreiras com a parte da frente dos pés na borda do degrau e os joelhos estendidos sem travar.","Place-toi sous les épaulières, l’avant des pieds sur le bord de la marche, genoux tendus sans les verrouiller.","Posizionati sotto gli spallacci con l’avampiede sul bordo del gradino e le ginocchia estese senza bloccarle.","Stell dich unter die Schulterpolster, Vorfüße auf der Stufenkante, Knie gestreckt, aber nicht durchgedrückt."],
  ["Exhalá al subir e inhalá al bajar.","Exhale on the way up and inhale on the way down.","Expire ao subir e inspire ao descer.","Expire en montant et inspire en descendant.","Espira salendo e inspira scendendo.","Atme beim Hochgehen aus und beim Absenken ein."],
  ["Ajustá la altura de las hombreras y apoyá solo el antepié en el escalón, con los talones libres.","Adjust the height of the shoulder pads and place only the front of your feet on the step, heels free.","Ajuste a altura das ombreiras e apoie só a parte da frente dos pés no degrau, com os calcanhares livres.","Règle la hauteur des épaulières et pose seulement l’avant des pieds sur la marche, talons dans le vide.","Regola l’altezza degli spallacci e appoggia solo l’avampiede sul gradino, con i talloni liberi.","Stell die Höhe der Schulterpolster ein und setz nur die Vorfüße auf die Stufe, die Fersen sind frei."],
  ["Bajá los talones lentamente hasta un estiramiento cómodo de la pantorrilla.","Lower your heels slowly into a comfortable calf stretch.","Abaixe os calcanhares lentamente até um alongamento confortável da panturrilha.","Descends lentement les talons jusqu’à un étirement confortable du mollet.","Abbassa lentamente i talloni fino a un allungamento comodo del polpaccio.","Senke die Fersen langsam bis zu einer angenehmen Wadendehnung ab."],
  ["Subí en puntas de pie lo más alto que puedas, empujando con la base de los dedos.","Rise onto your toes as high as you can, pushing through the balls of your feet.","Suba na ponta dos pés o mais alto que puder, empurrando com a base dos dedos.","Monte sur la pointe des pieds le plus haut possible en poussant avec la base des orteils.","Sali sulle punte il più in alto possibile, spingendo con la base delle dita.","Geh so hoch wie möglich auf die Zehenspitzen und drück über die Fußballen."],
  ["Pausá un segundo arriba y volvé a bajar con control.","Pause for a second at the top and lower again with control.","Pause um segundo em cima e volte a descer com controle.","Marque une seconde de pause en haut et redescends en contrôle.","Fai una pausa di un secondo in alto e riscendi con controllo.","Halte oben eine Sekunde und senk dich kontrolliert wieder ab."],
  ["Rebotar en la parte baja del recorrido.","Bouncing at the bottom of the movement.","Quicar na parte baixa do movimento.","Rebondir en bas du mouvement.","Rimbalzare nella parte bassa del movimento.","Unten im Bewegungsumfang federn."],
  ["Flexionar las rodillas para ayudarte a subir.","Bending your knees to help yourself up.","Flexionar os joelhos para ajudar a subir.","Fléchir les genoux pour t’aider à monter.","Piegare le ginocchia per aiutarti a salire.","Die Knie beugen, um beim Hochkommen nachzuhelfen."],
  ["Cargar el peso sobre el borde externo del pie.","Putting your weight on the outer edge of your foot.","Colocar o peso na borda externa do pé.","Mettre le poids sur le bord externe du pied.","Caricare il peso sul bordo esterno del piede.","Das Gewicht auf die Fußaußenkante verlagern."],
  ["Un rango completo y lento rinde más que mucho peso con recorrido corto.","A full, slow range of motion beats heavy weight with a short range.","Uma amplitude completa e lenta rende mais que muito peso com movimento curto.","Une amplitude complète et lente est plus efficace qu’une lourde charge sur une amplitude courte.","Un’ampiezza completa e lenta rende più di tanto peso con un movimento corto.","Ein voller, langsamer Bewegungsumfang bringt mehr als viel Gewicht mit kurzem Weg."],
  ["Mantené el peso repartido entre el dedo gordo y los demás dedos.","Keep your weight spread between your big toe and your other toes.","Mantenha o peso distribuído entre o dedão e os outros dedos.","Garde le poids réparti entre le gros orteil et les autres orteils.","Mantieni il peso distribuito tra l’alluce e le altre dita.","Verteile das Gewicht zwischen großem Zeh und den übrigen Zehen."],
  ["Si el escalón resbala, secá la superficie o cambiá de calzado.","If the step is slippery, dry the surface or change your shoes.","Se o degrau escorregar, seque a superfície ou troque de calçado.","Si la marche glisse, essuie la surface ou change de chaussures.","Se il gradino scivola, asciuga la superficie o cambia scarpe.","Wenn die Stufe rutschig ist, trockne die Fläche ab oder wechsle die Schuhe."],
  ["Máquina de pantorrillas sentado con almohadilla sobre los muslos","Seated calf raise machine with pad over the thighs","Máquina de panturrilha sentado com almofada sobre as coxas","Machine à mollets assis avec coussin sur les cuisses","Macchina per polpacci da seduti con cuscinetto sulle cosce","Wadenmaschine im Sitzen mit Polster auf den Oberschenkeln"],
  ["Sentate en la máquina con el antepié sobre la plataforma, rodillas a 90 grados y la almohadilla apoyada sobre la parte baja de los muslos.","Sit in the machine with the front of your feet on the platform, knees at 90 degrees and the pad resting on your lower thighs.","Sente-se na máquina com a parte da frente dos pés na plataforma, joelhos a 90 graus e a almofada apoiada na parte baixa das coxas.","Assieds-toi dans la machine, l’avant des pieds sur la plateforme, genoux à 90 degrés et coussin posé sur le bas des cuisses.","Siediti nella macchina con l’avampiede sulla pedana, ginocchia a 90 gradi e il cuscinetto appoggiato sulla parte bassa delle cosce.","Setz dich in die Maschine, Vorfüße auf der Plattform, Knie im 90-Grad-Winkel, Polster auf dem unteren Oberschenkel."],
  ["Exhalá al subir los talones e inhalá al bajarlos.","Exhale as you raise your heels and inhale as you lower them.","Expire ao subir os calcanhares e inspire ao abaixá-los.","Expire en montant les talons et inspire en les abaissant.","Espira sollevando i talloni e inspira abbassandoli.","Atme beim Anheben der Fersen aus und beim Absenken ein."],
  ["Ajustá la almohadilla para que quede firme sobre los muslos, cerca de las rodillas, y liberá el seguro.","Adjust the pad so it sits firmly on your thighs, close to your knees, and release the safety catch.","Ajuste a almofada para ficar firme sobre as coxas, perto dos joelhos, e solte a trava.","Règle le coussin pour qu’il soit bien calé sur les cuisses, près des genoux, et libère la sécurité.","Regola il cuscinetto perché sia ben fermo sulle cosce, vicino alle ginocchia, e sblocca la sicura.","Stell das Polster so ein, dass es fest auf den Oberschenkeln nahe den Knien sitzt, und löse die Sicherung."],
  ["Bajá los talones despacio hasta un estiramiento cómodo.","Lower your heels slowly into a comfortable stretch.","Abaixe os calcanhares devagar até um alongamento confortável.","Descends lentement les talons jusqu’à un étirement confortable.","Abbassa lentamente i talloni fino a un allungamento comodo.","Senke die Fersen langsam bis zu einer angenehmen Dehnung ab."],
  ["Subí los talones lo más alto posible y pausá un instante.","Raise your heels as high as possible and pause for a moment.","Suba os calcanhares o mais alto possível e pause um instante.","Monte les talons le plus haut possible et marque une courte pause.","Solleva i talloni il più in alto possibile e fai una breve pausa.","Heb die Fersen so hoch wie möglich und halte kurz."],
  ["Bajá con control y, al terminar, volvé a colocar el seguro.","Lower with control and, when you finish, re-engage the safety catch.","Desça com controle e, ao terminar, recoloque a trava.","Redescends en contrôle et, à la fin, remets la sécurité.","Scendi con controllo e, alla fine, reinserisci la sicura.","Senk dich kontrolliert ab und setz am Ende die Sicherung wieder ein."],
  ["Rebotar abajo usando el estiramiento como impulso.","Bouncing at the bottom, using the stretch for momentum.","Quicar embaixo usando o alongamento como impulso.","Rebondir en bas en utilisant l’étirement comme élan.","Rimbalzare in basso usando l’allungamento come slancio.","Unten federn und die Dehnung als Schwung nutzen."],
  ["Empujar con las manos en lugar de con las pantorrillas.","Pushing with your hands instead of your calves.","Empurrar com as mãos em vez de com as panturrilhas.","Pousser avec les mains au lieu des mollets.","Spingere con le mani invece che con i polpacci.","Mit den Händen statt mit den Waden drücken."],
  ["Hacer repeticiones cortas sin llegar arriba.","Doing short reps without reaching the top.","Fazer repetições curtas sem chegar em cima.","Faire des répétitions courtes sans aller jusqu’en haut.","Fare ripetizioni corte senza arrivare in alto.","Kurze Wiederholungen machen, ohne ganz nach oben zu kommen."],
  ["Con la rodilla flexionada el sóleo trabaja más; por eso complementa a la versión de pie.","With the knee bent the soleus works more; that is why it complements the standing version.","Com o joelho flexionado o sóleo trabalha mais; por isso complementa a versão em pé.","Genou fléchi, le soléaire travaille davantage ; c’est pourquoi cette version complète celle debout.","Con il ginocchio piegato il soleo lavora di più; per questo completa la versione in piedi.","Mit gebeugtem Knie arbeitet der Soleus stärker; deshalb ergänzt diese Übung die Variante im Stehen."],
  ["Usá un ritmo lento y constante.","Use a slow, steady tempo.","Use um ritmo lento e constante.","Adopte un rythme lent et régulier.","Usa un ritmo lento e costante.","Arbeite in einem langsamen, gleichmäßigen Tempo."],
  ["Mantené los pies paralelos y el peso centrado.","Keep your feet parallel and your weight centered.","Mantenha os pés paralelos e o peso centralizado.","Garde les pieds parallèles et le poids centré.","Mantieni i piedi paralleli e il peso centrato.","Halte die Füße parallel und das Gewicht mittig."],
  ["Glúteo medio y glúteo menor","Gluteus medius and gluteus minimus","Glúteo médio e glúteo mínimo","Moyen fessier et petit fessier","Medio gluteo e piccolo gluteo","Mittlerer und kleiner Gesäßmuskel"],
  ["Tensor de la fascia lata y glúteo mayor superior","Tensor fasciae latae and upper gluteus maximus","Tensor da fáscia lata e parte superior do glúteo máximo","Tenseur du fascia lata et partie haute du grand fessier","Tensore della fascia lata e parte alta del grande gluteo","Schenkelbindenspanner und oberer Teil des großen Gesäßmuskels"],
  ["Máquina de abducción de cadera","Hip abduction machine","Máquina de abdução de quadril","Machine d’abduction de hanche","Macchina per abduzione dell’anca","Abduktorenmaschine"],
  ["Sentate con la espalda apoyada, piernas juntas y las almohadillas en la cara externa de las rodillas.","Sit with your back supported, legs together and the pads on the outside of your knees.","Sente-se com as costas apoiadas, pernas juntas e as almofadas na parte externa dos joelhos.","Assieds-toi le dos en appui, jambes serrées et coussins à l’extérieur des genoux.","Siediti con la schiena appoggiata, gambe unite e i cuscinetti sulla parte esterna delle ginocchia.","Setz dich mit angelehntem Rücken hin, Beine geschlossen, die Polster außen an den Knien."],
  ["Exhalá al abrir las piernas e inhalá al cerrarlas.","Exhale as you open your legs and inhale as you close them.","Expire ao abrir as pernas e inspire ao fechá-las.","Expire en écartant les jambes et inspire en les refermant.","Espira aprendo le gambe e inspira chiudendole.","Atme beim Öffnen der Beine aus und beim Schließen ein."],
  ["Ajustá el rango inicial de la máquina para empezar con las piernas juntas y cómodas.","Set the machine’s starting range so you begin with your legs together and comfortable.","Ajuste a amplitude inicial da máquina para começar com as pernas juntas e confortáveis.","Règle l’amplitude de départ de la machine pour commencer jambes serrées et à l’aise.","Regola l’ampiezza iniziale della macchina per partire con le gambe unite e comode.","Stell den Startbereich der Maschine so ein, dass du mit geschlossenen Beinen bequem beginnst."],
  ["Abrí las piernas hacia afuera empujando las almohadillas con la cara externa de los muslos.","Open your legs outward, pushing the pads with the outside of your thighs.","Abra as pernas para fora empurrando as almofadas com a parte externa das coxas.","Écarte les jambes vers l’extérieur en poussant les coussins avec l’extérieur des cuisses.","Apri le gambe verso l’esterno spingendo i cuscinetti con la parte esterna delle cosce.","Öffne die Beine nach außen und drück die Polster mit der Oberschenkelaußenseite weg."],
  ["Pausá un instante en la apertura máxima cómoda.","Pause for a moment at the widest comfortable opening.","Pause um instante na abertura máxima confortável.","Marque une courte pause à l’ouverture maximale confortable.","Fai una breve pausa alla massima apertura comoda.","Halte kurz an der weitesten angenehmen Öffnung."],
  ["Volvé despacio sin dejar que las placas choquen.","Return slowly without letting the weight plates clash.","Volte devagar sem deixar as placas baterem.","Reviens lentement sans laisser les plaques s’entrechoquer.","Torna lentamente senza far sbattere le piastre.","Kehr langsam zurück, ohne die Gewichtsplatten aufschlagen zu lassen."],
  ["Soltar el peso de golpe al cerrar.","Letting the weight drop abruptly as you close.","Soltar o peso de uma vez ao fechar.","Lâcher la charge d’un coup en refermant.","Lasciare andare il peso di colpo in chiusura.","Das Gewicht beim Schließen abrupt fallen lassen."],
  ["Despegar la espalda o la cadera del asiento para ganar impulso.","Lifting your back or hips off the seat to gain momentum.","Descolar as costas ou o quadril do assento para ganhar impulso.","Décoller le dos ou les hanches du siège pour prendre de l’élan.","Staccare la schiena o le anche dal sedile per prendere slancio.","Rücken oder Hüfte vom Sitz lösen, um Schwung zu holen."],
  ["Usar un rango inicial demasiado abierto.","Using a starting range that is too wide.","Usar uma amplitude inicial aberta demais.","Utiliser une amplitude de départ trop ouverte.","Usare un’ampiezza iniziale troppo aperta.","Einen zu weiten Startbereich wählen."],
  ["Inclinar levemente el torso hacia adelante cambia el énfasis hacia el glúteo; probá qué te resulta cómodo.","Leaning your torso slightly forward shifts the emphasis to the glutes; try what feels comfortable.","Inclinar levemente o tronco para frente muda a ênfase para o glúteo; teste o que for confortável.","Pencher légèrement le buste en avant déplace l’accent vers les fessiers ; teste ce qui te convient.","Inclinare leggermente il busto in avanti sposta l’enfasi sui glutei; prova cosa ti risulta comodo.","Wenn du den Oberkörper leicht nach vorn neigst, verlagert sich der Fokus aufs Gesäß; probier aus, was sich gut anfühlt."],
  ["Mantené un ritmo controlado en ambas direcciones.","Keep a controlled tempo in both directions.","Mantenha um ritmo controlado nas duas direções.","Garde un rythme contrôlé dans les deux sens.","Mantieni un ritmo controllato in entrambe le direzioni.","Halte in beide Richtungen ein kontrolliertes Tempo."],
  ["Tomá las manijas para estabilizar el cuerpo.","Hold the handles to stabilize your body.","Segure as alças para estabilizar o corpo.","Tiens les poignées pour stabiliser ton corps.","Afferra le maniglie per stabilizzare il corpo.","Halt dich an den Griffen fest, um deinen Körper zu stabilisieren."],
  ["Aductores de cadera","Hip adductors","Adutores do quadril","Adducteurs de hanche","Adduttori dell’anca","Hüftadduktoren"],
  ["Grácil y pectíneo","Gracilis and pectineus","Grácil e pectíneo","Gracile et pectiné","Gracile e pettineo","Schlankmuskel und Kammmuskel"],
  ["Máquina de aducción de cadera","Hip adduction machine","Máquina de adução de quadril","Machine d’adduction de hanche","Macchina per adduzione dell’anca","Adduktorenmaschine"],
  ["Sentate con la espalda apoyada, piernas abiertas y las almohadillas en la cara interna de las rodillas.","Sit with your back supported, legs apart and the pads on the inside of your knees.","Sente-se com as costas apoiadas, pernas abertas e as almofadas na parte interna dos joelhos.","Assieds-toi le dos en appui, jambes écartées et coussins à l’intérieur des genoux.","Siediti con la schiena appoggiata, gambe aperte e i cuscinetti sulla parte interna delle ginocchia.","Setz dich mit angelehntem Rücken hin, Beine geöffnet, die Polster innen an den Knien."],
  ["Exhalá al cerrar las piernas e inhalá al abrirlas.","Exhale as you close your legs and inhale as you open them.","Expire ao fechar as pernas e inspire ao abri-las.","Expire en refermant les jambes et inspire en les écartant.","Espira chiudendo le gambe e inspira aprendole.","Atme beim Schließen der Beine aus und beim Öffnen ein."],
  ["Regulá la apertura inicial en un rango que sientas cómodo, sin forzar el estiramiento.","Set the starting opening to a range that feels comfortable, without forcing the stretch.","Regule a abertura inicial em uma amplitude confortável, sem forçar o alongamento.","Règle l’ouverture de départ sur une amplitude confortable, sans forcer l’étirement.","Regola l’apertura iniziale in un’ampiezza comoda, senza forzare l’allungamento.","Stell die Startöffnung so ein, dass sie sich angenehm anfühlt, ohne die Dehnung zu erzwingen."],
  ["Cerrá las piernas juntando las almohadillas con la cara interna de los muslos.","Close your legs, bringing the pads together with the inside of your thighs.","Feche as pernas juntando as almofadas com a parte interna das coxas.","Referme les jambes en rapprochant les coussins avec l’intérieur des cuisses.","Chiudi le gambe unendo i cuscinetti con la parte interna delle cosce.","Schließ die Beine und führ die Polster mit der Oberschenkelinnenseite zusammen."],
  ["Pausá un instante con las piernas juntas.","Pause for a moment with your legs together.","Pause um instante com as pernas juntas.","Marque une courte pause, jambes serrées.","Fai una breve pausa con le gambe unite.","Halte kurz mit geschlossenen Beinen."],
  ["Abrí de nuevo con control hasta la posición inicial.","Open again with control to the starting position.","Abra de novo com controle até a posição inicial.","Rouvre en contrôle jusqu’à la position de départ.","Riapri con controllo fino alla posizione iniziale.","Öffne die Beine kontrolliert wieder bis zur Ausgangsposition."],
  ["Empezar con una apertura excesiva que tira de la ingle.","Starting with an excessive opening that pulls on the groin.","Começar com uma abertura excessiva que puxa a virilha.","Commencer avec une ouverture excessive qui tire sur l’aine.","Iniziare con un’apertura eccessiva che tira l’inguine.","Mit einer zu weiten Öffnung beginnen, die an der Leiste zieht."],
  ["Dejar que las piernas se abran de golpe.","Letting your legs fly open.","Deixar as pernas se abrirem de uma vez.","Laisser les jambes s’ouvrir d’un coup.","Lasciare che le gambe si aprano di colpo.","Die Beine unkontrolliert aufgehen lassen."],
  ["Despegar la espalda del respaldo.","Lifting your back off the backrest.","Descolar as costas do encosto.","Décoller le dos du dossier.","Staccare la schiena dallo schienale.","Den Rücken von der Lehne lösen."],
  ["Aumentá la apertura de a poco a lo largo de las semanas.","Increase the opening gradually over the weeks.","Aumente a abertura aos poucos ao longo das semanas.","Augmente l’ouverture progressivement au fil des semaines.","Aumenta l’apertura poco alla volta nel corso delle settimane.","Vergrößere die Öffnung über die Wochen hinweg schrittweise."],
  ["Mantené los pies apoyados en los soportes.","Keep your feet on the supports.","Mantenha os pés apoiados nos suportes.","Garde les pieds sur les supports.","Mantieni i piedi appoggiati sui supporti.","Lass die Füße auf den Stützen."],
  ["Una carga moderada con buen control es suficiente para este músculo.","A moderate load with good control is enough for this muscle.","Uma carga moderada com bom controle é suficiente para este músculo.","Une charge modérée bien contrôlée suffit pour ce muscle.","Un carico moderato con buon controllo è sufficiente per questo muscolo.","Ein moderates Gewicht mit guter Kontrolle reicht für diesen Muskel."],
  ["Pectoral mayor, con énfasis relativo en la porción inferior","Pectoralis major, with relative emphasis on the lower portion","Peitoral maior, com ênfase relativa na porção inferior","Grand pectoral, avec un accent relatif sur la partie inférieure","Grande pettorale, con enfasi relativa sulla porzione inferiore","Großer Brustmuskel mit relativem Fokus auf den unteren Teil"],
  ["Tríceps y deltoides anterior","Triceps and front deltoid","Tríceps e deltoide anterior","Triceps et deltoïde antérieur","Tricipiti e deltoide anteriore","Trizeps und vorderer Deltamuskel"],
  ["Máquina de press declinado","Decline press machine","Máquina de supino declinado","Machine de développé décliné","Macchina per distensioni declinate","Maschine für Negativdrücken"],
  ["Sentate con la espalda apoyada y las manijas a la altura de la parte baja del pecho.","Sit with your back supported and the handles at the height of your lower chest.","Sente-se com as costas apoiadas e as alças na altura da parte baixa do peito.","Assieds-toi le dos en appui, poignées à hauteur du bas de la poitrine.","Siediti con la schiena appoggiata e le maniglie all’altezza della parte bassa del petto.","Setz dich mit angelehntem Rücken hin, die Griffe auf Höhe der unteren Brust."],
  ["Exhalá al empujar e inhalá al volver.","Exhale as you push and inhale as you return.","Expire ao empurrar e inspire ao voltar.","Expire en poussant et inspire en revenant.","Espira spingendo e inspira tornando.","Atme beim Drücken aus und beim Zurückführen ein."],
  ["60–120 segundos","60–120 seconds","60–120 segundos","60–120 secondes","60–120 secondi","60–120 Sekunden"],
  ["Ajustá el asiento para que las manijas queden alineadas con la parte inferior del pecho.","Adjust the seat so the handles line up with your lower chest.","Ajuste o assento para as alças ficarem alinhadas com a parte inferior do peito.","Règle le siège pour que les poignées soient alignées avec le bas de la poitrine.","Regola il sedile perché le maniglie siano allineate con la parte bassa del petto.","Stell den Sitz so ein, dass die Griffe auf einer Linie mit der unteren Brust liegen."],
  ["Empujá las manijas hacia adelante y abajo hasta extender los brazos sin bloquear los codos.","Push the handles forward and down until your arms are extended, without locking your elbows.","Empurre as alças para frente e para baixo até estender os braços, sem travar os cotovelos.","Pousse les poignées vers l’avant et le bas jusqu’à tendre les bras, sans verrouiller les coudes.","Spingi le maniglie in avanti e in basso fino a distendere le braccia, senza bloccare i gomiti.","Drück die Griffe nach vorn unten, bis die Arme gestreckt sind, ohne die Ellbogen durchzudrücken."],
  ["Volvé con control hasta sentir un estiramiento cómodo en el pecho.","Return with control until you feel a comfortable stretch in your chest.","Volte com controle até sentir um alongamento confortável no peito.","Reviens en contrôle jusqu’à sentir un étirement confortable dans la poitrine.","Torna con controllo fino a sentire un allungamento comodo nel petto.","Führ kontrolliert zurück, bis du eine angenehme Dehnung in der Brust spürst."],
  ["Mantené la espalda y la cabeza apoyadas durante toda la serie.","Keep your back and head supported throughout the set.","Mantenha as costas e a cabeça apoiadas durante toda a série.","Garde le dos et la tête en appui pendant toute la série.","Mantieni schiena e testa appoggiate per tutta la serie.","Halte Rücken und Kopf während des ganzen Satzes angelehnt."],
  ["Asiento mal regulado que deja las manijas a la altura de los hombros.","A poorly adjusted seat that leaves the handles at shoulder height.","Assento mal regulado que deixa as alças na altura dos ombros.","Un siège mal réglé qui place les poignées à hauteur des épaules.","Sedile regolato male che lascia le maniglie all’altezza delle spalle.","Ein falsch eingestellter Sitz, bei dem die Griffe auf Schulterhöhe liegen."],
  ["Despegar la espalda del respaldo al empujar.","Lifting your back off the backrest as you push.","Descolar as costas do encosto ao empurrar.","Décoller le dos du dossier en poussant.","Staccare la schiena dallo schienale mentre spingi.","Beim Drücken den Rücken von der Lehne lösen."],
  ["Dejar que las placas caigan al regresar.","Letting the weight plates drop on the way back.","Deixar as placas caírem ao voltar.","Laisser retomber les plaques au retour.","Lasciar cadere le piastre al ritorno.","Die Gewichtsplatten beim Zurückführen fallen lassen."],
  ["Mantené las escápulas apoyadas y los hombros lejos de las orejas.","Keep your shoulder blades against the pad and your shoulders away from your ears.","Mantenha as escápulas apoiadas e os ombros longe das orelhas.","Garde les omoplates en appui et les épaules loin des oreilles.","Mantieni le scapole appoggiate e le spalle lontane dalle orecchie.","Halte die Schulterblätter angelehnt und die Schultern weg von den Ohren."],
  ["Las muñecas deben quedar alineadas con los antebrazos.","Your wrists should stay aligned with your forearms.","Os punhos devem ficar alinhados com os antebraços.","Les poignets doivent rester alignés avec les avant-bras.","I polsi devono restare allineati con gli avambracci.","Die Handgelenke sollten in einer Linie mit den Unterarmen bleiben."],
  ["Controlá el regreso al menos tanto como el empuje.","Control the return at least as much as the push.","Controle a volta pelo menos tanto quanto o empurrão.","Contrôle le retour au moins autant que la poussée.","Controlla il ritorno almeno quanto la spinta.","Kontrolliere das Zurückführen mindestens so sehr wie das Drücken."],
  ["Pectoral mayor","Pectoralis major","Peitoral maior","Grand pectoral","Grande pettorale","Großer Brustmuskel"],
  ["Tríceps, deltoides anterior y tronco estabilizador","Triceps, front deltoid and stabilizing trunk","Tríceps, deltoide anterior e tronco estabilizador","Triceps, deltoïde antérieur et tronc stabilisateur","Tricipiti, deltoide anteriore e tronco stabilizzatore","Trizeps, vorderer Deltamuskel und stabilisierender Rumpf"],
  ["Dos poleas a la altura del pecho con manijas, o una estación de cruce de poleas","Two chest-height cables with handles, or a cable crossover station","Duas polias na altura do peito com alças, ou uma estação de crossover","Deux poulies à hauteur de poitrine avec poignées, ou une station de vis-à-vis","Due cavi all’altezza del petto con maniglie, o una stazione cable crossover","Zwei Kabelzüge auf Brusthöhe mit Griffen oder ein Kabelzugturm"],
  ["Principiante-intermedio; exige estabilidad de pie","Beginner–intermediate; requires standing stability","Iniciante-intermediário; exige estabilidade em pé","Débutant-intermédiaire ; demande de la stabilité debout","Principiante-intermedio; richiede stabilità in piedi","Anfänger bis Fortgeschrittene; erfordert Stabilität im Stand"],
  ["Parate en el centro entre las poleas, de espaldas a ellas, con una manija en cada mano a la altura del pecho y un pie adelantado.","Stand in the center between the cables, facing away from them, with a handle in each hand at chest height and one foot forward.","Fique no centro entre as polias, de costas para elas, com uma alça em cada mão na altura do peito e um pé à frente.","Place-toi au centre entre les poulies, dos à elles, une poignée dans chaque main à hauteur de poitrine et un pied en avant.","Mettiti al centro tra i cavi, di spalle, con una maniglia per mano all’altezza del petto e un piede avanti.","Stell dich mittig zwischen die Kabelzüge mit dem Rücken zu ihnen, je einen Griff auf Brusthöhe in der Hand, ein Fuß vorn."],
  ["Dá un paso adelante hasta que los cables queden tensos y adoptá una postura escalonada estable.","Step forward until the cables are taut and adopt a stable staggered stance.","Dê um passo à frente até os cabos ficarem tensos e adote uma postura escalonada estável.","Fais un pas en avant jusqu’à ce que les câbles soient tendus et adopte une position décalée stable.","Fai un passo avanti finché i cavi sono tesi e assumi una posizione sfalsata stabile.","Mach einen Schritt nach vorn, bis die Seile gespannt sind, und nimm eine stabile Schrittstellung ein."],
  ["Empujá las manijas al frente hasta extender los brazos, juntándolas delante del pecho.","Push the handles forward until your arms are extended, bringing them together in front of your chest.","Empurre as alças à frente até estender os braços, juntando-as diante do peito.","Pousse les poignées vers l’avant jusqu’à tendre les bras, en les rapprochant devant la poitrine.","Spingi le maniglie in avanti fino a distendere le braccia, unendole davanti al petto.","Drück die Griffe nach vorn, bis die Arme gestreckt sind, und führ sie vor der Brust zusammen."],
  ["Volvé despacio hasta que las manos queden a la altura del pecho, sin dejar que los cables tiren de los hombros hacia atrás.","Return slowly until your hands are at chest height, without letting the cables pull your shoulders back.","Volte devagar até as mãos ficarem na altura do peito, sem deixar os cabos puxarem os ombros para trás.","Reviens lentement jusqu’à ce que les mains soient à hauteur de poitrine, sans laisser les câbles tirer les épaules vers l’arrière.","Torna lentamente finché le mani sono all’altezza del petto, senza lasciare che i cavi tirino indietro le spalle.","Führ langsam zurück, bis die Hände auf Brusthöhe sind, ohne dass die Seile die Schultern nach hinten ziehen."],
  ["Mantené el tronco firme sin inclinarte durante la serie.","Keep your trunk firm without leaning during the set.","Mantenha o tronco firme sem se inclinar durante a série.","Garde le tronc gainé sans te pencher pendant la série.","Mantieni il tronco stabile senza inclinarti durante la serie.","Halte den Rumpf während des Satzes fest, ohne dich zu neigen."],
  ["Inclinar el tronco hacia adelante para mover más carga.","Leaning your torso forward to move more weight.","Inclinar o tronco para frente para mover mais carga.","Pencher le buste en avant pour déplacer plus de charge.","Inclinare il busto in avanti per spostare più carico.","Den Oberkörper nach vorn neigen, um mehr Gewicht zu bewegen."],
  ["Dejar que los codos se vayan muy atrás del cuerpo al regresar.","Letting your elbows travel far behind your body on the way back.","Deixar os cotovelos irem muito para trás do corpo ao voltar.","Laisser les coudes partir loin derrière le corps au retour.","Lasciare che i gomiti vadano molto dietro il corpo al ritorno.","Die Ellbogen beim Zurückführen weit hinter den Körper wandern lassen."],
  ["Arquear la zona lumbar.","Arching your lower back.","Arquear a lombar.","Cambrer le bas du dos.","Inarcare la zona lombare.","Ins Hohlkreuz gehen."],
  ["La postura escalonada da estabilidad; alterná el pie adelantado entre series.","The staggered stance gives you stability; alternate the front foot between sets.","A postura escalonada dá estabilidade; alterne o pé da frente entre as séries.","La position décalée apporte de la stabilité ; alterne le pied avant entre les séries.","La posizione sfalsata dà stabilità; alterna il piede avanti tra le serie.","Die Schrittstellung gibt dir Stabilität; wechsle den vorderen Fuß zwischen den Sätzen."],
  ["Elegí una carga que puedas sostener sin perder la postura.","Choose a load you can handle without losing your posture.","Escolha uma carga que consiga sustentar sem perder a postura.","Choisis une charge que tu peux tenir sans perdre ta posture.","Scegli un carico che riesci a gestire senza perdere la postura.","Wähle ein Gewicht, das du ohne Haltungsverlust bewältigst."],
  ["Pensá en juntar los bíceps al final del empuje.","Think about bringing your biceps together at the end of the push.","Pense em juntar os bíceps no final do empurrão.","Pense à rapprocher les biceps à la fin de la poussée.","Pensa di unire i bicipiti alla fine della spinta.","Denk daran, am Ende des Drückens die Bizepse zusammenzuführen."],
  ["Deltoides anterior y bíceps como estabilizador","Front deltoid, and biceps as a stabilizer","Deltoide anterior e bíceps como estabilizador","Deltoïde antérieur et biceps comme stabilisateur","Deltoide anteriore e bicipite come stabilizzatore","Vorderer Deltamuskel und Bizeps als Stabilisator"],
  ["Banco plano ubicado entre dos poleas bajas con manijas","Flat bench placed between two low cables with handles","Banco reto posicionado entre duas polias baixas com alças","Banc plat placé entre deux poulies basses avec poignées","Panca piana posizionata tra due cavi bassi con maniglie","Flachbank zwischen zwei tiefen Kabelzügen mit Griffen"],
  ["Acostate en un banco plano centrado entre dos poleas bajas, con una manija en cada mano y los brazos extendidos sobre el pecho.","Lie on a flat bench centered between two low cables, with a handle in each hand and your arms extended over your chest.","Deite-se em um banco reto centralizado entre duas polias baixas, com uma alça em cada mão e os braços estendidos sobre o peito.","Allonge-toi sur un banc plat centré entre deux poulies basses, une poignée dans chaque main, bras tendus au-dessus de la poitrine.","Sdraiati su una panca piana al centro tra due cavi bassi, con una maniglia per mano e le braccia distese sopra il petto.","Leg dich auf eine Flachbank mittig zwischen zwei tiefen Kabelzügen, je einen Griff in der Hand, Arme über der Brust gestreckt."],
  ["Inhalá al abrir los brazos y exhalá al cerrarlos.","Inhale as you open your arms and exhale as you close them.","Inspire ao abrir os braços e expire ao fechá-los.","Inspire en ouvrant les bras et expire en les refermant.","Inspira aprendo le braccia ed espira chiudendole.","Atme beim Öffnen der Arme ein und beim Schließen aus."],
  ["Tomá las manijas, acostate y llevá los brazos arriba del pecho con los codos apenas flexionados.","Take the handles, lie down and bring your arms above your chest with your elbows slightly bent.","Pegue as alças, deite-se e leve os braços acima do peito com os cotovelos levemente flexionados.","Prends les poignées, allonge-toi et amène les bras au-dessus de la poitrine, coudes légèrement fléchis.","Prendi le maniglie, sdraiati e porta le braccia sopra il petto con i gomiti leggermente piegati.","Nimm die Griffe, leg dich hin und bring die Arme mit leicht gebeugten Ellbogen über die Brust."],
  ["Abrí los brazos en un arco amplio hacia los costados hasta sentir un estiramiento cómodo en el pecho.","Open your arms in a wide arc out to the sides until you feel a comfortable stretch in your chest.","Abra os braços em um arco amplo para os lados até sentir um alongamento confortável no peito.","Ouvre les bras en un large arc sur les côtés jusqu’à sentir un étirement confortable dans la poitrine.","Apri le braccia in un ampio arco verso i lati fino a sentire un allungamento comodo nel petto.","Öffne die Arme in einem weiten Bogen zur Seite, bis du eine angenehme Dehnung in der Brust spürst."],
  ["Cerrá el arco volviendo a juntar las manos sobre el pecho, sin cambiar el ángulo de los codos.","Close the arc by bringing your hands back together over your chest, without changing the angle of your elbows.","Feche o arco voltando a juntar as mãos sobre o peito, sem mudar o ângulo dos cotovelos.","Referme l’arc en ramenant les mains au-dessus de la poitrine, sans changer l’angle des coudes.","Chiudi l’arco riunendo le mani sopra il petto, senza cambiare l’angolo dei gomiti.","Schließ den Bogen und führ die Hände wieder über der Brust zusammen, ohne den Ellbogenwinkel zu verändern."],
  ["Al terminar, acercá las manijas al cuerpo antes de sentarte para soltarlas.","When you finish, bring the handles close to your body before sitting up to release them.","Ao terminar, aproxime as alças do corpo antes de se sentar para soltá-las.","À la fin, rapproche les poignées du corps avant de t’asseoir pour les lâcher.","Alla fine, avvicina le maniglie al corpo prima di metterti seduto per lasciarle.","Bring die Griffe am Ende nah an den Körper, bevor du dich aufsetzt und sie loslässt."],
  ["Flexionar y extender los codos como si fuera un press.","Bending and straightening your elbows as if it were a press.","Flexionar e estender os cotovelos como se fosse um supino.","Fléchir et tendre les coudes comme pour un développé.","Piegare ed estendere i gomiti come in una distensione.","Die Ellbogen beugen und strecken, als wäre es ein Drücken."],
  ["Abrir más allá del rango cómodo del hombro.","Opening beyond your shoulder’s comfortable range.","Abrir além da amplitude confortável do ombro.","Ouvrir au-delà de l’amplitude confortable de l’épaule.","Aprire oltre l’ampiezza comoda della spalla.","Weiter öffnen, als es für die Schulter angenehm ist."],
  ["Soltar las manijas de golpe al terminar.","Letting go of the handles abruptly at the end.","Soltar as alças de uma vez ao terminar.","Lâcher les poignées d’un coup à la fin.","Lasciare le maniglie di colpo alla fine.","Die Griffe am Ende abrupt loslassen."],
  ["La polea mantiene tensión también arriba, a diferencia de las mancuernas.","The cable keeps tension at the top too, unlike dumbbells.","A polia mantém tensão também em cima, ao contrário dos halteres.","La poulie maintient la tension même en haut, contrairement aux haltères.","Il cavo mantiene la tensione anche in alto, a differenza dei manubri.","Der Kabelzug hält auch oben Spannung, anders als Kurzhanteln."],
  ["Mantené los pies firmes y la espalda apoyada.","Keep your feet planted and your back supported.","Mantenha os pés firmes e as costas apoiadas.","Garde les pieds bien ancrés et le dos en appui.","Mantieni i piedi ben piantati e la schiena appoggiata.","Halte die Füße fest am Boden und den Rücken angelehnt."],
  ["Usá poco peso: es un ejercicio de aislamiento.","Use a light weight: it is an isolation exercise.","Use pouco peso: é um exercício de isolamento.","Utilise une charge légère : c’est un exercice d’isolation.","Usa poco peso: è un esercizio di isolamento.","Nimm wenig Gewicht: Es ist eine Isolationsübung."],
  ["Banco plano y dos mancuernas livianas","Flat bench and two light dumbbells","Banco reto e dois halteres leves","Banc plat et deux haltères légers","Panca piana e due manubri leggeri","Flachbank und zwei leichte Kurzhanteln"],
  ["Principiante-intermedio con carga liviana","Beginner–intermediate with a light load","Iniciante-intermediário com carga leve","Débutant-intermédiaire avec charge légère","Principiante-intermedio con carico leggero","Anfänger bis Fortgeschrittene mit leichtem Gewicht"],
  ["Acostate en el banco con los pies firmes y las mancuernas arriba del pecho, palmas enfrentadas y codos levemente flexionados.","Lie on the bench with your feet planted and the dumbbells above your chest, palms facing each other and elbows slightly bent.","Deite-se no banco com os pés firmes e os halteres acima do peito, palmas voltadas uma para a outra e cotovelos levemente flexionados.","Allonge-toi sur le banc, pieds ancrés, haltères au-dessus de la poitrine, paumes face à face et coudes légèrement fléchis.","Sdraiati sulla panca con i piedi ben piantati e i manubri sopra il petto, palmi rivolti l’uno verso l’altro e gomiti leggermente piegati.","Leg dich auf die Bank, Füße fest am Boden, die Kurzhanteln über der Brust, Handflächen zueinander, Ellbogen leicht gebeugt."],
  ["Inhalá al abrir y exhalá al cerrar.","Inhale as you open and exhale as you close.","Inspire ao abrir e expire ao fechar.","Inspire en ouvrant et expire en refermant.","Inspira aprendo ed espira chiudendo.","Atme beim Öffnen ein und beim Schließen aus."],
  ["Llevá las mancuernas arriba del pecho con un leve ángulo en los codos que vas a mantener toda la serie.","Bring the dumbbells above your chest with a slight bend in your elbows that you will keep for the whole set.","Leve os halteres acima do peito com um leve ângulo nos cotovelos que você vai manter durante toda a série.","Amène les haltères au-dessus de la poitrine avec un léger angle aux coudes que tu garderas toute la série.","Porta i manubri sopra il petto con una leggera flessione dei gomiti che manterrai per tutta la serie.","Bring die Kurzhanteln über die Brust, mit einer leichten Ellbogenbeugung, die du den ganzen Satz hältst."],
  ["Abrí los brazos hacia los costados en arco, bajando las mancuernas hasta que los codos queden a la altura del banco o un poco antes.","Open your arms out to the sides in an arc, lowering the dumbbells until your elbows are level with the bench or slightly above.","Abra os braços para os lados em arco, abaixando os halteres até os cotovelos ficarem na altura do banco ou um pouco antes.","Ouvre les bras sur les côtés en arc, en descendant les haltères jusqu’à ce que les coudes soient à hauteur du banc ou un peu au-dessus.","Apri le braccia lateralmente ad arco, abbassando i manubri finché i gomiti sono all’altezza della panca o poco prima.","Öffne die Arme in einem Bogen zur Seite und senke die Kurzhanteln, bis die Ellbogen auf Bankhöhe oder knapp darüber sind."],
  ["Volvé por el mismo arco hasta juntar las mancuernas sobre el pecho.","Return along the same arc until the dumbbells meet over your chest.","Volte pelo mesmo arco até juntar os halteres sobre o peito.","Reviens par le même arc jusqu’à rapprocher les haltères au-dessus de la poitrine.","Torna lungo lo stesso arco fino a unire i manubri sopra il petto.","Führ sie auf demselben Bogen zurück, bis sich die Kurzhanteln über der Brust treffen."],
  ["Al terminar, acercá las mancuernas al pecho antes de incorporarte.","When you finish, bring the dumbbells to your chest before sitting up.","Ao terminar, aproxime os halteres do peito antes de se levantar.","À la fin, ramène les haltères contre la poitrine avant de te redresser.","Alla fine, avvicina i manubri al petto prima di rialzarti.","Bring die Kurzhanteln am Ende an die Brust, bevor du dich aufrichtest."],
  ["Bajar las mancuernas por debajo de la línea del banco con codos rectos.","Lowering the dumbbells below the line of the bench with straight elbows.","Abaixar os halteres abaixo da linha do banco com os cotovelos retos.","Descendre les haltères sous la ligne du banc avec les coudes tendus.","Abbassare i manubri sotto la linea della panca con i gomiti tesi.","Die Kurzhanteln mit gestreckten Ellbogen unter Bankhöhe senken."],
  ["Convertir el movimiento en un press flexionando mucho los codos.","Turning the movement into a press by bending your elbows a lot.","Transformar o movimento em supino flexionando muito os cotovelos.","Transformer le mouvement en développé en fléchissant beaucoup les coudes.","Trasformare il movimento in una distensione piegando molto i gomiti.","Durch starkes Beugen der Ellbogen ein Drücken daraus machen."],
  ["Usar mancuernas demasiado pesadas.","Using dumbbells that are too heavy.","Usar halteres pesados demais.","Utiliser des haltères trop lourds.","Usare manubri troppo pesanti.","Zu schwere Kurzhanteln verwenden."],
  ["Pensá en abrazar un árbol grande.","Think about hugging a big tree.","Pense em abraçar uma árvore grande.","Pense à enlacer un gros arbre.","Pensa di abbracciare un grande albero.","Stell dir vor, du umarmst einen großen Baum."],
  ["Detené la bajada donde el hombro siga cómodo.","Stop the descent where your shoulder still feels comfortable.","Pare a descida onde o ombro continuar confortável.","Arrête la descente là où l’épaule reste à l’aise.","Ferma la discesa dove la spalla resta comoda.","Stopp die Abwärtsbewegung dort, wo sich die Schulter noch gut anfühlt."],
  ["No hace falta chocar las mancuernas arriba.","There is no need to clash the dumbbells at the top.","Não é preciso bater os halteres em cima.","Inutile d’entrechoquer les haltères en haut.","Non serve far sbattere i manubri in alto.","Die Kurzhanteln müssen oben nicht aneinanderschlagen."],
  ["Deltoides anterior y tronco estabilizador","Front deltoid and stabilizing trunk","Deltoide anterior e tronco estabilizador","Deltoïde antérieur et tronc stabilisateur","Deltoide anteriore e tronco stabilizzatore","Vorderer Deltamuskel und stabilisierender Rumpf"],
  ["Estación de cruce de poleas con las poleas en posición alta","Cable crossover station with the pulleys set high","Estação de crossover com as polias na posição alta","Station de vis-à-vis avec poulies en position haute","Stazione cable crossover con i cavi in posizione alta","Kabelzugturm mit Rollen in hoher Position"],
  ["Parate en el centro de la estación con una manija de cada polea alta, un pie adelantado y el torso levemente inclinado.","Stand in the center of the station with a handle from each high pulley, one foot forward and your torso leaning slightly forward.","Fique no centro da estação com uma alça de cada polia alta, um pé à frente e o tronco levemente inclinado.","Place-toi au centre de la station avec une poignée de chaque poulie haute, un pied en avant et le buste légèrement penché.","Mettiti al centro della stazione con una maniglia di ogni cavo alto, un piede avanti e il busto leggermente inclinato.","Stell dich in die Mitte des Turms, je einen Griff der oberen Rollen in der Hand, ein Fuß vorn, Oberkörper leicht nach vorn geneigt."],
  ["Exhalá al juntar las manos e inhalá al abrir.","Exhale as you bring your hands together and inhale as you open.","Expire ao juntar as mãos e inspire ao abrir.","Expire en rapprochant les mains et inspire en ouvrant.","Espira unendo le mani e inspira aprendo.","Atme beim Zusammenführen der Hände aus und beim Öffnen ein."],
  ["Tomá las manijas, dá un paso adelante y abrí los brazos con los codos apenas flexionados.","Take the handles, step forward and open your arms with your elbows slightly bent.","Pegue as alças, dê um passo à frente e abra os braços com os cotovelos levemente flexionados.","Prends les poignées, fais un pas en avant et ouvre les bras, coudes légèrement fléchis.","Prendi le maniglie, fai un passo avanti e apri le braccia con i gomiti leggermente piegati.","Nimm die Griffe, mach einen Schritt nach vorn und öffne die Arme mit leicht gebeugten Ellbogen."],
  ["Llevá las manos hacia abajo y al frente en arco hasta juntarlas delante de la cadera.","Bring your hands down and forward in an arc until they meet in front of your hips.","Leve as mãos para baixo e para frente em arco até juntá-las diante do quadril.","Amène les mains vers le bas et l’avant en arc jusqu’à les rapprocher devant les hanches.","Porta le mani in basso e in avanti ad arco fino a unirle davanti alle anche.","Führ die Hände in einem Bogen nach unten vorn, bis sie sich vor der Hüfte treffen."],
  ["Volvé despacio por el mismo arco hasta sentir un estiramiento cómodo en el pecho.","Return slowly along the same arc until you feel a comfortable stretch in your chest.","Volte devagar pelo mesmo arco até sentir um alongamento confortável no peito.","Reviens lentement par le même arc jusqu’à sentir un étirement confortable dans la poitrine.","Torna lentamente lungo lo stesso arco fino a sentire un allungamento comodo nel petto.","Führ sie langsam auf demselben Bogen zurück, bis du eine angenehme Dehnung in der Brust spürst."],
  ["Mantené la postura y el ángulo de los codos fijos durante la serie.","Keep your posture and elbow angle fixed throughout the set.","Mantenha a postura e o ângulo dos cotovelos fixos durante a série.","Garde la posture et l’angle des coudes fixes pendant la série.","Mantieni postura e angolo dei gomiti fissi durante la serie.","Halte Haltung und Ellbogenwinkel während des Satzes konstant."],
  ["Doblar el tronco hacia adelante en cada repetición.","Bending your torso forward on every rep.","Dobrar o tronco para frente a cada repetição.","Plier le buste vers l’avant à chaque répétition.","Piegare il busto in avanti a ogni ripetizione.","Den Oberkörper bei jeder Wiederholung nach vorn beugen."],
  ["Dejar que los cables lleven los brazos muy atrás.","Letting the cables pull your arms far back.","Deixar os cabos levarem os braços muito para trás.","Laisser les câbles emmener les bras loin en arrière.","Lasciare che i cavi portino le braccia molto indietro.","Die Seile die Arme weit nach hinten ziehen lassen."],
  ["Flexionar y extender los codos durante el arco.","Bending and straightening your elbows during the arc.","Flexionar e estender os cotovelos durante o arco.","Fléchir et tendre les coudes pendant l’arc.","Piegare ed estendere i gomiti durante l’arco.","Die Ellbogen während des Bogens beugen und strecken."],
  ["La dirección del cable, de arriba hacia abajo, es lo que da el énfasis inferior.","The high-to-low direction of the cable is what gives the lower-chest emphasis.","A direção do cabo, de cima para baixo, é o que dá a ênfase inferior.","C’est la direction du câble, du haut vers le bas, qui donne l’accent sur le bas des pectoraux.","È la direzione del cavo, dall’alto verso il basso, a dare l’enfasi sulla parte inferiore.","Die Zugrichtung von oben nach unten sorgt für den Fokus auf die untere Brust."],
  ["Mantené los hombros bajos y el pecho abierto.","Keep your shoulders down and your chest open.","Mantenha os ombros baixos e o peito aberto.","Garde les épaules basses et la poitrine ouverte.","Mantieni le spalle basse e il petto aperto.","Halte die Schultern unten und die Brust offen."],
  ["Usá una carga que te permita pausar con las manos juntas.","Use a load that lets you pause with your hands together.","Use uma carga que permita pausar com as mãos juntas.","Utilise une charge qui te permet de marquer une pause mains jointes.","Usa un carico che ti permetta di fare una pausa con le mani unite.","Nimm ein Gewicht, mit dem du mit zusammengeführten Händen kurz halten kannst."],
  ["Pectoral mayor, con énfasis relativo en la porción clavicular","Pectoralis major, with relative emphasis on the clavicular portion","Peitoral maior, com ênfase relativa na porção clavicular","Grand pectoral, avec un accent relatif sur le faisceau claviculaire","Grande pettorale, con enfasi relativa sulla porzione clavicolare","Großer Brustmuskel mit relativem Fokus auf den Schlüsselbeinanteil"],
  ["Deltoides anterior","Front deltoid","Deltoide anterior","Deltoïde antérieur","Deltoide anteriore","Vorderer Deltamuskel"],
  ["Estación de cruce de poleas con las poleas en posición baja","Cable crossover station with the pulleys set low","Estação de crossover com as polias na posição baixa","Station de vis-à-vis avec poulies en position basse","Stazione cable crossover con i cavi in posizione bassa","Kabelzugturm mit Rollen in tiefer Position"],
  ["Parate en el centro de la estación con una manija de cada polea baja, brazos abajo a los costados y palmas mirando al frente.","Stand in the center of the station with a handle from each low pulley, arms down at your sides and palms facing forward.","Fique no centro da estação com uma alça de cada polia baixa, braços para baixo ao lado do corpo e palmas voltadas para frente.","Place-toi au centre de la station avec une poignée de chaque poulie basse, bras le long du corps et paumes vers l’avant.","Mettiti al centro della stazione con una maniglia di ogni cavo basso, braccia in basso lungo i fianchi e palmi rivolti in avanti.","Stell dich in die Mitte des Turms, je einen Griff der unteren Rollen in der Hand, Arme seitlich unten, Handflächen nach vorn."],
  ["Exhalá al subir las manos e inhalá al bajarlas.","Exhale as you raise your hands and inhale as you lower them.","Expire ao subir as mãos e inspire ao abaixá-las.","Expire en montant les mains et inspire en les abaissant.","Espira sollevando le mani e inspira abbassandole.","Atme beim Heben der Hände aus und beim Senken ein."],
  ["Tomá las manijas y dá un paso adelante con postura escalonada y codos levemente flexionados.","Take the handles and step forward into a staggered stance with your elbows slightly bent.","Pegue as alças e dê um passo à frente em postura escalonada, com os cotovelos levemente flexionados.","Prends les poignées et fais un pas en avant en position décalée, coudes légèrement fléchis.","Prendi le maniglie e fai un passo avanti in posizione sfalsata, con i gomiti leggermente piegati.","Nimm die Griffe und geh mit leicht gebeugten Ellbogen einen Schritt nach vorn in die Schrittstellung."],
  ["Llevá las manos hacia arriba y al centro en arco hasta juntarlas a la altura del pecho alto o la barbilla.","Bring your hands up and to the center in an arc until they meet at upper-chest or chin height.","Leve as mãos para cima e para o centro em arco até juntá-las na altura do peito alto ou do queixo.","Amène les mains vers le haut et le centre en arc jusqu’à les rapprocher à hauteur du haut de la poitrine ou du menton.","Porta le mani in alto e al centro ad arco fino a unirle all’altezza della parte alta del petto o del mento.","Führ die Hände in einem Bogen nach oben zur Mitte, bis sie sich auf Höhe der oberen Brust oder des Kinns treffen."],
  ["Bajá despacio por el mismo arco hasta la posición inicial.","Lower slowly along the same arc to the starting position.","Desça devagar pelo mesmo arco até a posição inicial.","Redescends lentement par le même arc jusqu’à la position de départ.","Scendi lentamente lungo lo stesso arco fino alla posizione iniziale.","Senke die Hände langsam auf demselben Bogen in die Ausgangsposition."],
  ["Mantené el tronco quieto sin arquear la espalda.","Keep your trunk still without arching your back.","Mantenha o tronco parado sem arquear as costas.","Garde le tronc immobile sans cambrer le dos.","Mantieni il tronco fermo senza inarcare la schiena.","Halte den Rumpf ruhig, ohne ins Hohlkreuz zu gehen."],
  ["Arquear la zona lumbar para subir las manos.","Arching your lower back to raise your hands.","Arquear a lombar para subir as mãos.","Cambrer le bas du dos pour monter les mains.","Inarcare la zona lombare per sollevare le mani.","Ins Hohlkreuz gehen, um die Hände zu heben."],
  ["Encoger los hombros hacia las orejas.","Shrugging your shoulders up toward your ears.","Encolher os ombros em direção às orelhas.","Hausser les épaules vers les oreilles.","Sollevare le spalle verso le orecchie.","Die Schultern zu den Ohren hochziehen."],
  ["Subir las manos por encima de la cabeza.","Raising your hands above your head.","Subir as mãos acima da cabeça.","Monter les mains au-dessus de la tête.","Portare le mani sopra la testa.","Die Hände über den Kopf heben."],
  ["Pensá en llevar las manos hacia arriba y adentro, como sirviendo una bandeja.","Think about bringing your hands up and in, as if serving a tray.","Pense em levar as mãos para cima e para dentro, como se servisse uma bandeja.","Pense à amener les mains vers le haut et vers l’intérieur, comme pour servir un plateau.","Pensa di portare le mani in alto e verso l’interno, come se servissi un vassoio.","Stell dir vor, du führst die Hände nach oben innen, als würdest du ein Tablett servieren."],
  ["Usá poco peso para aprender el arco.","Use a light weight to learn the arc.","Use pouco peso para aprender o arco.","Utilise une charge légère pour apprendre l’arc.","Usa poco peso per imparare l’arco.","Nimm wenig Gewicht, um den Bogen zu lernen."],
  ["Mantené el abdomen firme para que no se mueva la pelvis.","Keep your abs tight so your pelvis doesn’t move.","Mantenha o abdômen firme para a pelve não se mover.","Garde les abdos gainés pour que le bassin ne bouge pas.","Mantieni l’addome contratto perché il bacino non si muova.","Halte den Bauch fest, damit sich das Becken nicht bewegt."],
  ["Dorsal ancho y bíceps","Latissimus dorsi and biceps","Grande dorsal e bíceps","Grand dorsal et biceps","Gran dorsale e bicipiti","Breiter Rückenmuskel und Bizeps"],
  ["Braquial, romboides, trapecio inferior y core","Brachialis, rhomboids, lower trapezius and core","Braquial, romboides, trapézio inferior e core","Brachial, rhomboïdes, trapèze inférieur et sangle abdominale","Brachiale, romboidi, trapezio inferiore e core","Oberarmmuskel (Brachialis), Rautenmuskeln, unterer Trapezmuskel und Rumpf"],
  ["Barra de dominadas fija","Fixed pull-up bar","Barra fixa","Barre de traction fixe","Sbarra fissa per trazioni","Fest montierte Klimmzugstange"],
  ["Intermedio-avanzado; usar jalón como progresión si todavía no salen","Intermediate–advanced; use lat pulldowns as a progression if you can’t do them yet","Intermediário-avançado; use o puxador como progressão se ainda não conseguir","Intermédiaire-avancé ; utilise le tirage vertical comme progression si tu n’y arrives pas encore","Intermedio-avanzato; usa la lat machine come progressione se non ti riescono ancora","Fortgeschritten; nutze Latziehen als Vorstufe, wenn sie noch nicht klappen"],
  ["Colgate de la barra con agarre supino (palmas hacia vos) al ancho de hombros y brazos extendidos.","Hang from the bar with an underhand grip (palms facing you) at shoulder width and arms extended.","Pendure-se na barra com pegada supinada (palmas voltadas para você) na largura dos ombros e braços estendidos.","Suspends-toi à la barre en prise supination (paumes vers toi), à la largeur des épaules, bras tendus.","Appenditi alla sbarra con presa supina (palmi verso di te) alla larghezza delle spalle e braccia distese.","Häng dich im Untergriff (Handflächen zu dir) schulterbreit an die Stange, Arme gestreckt."],
  ["Tomá la barra con las palmas hacia vos y colgate con el cuerpo quieto y el abdomen firme.","Grab the bar with your palms facing you and hang with your body still and abs tight.","Segure a barra com as palmas voltadas para você e pendure-se com o corpo parado e o abdômen firme.","Saisis la barre paumes vers toi et suspends-toi, le corps immobile et les abdos gainés.","Afferra la sbarra con i palmi verso di te e appenditi con il corpo fermo e l’addome contratto.","Greif die Stange mit den Handflächen zu dir und häng dich mit ruhigem Körper und festem Bauch hin."],
  ["Iniciá bajando los hombros y llevá los codos hacia abajo y adelante para subir.","Start by pulling your shoulders down and drive your elbows down and forward to rise.","Comece abaixando os ombros e leve os cotovelos para baixo e para frente para subir.","Commence par abaisser les épaules et tire les coudes vers le bas et l’avant pour monter.","Inizia abbassando le spalle e porta i gomiti in basso e in avanti per salire.","Beginne damit, die Schultern nach unten zu ziehen, und führ die Ellbogen nach unten vorn, um hochzukommen."],
  ["Subí hasta que la barbilla pase la barra, sin balancearte.","Rise until your chin clears the bar, without swinging.","Suba até o queixo passar a barra, sem balançar.","Monte jusqu’à ce que le menton passe la barre, sans te balancer.","Sali finché il mento supera la sbarra, senza dondolare.","Zieh dich hoch, bis das Kinn über der Stange ist, ohne zu schwingen."],
  ["Bajá con control hasta extender casi por completo los brazos.","Lower with control until your arms are almost fully extended.","Desça com controle até estender quase totalmente os braços.","Redescends en contrôle jusqu’à tendre presque complètement les bras.","Scendi con controllo fino a distendere quasi del tutto le braccia.","Senk dich kontrolliert ab, bis die Arme fast ganz gestreckt sind."],
  ["Balancear las piernas para tomar impulso.","Swinging your legs to gain momentum.","Balançar as pernas para ganhar impulso.","Balancer les jambes pour prendre de l’élan.","Far oscillare le gambe per prendere slancio.","Mit den Beinen schwingen, um Schwung zu holen."],
  ["Hacer medias repeticiones sin bajar.","Doing half reps without going all the way down.","Fazer meias repetições sem descer.","Faire des demi-répétitions sans redescendre complètement.","Fare mezze ripetizioni senza scendere.","Halbe Wiederholungen machen, ohne ganz runterzugehen."],
  ["Estirar el cuello para que la barbilla pase la barra.","Craning your neck to get your chin over the bar.","Esticar o pescoço para o queixo passar a barra.","Tendre le cou pour que le menton passe la barre.","Allungare il collo per far passare il mento sopra la sbarra.","Den Hals strecken, damit das Kinn über die Stange kommt."],
  ["La bajada lenta también entrena fuerza; si no llegás arriba, practicá solo esa fase.","The slow descent also builds strength; if you can’t get to the top, practice just that phase.","A descida lenta também treina força; se não chegar em cima, pratique só essa fase.","La descente lente développe aussi la force ; si tu n’arrives pas en haut, travaille uniquement cette phase.","Anche la discesa lenta allena la forza; se non arrivi in alto, pratica solo quella fase.","Das langsame Ablassen trainiert ebenfalls Kraft; wenn du nicht hochkommst, übe nur diese Phase."],
  ["Mantené las piernas juntas o cruzadas para evitar balanceos.","Keep your legs together or crossed to avoid swinging.","Mantenha as pernas juntas ou cruzadas para evitar balanços.","Garde les jambes serrées ou croisées pour éviter de te balancer.","Tieni le gambe unite o incrociate per evitare oscillazioni.","Halte die Beine geschlossen oder gekreuzt, um Schwingen zu vermeiden."],
  ["Asegurá la barra antes de colgarte.","Make sure the bar is secure before hanging from it.","Verifique se a barra está firme antes de se pendurar.","Vérifie que la barre est bien fixée avant de t’y suspendre.","Assicurati che la sbarra sia ben fissata prima di appenderti.","Prüfe, ob die Stange sicher befestigt ist, bevor du dich dranhängst."],
  ["Dorsal ancho","Latissimus dorsi","Grande dorsal","Grand dorsal","Gran dorsale","Breiter Rückenmuskel"],
  ["Bíceps, braquial, romboides, trapecio inferior y core","Biceps, brachialis, rhomboids, lower trapezius and core","Bíceps, braquial, romboides, trapézio inferior e core","Biceps, brachial, rhomboïdes, trapèze inférieur et sangle abdominale","Bicipiti, brachiale, romboidi, trapezio inferiore e core","Bizeps, Oberarmmuskel (Brachialis), Rautenmuskeln, unterer Trapezmuskel und Rumpf"],
  ["Colgate de la barra con agarre prono (palmas hacia adelante) algo más ancho que los hombros y brazos extendidos.","Hang from the bar with an overhand grip (palms facing forward) slightly wider than your shoulders and arms extended.","Pendure-se na barra com pegada pronada (palmas para frente) um pouco mais larga que os ombros e braços estendidos.","Suspends-toi à la barre en prise pronation (paumes vers l’avant), un peu plus large que les épaules, bras tendus.","Appenditi alla sbarra con presa prona (palmi in avanti) poco più larga delle spalle e braccia distese.","Häng dich im Obergriff (Handflächen nach vorn) etwas breiter als schulterbreit an die Stange, Arme gestreckt."],
  ["Tomá la barra con las palmas hacia adelante y colgate con el cuerpo quieto.","Grab the bar with your palms facing forward and hang with your body still.","Segure a barra com as palmas para frente e pendure-se com o corpo parado.","Saisis la barre paumes vers l’avant et suspends-toi, le corps immobile.","Afferra la sbarra con i palmi in avanti e appenditi con il corpo fermo.","Greif die Stange mit den Handflächen nach vorn und häng dich mit ruhigem Körper hin."],
  ["Bajá los hombros y tirá de los codos hacia abajo y hacia los costados para subir.","Pull your shoulders down and drive your elbows down and out to the sides to rise.","Abaixe os ombros e puxe os cotovelos para baixo e para os lados para subir.","Abaisse les épaules et tire les coudes vers le bas et sur les côtés pour monter.","Abbassa le spalle e tira i gomiti in basso e verso i lati per salire.","Zieh die Schultern nach unten und die Ellbogen nach unten zur Seite, um hochzukommen."],
  ["Subí hasta que la barbilla pase la barra, con el pecho orientado hacia ella.","Rise until your chin clears the bar, with your chest facing it.","Suba até o queixo passar a barra, com o peito voltado para ela.","Monte jusqu’à ce que le menton passe la barre, la poitrine tournée vers elle.","Sali finché il mento supera la sbarra, con il petto rivolto verso di essa.","Zieh dich hoch, bis das Kinn über der Stange ist, die Brust zur Stange gerichtet."],
  ["Patear o balancearse para completar la repetición.","Kicking or swinging to finish the rep.","Chutar ou balançar para completar a repetição.","Donner des coups de pied ou se balancer pour finir la répétition.","Scalciare o dondolarsi per completare la ripetizione.","Strampeln oder schwingen, um die Wiederholung zu schaffen."],
  ["Encoger los hombros hacia las orejas en la parte baja.","Shrugging your shoulders toward your ears at the bottom.","Encolher os ombros em direção às orelhas na parte baixa.","Hausser les épaules vers les oreilles en bas.","Sollevare le spalle verso le orecchie nella parte bassa.","Unten die Schultern zu den Ohren hochziehen."],
  ["Soltarse de golpe en la bajada.","Dropping abruptly on the way down.","Se soltar de uma vez na descida.","Se laisser tomber d’un coup à la descente.","Lasciarsi cadere di colpo in discesa.","Sich beim Ablassen fallen lassen."],
  ["Si todavía no hacés repeticiones completas, trabajá jalón al pecho o bajadas lentas.","If you can’t do full reps yet, work on lat pulldowns or slow negatives.","Se ainda não faz repetições completas, trabalhe puxador frontal ou descidas lentas.","Si tu ne fais pas encore de répétitions complètes, travaille le tirage vertical ou les descentes lentes.","Se non fai ancora ripetizioni complete, lavora con la lat machine o con discese lente.","Wenn du noch keine vollen Wiederholungen schaffst, trainiere Latziehen oder langsame Negative."],
  ["Pensá en llevar los codos hacia los bolsillos.","Think about driving your elbows toward your pockets.","Pense em levar os cotovelos em direção aos bolsos.","Pense à amener les coudes vers tes poches.","Pensa di portare i gomiti verso le tasche.","Stell dir vor, du ziehst die Ellbogen in Richtung Hosentaschen."],
  ["Mantené el abdomen firme para que el cuerpo no se arquee.","Keep your abs tight so your body doesn’t arch.","Mantenha o abdômen firme para o corpo não arquear.","Garde les abdos gainés pour que ton corps ne se cambre pas.","Mantieni l’addome contratto perché il corpo non si inarchi.","Halte den Bauch fest, damit dein Körper nicht ins Hohlkreuz fällt."],
  ["Dorsal ancho, romboides y trapecio medio","Latissimus dorsi, rhomboids and middle trapezius","Grande dorsal, romboides e trapézio médio","Grand dorsal, rhomboïdes et trapèze moyen","Gran dorsale, romboidi e trapezio medio","Breiter Rückenmuskel, Rautenmuskeln und mittlerer Trapezmuskel"],
  ["Deltoides posterior, bíceps y braquial","Rear deltoid, biceps and brachialis","Deltoide posterior, bíceps e braquial","Deltoïde postérieur, biceps et brachial","Deltoide posteriore, bicipiti e brachiale","Hinterer Deltamuskel, Bizeps und Oberarmmuskel (Brachialis)"],
  ["Banco inclinado (unos 30–45 grados) y dos mancuernas","Incline bench (about 30–45 degrees) and two dumbbells","Banco inclinado (cerca de 30–45 graus) e dois halteres","Banc incliné (environ 30–45 degrés) et deux haltères","Panca inclinata (circa 30–45 gradi) e due manubri","Schrägbank (etwa 30–45 Grad) und zwei Kurzhanteln"],
  ["Acostate boca abajo en un banco inclinado con el pecho apoyado, pies en el suelo y una mancuerna colgando en cada mano.","Lie face down on an incline bench with your chest supported, feet on the floor and a dumbbell hanging in each hand.","Deite-se de bruços em um banco inclinado com o peito apoiado, pés no chão e um halter pendurado em cada mão.","Allonge-toi sur le ventre sur un banc incliné, poitrine en appui, pieds au sol et un haltère pendant dans chaque main.","Sdraiati a pancia in giù su una panca inclinata con il petto appoggiato, piedi a terra e un manubrio pendente in ogni mano.","Leg dich bäuchlings auf eine Schrägbank, Brust aufgelegt, Füße am Boden, in jeder Hand hängt eine Kurzhantel."],
  ["Exhalá al remar e inhalá al bajar.","Exhale as you row and inhale as you lower.","Expire ao remar e inspire ao descer.","Expire en tirant et inspire en redescendant.","Espira tirando e inspira scendendo.","Atme beim Rudern aus und beim Absenken ein."],
  ["Apoyá el pecho en el respaldo y dejá colgar los brazos extendidos con las mancuernas.","Rest your chest on the backrest and let your arms hang straight with the dumbbells.","Apoie o peito no encosto e deixe os braços estendidos pendurados com os halteres.","Pose la poitrine sur le dossier et laisse pendre les bras tendus avec les haltères.","Appoggia il petto allo schienale e lascia pendere le braccia distese con i manubri.","Leg die Brust auf die Lehne und lass die gestreckten Arme mit den Kurzhanteln hängen."],
  ["Llevá los codos hacia atrás y arriba, acercando las mancuernas a los costados del abdomen.","Drive your elbows back and up, bringing the dumbbells to the sides of your abdomen.","Leve os cotovelos para trás e para cima, aproximando os halteres das laterais do abdômen.","Tire les coudes vers l’arrière et le haut, en amenant les haltères sur les côtés de l’abdomen.","Porta i gomiti indietro e in alto, avvicinando i manubri ai lati dell’addome.","Zieh die Ellbogen nach hinten oben und bring die Kurzhanteln seitlich an den Bauch."],
  ["Pausá un instante juntando las escápulas.","Pause for a moment, squeezing your shoulder blades together.","Pause um instante juntando as escápulas.","Marque une courte pause en serrant les omoplates.","Fai una breve pausa stringendo le scapole.","Halte kurz und zieh die Schulterblätter zusammen."],
  ["Bajá las mancuernas con control hasta extender los brazos.","Lower the dumbbells with control until your arms are extended.","Abaixe os halteres com controle até estender os braços.","Redescends les haltères en contrôle jusqu’à tendre les bras.","Abbassa i manubri con controllo fino a distendere le braccia.","Senke die Kurzhanteln kontrolliert, bis die Arme gestreckt sind."],
  ["Despegar el pecho del banco para impulsarse.","Lifting your chest off the bench to generate momentum.","Descolar o peito do banco para pegar impulso.","Décoller la poitrine du banc pour prendre de l’élan.","Staccare il petto dalla panca per darsi slancio.","Die Brust von der Bank lösen, um Schwung zu holen."],
  ["Tirar solo con los brazos sin mover las escápulas.","Pulling only with your arms without moving your shoulder blades.","Puxar só com os braços sem mover as escápulas.","Tirer uniquement avec les bras sans bouger les omoplates.","Tirare solo con le braccia senza muovere le scapole.","Nur mit den Armen ziehen, ohne die Schulterblätter zu bewegen."],
  ["El apoyo del pecho saca carga de la zona lumbar y evita el balanceo.","Chest support takes load off your lower back and prevents swinging.","O apoio do peito tira carga da lombar e evita o balanço.","L’appui de la poitrine soulage le bas du dos et évite l’élan.","L’appoggio del petto toglie carico alla zona lombare ed evita lo slancio.","Die Brustauflage entlastet den unteren Rücken und verhindert Schwungholen."],
  ["Mantené el cuello neutro mirando hacia el suelo.","Keep your neck neutral, looking at the floor.","Mantenha o pescoço neutro olhando para o chão.","Garde la nuque neutre en regardant le sol.","Mantieni il collo neutro guardando verso il pavimento.","Halte den Nacken neutral und schau zum Boden."],
  ["Probá agarre neutro si te resulta más cómodo para los hombros.","Try a neutral grip if it feels more comfortable for your shoulders.","Teste a pegada neutra se for mais confortável para os ombros.","Essaie la prise neutre si elle est plus confortable pour tes épaules.","Prova la presa neutra se è più comoda per le spalle.","Probier den neutralen Griff, wenn er für deine Schultern angenehmer ist."],
  ["Máquina de remo con almohadilla de pecho","Row machine with chest pad","Máquina de remada com apoio de peito","Machine de rowing avec appui pectoral","Macchina per rematore con appoggio per il petto","Rudermaschine mit Brustpolster"],
  ["Sentate con el pecho apoyado en la almohadilla y las manijas al alcance con los brazos extendidos.","Sit with your chest against the pad and the handles within reach with your arms extended.","Sente-se com o peito apoiado na almofada e as alças ao alcance com os braços estendidos.","Assieds-toi la poitrine contre le coussin, les poignées à portée bras tendus.","Siediti con il petto appoggiato al cuscinetto e le maniglie a portata con le braccia distese.","Setz dich mit der Brust ans Polster, die Griffe mit gestreckten Armen in Reichweite."],
  ["Exhalá al tirar e inhalá al volver.","Exhale as you pull and inhale as you return.","Expire ao puxar e inspire ao voltar.","Expire en tirant et inspire en revenant.","Espira tirando e inspira tornando.","Atme beim Ziehen aus und beim Zurückführen ein."],
  ["Ajustá el asiento para que las manijas queden a la altura del pecho y apoyá el pecho en la almohadilla.","Adjust the seat so the handles are at chest height and rest your chest on the pad.","Ajuste o assento para as alças ficarem na altura do peito e apoie o peito na almofada.","Règle le siège pour que les poignées soient à hauteur de poitrine et appuie la poitrine sur le coussin.","Regola il sedile perché le maniglie siano all’altezza del petto e appoggia il petto al cuscinetto.","Stell den Sitz so ein, dass die Griffe auf Brusthöhe sind, und leg die Brust ans Polster."],
  ["Tirá de las manijas hacia el torso llevando los codos atrás y juntando las escápulas.","Pull the handles toward your torso, driving your elbows back and squeezing your shoulder blades together.","Puxe as alças em direção ao tronco levando os cotovelos para trás e juntando as escápulas.","Tire les poignées vers le buste en amenant les coudes vers l’arrière et en serrant les omoplates.","Tira le maniglie verso il busto portando i gomiti indietro e stringendo le scapole.","Zieh die Griffe zum Oberkörper, Ellbogen nach hinten, Schulterblätter zusammen."],
  ["Pausá un instante sin despegar el pecho del apoyo.","Pause for a moment without lifting your chest off the pad.","Pause um instante sem descolar o peito do apoio.","Marque une courte pause sans décoller la poitrine de l’appui.","Fai una breve pausa senza staccare il petto dall’appoggio.","Halte kurz, ohne die Brust vom Polster zu lösen."],
  ["Volvé despacio hasta extender los brazos sin dejar caer las placas.","Return slowly until your arms are extended, without letting the plates drop.","Volte devagar até estender os braços sem deixar as placas caírem.","Reviens lentement jusqu’à tendre les bras sans laisser retomber les plaques.","Torna lentamente fino a distendere le braccia senza lasciar cadere le piastre.","Führ langsam zurück, bis die Arme gestreckt sind, ohne die Platten fallen zu lassen."],
  ["Separar el pecho de la almohadilla para ayudarte con el tronco.","Moving your chest away from the pad to help with your torso.","Afastar o peito da almofada para ajudar com o tronco.","Écarter la poitrine du coussin pour t’aider avec le buste.","Staccare il petto dal cuscinetto per aiutarti con il busto.","Die Brust vom Polster lösen, um mit dem Oberkörper nachzuhelfen."],
  ["Tirar con las muñecas dobladas.","Pulling with bent wrists.","Puxar com os punhos dobrados.","Tirer avec les poignets pliés.","Tirare con i polsi piegati.","Mit abgeknickten Handgelenken ziehen."],
  ["Dejar que la carga vuelva de golpe.","Letting the load slam back.","Deixar a carga voltar de uma vez.","Laisser la charge revenir d’un coup.","Lasciare che il carico torni di colpo.","Das Gewicht unkontrolliert zurückschnellen lassen."],
  ["El apoyo del pecho permite concentrarte en la espalda sin cargar la zona lumbar.","Chest support lets you focus on your back without loading your lower back.","O apoio do peito permite se concentrar nas costas sem sobrecarregar a lombar.","L’appui pectoral te permet de te concentrer sur le dos sans charger le bas du dos.","L’appoggio del petto ti permette di concentrarti sulla schiena senza caricare la zona lombare.","Die Brustauflage lässt dich auf den Rücken konzentrieren, ohne den unteren Rücken zu belasten."],
  ["Probá agarre neutro o prono según la máquina y tu comodidad.","Try a neutral or overhand grip depending on the machine and your comfort.","Teste pegada neutra ou pronada conforme a máquina e o seu conforto.","Essaie la prise neutre ou en pronation selon la machine et ton confort.","Prova la presa neutra o prona a seconda della macchina e della tua comodità.","Probier je nach Maschine und Komfort neutralen Griff oder Obergriff."],
  ["Mantené los hombros lejos de las orejas.","Keep your shoulders away from your ears.","Mantenha os ombros longe das orelhas.","Garde les épaules loin des oreilles.","Mantieni le spalle lontane dalle orecchie.","Halte die Schultern weg von den Ohren."],
  ["Bíceps, deltoides posterior y oblicuos como estabilizadores","Biceps, rear deltoid and obliques as stabilizers","Bíceps, deltoide posterior e oblíquos como estabilizadores","Biceps, deltoïde postérieur et obliques comme stabilisateurs","Bicipiti, deltoide posteriore e obliqui come stabilizzatori","Bizeps, hinterer Deltamuskel und schräge Bauchmuskeln als Stabilisatoren"],
  ["Polea baja o media con manija simple","Low or mid cable with a single handle","Polia baixa ou média com alça simples","Poulie basse ou médiane avec poignée simple","Cavo basso o medio con maniglia singola","Tiefer oder mittlerer Kabelzug mit Einhandgriff"],
  ["Sentate o parate frente a la polea con la manija en una mano, brazo extendido y tronco erguido.","Sit or stand facing the cable with the handle in one hand, arm extended and torso upright.","Sente-se ou fique em pé de frente para a polia com a alça em uma mão, braço estendido e tronco ereto.","Assieds-toi ou tiens-toi face à la poulie, la poignée dans une main, bras tendu et buste droit.","Siediti o stai in piedi di fronte al cavo con la maniglia in una mano, braccio disteso e busto eretto.","Setz oder stell dich vor den Kabelzug, den Griff in einer Hand, Arm gestreckt, Oberkörper aufrecht."],
  ["Exhalá al tirar e inhalá al extender el brazo.","Exhale as you pull and inhale as you extend your arm.","Expire ao puxar e inspire ao estender o braço.","Expire en tirant et inspire en tendant le bras.","Espira tirando e inspira distendendo il braccio.","Atme beim Ziehen aus und beim Strecken des Arms ein."],
  ["45–75 segundos entre lados","45–75 seconds between sides","45–75 segundos entre lados","45–75 secondes entre les côtés","45–75 secondi tra i lati","45–75 Sekunden zwischen den Seiten"],
  ["Tomá la manija con una mano y alejate hasta que el cable quede tenso, con el tronco estable.","Take the handle in one hand and step back until the cable is taut, keeping your trunk stable.","Pegue a alça com uma mão e afaste-se até o cabo ficar tenso, com o tronco estável.","Prends la poignée d’une main et recule jusqu’à ce que le câble soit tendu, le tronc stable.","Prendi la maniglia con una mano e allontanati finché il cavo è teso, con il tronco stabile.","Nimm den Griff in eine Hand und geh zurück, bis das Seil gespannt ist, Rumpf stabil."],
  ["Tirá de la manija hacia el costado del abdomen llevando el codo atrás, cerca del cuerpo.","Pull the handle toward the side of your abdomen, driving your elbow back close to your body.","Puxe a alça em direção à lateral do abdômen levando o cotovelo para trás, perto do corpo.","Tire la poignée vers le côté de l’abdomen en amenant le coude vers l’arrière, près du corps.","Tira la maniglia verso il fianco dell’addome portando il gomito indietro, vicino al corpo.","Zieh den Griff seitlich zum Bauch, der Ellbogen geht nah am Körper nach hinten."],
  ["Pausá un instante sin girar el torso.","Pause for a moment without rotating your torso.","Pause um instante sem girar o tronco.","Marque une courte pause sans faire pivoter le buste.","Fai una breve pausa senza ruotare il busto.","Halte kurz, ohne den Oberkörper zu drehen."],
  ["Volvé con control y completá un lado antes de cambiar al otro.","Return with control and finish one side before switching to the other.","Volte com controle e complete um lado antes de trocar para o outro.","Reviens en contrôle et termine un côté avant de passer à l’autre.","Torna con controllo e completa un lato prima di passare all’altro.","Führ kontrolliert zurück und beende eine Seite, bevor du wechselst."],
  ["Rotar el tronco para ganar recorrido.","Rotating your trunk to gain range.","Girar o tronco para ganhar amplitude.","Faire pivoter le tronc pour gagner de l’amplitude.","Ruotare il tronco per guadagnare ampiezza.","Den Rumpf drehen, um mehr Bewegungsumfang zu bekommen."],
  ["Encoger el hombro del lado que trabaja.","Shrugging the shoulder on the working side.","Encolher o ombro do lado que trabalha.","Hausser l’épaule du côté qui travaille.","Sollevare la spalla del lato che lavora.","Die Schulter der arbeitenden Seite hochziehen."],
  ["Inclinarse hacia atrás para mover más peso.","Leaning back to move more weight.","Inclinar-se para trás para mover mais peso.","Se pencher en arrière pour déplacer plus de poids.","Inclinarsi indietro per spostare più peso.","Sich nach hinten lehnen, um mehr Gewicht zu bewegen."],
  ["Trabajar un brazo por vez ayuda a detectar diferencias entre lados.","Working one arm at a time helps you spot differences between sides.","Trabalhar um braço por vez ajuda a detectar diferenças entre os lados.","Travailler un bras à la fois aide à repérer les différences entre les côtés.","Lavorare un braccio alla volta aiuta a notare le differenze tra i lati.","Einarmiges Training hilft dir, Unterschiede zwischen den Seiten zu erkennen."],
  ["Al extender, dejá que el omóplato se adelante apenas sin girar el cuerpo.","As you extend, let your shoulder blade move forward slightly without rotating your body.","Ao estender, deixe a escápula avançar levemente sem girar o corpo.","En tendant le bras, laisse l’omoplate avancer légèrement sans faire pivoter le corps.","Quando distendi, lascia che la scapola avanzi appena senza ruotare il corpo.","Lass beim Strecken das Schulterblatt leicht nach vorn gleiten, ohne den Körper zu drehen."],
  ["Hacé el mismo número de repeticiones con cada brazo.","Do the same number of reps with each arm.","Faça o mesmo número de repetições com cada braço.","Fais le même nombre de répétitions avec chaque bras.","Fai lo stesso numero di ripetizioni con ogni braccio.","Mach mit jedem Arm gleich viele Wiederholungen."],
  ["Redondo mayor, porción larga del tríceps y core","Teres major, long head of the triceps and core","Redondo maior, porção longa do tríceps e core","Grand rond, chef long du triceps et sangle abdominale","Grande rotondo, capo lungo del tricipite e core","Großer Rundmuskel, langer Trizepskopf und Rumpf"],
  ["Polea alta con barra recta o cuerda","High cable with straight bar or rope","Polia alta com barra reta ou corda","Poulie haute avec barre droite ou corde","Cavo alto con barra dritta o corda","Oberer Kabelzug mit gerader Stange oder Seil"],
  ["Parate frente a la polea alta con la barra tomada al ancho de hombros, brazos casi extendidos y torso levemente inclinado hacia adelante.","Stand facing the high cable holding the bar at shoulder width, arms almost straight and torso leaning slightly forward.","Fique de frente para a polia alta com a barra segura na largura dos ombros, braços quase estendidos e tronco levemente inclinado para frente.","Tiens-toi face à la poulie haute, barre tenue à la largeur des épaules, bras presque tendus et buste légèrement penché vers l’avant.","Mettiti di fronte al cavo alto con la barra impugnata alla larghezza delle spalle, braccia quasi distese e busto leggermente inclinato in avanti.","Stell dich vor den oberen Kabelzug, die Stange schulterbreit gefasst, Arme fast gestreckt, Oberkörper leicht nach vorn geneigt."],
  ["Exhalá al bajar la barra e inhalá al subirla.","Exhale as you pull the bar down and inhale as you let it rise.","Expire ao abaixar a barra e inspire ao subi-la.","Expire en descendant la barre et inspire en la remontant.","Espira abbassando la barra e inspira risalendo.","Atme beim Runterziehen der Stange aus und beim Hochlassen ein."],
  ["Tomá la barra, retrocedé un paso y adoptá una inclinación leve con rodillas suaves.","Grab the bar, take a step back and lean forward slightly with soft knees.","Pegue a barra, dê um passo para trás e incline-se levemente com os joelhos soltos.","Prends la barre, recule d’un pas et penche-toi légèrement, genoux souples.","Prendi la barra, fai un passo indietro e inclinati leggermente con le ginocchia morbide.","Greif die Stange, geh einen Schritt zurück und neig dich mit weichen Knien leicht nach vorn."],
  ["Con los codos casi rectos, llevá la barra hacia abajo en arco hasta los muslos.","With your elbows almost straight, bring the bar down in an arc to your thighs.","Com os cotovelos quase retos, leve a barra para baixo em arco até as coxas.","Coudes presque tendus, descends la barre en arc jusqu’aux cuisses.","Con i gomiti quasi tesi, porta la barra in basso ad arco fino alle cosce.","Führ die Stange mit fast gestreckten Ellbogen in einem Bogen nach unten bis zu den Oberschenkeln."],
  ["Pausá un instante sintiendo los dorsales.","Pause for a moment, feeling your lats.","Pause um instante sentindo os dorsais.","Marque une courte pause en sentant les dorsaux.","Fai una breve pausa sentendo i dorsali.","Halte kurz und spür den Latissimus."],
  ["Subí la barra con control hasta la altura de los ojos o la cabeza.","Let the bar rise with control to eye or head height.","Suba a barra com controle até a altura dos olhos ou da cabeça.","Remonte la barre en contrôle jusqu’à hauteur des yeux ou de la tête.","Riporta su la barra con controllo fino all’altezza degli occhi o della testa.","Lass die Stange kontrolliert bis auf Augen- oder Kopfhöhe zurück."],
  ["Flexionar los codos y convertirlo en extensión de tríceps.","Bending your elbows and turning it into a triceps extension.","Flexionar os cotovelos e transformar em extensão de tríceps.","Fléchir les coudes et en faire une extension des triceps.","Piegare i gomiti e trasformarlo in un’estensione per i tricipiti.","Die Ellbogen beugen und eine Trizepsübung daraus machen."],
  ["Mover el tronco hacia arriba y abajo para ayudarte.","Moving your torso up and down to help.","Mover o tronco para cima e para baixo para ajudar.","Bouger le buste de haut en bas pour t’aider.","Muovere il busto su e giù per aiutarti.","Den Oberkörper auf und ab bewegen, um nachzuhelfen."],
  ["Encoger los hombros al subir la barra.","Shrugging your shoulders as the bar rises.","Encolher os ombros ao subir a barra.","Hausser les épaules quand la barre remonte.","Sollevare le spalle mentre la barra risale.","Die Schultern hochziehen, wenn die Stange nach oben geht."],
  ["Mantené el mismo ángulo de codo de principio a fin.","Keep the same elbow angle from start to finish.","Mantenha o mesmo ângulo de cotovelo do início ao fim.","Garde le même angle de coude du début à la fin.","Mantieni lo stesso angolo del gomito dall’inizio alla fine.","Halte den Ellbogenwinkel von Anfang bis Ende gleich."],
  ["Pensá en empujar la barra hacia atrás con las palmas.","Think about pushing the bar back with your palms.","Pense em empurrar a barra para trás com as palmas.","Pense à pousser la barre vers l’arrière avec les paumes.","Pensa di spingere la barra indietro con i palmi.","Stell dir vor, du drückst die Stange mit den Handflächen nach hinten."],
  ["Usá una carga moderada; no es un ejercicio de mucho peso.","Use a moderate load; this is not a heavy exercise.","Use uma carga moderada; não é um exercício de muito peso.","Utilise une charge modérée ; ce n’est pas un exercice à lourde charge.","Usa un carico moderato; non è un esercizio da carichi pesanti.","Nimm ein moderates Gewicht; das ist keine Übung für schwere Lasten."],
  ["Erectores espinales","Spinal erectors","Eretores da espinha","Érecteurs du rachis","Erettori spinali","Rückenstrecker"],
  ["Banco de hiperextensiones (45 grados o romano)","Hyperextension bench (45-degree or Roman chair)","Banco de hiperextensão (45 graus ou romano)","Banc à hyperextensions (45 degrés ou chaise romaine)","Panca per iperestensioni (45 gradi o sedia romana)","Hyperextensionsbank (45 Grad oder Römischer Stuhl)"],
  ["Ubicate en el banco con los tobillos trabados, la almohadilla justo debajo de la cadera y el cuerpo en línea recta.","Position yourself on the bench with your ankles locked in, the pad just below your hips and your body in a straight line.","Posicione-se no banco com os tornozelos travados, a almofada logo abaixo do quadril e o corpo em linha reta.","Installe-toi sur le banc, chevilles bloquées, coussin juste sous les hanches et corps aligné.","Posizionati sulla panca con le caviglie bloccate, il cuscinetto appena sotto le anche e il corpo in linea retta.","Leg dich auf die Bank, Knöchel fixiert, Polster direkt unter der Hüfte, Körper in einer geraden Linie."],
  ["Ajustá la almohadilla para que la cadera quede libre y pueda flexionarse; cruzá los brazos sobre el pecho.","Adjust the pad so your hips are free to bend; cross your arms over your chest.","Ajuste a almofada para o quadril ficar livre para flexionar; cruze os braços sobre o peito.","Règle le coussin pour que les hanches puissent fléchir librement ; croise les bras sur la poitrine.","Regola il cuscinetto in modo che le anche siano libere di flettersi; incrocia le braccia sul petto.","Stell das Polster so ein, dass die Hüfte frei beugen kann; verschränk die Arme vor der Brust."],
  ["Bajá el torso flexionando la cadera de forma controlada hasta un estiramiento cómodo.","Lower your torso by bending at the hips in a controlled way to a comfortable stretch.","Abaixe o tronco flexionando o quadril de forma controlada até um alongamento confortável.","Descends le buste en fléchissant les hanches de façon contrôlée jusqu’à un étirement confortable.","Abbassa il busto flettendo le anche in modo controllato fino a un allungamento comodo.","Senk den Oberkörper durch kontrolliertes Beugen der Hüfte bis zu einer angenehmen Dehnung ab."],
  ["Subí hasta que el cuerpo quede en línea recta con las piernas.","Rise until your body is in a straight line with your legs.","Suba até o corpo ficar em linha reta com as pernas.","Remonte jusqu’à ce que le corps soit aligné avec les jambes.","Risali finché il corpo è in linea retta con le gambe.","Komm hoch, bis dein Körper eine gerade Linie mit den Beinen bildet."],
  ["No sigas subiendo más allá de esa línea.","Don’t keep rising past that line.","Não continue subindo além dessa linha.","Ne remonte pas au-delà de cette ligne.","Non salire oltre quella linea.","Geh nicht über diese Linie hinaus."],
  ["Hiperextender la espalda arriba de la línea del cuerpo.","Hyperextending your back above the line of your body.","Hiperestender as costas acima da linha do corpo.","Hyperétendre le dos au-delà de l’alignement du corps.","Iperestendere la schiena oltre la linea del corpo.","Den Rücken über die Körperlinie hinaus überstrecken."],
  ["Subir y bajar con impulso rápido.","Going up and down with quick momentum.","Subir e descer com impulso rápido.","Monter et descendre avec un élan rapide.","Salire e scendere con slancio rapido.","Mit schnellem Schwung auf und ab gehen."],
  ["Colocar la almohadilla tan alta que bloquea la cadera.","Setting the pad so high that it blocks your hips.","Colocar a almofada tão alta que bloqueia o quadril.","Placer le coussin si haut qu’il bloque les hanches.","Mettere il cuscinetto così in alto da bloccare le anche.","Das Polster so hoch einstellen, dass es die Hüfte blockiert."],
  ["El final del movimiento es el cuerpo alineado, no arqueado.","The end of the movement is an aligned body, not an arched one.","O final do movimento é o corpo alinhado, não arqueado.","La fin du mouvement, c’est le corps aligné, pas cambré.","La fine del movimento è il corpo allineato, non inarcato.","Das Ende der Bewegung ist ein gerader Körper, kein Hohlkreuz."],
  ["Agregá carga solo cuando controles bien el rango sin peso.","Add load only once you control the range well without weight.","Adicione carga só quando controlar bem a amplitude sem peso.","N’ajoute une charge qu’une fois l’amplitude bien maîtrisée sans poids.","Aggiungi carico solo quando controlli bene l’ampiezza senza peso.","Nimm erst Gewicht dazu, wenn du den Bewegungsumfang ohne Gewicht gut kontrollierst."],
  ["Mantené el cuello neutro, alineado con la espalda.","Keep your neck neutral, in line with your back.","Mantenha o pescoço neutro, alinhado com as costas.","Garde la nuque neutre, dans l’alignement du dos.","Mantieni il collo neutro, allineato con la schiena.","Halte den Nacken neutral in Verlängerung des Rückens."],
  ["Pectoral mayor clavicular, serrato anterior y trapecio","Clavicular pectoralis major, serratus anterior and trapezius","Peitoral maior clavicular, serrátil anterior e trapézio","Faisceau claviculaire du grand pectoral, dentelé antérieur et trapèze","Grande pettorale clavicolare, dentato anteriore e trapezio","Schlüsselbeinanteil des großen Brustmuskels, vorderer Sägemuskel und Trapezmuskel"],
  ["Dos mancuernas livianas","Two light dumbbells","Dois halteres leves","Deux haltères légers","Due manubri leggeri","Zwei leichte Kurzhanteln"],
  ["Parate con los pies al ancho de cadera y una mancuerna en cada mano delante de los muslos, palmas hacia el cuerpo.","Stand with your feet hip-width apart and a dumbbell in each hand in front of your thighs, palms facing your body.","Fique com os pés na largura do quadril e um halter em cada mão diante das coxas, palmas voltadas para o corpo.","Tiens-toi pieds à la largeur des hanches, un haltère dans chaque main devant les cuisses, paumes vers le corps.","Mettiti in piedi con i piedi alla larghezza delle anche e un manubrio per mano davanti alle cosce, palmi verso il corpo.","Stell dich hüftbreit hin, je eine Kurzhantel vor den Oberschenkeln, Handflächen zum Körper."],
  ["Afirmá el tronco con las rodillas suaves y los hombros bajos.","Brace your trunk with soft knees and your shoulders down.","Firme o tronco com os joelhos soltos e os ombros baixos.","Gaine le tronc, genoux souples et épaules basses.","Stabilizza il tronco con le ginocchia morbide e le spalle basse.","Spann den Rumpf an, Knie weich, Schultern unten."],
  ["Elevá un brazo o ambos hacia adelante con el codo apenas flexionado hasta la altura de los hombros.","Raise one or both arms forward with your elbow slightly bent up to shoulder height.","Eleve um braço ou os dois para frente com o cotovelo levemente flexionado até a altura dos ombros.","Lève un bras ou les deux vers l’avant, coude légèrement fléchi, jusqu’à hauteur des épaules.","Solleva uno o entrambi i bracci in avanti con il gomito leggermente piegato fino all’altezza delle spalle.","Heb einen oder beide Arme mit leicht gebeugtem Ellbogen nach vorn bis auf Schulterhöhe."],
  ["Pausá un instante sin balancear el cuerpo.","Pause for a moment without swinging your body.","Pause um instante sem balançar o corpo.","Marque une courte pause sans balancer le corps.","Fai una breve pausa senza far oscillare il corpo.","Halte kurz, ohne den Körper zu schwingen."],
  ["Bajá despacio hasta los muslos; si alternás, repetí con el otro brazo.","Lower slowly to your thighs; if alternating, repeat with the other arm.","Abaixe devagar até as coxas; se alternar, repita com o outro braço.","Redescends lentement jusqu’aux cuisses ; si tu alternes, recommence avec l’autre bras.","Scendi lentamente fino alle cosce; se alterni, ripeti con l’altro braccio.","Senk langsam bis zu den Oberschenkeln ab; wenn du abwechselst, wiederhol es mit dem anderen Arm."],
  ["Balancear el tronco hacia atrás para subir la mancuerna.","Swinging your torso back to lift the dumbbell.","Balançar o tronco para trás para subir o halter.","Balancer le buste en arrière pour monter l’haltère.","Far oscillare il busto indietro per sollevare il manubrio.","Den Oberkörper nach hinten schwingen, um die Kurzhantel hochzubringen."],
  ["Subir más arriba de los hombros con los hombros encogidos.","Going above shoulder height with shrugged shoulders.","Subir acima dos ombros com os ombros encolhidos.","Monter au-dessus des épaules en les haussant.","Salire oltre le spalle con le spalle sollevate.","Mit hochgezogenen Schultern über Schulterhöhe gehen."],
  ["Dejar caer las mancuernas al bajar.","Letting the dumbbells drop on the way down.","Deixar os halteres caírem ao descer.","Laisser tomber les haltères à la descente.","Lasciar cadere i manubri in discesa.","Die Kurzhanteln beim Absenken fallen lassen."],
  ["Usá poco peso: el deltoides anterior ya trabaja en los press.","Use a light weight: the front deltoid already works in presses.","Use pouco peso: o deltoide anterior já trabalha nos supinos e desenvolvimentos.","Utilise une charge légère : le deltoïde antérieur travaille déjà dans les développés.","Usa poco peso: il deltoide anteriore lavora già nelle distensioni.","Nimm wenig Gewicht: Der vordere Deltamuskel arbeitet schon bei Drückübungen mit."],
  ["Mantené las muñecas neutras, alineadas con los antebrazos.","Keep your wrists neutral, aligned with your forearms.","Mantenha os punhos neutros, alinhados com os antebraços.","Garde les poignets neutres, alignés avec les avant-bras.","Mantieni i polsi neutri, allineati con gli avambracci.","Halte die Handgelenke neutral in einer Linie mit den Unterarmen."],
  ["Si alternás brazos, mantené el tronco quieto sin girar.","If you alternate arms, keep your torso still without rotating.","Se alternar os braços, mantenha o tronco parado sem girar.","Si tu alternes les bras, garde le buste immobile sans pivoter.","Se alterni le braccia, mantieni il busto fermo senza ruotare.","Wenn du die Arme abwechselst, halte den Oberkörper ruhig, ohne zu drehen."],
  ["Deltoides posterior y trapecio medio","Rear deltoid and middle trapezius","Deltoide posterior e trapézio médio","Deltoïde postérieur et trapèze moyen","Deltoide posteriore e trapezio medio","Hinterer Deltamuskel und mittlerer Trapezmuskel"],
  ["Romboides, manguito rotador (rotadores externos) y trapecio inferior","Rhomboids, rotator cuff (external rotators) and lower trapezius","Romboides, manguito rotador (rotadores externos) e trapézio inferior","Rhomboïdes, coiffe des rotateurs (rotateurs externes) et trapèze inférieur","Romboidi, cuffia dei rotatori (extrarotatori) e trapezio inferiore","Rautenmuskeln, Rotatorenmanschette (Außenrotatoren) und unterer Trapezmuskel"],
  ["Polea alta o a la altura de la cara con cuerda","High or face-height cable with rope","Polia alta ou na altura do rosto com corda","Poulie haute ou à hauteur du visage avec corde","Cavo alto o all’altezza del viso con corda","Kabelzug hoch oder auf Gesichtshöhe mit Seil"],
  ["Parate frente a la polea regulada a la altura de la cara, con la cuerda tomada con ambas manos y brazos extendidos.","Stand facing the cable set at face height, holding the rope with both hands and arms extended.","Fique de frente para a polia regulada na altura do rosto, com a corda segura com as duas mãos e os braços estendidos.","Tiens-toi face à la poulie réglée à hauteur du visage, la corde tenue à deux mains, bras tendus.","Mettiti di fronte al cavo regolato all’altezza del viso, con la corda impugnata con entrambe le mani e le braccia distese.","Stell dich vor den Kabelzug auf Gesichtshöhe, das Seil mit beiden Händen gefasst, Arme gestreckt."],
  ["Tomá los extremos de la cuerda con las palmas hacia abajo o enfrentadas y retrocedé hasta tensar el cable.","Grab the ends of the rope with palms down or facing each other and step back until the cable is taut.","Segure as pontas da corda com as palmas para baixo ou voltadas uma para a outra e recue até tensionar o cabo.","Saisis les extrémités de la corde paumes vers le bas ou face à face et recule jusqu’à tendre le câble.","Afferra le estremità della corda con i palmi in basso o rivolti l’uno verso l’altro e arretra fino a tendere il cavo.","Greif die Seilenden mit Handflächen nach unten oder zueinander und geh zurück, bis das Seil gespannt ist."],
  ["Tirá de la cuerda hacia la cara separando las manos, con los codos altos y abiertos.","Pull the rope toward your face while separating your hands, with your elbows high and wide.","Puxe a corda em direção ao rosto separando as mãos, com os cotovelos altos e abertos.","Tire la corde vers le visage en écartant les mains, coudes hauts et ouverts.","Tira la corda verso il viso separando le mani, con i gomiti alti e aperti.","Zieh das Seil zum Gesicht und zieh dabei die Hände auseinander, Ellbogen hoch und weit."],
  ["Terminá con las manos a los costados de la cabeza y los nudillos apuntando hacia atrás.","Finish with your hands beside your head and your knuckles pointing back.","Termine com as mãos ao lado da cabeça e os nós dos dedos apontando para trás.","Termine les mains de chaque côté de la tête, jointures orientées vers l’arrière.","Termina con le mani ai lati della testa e le nocche rivolte all’indietro.","Beende die Bewegung mit den Händen neben dem Kopf, die Fingerknöchel zeigen nach hinten."],
  ["Volvé con control hasta extender los brazos.","Return with control until your arms are extended.","Volte com controle até estender os braços.","Reviens en contrôle jusqu’à tendre les bras.","Torna con controllo fino a distendere le braccia.","Führ kontrolliert zurück, bis die Arme gestreckt sind."],
  ["Tirar con los codos bajos, como en un remo.","Pulling with low elbows, as in a row.","Puxar com os cotovelos baixos, como em uma remada.","Tirer avec les coudes bas, comme pour un rowing.","Tirare con i gomiti bassi, come in un rematore.","Mit tiefen Ellbogen ziehen wie beim Rudern."],
  ["Inclinarse hacia atrás para mover más carga.","Leaning back to move more load.","Inclinar-se para trás para mover mais carga.","Se pencher en arrière pour déplacer plus de charge.","Inclinarsi indietro per spostare più carico.","Sich nach hinten lehnen, um mehr Gewicht zu bewegen."],
  ["Pensá en separar la cuerda en dos al llegar a la cara.","Think about pulling the rope apart as it reaches your face.","Pense em separar a corda em duas ao chegar ao rosto.","Pense à séparer la corde en deux en arrivant au visage.","Pensa di dividere la corda in due quando arriva al viso.","Stell dir vor, du ziehst das Seil auf Gesichtshöhe auseinander."],
  ["Una carga liviana con pausa al final rinde más que mucho peso.","A light load with a pause at the end works better than heavy weight.","Uma carga leve com pausa no final rende mais que muito peso.","Une charge légère avec une pause à la fin est plus efficace qu’une lourde charge.","Un carico leggero con pausa finale rende più di tanto peso.","Ein leichtes Gewicht mit Pause am Ende bringt mehr als viel Gewicht."],
  ["Mantené las costillas abajo y el abdomen firme.","Keep your ribs down and your abs tight.","Mantenha as costelas para baixo e o abdômen firme.","Garde les côtes basses et les abdos gainés.","Tieni le costole basse e l’addome contratto.","Halte die Rippen unten und den Bauch fest."],
  ["Deltoides posterior","Rear deltoid","Deltoide posterior","Deltoïde postérieur","Deltoide posteriore","Hinterer Deltamuskel"],
  ["Romboides y trapecio medio","Rhomboids and middle trapezius","Romboides e trapézio médio","Rhomboïdes et trapèze moyen","Romboidi e trapezio medio","Rautenmuskeln und mittlerer Trapezmuskel"],
  ["Máquina de aperturas con función inversa (pec deck inverso)","Fly machine with reverse function (reverse pec deck)","Máquina de voador com função inversa (voador invertido)","Machine à écartés avec fonction inversée (pec deck inversé)","Macchina per aperture con funzione inversa (pectoral machine inversa)","Butterflymaschine mit Reverse-Funktion (Reverse Butterfly)"],
  ["Sentate mirando hacia el respaldo, con el pecho apoyado y las manijas tomadas al frente con los brazos extendidos a la altura de los hombros.","Sit facing the backrest with your chest supported and the handles held in front with your arms extended at shoulder height.","Sente-se de frente para o encosto, com o peito apoiado e as alças seguras à frente com os braços estendidos na altura dos ombros.","Assieds-toi face au dossier, poitrine en appui, poignées tenues devant toi, bras tendus à hauteur des épaules.","Siediti rivolto verso lo schienale, con il petto appoggiato e le maniglie impugnate davanti con le braccia distese all’altezza delle spalle.","Setz dich mit dem Gesicht zur Lehne, Brust aufgelegt, die Griffe vorn mit gestreckten Armen auf Schulterhöhe gefasst."],
  ["Exhalá al abrir e inhalá al volver.","Exhale as you open and inhale as you return.","Expire ao abrir e inspire ao voltar.","Expire en ouvrant et inspire en revenant.","Espira aprendo e inspira tornando.","Atme beim Öffnen aus und beim Zurückführen ein."],
  ["Ajustá el asiento para que las manijas queden a la altura de los hombros y los brazos en las manijas traseras.","Adjust the seat so the handles are at shoulder height and your arms are on the rear handles.","Ajuste o assento para as alças ficarem na altura dos ombros e os braços nas alças traseiras.","Règle le siège pour que les poignées soient à hauteur des épaules et les bras sur les poignées arrière.","Regola il sedile perché le maniglie siano all’altezza delle spalle e le braccia sulle maniglie posteriori.","Stell den Sitz so ein, dass die Griffe auf Schulterhöhe sind und die Arme an den hinteren Griffen liegen."],
  ["Abrí los brazos hacia atrás en arco, con los codos apenas flexionados.","Open your arms back in an arc, with your elbows slightly bent.","Abra os braços para trás em arco, com os cotovelos levemente flexionados.","Ouvre les bras vers l’arrière en arc, coudes légèrement fléchis.","Apri le braccia indietro ad arco, con i gomiti leggermente piegati.","Öffne die Arme in einem Bogen nach hinten, Ellbogen leicht gebeugt."],
  ["Pausá cuando los brazos queden alineados con el cuerpo.","Pause when your arms are in line with your body.","Pause quando os braços ficarem alinhados com o corpo.","Marque une pause quand les bras sont alignés avec le corps.","Fai una pausa quando le braccia sono allineate con il corpo.","Halte kurz, wenn die Arme in einer Linie mit dem Körper sind."],
  ["Volvé despacio al frente sin dejar que las placas choquen.","Return slowly to the front without letting the plates clash.","Volte devagar à frente sem deixar as placas baterem.","Reviens lentement vers l’avant sans laisser les plaques s’entrechoquer.","Torna lentamente in avanti senza far sbattere le piastre.","Führ langsam nach vorn zurück, ohne die Platten aufschlagen zu lassen."],
  ["Llevar los brazos tan atrás que los hombros se adelantan.","Taking your arms so far back that your shoulders roll forward.","Levar os braços tão para trás que os ombros avançam.","Amener les bras si loin en arrière que les épaules partent vers l’avant.","Portare le braccia così indietro che le spalle vanno in avanti.","Die Arme so weit nach hinten führen, dass die Schultern nach vorn kippen."],
  ["Despegar el pecho del respaldo.","Lifting your chest off the backrest.","Descolar o peito do encosto.","Décoller la poitrine du dossier.","Staccare il petto dallo schienale.","Die Brust von der Lehne lösen."],
  ["Encoger los hombros durante la apertura.","Shrugging your shoulders during the opening.","Encolher os ombros durante a abertura.","Hausser les épaules pendant l’ouverture.","Sollevare le spalle durante l’apertura.","Beim Öffnen die Schultern hochziehen."],
  ["Pensá en empujar las manijas hacia los costados, no hacia atrás.","Think about pushing the handles out to the sides, not back.","Pense em empurrar as alças para os lados, não para trás.","Pense à pousser les poignées sur les côtés, pas vers l’arrière.","Pensa di spingere le maniglie verso i lati, non indietro.","Denk daran, die Griffe zur Seite zu drücken, nicht nach hinten."],
  ["Usá un peso que permita una pausa breve al final.","Use a weight that allows a brief pause at the end.","Use um peso que permita uma pausa breve no final.","Utilise une charge qui permet une courte pause à la fin.","Usa un peso che permetta una breve pausa alla fine.","Nimm ein Gewicht, das am Ende eine kurze Pause erlaubt."],
  ["Mantené el cuello relajado.","Keep your neck relaxed.","Mantenha o pescoço relaxado.","Garde la nuque détendue.","Mantieni il collo rilassato.","Halte den Nacken locker."],
  ["Romboides, trapecio medio y erectores como estabilizadores","Rhomboids, middle trapezius and spinal erectors as stabilizers","Romboides, trapézio médio e eretores como estabilizadores","Rhomboïdes, trapèze moyen et érecteurs comme stabilisateurs","Romboidi, trapezio medio ed erettori come stabilizzatori","Rautenmuskeln, mittlerer Trapezmuskel und Rückenstrecker als Stabilisatoren"],
  ["Dos mancuernas livianas; opcionalmente banco para apoyar el pecho","Two light dumbbells; optionally a bench to support your chest","Dois halteres leves; opcionalmente um banco para apoiar o peito","Deux haltères légers ; éventuellement un banc pour appuyer la poitrine","Due manubri leggeri; facoltativamente una panca per appoggiare il petto","Zwei leichte Kurzhanteln; optional eine Bank als Brustauflage"],
  ["Inclinate hacia adelante desde la cadera con la espalda neutra, rodillas suaves y una mancuerna en cada mano colgando bajo los hombros.","Hinge forward from the hips with a neutral back, soft knees and a dumbbell in each hand hanging below your shoulders.","Incline-se para frente a partir do quadril com as costas neutras, joelhos soltos e um halter em cada mão pendurado sob os ombros.","Penche-toi vers l’avant depuis les hanches, dos neutre, genoux souples, un haltère dans chaque main pendant sous les épaules.","Inclinati in avanti dalle anche con la schiena neutra, ginocchia morbide e un manubrio per mano pendente sotto le spalle.","Beug dich aus der Hüfte nach vorn, Rücken neutral, Knie weich, je eine Kurzhantel hängt unter den Schultern."],
  ["Exhalá al abrir los brazos e inhalá al bajarlos.","Exhale as you open your arms and inhale as you lower them.","Expire ao abrir os braços e inspire ao abaixá-los.","Expire en ouvrant les bras et inspire en les abaissant.","Espira aprendo le braccia e inspira abbassandole.","Atme beim Öffnen der Arme aus und beim Senken ein."],
  ["Hacé una bisagra de cadera hasta que el torso quede inclinado y estable, o apoyá el pecho en un banco inclinado.","Hinge at the hips until your torso is tilted and stable, or rest your chest on an incline bench.","Faça uma dobradiça de quadril até o tronco ficar inclinado e estável, ou apoie o peito em um banco inclinado.","Fais une charnière de hanche jusqu’à ce que le buste soit incliné et stable, ou appuie la poitrine sur un banc incliné.","Fai una cerniera d’anca finché il busto è inclinato e stabile, oppure appoggia il petto su una panca inclinata.","Beug dich aus der Hüfte, bis der Oberkörper stabil geneigt ist, oder leg die Brust auf eine Schrägbank."],
  ["Abrí los brazos hacia los costados con los codos apenas flexionados, hasta la altura de los hombros.","Open your arms out to the sides with your elbows slightly bent, up to shoulder height.","Abra os braços para os lados com os cotovelos levemente flexionados, até a altura dos ombros.","Ouvre les bras sur les côtés, coudes légèrement fléchis, jusqu’à hauteur des épaules.","Apri le braccia lateralmente con i gomiti leggermente piegati, fino all’altezza delle spalle.","Öffne die Arme mit leicht gebeugten Ellbogen zur Seite bis auf Schulterhöhe."],
  ["Pausá un instante sin juntar de más las escápulas.","Pause for a moment without over-squeezing your shoulder blades.","Pause um instante sem juntar demais as escápulas.","Marque une courte pause sans trop serrer les omoplates.","Fai una breve pausa senza stringere troppo le scapole.","Halte kurz, ohne die Schulterblätter zu stark zusammenzuziehen."],
  ["Bajá las mancuernas con control.","Lower the dumbbells with control.","Abaixe os halteres com controle.","Redescends les haltères en contrôle.","Abbassa i manubri con controllo.","Senk die Kurzhanteln kontrolliert ab."],
  ["Levantar el torso en cada repetición para impulsarse.","Lifting your torso on each rep to generate momentum.","Levantar o tronco a cada repetição para pegar impulso.","Redresser le buste à chaque répétition pour prendre de l’élan.","Sollevare il busto a ogni ripetizione per darsi slancio.","Bei jeder Wiederholung den Oberkörper anheben, um Schwung zu holen."],
  ["Redondear la espalda en la inclinación.","Rounding your back in the bent-over position.","Arredondar as costas na inclinação.","Arrondir le dos en position penchée.","Arrotondare la schiena in inclinazione.","Den Rücken in der vorgebeugten Position runden."],
  ["Usar mancuernas demasiado pesadas y tirar con los trapecios.","Using dumbbells that are too heavy and pulling with your traps.","Usar halteres pesados demais e puxar com os trapézios.","Utiliser des haltères trop lourds et tirer avec les trapèzes.","Usare manubri troppo pesanti e tirare con i trapezi.","Zu schwere Kurzhanteln nehmen und mit dem Trapezmuskel ziehen."],
  ["Si la zona lumbar se cansa antes que los hombros, apoyá el pecho en un banco.","If your lower back tires before your shoulders, rest your chest on a bench.","Se a lombar cansar antes dos ombros, apoie o peito em um banco.","Si le bas du dos fatigue avant les épaules, appuie la poitrine sur un banc.","Se la zona lombare si stanca prima delle spalle, appoggia il petto su una panca.","Wenn der untere Rücken vor den Schultern ermüdet, leg die Brust auf eine Bank."],
  ["Llevá las manos hacia afuera, no hacia arriba.","Move your hands outward, not upward.","Leve as mãos para fora, não para cima.","Amène les mains vers l’extérieur, pas vers le haut.","Porta le mani verso l’esterno, non verso l’alto.","Führ die Hände nach außen, nicht nach oben."],
  ["Mantené el cuello alineado mirando al suelo.","Keep your neck aligned, looking at the floor.","Mantenha o pescoço alinhado olhando para o chão.","Garde la nuque alignée en regardant le sol.","Mantieni il collo allineato guardando il pavimento.","Halte den Nacken gerade und schau zum Boden."],
  ["Infraespinoso y redondo menor","Infraspinatus and teres minor","Infraespinal e redondo menor","Sous-épineux et petit rond","Sottospinato e piccolo rotondo","Untergrätenmuskel und kleiner Rundmuskel"],
  ["Deltoides posterior y estabilizadores escapulares","Rear deltoid and scapular stabilizers","Deltoide posterior e estabilizadores escapulares","Deltoïde postérieur et stabilisateurs de l’omoplate","Deltoide posteriore e stabilizzatori scapolari","Hinterer Deltamuskel und Schulterblattstabilisatoren"],
  ["Polea regulada a la altura del codo con manija simple; opcionalmente una toalla enrollada","Cable set at elbow height with a single handle; optionally a rolled towel","Polia regulada na altura do cotovelo com alça simples; opcionalmente uma toalha enrolada","Poulie réglée à hauteur du coude avec poignée simple ; éventuellement une serviette roulée","Cavo regolato all’altezza del gomito con maniglia singola; facoltativamente un asciugamano arrotolato","Kabelzug auf Ellbogenhöhe mit Einhandgriff; optional ein gerolltes Handtuch"],
  ["Parate de costado a la polea con la manija en la mano más alejada, codo a 90 grados pegado al costado y antebrazo cruzando el abdomen.","Stand side-on to the cable with the handle in your far hand, elbow at 90 degrees tucked to your side and forearm across your abdomen.","Fique de lado para a polia com a alça na mão mais afastada, cotovelo a 90 graus colado ao corpo e antebraço cruzando o abdômen.","Tiens-toi de profil par rapport à la poulie, la poignée dans la main la plus éloignée, coude à 90 degrés collé au flanc et avant-bras devant l’abdomen.","Mettiti di lato rispetto al cavo con la maniglia nella mano più lontana, gomito a 90 gradi aderente al fianco e avambraccio davanti all’addome.","Stell dich seitlich zum Kabelzug, den Griff in der entfernten Hand, Ellbogen im 90-Grad-Winkel am Körper, Unterarm quer vor dem Bauch."],
  ["Exhalá al rotar hacia afuera e inhalá al volver.","Exhale as you rotate outward and inhale as you return.","Expire ao girar para fora e inspire ao voltar.","Expire en tournant vers l’extérieur et inspire en revenant.","Espira ruotando verso l’esterno e inspira tornando.","Atme beim Nach-außen-Drehen aus und beim Zurückführen ein."],
  ["30–60 segundos entre lados","30–60 seconds between sides","30–60 segundos entre lados","30–60 secondes entre les côtés","30–60 secondi tra i lati","30–60 Sekunden zwischen den Seiten"],
  ["Colocá una toalla enrollada entre el codo y el costado si te ayuda a mantener la posición.","Place a rolled towel between your elbow and your side if it helps you hold the position.","Coloque uma toalha enrolada entre o cotovelo e o corpo se ajudar a manter a posição.","Place une serviette roulée entre le coude et le flanc si cela t’aide à garder la position.","Metti un asciugamano arrotolato tra gomito e fianco se ti aiuta a mantenere la posizione.","Leg ein gerolltes Handtuch zwischen Ellbogen und Körper, wenn es dir hilft, die Position zu halten."],
  ["Girá el antebrazo hacia afuera, como una puerta que se abre, manteniendo el codo pegado al cuerpo.","Rotate your forearm outward, like a door opening, keeping your elbow against your body.","Gire o antebraço para fora, como uma porta que se abre, mantendo o cotovelo colado ao corpo.","Fais pivoter l’avant-bras vers l’extérieur, comme une porte qui s’ouvre, en gardant le coude collé au corps.","Ruota l’avambraccio verso l’esterno, come una porta che si apre, mantenendo il gomito aderente al corpo.","Dreh den Unterarm nach außen wie eine sich öffnende Tür, der Ellbogen bleibt am Körper."],
  ["Llegá hasta un rango cómodo sin girar el tronco.","Go to a comfortable range without rotating your trunk.","Vá até uma amplitude confortável sem girar o tronco.","Va jusqu’à une amplitude confortable sans faire pivoter le tronc.","Arriva a un’ampiezza comoda senza ruotare il tronco.","Geh bis zu einem angenehmen Bewegungsumfang, ohne den Rumpf zu drehen."],
  ["Volvé despacio y completá un lado antes de cambiar al otro.","Return slowly and finish one side before switching to the other.","Volte devagar e complete um lado antes de trocar para o outro.","Reviens lentement et termine un côté avant de passer à l’autre.","Torna lentamente e completa un lato prima di passare all’altro.","Führ langsam zurück und beende eine Seite, bevor du wechselst."],
  ["Separar el codo del costado.","Moving your elbow away from your side.","Afastar o cotovelo do corpo.","Écarter le coude du flanc.","Staccare il gomito dal fianco.","Den Ellbogen vom Körper lösen."],
  ["Rotar el tronco en lugar del hombro.","Rotating your trunk instead of your shoulder.","Girar o tronco em vez do ombro.","Faire pivoter le tronc au lieu de l’épaule.","Ruotare il tronco invece della spalla.","Den Rumpf statt der Schulter drehen."],
  ["Usar una carga que obliga a dar tirones.","Using a load that forces you to jerk.","Usar uma carga que obriga a dar puxões.","Utiliser une charge qui oblige à donner des à-coups.","Usare un carico che costringe a dare strattoni.","Ein Gewicht nehmen, das dich zum Reißen zwingt."],
  ["Es un ejercicio de control: usá una carga liviana.","It is a control exercise: use a light load.","É um exercício de controle: use carga leve.","C’est un exercice de contrôle : utilise une charge légère.","È un esercizio di controllo: usa un carico leggero.","Es ist eine Kontrollübung: Nimm ein leichtes Gewicht."],
  ["Mantené la muñeca recta, alineada con el antebrazo.","Keep your wrist straight, aligned with your forearm.","Mantenha o punho reto, alinhado com o antebraço.","Garde le poignet droit, aligné avec l’avant-bras.","Mantieni il polso dritto, allineato con l’avambraccio.","Halte das Handgelenk gerade in einer Linie mit dem Unterarm."],
  ["Hacé las mismas repeticiones con ambos lados.","Do the same reps on both sides.","Faça as mesmas repetições dos dois lados.","Fais le même nombre de répétitions des deux côtés.","Fai le stesse ripetizioni su entrambi i lati.","Mach auf beiden Seiten gleich viele Wiederholungen."],
  ["Trapecio superior","Upper trapezius","Trapézio superior","Trapèze supérieur","Trapezio superiore","Oberer Trapezmuskel"],
  ["Elevador de la escápula y antebrazos (agarre)","Levator scapulae and forearms (grip)","Elevador da escápula e antebraços (pegada)","Élévateur de la scapula et avant-bras (préhension)","Elevatore della scapola e avambracci (presa)","Schulterblattheber und Unterarme (Griff)"],
  ["Parate erguido con una mancuerna en cada mano a los costados, palmas enfrentadas y brazos extendidos.","Stand upright with a dumbbell in each hand at your sides, palms facing each other and arms extended.","Fique ereto com um halter em cada mão ao lado do corpo, palmas voltadas uma para a outra e braços estendidos.","Tiens-toi droit, un haltère dans chaque main le long du corps, paumes face à face et bras tendus.","Mettiti dritto con un manubrio per mano lungo i fianchi, palmi rivolti l’uno verso l’altro e braccia distese.","Stell dich aufrecht hin, je eine Kurzhantel seitlich, Handflächen zueinander, Arme gestreckt."],
  ["Exhalá al subir los hombros e inhalá al bajarlos.","Exhale as you raise your shoulders and inhale as you lower them.","Expire ao subir os ombros e inspire ao abaixá-los.","Expire en montant les épaules et inspire en les abaissant.","Espira sollevando le spalle e inspira abbassandole.","Atme beim Hochziehen der Schultern aus und beim Senken ein."],
  ["Afirmá el tronco con los pies al ancho de cadera y el cuello neutro.","Brace your trunk with your feet hip-width apart and your neck neutral.","Firme o tronco com os pés na largura do quadril e o pescoço neutro.","Gaine le tronc, pieds à la largeur des hanches et nuque neutre.","Stabilizza il tronco con i piedi alla larghezza delle anche e il collo neutro.","Spann den Rumpf an, Füße hüftbreit, Nacken neutral."],
  ["Elevá los hombros en línea recta hacia las orejas, sin flexionar los codos.","Raise your shoulders straight up toward your ears, without bending your elbows.","Eleve os ombros em linha reta em direção às orelhas, sem flexionar os cotovelos.","Monte les épaules en ligne droite vers les oreilles, sans fléchir les coudes.","Solleva le spalle in linea retta verso le orecchie, senza piegare i gomiti.","Zieh die Schultern senkrecht zu den Ohren hoch, ohne die Ellbogen zu beugen."],
  ["Pausá un segundo arriba.","Pause for a second at the top.","Pause um segundo em cima.","Marque une seconde de pause en haut.","Fai una pausa di un secondo in alto.","Halte oben eine Sekunde."],
  ["Bajá los hombros despacio hasta la posición inicial.","Lower your shoulders slowly to the starting position.","Abaixe os ombros devagar até a posição inicial.","Redescends lentement les épaules jusqu’à la position de départ.","Abbassa lentamente le spalle fino alla posizione iniziale.","Senk die Schultern langsam in die Ausgangsposition ab."],
  ["Girar los hombros en círculos con la carga.","Rolling your shoulders in circles with the load.","Girar os ombros em círculos com a carga.","Faire des cercles avec les épaules sous charge.","Ruotare le spalle in cerchio con il carico.","Die Schultern mit Gewicht kreisen lassen."],
  ["Adelantar la cabeza o mirar hacia arriba.","Pushing your head forward or looking up.","Projetar a cabeça para frente ou olhar para cima.","Avancer la tête ou regarder vers le haut.","Spingere la testa in avanti o guardare in alto.","Den Kopf nach vorn schieben oder nach oben schauen."],
  ["Flexionar los codos para ayudarte.","Bending your elbows to help.","Flexionar os cotovelos para ajudar.","Fléchir les coudes pour t’aider.","Piegare i gomiti per aiutarti.","Die Ellbogen beugen, um nachzuhelfen."],
  ["El movimiento es vertical: arriba y abajo.","The movement is vertical: up and down.","O movimento é vertical: para cima e para baixo.","Le mouvement est vertical : de haut en bas.","Il movimento è verticale: su e giù.","Die Bewegung ist senkrecht: hoch und runter."],
  ["Si el agarre falla antes que el trapecio, usá mancuernas algo más livianas.","If your grip gives out before your traps, use slightly lighter dumbbells.","Se a pegada falhar antes do trapézio, use halteres um pouco mais leves.","Si ta prise lâche avant les trapèzes, utilise des haltères un peu plus légers.","Se la presa cede prima del trapezio, usa manubri un po’ più leggeri.","Wenn der Griff vor dem Trapezmuskel nachgibt, nimm etwas leichtere Kurzhanteln."],
  ["Mantené las mancuernas pegadas a los costados.","Keep the dumbbells close to your sides.","Mantenha os halteres colados ao lado do corpo.","Garde les haltères collés le long du corps.","Tieni i manubri aderenti ai fianchi.","Halte die Kurzhanteln eng an den Seiten."],
  ["Braquial y braquiorradial","Brachialis and brachioradialis","Braquial e braquiorradial","Brachial et brachio-radial","Brachiale e brachioradiale","Oberarmmuskel (Brachialis) und Oberarmspeichenmuskel"],
  ["Bíceps braquial y flexores del antebrazo","Biceps brachii and forearm flexors","Bíceps braquial e flexores do antebraço","Biceps brachial et fléchisseurs de l’avant-bras","Bicipite brachiale e flessori dell’avambraccio","Bizeps und Unterarmbeuger"],
  ["Parate con una mancuerna en cada mano a los costados, palmas enfrentadas hacia el cuerpo.","Stand with a dumbbell in each hand at your sides, palms facing your body.","Fique com um halter em cada mão ao lado do corpo, palmas voltadas para o corpo.","Tiens-toi avec un haltère dans chaque main le long du corps, paumes vers le corps.","Mettiti in piedi con un manubrio per mano lungo i fianchi, palmi rivolti verso il corpo.","Stell dich mit je einer Kurzhantel seitlich hin, Handflächen zum Körper."],
  ["Pegá los codos a los costados y mantené las muñecas rectas.","Tuck your elbows to your sides and keep your wrists straight.","Cole os cotovelos ao corpo e mantenha os punhos retos.","Colle les coudes au corps et garde les poignets droits.","Tieni i gomiti aderenti ai fianchi e i polsi dritti.","Leg die Ellbogen an den Körper und halte die Handgelenke gerade."],
  ["Flexioná los codos subiendo las mancuernas con las palmas enfrentadas, como si sostuvieras un martillo.","Bend your elbows, raising the dumbbells with palms facing each other, as if holding a hammer.","Flexione os cotovelos subindo os halteres com as palmas voltadas uma para a outra, como se segurasse um martelo.","Fléchis les coudes en montant les haltères paumes face à face, comme si tu tenais un marteau.","Piega i gomiti sollevando i manubri con i palmi rivolti l’uno verso l’altro, come se tenessi un martello.","Beuge die Ellbogen und heb die Kurzhanteln mit zueinander zeigenden Handflächen, als hieltest du einen Hammer."],
  ["Pausá un instante arriba sin adelantar los codos.","Pause for a moment at the top without bringing your elbows forward.","Pause um instante em cima sem levar os cotovelos para frente.","Marque une courte pause en haut sans avancer les coudes.","Fai una breve pausa in alto senza portare avanti i gomiti.","Halte oben kurz, ohne die Ellbogen nach vorn zu schieben."],
  ["Bajá con control; podés hacerlo con ambos brazos a la vez o alternando.","Lower with control; you can do it with both arms at once or alternating.","Desça com controle; você pode fazer com os dois braços ao mesmo tempo ou alternando.","Redescends en contrôle ; tu peux le faire avec les deux bras en même temps ou en alternant.","Scendi con controllo; puoi farlo con entrambe le braccia insieme o alternando.","Senk kontrolliert ab; du kannst beide Arme gleichzeitig oder abwechselnd bewegen."],
  ["Balancear el cuerpo para subir el peso.","Swinging your body to lift the weight.","Balançar o corpo para subir o peso.","Balancer le corps pour monter la charge.","Far oscillare il corpo per sollevare il peso.","Mit dem Körper schwingen, um das Gewicht hochzubringen."],
  ["Separar los codos del cuerpo y llevarlos adelante.","Moving your elbows away from your body and forward.","Afastar os cotovelos do corpo e levá-los para frente.","Écarter les coudes du corps et les avancer.","Staccare i gomiti dal corpo e portarli in avanti.","Die Ellbogen vom Körper lösen und nach vorn schieben."],
  ["Girar las muñecas durante el movimiento.","Rotating your wrists during the movement.","Girar os punhos durante o movimento.","Tourner les poignets pendant le mouvement.","Ruotare i polsi durante il movimento.","Die Handgelenke während der Bewegung drehen."],
  ["El agarre neutro suele ser cómodo para muñecas y codos.","A neutral grip is usually comfortable for wrists and elbows.","A pegada neutra costuma ser confortável para punhos e cotovelos.","La prise neutre est généralement confortable pour les poignets et les coudes.","La presa neutra di solito è comoda per polsi e gomiti.","Der neutrale Griff ist meist angenehm für Handgelenke und Ellbogen."],
  ["Bajá hasta extender casi por completo el codo.","Lower until your elbow is almost fully extended.","Desça até estender quase totalmente o cotovelo.","Redescends jusqu’à tendre presque complètement le coude.","Scendi fino a distendere quasi del tutto il gomito.","Senk ab, bis der Ellbogen fast ganz gestreckt ist."],
  ["Si alternás, mantené el tronco quieto.","If you alternate, keep your torso still.","Se alternar, mantenha o tronco parado.","Si tu alternes, garde le buste immobile.","Se alterni, mantieni il busto fermo.","Wenn du abwechselst, halte den Oberkörper ruhig."],
  ["Bíceps braquial","Biceps brachii","Bíceps braquial","Biceps brachial","Bicipite brachiale","Bizeps"],
  ["Máquina de curl predicador con apoyo para brazos","Preacher curl machine with arm pad","Máquina de rosca Scott com apoio para os braços","Machine à curl pupitre avec appui pour les bras","Macchina curl con panca Scott e appoggio per le braccia","Scottcurl-Maschine mit Armauflage"],
  ["Sentate con la parte trasera de los brazos apoyada en la almohadilla inclinada y las manijas tomadas con las palmas hacia arriba.","Sit with the backs of your arms on the angled pad and the handles held with palms up.","Sente-se com a parte de trás dos braços apoiada na almofada inclinada e as alças seguras com as palmas para cima.","Assieds-toi, l’arrière des bras posé sur le coussin incliné, poignées tenues paumes vers le haut.","Siediti con la parte posteriore delle braccia appoggiata al cuscinetto inclinato e le maniglie impugnate con i palmi in alto.","Setz dich, die Oberarmrückseiten auf dem schrägen Polster, die Griffe mit Handflächen nach oben gefasst."],
  ["Ajustá el asiento para que las axilas queden cerca del borde superior de la almohadilla.","Adjust the seat so your armpits are close to the top edge of the pad.","Ajuste o assento para as axilas ficarem perto da borda superior da almofada.","Règle le siège pour que tes aisselles soient près du bord supérieur du coussin.","Regola il sedile perché le ascelle siano vicine al bordo superiore del cuscinetto.","Stell den Sitz so ein, dass die Achseln nah an der Oberkante des Polsters sind."],
  ["Flexioná los codos llevando las manijas hacia los hombros sin despegar los brazos del apoyo.","Bend your elbows, bringing the handles toward your shoulders without lifting your arms off the pad.","Flexione os cotovelos levando as alças em direção aos ombros sem descolar os braços do apoio.","Fléchis les coudes en amenant les poignées vers les épaules sans décoller les bras de l’appui.","Piega i gomiti portando le maniglie verso le spalle senza staccare le braccia dall’appoggio.","Beuge die Ellbogen und führ die Griffe zu den Schultern, ohne die Arme vom Polster zu lösen."],
  ["Pausá un instante arriba.","Pause for a moment at the top.","Pause um instante em cima.","Marque une courte pause en haut.","Fai una breve pausa in alto.","Halte oben kurz."],
  ["Bajá despacio hasta casi extender los codos, sin soltar la tensión de golpe.","Lower slowly until your elbows are almost extended, without releasing the tension abruptly.","Desça devagar até quase estender os cotovelos, sem soltar a tensão de uma vez.","Redescends lentement jusqu’à presque tendre les coudes, sans relâcher la tension d’un coup.","Scendi lentamente fino a distendere quasi i gomiti, senza rilasciare la tensione di colpo.","Senk langsam ab, bis die Ellbogen fast gestreckt sind, ohne die Spannung abrupt zu lösen."],
  ["Despegar los codos de la almohadilla.","Lifting your elbows off the pad.","Descolar os cotovelos da almofada.","Décoller les coudes du coussin.","Staccare i gomiti dal cuscinetto.","Die Ellbogen vom Polster lösen."],
  ["Dejar caer la carga en la bajada y estirar el codo de golpe.","Letting the load drop on the way down and snapping your elbow straight.","Deixar a carga cair na descida e estender o cotovelo de uma vez.","Laisser tomber la charge à la descente et tendre le coude d’un coup.","Lasciar cadere il carico in discesa e distendere il gomito di colpo.","Das Gewicht beim Absenken fallen lassen und den Ellbogen ruckartig strecken."],
  ["Levantar la cadera del asiento para ayudarte.","Lifting your hips off the seat to help.","Levantar o quadril do assento para ajudar.","Soulever les hanches du siège pour t’aider.","Sollevare le anche dal sedile per aiutarti.","Die Hüfte vom Sitz heben, um nachzuhelfen."],
  ["El apoyo impide el balanceo y aísla el bíceps.","The pad prevents swinging and isolates the biceps.","O apoio impede o balanço e isola o bíceps.","L’appui empêche l’élan et isole le biceps.","L’appoggio impedisce lo slancio e isola il bicipite.","Die Auflage verhindert Schwung und isoliert den Bizeps."],
  ["La parte final de la bajada es exigente: controlala bien.","The last part of the descent is demanding: control it well.","A parte final da descida é exigente: controle bem.","La fin de la descente est exigeante : contrôle-la bien.","La parte finale della discesa è impegnativa: controllala bene.","Der letzte Teil des Absenkens ist anspruchsvoll: Kontrolliere ihn gut."],
  ["Usá una carga que permita un rango completo.","Use a load that allows a full range of motion.","Use uma carga que permita uma amplitude completa.","Utilise une charge qui permet une amplitude complète.","Usa un carico che permetta un’ampiezza completa.","Nimm ein Gewicht, das einen vollen Bewegungsumfang erlaubt."],
  ["Polea baja con barra recta o barra EZ","Low cable with straight bar or EZ bar","Polia baixa com barra reta ou barra W","Poulie basse avec barre droite ou barre EZ","Cavo basso con barra dritta o barra EZ","Tiefer Kabelzug mit gerader Stange oder SZ-Stange"],
  ["Parate frente a la polea baja con la barra tomada con las palmas hacia arriba, brazos extendidos y codos a los costados.","Stand facing the low cable holding the bar with palms up, arms extended and elbows at your sides.","Fique de frente para a polia baixa com a barra segura com as palmas para cima, braços estendidos e cotovelos ao lado do corpo.","Tiens-toi face à la poulie basse, barre tenue paumes vers le haut, bras tendus et coudes le long du corps.","Mettiti di fronte al cavo basso con la barra impugnata con i palmi in alto, braccia distese e gomiti ai fianchi.","Stell dich vor den tiefen Kabelzug, die Stange mit Handflächen nach oben gefasst, Arme gestreckt, Ellbogen seitlich am Körper."],
  ["Dá un pequeño paso atrás para tensar el cable y afirmá el tronco.","Take a small step back to tension the cable and brace your trunk.","Dê um pequeno passo para trás para tensionar o cabo e firme o tronco.","Fais un petit pas en arrière pour tendre le câble et gaine le tronc.","Fai un piccolo passo indietro per tendere il cavo e stabilizza il tronco.","Mach einen kleinen Schritt zurück, um das Seil zu spannen, und spann den Rumpf an."],
  ["Flexioná los codos llevando la barra hacia los hombros sin mover la parte superior de los brazos.","Bend your elbows, bringing the bar toward your shoulders without moving your upper arms.","Flexione os cotovelos levando a barra em direção aos ombros sem mover a parte superior dos braços.","Fléchis les coudes en amenant la barre vers les épaules sans bouger le haut des bras.","Piega i gomiti portando la barra verso le spalle senza muovere la parte superiore delle braccia.","Beuge die Ellbogen und führ die Stange zu den Schultern, ohne die Oberarme zu bewegen."],
  ["Bajá con control hasta extender los brazos.","Lower with control until your arms are extended.","Desça com controle até estender os braços.","Redescends en contrôle jusqu’à tendre les bras.","Scendi con controllo fino a distendere le braccia.","Senk kontrolliert ab, bis die Arme gestreckt sind."],
  ["Inclinarse hacia atrás para subir la barra.","Leaning back to lift the bar.","Inclinar-se para trás para subir a barra.","Se pencher en arrière pour monter la barre.","Inclinarsi indietro per sollevare la barra.","Sich nach hinten lehnen, um die Stange hochzubringen."],
  ["Adelantar los codos al final del recorrido.","Bringing your elbows forward at the end of the movement.","Levar os cotovelos para frente no final do movimento.","Avancer les coudes en fin de mouvement.","Portare avanti i gomiti alla fine del movimento.","Am Ende der Bewegung die Ellbogen nach vorn schieben."],
  ["Doblar las muñecas hacia atrás.","Bending your wrists back.","Dobrar os punhos para trás.","Plier les poignets vers l’arrière.","Piegare i polsi all’indietro.","Die Handgelenke nach hinten abknicken."],
  ["El cable mantiene tensión durante todo el recorrido.","The cable keeps tension throughout the movement.","O cabo mantém tensão durante todo o movimento.","Le câble maintient la tension tout au long du mouvement.","Il cavo mantiene la tensione per tutto il movimento.","Der Kabelzug hält über die ganze Bewegung Spannung."],
  ["Elegí un agarre que no moleste las muñecas.","Choose a grip that doesn’t bother your wrists.","Escolha uma pegada que não incomode os punhos.","Choisis une prise qui ne gêne pas tes poignets.","Scegli una presa che non dia fastidio ai polsi.","Wähle einen Griff, der deine Handgelenke nicht stört."],
  ["Braquial","Brachialis","Braquial","Brachial","Brachiale","Oberarmmuskel (Brachialis)"],
  ["Una mancuerna y un banco","One dumbbell and a bench","Um halter e um banco","Un haltère et un banc","Un manubrio e una panca","Eine Kurzhantel und eine Bank"],
  ["Sentate en el banco con las piernas abiertas, inclinado hacia adelante, y apoyá el codo del brazo que trabaja en la cara interna del muslo.","Sit on the bench with your legs apart, leaning forward, and rest the elbow of your working arm against your inner thigh.","Sente-se no banco com as pernas abertas, inclinado para frente, e apoie o cotovelo do braço que trabalha na parte interna da coxa.","Assieds-toi sur le banc, jambes écartées, penché vers l’avant, et appuie le coude du bras qui travaille contre l’intérieur de la cuisse.","Siediti sulla panca con le gambe aperte, inclinato in avanti, e appoggia il gomito del braccio che lavora all’interno della coscia.","Setz dich mit geöffneten Beinen auf die Bank, beug dich vor und stütz den Ellbogen des Arbeitsarms an der Oberschenkelinnenseite ab."],
  ["Tomá la mancuerna con la palma hacia arriba y dejá el brazo extendido, con el codo apoyado en el muslo.","Hold the dumbbell with your palm up and let your arm hang extended, with your elbow against your thigh.","Segure o halter com a palma para cima e deixe o braço estendido, com o cotovelo apoiado na coxa.","Tiens l’haltère paume vers le haut, bras tendu, coude appuyé contre la cuisse.","Tieni il manubrio con il palmo in alto e lascia il braccio disteso, con il gomito appoggiato alla coscia.","Halte die Kurzhantel mit der Handfläche nach oben, Arm gestreckt, Ellbogen am Oberschenkel."],
  ["Flexioná el codo llevando la mancuerna hacia el hombro sin mover la parte superior del brazo.","Bend your elbow, bringing the dumbbell toward your shoulder without moving your upper arm.","Flexione o cotovelo levando o halter em direção ao ombro sem mover a parte superior do braço.","Fléchis le coude en amenant l’haltère vers l’épaule sans bouger le haut du bras.","Piega il gomito portando il manubrio verso la spalla senza muovere la parte superiore del braccio.","Beuge den Ellbogen und führ die Kurzhantel zur Schulter, ohne den Oberarm zu bewegen."],
  ["Bajá despacio y completá todas las repeticiones de un lado antes de cambiar al otro.","Lower slowly and finish all the reps on one side before switching to the other.","Desça devagar e complete todas as repetições de um lado antes de trocar para o outro.","Redescends lentement et termine toutes les répétitions d’un côté avant de passer à l’autre.","Scendi lentamente e completa tutte le ripetizioni da un lato prima di passare all’altro.","Senk langsam ab und mach alle Wiederholungen auf einer Seite, bevor du wechselst."],
  ["Mover el tronco para ayudar a subir.","Moving your torso to help lift.","Mover o tronco para ajudar a subir.","Bouger le buste pour aider à monter.","Muovere il busto per aiutarti a salire.","Den Oberkörper bewegen, um beim Heben nachzuhelfen."],
  ["Despegar el codo del muslo.","Lifting your elbow off your thigh.","Descolar o cotovelo da coxa.","Décoller le coude de la cuisse.","Staccare il gomito dalla coscia.","Den Ellbogen vom Oberschenkel lösen."],
  ["Bajar a medias sin extender el codo.","Lowering only halfway without extending your elbow.","Descer pela metade sem estender o cotovelo.","Ne descendre qu’à moitié sans tendre le coude.","Scendere a metà senza distendere il gomito.","Nur halb absenken, ohne den Ellbogen zu strecken."],
  ["Apoyá la mano libre sobre la otra rodilla para estabilizarte.","Rest your free hand on your other knee to steady yourself.","Apoie a mão livre sobre o outro joelho para se estabilizar.","Pose la main libre sur l’autre genou pour te stabiliser.","Appoggia la mano libera sull’altro ginocchio per stabilizzarti.","Stütz die freie Hand auf das andere Knie, um dich zu stabilisieren."],
  ["Es un ejercicio de control, no de carga máxima.","It is a control exercise, not a max-load one.","É um exercício de controle, não de carga máxima.","C’est un exercice de contrôle, pas de charge maximale.","È un esercizio di controllo, non di carico massimo.","Es ist eine Kontrollübung, keine Maximalkraftübung."],
  ["Hacé el mismo número de repeticiones con ambos brazos.","Do the same number of reps with both arms.","Faça o mesmo número de repetições com os dois braços.","Fais le même nombre de répétitions avec les deux bras.","Fai lo stesso numero di ripetizioni con entrambe le braccia.","Mach mit beiden Armen gleich viele Wiederholungen."],
  ["Braquiorradial y braquial","Brachioradialis and brachialis","Braquiorradial e braquial","Brachio-radial et brachial","Brachioradiale e brachiale","Oberarmspeichenmuskel und Oberarmmuskel (Brachialis)"],
  ["Bíceps braquial y extensores del antebrazo","Biceps brachii and forearm extensors","Bíceps braquial e extensores do antebraço","Biceps brachial et extenseurs de l’avant-bras","Bicipite brachiale ed estensori dell’avambraccio","Bizeps und Unterarmstrecker"],
  ["Barra recta o barra EZ liviana","Light straight bar or EZ bar","Barra reta ou barra W leve","Barre droite ou barre EZ légère","Barra dritta o barra EZ leggera","Leichte gerade Stange oder SZ-Stange"],
  ["Parate con la barra tomada con agarre prono (palmas hacia abajo) al ancho de hombros, delante de los muslos.","Stand holding the bar with an overhand grip (palms down) at shoulder width, in front of your thighs.","Fique em pé com a barra segura com pegada pronada (palmas para baixo) na largura dos ombros, diante das coxas.","Tiens-toi debout, barre tenue en pronation (paumes vers le bas) à la largeur des épaules, devant les cuisses.","Stai in piedi con la barra impugnata con presa prona (palmi in basso) alla larghezza delle spalle, davanti alle cosce.","Stell dich hin, die Stange im Obergriff (Handflächen nach unten) schulterbreit vor den Oberschenkeln gefasst."],
  ["Flexioná los codos subiendo la barra hacia los hombros con las palmas hacia abajo.","Bend your elbows, raising the bar toward your shoulders with palms down.","Flexione os cotovelos subindo a barra em direção aos ombros com as palmas para baixo.","Fléchis les coudes en montant la barre vers les épaules, paumes vers le bas.","Piega i gomiti sollevando la barra verso le spalle con i palmi in basso.","Beuge die Ellbogen und heb die Stange mit Handflächen nach unten zu den Schultern."],
  ["Dejar que las muñecas se doblen hacia abajo.","Letting your wrists bend downward.","Deixar os punhos dobrarem para baixo.","Laisser les poignets plier vers le bas.","Lasciare che i polsi si pieghino verso il basso.","Die Handgelenke nach unten abknicken lassen."],
  ["Balancear el cuerpo para subir la barra.","Swinging your body to lift the bar.","Balançar o corpo para subir a barra.","Balancer le corps pour monter la barre.","Far oscillare il corpo per sollevare la barra.","Mit dem Körper schwingen, um die Stange hochzubringen."],
  ["Usar la misma carga que en el curl normal.","Using the same load as in a regular curl.","Usar a mesma carga da rosca normal.","Utiliser la même charge que pour un curl classique.","Usare lo stesso carico del curl normale.","Dasselbe Gewicht wie beim normalen Curl nehmen."],
  ["Con agarre prono vas a mover menos peso que en un curl supino; es normal.","With an overhand grip you will move less weight than in an underhand curl; that’s normal.","Com pegada pronada você vai mover menos peso que na rosca supinada; é normal.","En pronation, tu soulèveras moins lourd qu’en supination ; c’est normal.","Con la presa prona sposterai meno peso che nel curl supino; è normale.","Im Obergriff bewegst du weniger Gewicht als im Untergriff; das ist normal."],
  ["La barra EZ suele ser más cómoda para las muñecas.","The EZ bar is usually more comfortable for the wrists.","A barra W costuma ser mais confortável para os punhos.","La barre EZ est généralement plus confortable pour les poignets.","La barra EZ di solito è più comoda per i polsi.","Die SZ-Stange ist meist angenehmer für die Handgelenke."],
  ["Mantené los codos fijos a los costados.","Keep your elbows fixed at your sides.","Mantenha os cotovelos fixos ao lado do corpo.","Garde les coudes fixes le long du corps.","Mantieni i gomiti fissi ai fianchi.","Halte die Ellbogen fest an den Seiten."],
  ["Tríceps braquial","Triceps brachii","Tríceps braquial","Triceps brachial","Tricipite brachiale","Trizeps"],
  ["Ancóneo y estabilizadores del hombro","Anconeus and shoulder stabilizers","Ancôneo e estabilizadores do ombro","Anconé et stabilisateurs de l’épaule","Anconeo e stabilizzatori della spalla","Ellbogenmuskel (Anconeus) und Schulterstabilisatoren"],
  ["Polea alta con cuerda","High cable with rope","Polia alta com corda","Poulie haute avec corde","Cavo alto con corda","Oberer Kabelzug mit Seil"],
  ["Parate frente a la polea alta con la cuerda tomada con palmas enfrentadas, codos pegados a los costados y flexionados a unos 90 grados.","Stand facing the high cable holding the rope with palms facing each other, elbows tucked at your sides and bent to about 90 degrees.","Fique de frente para a polia alta com a corda segura com as palmas voltadas uma para a outra, cotovelos colados ao corpo e flexionados a cerca de 90 graus.","Tiens-toi face à la poulie haute, corde tenue paumes face à face, coudes collés au corps et fléchis à environ 90 degrés.","Mettiti di fronte al cavo alto con la corda impugnata con i palmi rivolti l’uno verso l’altro, gomiti aderenti ai fianchi e piegati a circa 90 gradi.","Stell dich vor den oberen Kabelzug, das Seil mit zueinander zeigenden Handflächen gefasst, Ellbogen am Körper, etwa 90 Grad gebeugt."],
  ["Exhalá al extender e inhalá al volver.","Exhale as you extend and inhale as you return.","Expire ao estender e inspire ao voltar.","Expire en tendant et inspire en revenant.","Espira distendendo e inspira tornando.","Atme beim Strecken aus und beim Zurückführen ein."],
  ["Inclinate apenas hacia adelante con las rodillas suaves y los hombros bajos.","Lean slightly forward with soft knees and your shoulders down.","Incline-se levemente para frente com os joelhos soltos e os ombros baixos.","Penche-toi légèrement en avant, genoux souples et épaules basses.","Inclinati leggermente in avanti con le ginocchia morbide e le spalle basse.","Neig dich mit weichen Knien und tiefen Schultern leicht nach vorn."],
  ["Extendé los codos llevando la cuerda hacia abajo y separando los extremos al final.","Extend your elbows, pulling the rope down and separating the ends at the bottom.","Estenda os cotovelos levando a corda para baixo e separando as pontas no final.","Tends les coudes en descendant la corde et en écartant les extrémités en bas.","Distendi i gomiti portando la corda in basso e separando le estremità alla fine.","Streck die Ellbogen, zieh das Seil nach unten und zieh die Enden unten auseinander."],
  ["Pausá un instante con los brazos extendidos.","Pause for a moment with your arms extended.","Pause um instante com os braços estendidos.","Marque une courte pause bras tendus.","Fai una breve pausa con le braccia distese.","Halte kurz mit gestreckten Armen."],
  ["Volvé despacio hasta que los antebrazos queden cerca de paralelos al suelo.","Return slowly until your forearms are close to parallel to the floor.","Volte devagar até os antebraços ficarem perto de paralelos ao chão.","Reviens lentement jusqu’à ce que les avant-bras soient presque parallèles au sol.","Torna lentamente finché gli avambracci sono quasi paralleli al pavimento.","Führ langsam zurück, bis die Unterarme etwa parallel zum Boden sind."],
  ["Mover los codos hacia adelante y atrás.","Moving your elbows forward and back.","Mover os cotovelos para frente e para trás.","Bouger les coudes d’avant en arrière.","Muovere i gomiti avanti e indietro.","Die Ellbogen vor und zurück bewegen."],
  ["Inclinar el tronco sobre la cuerda para empujar con el peso del cuerpo.","Leaning your torso over the rope to push with your body weight.","Inclinar o tronco sobre a corda para empurrar com o peso do corpo.","Pencher le buste au-dessus de la corde pour pousser avec le poids du corps.","Inclinare il busto sopra la corda per spingere con il peso del corpo.","Den Oberkörper über das Seil lehnen, um mit dem Körpergewicht zu drücken."],
  ["Dejar que la cuerda suba de golpe.","Letting the rope shoot back up.","Deixar a corda subir de uma vez.","Laisser la corde remonter d’un coup.","Lasciare che la corda risalga di colpo.","Das Seil unkontrolliert hochschnellen lassen."],
  ["Separar los extremos de la cuerda abajo ayuda a completar la extensión.","Separating the ends of the rope at the bottom helps complete the extension.","Separar as pontas da corda embaixo ajuda a completar a extensão.","Écarter les extrémités de la corde en bas aide à terminer l’extension.","Separare le estremità della corda in basso aiuta a completare l’estensione.","Wenn du die Seilenden unten auseinanderziehst, schaffst du die volle Streckung."],
  ["Los codos funcionan como bisagra fija.","Your elbows act as a fixed hinge.","Os cotovelos funcionam como uma dobradiça fixa.","Les coudes servent de charnière fixe.","I gomiti funzionano come una cerniera fissa.","Die Ellbogen funktionieren wie ein festes Scharnier."],
  ["Mantené las muñecas rectas.","Keep your wrists straight.","Mantenha os punhos retos.","Garde les poignets droits.","Mantieni i polsi dritti.","Halte die Handgelenke gerade."],
  ["Tríceps braquial, con énfasis en la porción larga","Triceps brachii, with emphasis on the long head","Tríceps braquial, com ênfase na porção longa","Triceps brachial, avec un accent sur le chef long","Tricipite brachiale, con enfasi sul capo lungo","Trizeps mit Fokus auf den langen Kopf"],
  ["Core y estabilizadores del hombro","Core and shoulder stabilizers","Core e estabilizadores do ombro","Sangle abdominale et stabilisateurs de l’épaule","Core e stabilizzatori della spalla","Rumpf und Schulterstabilisatoren"],
  ["Polea baja o media con cuerda","Low or mid cable with rope","Polia baixa ou média com corda","Poulie basse ou médiane avec corde","Cavo basso o medio con corda","Tiefer oder mittlerer Kabelzug mit Seil"],
  ["Principiante-intermedio; requiere movilidad de hombro","Beginner–intermediate; requires shoulder mobility","Iniciante-intermediário; exige mobilidade de ombro","Débutant-intermédiaire ; demande de la mobilité d’épaule","Principiante-intermedio; richiede mobilità della spalla","Anfänger bis Fortgeschrittene; erfordert Schulterbeweglichkeit"],
  ["Parate de espaldas a la polea con la cuerda tomada detrás de la cabeza, codos apuntando hacia adelante y arriba, y un pie adelantado.","Stand with your back to the cable holding the rope behind your head, elbows pointing forward and up, and one foot forward.","Fique de costas para a polia com a corda segura atrás da cabeça, cotovelos apontando para frente e para cima, e um pé à frente.","Tiens-toi dos à la poulie, corde tenue derrière la tête, coudes pointés vers l’avant et le haut, un pied en avant.","Mettiti di spalle al cavo con la corda impugnata dietro la testa, gomiti rivolti in avanti e in alto, e un piede avanti.","Stell dich mit dem Rücken zum Kabelzug, das Seil hinter dem Kopf gefasst, Ellbogen nach vorn oben, ein Fuß vorn."],
  ["Tomá la cuerda, girá y dá un paso adelante en postura escalonada con el tronco levemente inclinado.","Take the rope, turn around and step forward into a staggered stance with your torso slightly leaning.","Pegue a corda, vire-se e dê um passo à frente em postura escalonada com o tronco levemente inclinado.","Prends la corde, retourne-toi et fais un pas en avant en position décalée, buste légèrement penché.","Prendi la corda, girati e fai un passo avanti in posizione sfalsata con il busto leggermente inclinato.","Nimm das Seil, dreh dich um und geh einen Schritt nach vorn in die Schrittstellung, Oberkörper leicht geneigt."],
  ["Con los codos fijos cerca de la cabeza, extendé los brazos hacia adelante y arriba.","With your elbows fixed near your head, extend your arms forward and up.","Com os cotovelos fixos perto da cabeça, estenda os braços para frente e para cima.","Coudes fixes près de la tête, tends les bras vers l’avant et le haut.","Con i gomiti fissi vicino alla testa, distendi le braccia in avanti e in alto.","Streck die Arme mit fixierten Ellbogen nahe am Kopf nach vorn oben."],
  ["Pausá un instante con los codos extendidos.","Pause for a moment with your elbows extended.","Pause um instante com os cotovelos estendidos.","Marque une courte pause, coudes tendus.","Fai una breve pausa con i gomiti distesi.","Halte kurz mit gestreckten Ellbogen."],
  ["Volvé despacio flexionando los codos hasta sentir un estiramiento cómodo del tríceps.","Return slowly, bending your elbows until you feel a comfortable triceps stretch.","Volte devagar flexionando os cotovelos até sentir um alongamento confortável do tríceps.","Reviens lentement en fléchissant les coudes jusqu’à sentir un étirement confortable des triceps.","Torna lentamente piegando i gomiti fino a sentire un allungamento comodo del tricipite.","Führ langsam zurück und beuge die Ellbogen, bis du eine angenehme Trizepsdehnung spürst."],
  ["Abrir mucho los codos hacia los costados.","Flaring your elbows wide to the sides.","Abrir muito os cotovelos para os lados.","Écarter fortement les coudes sur les côtés.","Aprire molto i gomiti verso i lati.","Die Ellbogen weit zur Seite ausstellen."],
  ["Bajar más de lo que el hombro tolera con comodidad.","Going lower than your shoulder comfortably tolerates.","Descer mais do que o ombro tolera com conforto.","Descendre plus bas que ce que ton épaule tolère confortablement.","Scendere più di quanto la spalla tolleri comodamente.","Tiefer gehen, als die Schulter angenehm verträgt."],
  ["Mantené el abdomen firme para no arquear la espalda.","Keep your abs tight so you don’t arch your back.","Mantenha o abdômen firme para não arquear as costas.","Garde les abdos gainés pour ne pas cambrer le dos.","Mantieni l’addome contratto per non inarcare la schiena.","Halte den Bauch fest, damit du nicht ins Hohlkreuz gehst."],
  ["La posición sobre la cabeza estira la porción larga del tríceps.","The overhead position stretches the long head of the triceps.","A posição acima da cabeça alonga a porção longa do tríceps.","La position au-dessus de la tête étire le chef long du triceps.","La posizione sopra la testa allunga il capo lungo del tricipite.","Die Überkopfposition dehnt den langen Trizepskopf."],
  ["Si el hombro molesta, probá la versión con cuerda hacia abajo.","If your shoulder bothers you, try the rope pushdown version.","Se o ombro incomodar, teste a versão com corda para baixo.","Si ton épaule te gêne, essaie la version à la corde vers le bas.","Se la spalla dà fastidio, prova la versione con corda verso il basso.","Wenn die Schulter zwickt, probier die Variante mit Seil nach unten."],
  ["Polea alta con manija simple","High cable with a single handle","Polia alta com alça simples","Poulie haute avec poignée simple","Cavo alto con maniglia singola","Oberer Kabelzug mit Einhandgriff"],
  ["Parate frente a la polea alta con la manija en una mano, codo pegado al costado y flexionado a 90 grados.","Stand facing the high cable with the handle in one hand, elbow tucked to your side and bent to 90 degrees.","Fique de frente para a polia alta com a alça em uma mão, cotovelo colado ao corpo e flexionado a 90 graus.","Tiens-toi face à la poulie haute, la poignée dans une main, coude collé au corps et fléchi à 90 degrés.","Mettiti di fronte al cavo alto con la maniglia in una mano, gomito aderente al fianco e piegato a 90 gradi.","Stell dich vor den oberen Kabelzug, den Griff in einer Hand, Ellbogen am Körper und im 90-Grad-Winkel gebeugt."],
  ["Apoyá la mano libre en la máquina o en la cintura y mantené el tronco quieto.","Rest your free hand on the machine or your waist and keep your torso still.","Apoie a mão livre na máquina ou na cintura e mantenha o tronco parado.","Pose la main libre sur la machine ou sur ta taille et garde le buste immobile.","Appoggia la mano libera sulla macchina o sul fianco e mantieni il busto fermo.","Leg die freie Hand an die Maschine oder an die Taille und halte den Oberkörper ruhig."],
  ["Extendé el codo llevando la manija hacia abajo hasta estirar el brazo.","Extend your elbow, pulling the handle down until your arm is straight.","Estenda o cotovelo levando a alça para baixo até esticar o braço.","Tends le coude en descendant la poignée jusqu’à ce que le bras soit tendu.","Distendi il gomito portando la maniglia in basso fino a stendere il braccio.","Streck den Ellbogen und zieh den Griff nach unten, bis der Arm gestreckt ist."],
  ["Pausá un instante abajo.","Pause for a moment at the bottom.","Pause um instante embaixo.","Marque une courte pause en bas.","Fai una breve pausa in basso.","Halte unten kurz."],
  ["Volvé con control y completá todas las repeticiones de un lado antes de cambiar al otro.","Return with control and finish all the reps on one side before switching to the other.","Volte com controle e complete todas as repetições de um lado antes de trocar para o outro.","Reviens en contrôle et termine toutes les répétitions d’un côté avant de passer à l’autre.","Torna con controllo e completa tutte le ripetizioni da un lato prima di passare all’altro.","Führ kontrolliert zurück und mach alle Wiederholungen auf einer Seite, bevor du wechselst."],
  ["Mover el hombro y el codo hacia adelante.","Moving your shoulder and elbow forward.","Mover o ombro e o cotovelo para frente.","Avancer l’épaule et le coude.","Spostare spalla e gomito in avanti.","Schulter und Ellbogen nach vorn schieben."],
  ["Girar el tronco para ayudar.","Rotating your torso to help.","Girar o tronco para ajudar.","Faire pivoter le buste pour t’aider.","Ruotare il busto per aiutarti.","Den Oberkörper drehen, um nachzuhelfen."],
  ["Soltar la tensión arriba.","Releasing the tension at the top.","Soltar a tensão em cima.","Relâcher la tension en haut.","Rilasciare la tensione in alto.","Oben die Spannung lösen."],
  ["Trabajar un brazo por vez permite igualar la fuerza entre lados.","Working one arm at a time lets you even out strength between sides.","Trabalhar um braço por vez permite igualar a força entre os lados.","Travailler un bras à la fois permet d’équilibrer la force entre les côtés.","Lavorare un braccio alla volta permette di pareggiare la forza tra i lati.","Einarmiges Training hilft, die Kraft zwischen den Seiten anzugleichen."],
  ["Probá agarre supino o prono según tu comodidad.","Try an underhand or overhand grip depending on your comfort.","Teste pegada supinada ou pronada conforme o seu conforto.","Essaie une prise en supination ou en pronation selon ton confort.","Prova la presa supina o prona a seconda della tua comodità.","Probier je nach Komfort Unter- oder Obergriff."],
  ["Mantené la muñeca recta.","Keep your wrist straight.","Mantenha o punho reto.","Garde le poignet droit.","Mantieni il polso dritto.","Halte das Handgelenk gerade."],
  ["Barra Z (EZ) y banco plano","EZ bar and flat bench","Barra W e banco reto","Barre EZ et banc plat","Barra EZ e panca piana","SZ-Stange und Flachbank"],
  ["Intermedio; empezá con poco peso","Intermediate; start with a light weight","Intermediário; comece com pouco peso","Intermédiaire ; commence avec une charge légère","Intermedio; inizia con poco peso","Fortgeschritten; beginne mit wenig Gewicht"],
  ["Acostate en el banco con la barra Z sostenida sobre el pecho, brazos extendidos y agarre cerrado en la parte angulada.","Lie on the bench with the EZ bar held over your chest, arms extended and a narrow grip on the angled part.","Deite-se no banco com a barra W sustentada sobre o peito, braços estendidos e pegada fechada na parte angulada.","Allonge-toi sur le banc, barre EZ tenue au-dessus de la poitrine, bras tendus et prise serrée sur la partie coudée.","Sdraiati sulla panca con la barra EZ sopra il petto, braccia distese e presa stretta sulla parte angolata.","Leg dich auf die Bank, die SZ-Stange über der Brust, Arme gestreckt, enger Griff am abgewinkelten Teil."],
  ["Inhalá al bajar la barra y exhalá al extender.","Inhale as you lower the bar and exhale as you extend.","Inspire ao abaixar a barra e expire ao estender.","Inspire en descendant la barre et expire en tendant les bras.","Inspira abbassando la barra ed espira distendendo.","Atme beim Absenken der Stange ein und beim Strecken aus."],
  ["Llevá la barra arriba del pecho con los brazos extendidos y levemente inclinados hacia la cabeza.","Bring the bar above your chest with your arms extended and slightly tilted toward your head.","Leve a barra acima do peito com os braços estendidos e levemente inclinados em direção à cabeça.","Amène la barre au-dessus de la poitrine, bras tendus et légèrement inclinés vers la tête.","Porta la barra sopra il petto con le braccia distese e leggermente inclinate verso la testa.","Bring die Stange mit gestreckten, leicht zum Kopf geneigten Armen über die Brust."],
  ["Flexioná solo los codos bajando la barra hacia la frente o apenas por detrás de la cabeza.","Bend only your elbows, lowering the bar toward your forehead or just behind your head.","Flexione só os cotovelos abaixando a barra em direção à testa ou um pouco atrás da cabeça.","Fléchis seulement les coudes en descendant la barre vers le front ou juste derrière la tête.","Piega solo i gomiti abbassando la barra verso la fronte o appena dietro la testa.","Beuge nur die Ellbogen und senk die Stange zur Stirn oder knapp hinter den Kopf."],
  ["Mantené los codos apuntando hacia arriba, sin abrirlos.","Keep your elbows pointing up, without flaring them.","Mantenha os cotovelos apontando para cima, sem abri-los.","Garde les coudes pointés vers le haut, sans les écarter.","Mantieni i gomiti rivolti verso l’alto, senza aprirli.","Halte die Ellbogen nach oben gerichtet, ohne sie auszustellen."],
  ["Extendé los codos para volver a la posición inicial.","Extend your elbows to return to the starting position.","Estenda os cotovelos para voltar à posição inicial.","Tends les coudes pour revenir à la position de départ.","Distendi i gomiti per tornare alla posizione iniziale.","Streck die Ellbogen, um in die Ausgangsposition zurückzukehren."],
  ["Abrir los codos hacia los costados.","Flaring your elbows out to the sides.","Abrir os cotovelos para os lados.","Écarter les coudes sur les côtés.","Aprire i gomiti verso i lati.","Die Ellbogen zur Seite ausstellen."],
  ["Mover los hombros y convertirlo en un press.","Moving your shoulders and turning it into a press.","Mover os ombros e transformar em supino.","Bouger les épaules et en faire un développé.","Muovere le spalle e trasformarlo in una distensione.","Die Schultern bewegen und ein Drücken daraus machen."],
  ["Bajar rápido y sin control cerca de la cara.","Lowering fast and without control near your face.","Descer rápido e sem controle perto do rosto.","Descendre vite et sans contrôle près du visage.","Scendere veloce e senza controllo vicino al viso.","Schnell und unkontrolliert nahe am Gesicht absenken."],
  ["Bajá siempre despacio: la barra pasa cerca de la cabeza.","Always lower slowly: the bar passes close to your head.","Desça sempre devagar: a barra passa perto da cabeça.","Descends toujours lentement : la barre passe près de la tête.","Scendi sempre lentamente: la barra passa vicino alla testa.","Senk immer langsam ab: Die Stange kommt nah an den Kopf."],
  ["La barra Z reduce la tensión en las muñecas respecto de la recta.","The EZ bar reduces wrist strain compared with a straight bar.","A barra W reduz a tensão nos punhos em relação à reta.","La barre EZ réduit la contrainte sur les poignets par rapport à la barre droite.","La barra EZ riduce la tensione sui polsi rispetto a quella dritta.","Die SZ-Stange entlastet die Handgelenke im Vergleich zur geraden Stange."],
  ["Pedí a alguien que te pase y retire la barra si la carga es alta.","Ask someone to hand you and take the bar if the load is heavy.","Peça a alguém para passar e retirar a barra se a carga for alta.","Demande à quelqu’un de te passer et reprendre la barre si la charge est lourde.","Chiedi a qualcuno di passarti e riprendere la barra se il carico è alto.","Lass dir die Stange bei schwerem Gewicht von jemandem anreichen und abnehmen."],
  ["Pectoral mayor y deltoides anterior","Pectoralis major and front deltoid","Peitoral maior e deltoide anterior","Grand pectoral et deltoïde antérieur","Grande pettorale e deltoide anteriore","Großer Brustmuskel und vorderer Deltamuskel"],
  ["Máquina de fondos sentado","Seated dip machine","Máquina de mergulho sentado","Machine à dips assis","Macchina per dip da seduti","Dipmaschine im Sitzen"],
  ["Sentate en la máquina con la espalda apoyada y las manijas tomadas a los costados del cuerpo con los codos flexionados.","Sit in the machine with your back supported and the handles held at your sides with your elbows bent.","Sente-se na máquina com as costas apoiadas e as alças seguras ao lado do corpo com os cotovelos flexionados.","Assieds-toi dans la machine, dos en appui, poignées tenues sur les côtés, coudes fléchis.","Siediti nella macchina con la schiena appoggiata e le maniglie impugnate ai lati del corpo con i gomiti piegati.","Setz dich mit angelehntem Rücken in die Maschine, die Griffe seitlich gefasst, Ellbogen gebeugt."],
  ["Ajustá el asiento para que las manijas queden a la altura del pecho bajo al empezar.","Adjust the seat so the handles are at lower-chest height at the start.","Ajuste o assento para as alças ficarem na altura da parte baixa do peito ao começar.","Règle le siège pour que les poignées soient à hauteur du bas de la poitrine au départ.","Regola il sedile perché le maniglie siano all’altezza della parte bassa del petto all’inizio.","Stell den Sitz so ein, dass die Griffe zu Beginn auf Höhe der unteren Brust sind."],
  ["Empujá las manijas hacia abajo extendiendo los codos, con los codos cerca del cuerpo.","Push the handles down by extending your elbows, keeping your elbows close to your body.","Empurre as alças para baixo estendendo os cotovelos, com os cotovelos perto do corpo.","Pousse les poignées vers le bas en tendant les coudes, coudes près du corps.","Spingi le maniglie verso il basso distendendo i gomiti, con i gomiti vicini al corpo.","Drück die Griffe durch Strecken der Ellbogen nach unten, Ellbogen nah am Körper."],
  ["Pausá un instante con los brazos extendidos sin bloquear de golpe.","Pause for a moment with your arms extended without snapping into lockout.","Pause um instante com os braços estendidos sem travar de uma vez.","Marque une courte pause bras tendus sans verrouiller brusquement.","Fai una breve pausa con le braccia distese senza bloccare di colpo.","Halte kurz mit gestreckten Armen, ohne ruckartig durchzudrücken."],
  ["Volvé despacio hasta la flexión inicial.","Return slowly to the starting bend.","Volte devagar até a flexão inicial.","Reviens lentement à la flexion de départ.","Torna lentamente alla flessione iniziale.","Kehr langsam in die Ausgangsbeugung zurück."],
  ["Abrir mucho los codos hacia afuera.","Flaring your elbows wide.","Abrir muito os cotovelos para fora.","Écarter fortement les coudes vers l’extérieur.","Aprire molto i gomiti verso l’esterno.","Die Ellbogen weit nach außen ausstellen."],
  ["Dejar que la carga suba de golpe.","Letting the load shoot back up.","Deixar a carga subir de uma vez.","Laisser la charge remonter d’un coup.","Lasciare che il carico risalga di colpo.","Das Gewicht unkontrolliert hochschnellen lassen."],
  ["A diferencia de las paralelas, la máquina permite regular el peso y el rango.","Unlike parallel bars, the machine lets you adjust the weight and range.","Ao contrário das paralelas, a máquina permite regular o peso e a amplitude.","Contrairement aux barres parallèles, la machine permet de régler la charge et l’amplitude.","A differenza delle parallele, la macchina permette di regolare peso e ampiezza.","Anders als am Barren kannst du an der Maschine Gewicht und Bewegungsumfang einstellen."],
  ["Mantené el pecho abierto y la espalda apoyada.","Keep your chest open and your back supported.","Mantenha o peito aberto e as costas apoiadas.","Garde la poitrine ouverte et le dos en appui.","Mantieni il petto aperto e la schiena appoggiata.","Halte die Brust offen und den Rücken angelehnt."],
  ["No bajes más allá del rango cómodo del hombro.","Don’t go lower than your shoulder’s comfortable range.","Não desça além da amplitude confortável do ombro.","Ne descends pas au-delà de l’amplitude confortable de l’épaule.","Non scendere oltre l’ampiezza comoda della spalla.","Geh nicht tiefer, als es für die Schulter angenehm ist."],
  ["Oblicuos y transverso del abdomen","Obliques and transversus abdominis","Oblíquos e transverso do abdômen","Obliques et transverse de l’abdomen","Obliqui e trasverso dell’addome","Schräge Bauchmuskeln und querer Bauchmuskel"],
  ["Recto abdominal, glúteos y estabilizadores del hombro","Rectus abdominis, glutes and shoulder stabilizers","Reto abdominal, glúteos e estabilizadores do ombro","Grand droit de l’abdomen, fessiers et stabilisateurs de l’épaule","Retto addominale, glutei e stabilizzatori della spalla","Gerader Bauchmuskel, Gesäß und Schulterstabilisatoren"],
  ["Polea regulada a la altura del pecho con manija simple","Cable set at chest height with a single handle","Polia regulada na altura do peito com alça simples","Poulie réglée à hauteur de poitrine avec poignée simple","Cavo regolato all’altezza del petto con maniglia singola","Kabelzug auf Brusthöhe mit Einhandgriff"],
  ["Parate de costado a la polea con la manija tomada con ambas manos contra el pecho, pies al ancho de hombros y rodillas suaves.","Stand side-on to the cable holding the handle with both hands against your chest, feet shoulder-width apart and knees soft.","Fique de lado para a polia com a alça segura com as duas mãos contra o peito, pés na largura dos ombros e joelhos soltos.","Tiens-toi de profil par rapport à la poulie, poignée tenue à deux mains contre la poitrine, pieds à la largeur des épaules et genoux souples.","Mettiti di lato rispetto al cavo con la maniglia impugnata con entrambe le mani contro il petto, piedi alla larghezza delle spalle e ginocchia morbide.","Stell dich seitlich zum Kabelzug, den Griff mit beiden Händen an der Brust, Füße schulterbreit, Knie weich."],
  ["Exhalá al extender los brazos y respirá con normalidad durante la pausa.","Exhale as you extend your arms and breathe normally during the hold.","Expire ao estender os braços e respire normalmente durante a pausa.","Expire en tendant les bras et respire normalement pendant le maintien.","Espira distendendo le braccia e respira normalmente durante la pausa.","Atme beim Strecken der Arme aus und während des Haltens normal weiter."],
  ["45–60 segundos entre lados","45–60 seconds between sides","45–60 segundos entre lados","45–60 secondes entre les côtés","45–60 secondi tra i lati","45–60 Sekunden zwischen den Seiten"],
  ["Alejate de la polea hasta que el cable quede tenso y afirmá el abdomen.","Step away from the cable until it is taut and brace your abs.","Afaste-se da polia até o cabo ficar tenso e firme o abdômen.","Éloigne-toi de la poulie jusqu’à ce que le câble soit tendu et gaine les abdos.","Allontanati dal cavo finché è teso e contrai l’addome.","Geh vom Kabelzug weg, bis das Seil gespannt ist, und spann den Bauch an."],
  ["Empujá la manija al frente hasta extender los brazos, sin dejar que el cuerpo gire hacia la polea.","Press the handle forward until your arms are extended, without letting your body rotate toward the cable.","Empurre a alça à frente até estender os braços, sem deixar o corpo girar em direção à polia.","Pousse la poignée devant toi jusqu’à tendre les bras, sans laisser le corps pivoter vers la poulie.","Spingi la maniglia in avanti fino a distendere le braccia, senza lasciare che il corpo ruoti verso il cavo.","Drück den Griff nach vorn, bis die Arme gestreckt sind, ohne dass sich der Körper zum Kabelzug dreht."],
  ["Sostené uno o dos segundos con los brazos extendidos.","Hold for one or two seconds with your arms extended.","Sustente um ou dois segundos com os braços estendidos.","Tiens une ou deux secondes bras tendus.","Mantieni uno o due secondi con le braccia distese.","Halte ein bis zwei Sekunden mit gestreckten Armen."],
  ["Volvé la manija al pecho y completá un lado antes de cambiar al otro.","Bring the handle back to your chest and finish one side before switching to the other.","Volte a alça ao peito e complete um lado antes de trocar para o outro.","Ramène la poignée à la poitrine et termine un côté avant de passer à l’autre.","Riporta la maniglia al petto e completa un lato prima di passare all’altro.","Führ den Griff zur Brust zurück und beende eine Seite, bevor du wechselst."],
  ["Dejar que el tronco rote hacia la polea.","Letting your trunk rotate toward the cable.","Deixar o tronco girar em direção à polia.","Laisser le tronc pivoter vers la poulie.","Lasciare che il tronco ruoti verso il cavo.","Den Rumpf zum Kabelzug drehen lassen."],
  ["Inclinarse hacia el lado contrario para compensar.","Leaning to the opposite side to compensate.","Inclinar-se para o lado oposto para compensar.","Se pencher du côté opposé pour compenser.","Inclinarsi dal lato opposto per compensare.","Sich zum Ausgleich zur Gegenseite neigen."],
  ["El objetivo es resistir la rotación, no mover mucho peso.","The goal is to resist rotation, not to move a lot of weight.","O objetivo é resistir à rotação, não mover muito peso.","Le but est de résister à la rotation, pas de déplacer beaucoup de poids.","L’obiettivo è resistere alla rotazione, non spostare tanto peso.","Ziel ist es, der Rotation zu widerstehen, nicht viel Gewicht zu bewegen."],
  ["Más lejos de la polea aumenta la dificultad.","Standing farther from the cable increases the difficulty.","Mais longe da polia, maior a dificuldade.","Plus tu es loin de la poulie, plus c’est difficile.","Più lontano dal cavo aumenta la difficoltà.","Je weiter du vom Kabelzug weg stehst, desto schwerer wird es."],
  ["Mantené cadera y hombros mirando al frente.","Keep your hips and shoulders facing forward.","Mantenha quadril e ombros voltados para frente.","Garde les hanches et les épaules face à l’avant.","Mantieni anche e spalle rivolte in avanti.","Halte Hüfte und Schultern nach vorn ausgerichtet."],
  ["Oblicuos y cuadrado lumbar","Obliques and quadratus lumborum","Oblíquos e quadrado lombar","Obliques et carré des lombes","Obliqui e quadrato dei lombi","Schräge Bauchmuskeln und quadratischer Lendenmuskel"],
  ["Glúteo medio, transverso del abdomen y estabilizadores del hombro","Gluteus medius, transversus abdominis and shoulder stabilizers","Glúteo médio, transverso do abdômen e estabilizadores do ombro","Moyen fessier, transverse de l’abdomen et stabilisateurs de l’épaule","Medio gluteo, trasverso dell’addome e stabilizzatori della spalla","Mittlerer Gesäßmuskel, querer Bauchmuskel und Schulterstabilisatoren"],
  ["Colchoneta o superficie firme","Mat or firm surface","Colchonete ou superfície firme","Tapis ou surface ferme","Tappetino o superficie stabile","Matte oder fester Untergrund"],
  ["Intermedio; usar rodillas apoyadas si hace falta","Intermediate; rest on your knees if needed","Intermediário; apoie os joelhos se precisar","Intermédiaire ; pose les genoux si nécessaire","Intermedio; appoggia le ginocchia se serve","Fortgeschritten; bei Bedarf auf den Knien abstützen"],
  ["Acostate de costado con el antebrazo apoyado bajo el hombro y las piernas extendidas una sobre otra.","Lie on your side with your forearm under your shoulder and your legs extended, one on top of the other.","Deite-se de lado com o antebraço apoiado sob o ombro e as pernas estendidas uma sobre a outra.","Allonge-toi sur le côté, avant-bras sous l’épaule et jambes tendues l’une sur l’autre.","Sdraiati su un fianco con l’avambraccio sotto la spalla e le gambe distese una sull’altra.","Leg dich auf die Seite, Unterarm unter der Schulter, Beine gestreckt übereinander."],
  ["Respirá de forma pareja durante todo el sostén, sin contener el aire.","Breathe evenly throughout the hold, without holding your breath.","Respire de forma regular durante toda a sustentação, sem prender o ar.","Respire régulièrement pendant tout le maintien, sans bloquer ta respiration.","Respira in modo regolare per tutta la tenuta, senza trattenere il respiro.","Atme während des ganzen Haltens gleichmäßig, ohne die Luft anzuhalten."],
  ["Colocá el codo justo debajo del hombro y apilá los pies o poné uno delante del otro.","Place your elbow directly under your shoulder and stack your feet or put one in front of the other.","Coloque o cotovelo logo abaixo do ombro e empilhe os pés ou coloque um na frente do outro.","Place le coude juste sous l’épaule et superpose les pieds ou mets-en un devant l’autre.","Metti il gomito proprio sotto la spalla e sovrapponi i piedi o mettine uno davanti all’altro.","Setz den Ellbogen direkt unter die Schulter und leg die Füße übereinander oder voreinander."],
  ["Elevá la cadera hasta que el cuerpo forme una línea recta de cabeza a pies.","Lift your hips until your body forms a straight line from head to feet.","Eleve o quadril até o corpo formar uma linha reta da cabeça aos pés.","Monte les hanches jusqu’à ce que le corps forme une ligne droite de la tête aux pieds.","Solleva le anche finché il corpo forma una linea retta dalla testa ai piedi.","Heb die Hüfte, bis dein Körper eine gerade Linie vom Kopf bis zu den Füßen bildet."],
  ["Sostené la posición sin dejar caer la cadera ni girar el tronco, respirando con calma.","Hold the position without letting your hips drop or your trunk rotate, breathing calmly.","Sustente a posição sem deixar o quadril cair nem girar o tronco, respirando com calma.","Tiens la position sans laisser tomber les hanches ni faire pivoter le tronc, en respirant calmement.","Mantieni la posizione senza far cadere le anche né ruotare il tronco, respirando con calma.","Halte die Position, ohne die Hüfte absinken zu lassen oder den Rumpf zu drehen, und atme ruhig."],
  ["Bajá la cadera con control y repetí del otro lado.","Lower your hips with control and repeat on the other side.","Abaixe o quadril com controle e repita do outro lado.","Redescends les hanches en contrôle et recommence de l’autre côté.","Abbassa le anche con controllo e ripeti dall’altro lato.","Senk die Hüfte kontrolliert ab und wiederhol es auf der anderen Seite."],
  ["Dejar caer la cadera hacia el suelo.","Letting your hips drop toward the floor.","Deixar o quadril cair em direção ao chão.","Laisser les hanches tomber vers le sol.","Lasciar cadere le anche verso il pavimento.","Die Hüfte zum Boden absinken lassen."],
  ["Llevar la cadera hacia atrás y salir de la línea.","Pushing your hips back and breaking the line.","Levar o quadril para trás e sair do alinhamento.","Reculer les hanches et sortir de l’alignement.","Portare le anche indietro e uscire dalla linea.","Die Hüfte nach hinten schieben und aus der Linie kommen."],
  ["Encoger el hombro de apoyo hacia la oreja.","Shrugging your supporting shoulder toward your ear.","Encolher o ombro de apoio em direção à orelha.","Hausser l’épaule d’appui vers l’oreille.","Sollevare la spalla d’appoggio verso l’orecchio.","Die Stützschulter zum Ohr hochziehen."],
  ["Empujá el suelo con el antebrazo para estabilizar el hombro.","Push the floor away with your forearm to stabilize your shoulder.","Empurre o chão com o antebraço para estabilizar o ombro.","Pousse le sol avec l’avant-bras pour stabiliser l’épaule.","Spingi il pavimento con l’avambraccio per stabilizzare la spalla.","Drück dich mit dem Unterarm vom Boden weg, um die Schulter zu stabilisieren."],
  ["Si no llegás al tiempo con buena forma, apoyá las rodillas.","If you can’t reach the time with good form, rest on your knees.","Se não chegar ao tempo com boa forma, apoie os joelhos.","Si tu ne tiens pas le temps avec une bonne forme, pose les genoux.","Se non arrivi al tempo con una buona forma, appoggia le ginocchia.","Wenn du die Zeit nicht mit guter Technik schaffst, stütz dich auf die Knie."],
  ["Terminá la serie cuando pierdas la alineación.","End the set when you lose alignment.","Termine a série quando perder o alinhamento.","Arrête la série quand tu perds l’alignement.","Termina la serie quando perdi l’allineamento.","Beende den Satz, sobald du die Linie verlierst."],
  ["Recto abdominal","Rectus abdominis","Reto abdominal","Grand droit de l’abdomen","Retto addominale","Gerader Bauchmuskel"],
  ["Oblicuos","Obliques","Oblíquos","Obliques","Obliqui","Schräge Bauchmuskeln"],
  ["Máquina de crunch abdominal","Ab crunch machine","Máquina de abdominal","Machine à crunch","Macchina per crunch addominali","Bauchmaschine (Crunch)"],
  ["Sentate en la máquina con los pies trabados, la espalda apoyada y las manijas o almohadillas tomadas según el diseño.","Sit in the machine with your feet locked in, back supported and handles or pads held according to the design.","Sente-se na máquina com os pés travados, as costas apoiadas e as alças ou almofadas seguras conforme o modelo.","Assieds-toi dans la machine, pieds bloqués, dos en appui et poignées ou coussins tenus selon le modèle.","Siediti nella macchina con i piedi bloccati, la schiena appoggiata e le maniglie o i cuscinetti impugnati secondo il modello.","Setz dich in die Maschine, Füße fixiert, Rücken angelehnt, Griffe oder Polster je nach Bauart gefasst."],
  ["Exhalá al flexionar el tronco e inhalá al volver.","Exhale as you flex your trunk and inhale as you return.","Expire ao flexionar o tronco e inspire ao voltar.","Expire en fléchissant le tronc et inspire en revenant.","Espira flettendo il tronco e inspira tornando.","Atme beim Einrollen des Rumpfs aus und beim Zurückkehren ein."],
  ["45–60 segundos","45–60 seconds","45–60 segundos","45–60 secondes","45–60 secondi","45–60 Sekunden"],
  ["Ajustá el asiento y elegí una carga liviana para empezar.","Adjust the seat and choose a light load to start.","Ajuste o assento e escolha uma carga leve para começar.","Règle le siège et choisis une charge légère pour commencer.","Regola il sedile e scegli un carico leggero per iniziare.","Stell den Sitz ein und wähle zum Start ein leichtes Gewicht."],
  ["Flexioná el tronco enrollando la columna hacia adelante, acercando las costillas a la pelvis.","Flex your trunk by curling your spine forward, bringing your ribs toward your pelvis.","Flexione o tronco enrolando a coluna para frente, aproximando as costelas da pelve.","Fléchis le tronc en enroulant la colonne vers l’avant, en rapprochant les côtes du bassin.","Fletti il tronco arrotolando la colonna in avanti, avvicinando le costole al bacino.","Roll die Wirbelsäule nach vorn ein und bring die Rippen zum Becken."],
  ["Pausá un instante con el abdomen contraído.","Pause for a moment with your abs contracted.","Pause um instante com o abdômen contraído.","Marque une courte pause, abdos contractés.","Fai una breve pausa con l’addome contratto.","Halte kurz mit angespanntem Bauch."],
  ["Tirar con los brazos en lugar de usar el abdomen.","Pulling with your arms instead of using your abs.","Puxar com os braços em vez de usar o abdômen.","Tirer avec les bras au lieu d’utiliser les abdos.","Tirare con le braccia invece di usare l’addome.","Mit den Armen ziehen statt den Bauch zu benutzen."],
  ["Usar mucha carga y mover el cuerpo con impulso.","Using a lot of load and moving your body with momentum.","Usar muita carga e mover o corpo com impulso.","Utiliser beaucoup de charge et bouger le corps avec de l’élan.","Usare molto carico e muovere il corpo con slancio.","Viel Gewicht nehmen und den Körper mit Schwung bewegen."],
  ["Flexionar desde la cadera sin enrollar la columna.","Bending from the hips without curling your spine.","Flexionar a partir do quadril sem enrolar a coluna.","Fléchir depuis les hanches sans enrouler la colonne.","Flettere dalle anche senza arrotolare la colonna.","Aus der Hüfte beugen, ohne die Wirbelsäule einzurollen."],
  ["Pensá en acercar el esternón al ombligo.","Think about bringing your breastbone toward your belly button.","Pense em aproximar o esterno do umbigo.","Pense à rapprocher le sternum du nombril.","Pensa di avvicinare lo sterno all’ombelico.","Stell dir vor, du bringst das Brustbein zum Bauchnabel."],
  ["El recorrido es corto; priorizá el control.","The range is short; prioritize control.","O movimento é curto; priorize o controle.","L’amplitude est courte ; privilégie le contrôle.","L’ampiezza è breve; dai priorità al controllo.","Der Bewegungsweg ist kurz; Kontrolle hat Vorrang."],
  ["Polea alta con cuerda y colchoneta para las rodillas","High cable with rope and a mat for your knees","Polia alta com corda e colchonete para os joelhos","Poulie haute avec corde et tapis pour les genoux","Cavo alto con corda e tappetino per le ginocchia","Oberer Kabelzug mit Seil und Matte für die Knie"],
  ["Arrodillate frente a la polea alta con la cuerda tomada a los costados de la cabeza y la cadera sobre las rodillas.","Kneel facing the high cable holding the rope beside your head, hips over your knees.","Ajoelhe-se de frente para a polia alta com a corda segura ao lado da cabeça e o quadril sobre os joelhos.","Mets-toi à genoux face à la poulie haute, corde tenue de chaque côté de la tête, hanches au-dessus des genoux.","Inginocchiati di fronte al cavo alto con la corda impugnata ai lati della testa e le anche sopra le ginocchia.","Knie dich vor den oberen Kabelzug, das Seil neben dem Kopf gefasst, Hüfte über den Knien."],
  ["Exhalá al enrollar el tronco e inhalá al volver.","Exhale as you curl your trunk and inhale as you return.","Expire ao enrolar o tronco e inspire ao voltar.","Expire en enroulant le tronc et inspire en revenant.","Espira arrotolando il tronco e inspira tornando.","Atme beim Einrollen des Rumpfs aus und beim Zurückkehren ein."],
  ["Tomá la cuerda, arrodillate a una distancia que tense el cable y mantené las manos junto a la cabeza.","Take the rope, kneel at a distance that tensions the cable and keep your hands by your head.","Pegue a corda, ajoelhe-se a uma distância que tensione o cabo e mantenha as mãos junto à cabeça.","Prends la corde, mets-toi à genoux à une distance qui tend le câble et garde les mains près de la tête.","Prendi la corda, inginocchiati a una distanza che tenda il cavo e tieni le mani vicino alla testa.","Nimm das Seil, knie dich so hin, dass das Seil gespannt ist, und halte die Hände am Kopf."],
  ["Enrollá el tronco hacia abajo llevando los codos hacia los muslos, sin mover la cadera hacia atrás.","Curl your trunk down, bringing your elbows toward your thighs, without moving your hips back.","Enrole o tronco para baixo levando os cotovelos em direção às coxas, sem mover o quadril para trás.","Enroule le tronc vers le bas en amenant les coudes vers les cuisses, sans reculer les hanches.","Arrotola il tronco verso il basso portando i gomiti verso le cosce, senza spostare le anche indietro.","Roll den Rumpf nach unten ein und führ die Ellbogen zu den Oberschenkeln, ohne die Hüfte nach hinten zu schieben."],
  ["Volvé despacio a la posición erguida sin soltar la tensión.","Return slowly to upright without releasing the tension.","Volte devagar à posição ereta sem soltar a tensão.","Reviens lentement en position droite sans relâcher la tension.","Torna lentamente in posizione eretta senza rilasciare la tensione.","Richte dich langsam wieder auf, ohne die Spannung zu lösen."],
  ["Sentarse sobre los talones y hacer el movimiento con la cadera.","Sitting back on your heels and doing the movement with your hips.","Sentar sobre os calcanhares e fazer o movimento com o quadril.","S’asseoir sur les talons et faire le mouvement avec les hanches.","Sedersi sui talloni e fare il movimento con le anche.","Sich auf die Fersen setzen und die Bewegung aus der Hüfte machen."],
  ["Tirar de la cuerda con los brazos.","Pulling the rope with your arms.","Puxar a corda com os braços.","Tirer la corde avec les bras.","Tirare la corda con le braccia.","Mit den Armen am Seil ziehen."],
  ["Usar demasiado peso y perder el control.","Using too much weight and losing control.","Usar peso demais e perder o controle.","Utiliser trop de poids et perdre le contrôle.","Usare troppo peso e perdere il controllo.","Zu viel Gewicht nehmen und die Kontrolle verlieren."],
  ["La cadera queda quieta: solo se mueve la columna.","Your hips stay still: only your spine moves.","O quadril fica parado: só a coluna se move.","Les hanches restent immobiles : seule la colonne bouge.","Le anche restano ferme: si muove solo la colonna.","Die Hüfte bleibt ruhig: Nur die Wirbelsäule bewegt sich."],
  ["Usá una colchoneta para proteger las rodillas.","Use a mat to protect your knees.","Use um colchonete para proteger os joelhos.","Utilise un tapis pour protéger tes genoux.","Usa un tappetino per proteggere le ginocchia.","Nutze eine Matte, um die Knie zu schützen."],
  ["Mantené las manos fijas junto a la cabeza.","Keep your hands fixed by your head.","Mantenha as mãos fixas junto à cabeça.","Garde les mains fixes près de la tête.","Tieni le mani ferme vicino alla testa.","Halte die Hände fest am Kopf."],
  ["Recto abdominal y flexores de cadera","Rectus abdominis and hip flexors","Reto abdominal e flexores do quadril","Grand droit de l’abdomen et fléchisseurs de hanche","Retto addominale e flessori dell’anca","Gerader Bauchmuskel und Hüftbeuger"],
  ["Oblicuos y estabilizadores del hombro","Obliques and shoulder stabilizers","Oblíquos e estabilizadores do ombro","Obliques et stabilisateurs de l’épaule","Obliqui e stabilizzatori della spalla","Schräge Bauchmuskeln und Schulterstabilisatoren"],
  ["Silla romana (estación de elevación de piernas con apoyo de antebrazos)","Captain’s chair (leg raise station with forearm support)","Cadeira romana (estação de elevação de pernas com apoio de antebraços)","Chaise romaine (station de relevés de jambes avec appui des avant-bras)","Sedia romana (stazione per sollevamento gambe con appoggio per avambracci)","Dip-Station mit Unterarmauflage (Captain’s Chair)"],
  ["Subite a la silla romana con los antebrazos en las almohadillas, la espalda contra el respaldo y las piernas colgando.","Get into the captain’s chair with your forearms on the pads, back against the backrest and legs hanging.","Suba na cadeira romana com os antebraços nas almofadas, as costas contra o encosto e as pernas penduradas.","Installe-toi sur la chaise romaine, avant-bras sur les coussins, dos contre le dossier et jambes pendantes.","Sali sulla sedia romana con gli avambracci sui cuscinetti, la schiena contro lo schienale e le gambe sospese.","Stütz dich in der Station mit den Unterarmen auf die Polster, Rücken an der Lehne, Beine hängen."],
  ["Exhalá al subir las rodillas e inhalá al bajarlas.","Exhale as you raise your knees and inhale as you lower them.","Expire ao subir os joelhos e inspire ao abaixá-los.","Expire en montant les genoux et inspire en les abaissant.","Espira sollevando le ginocchia e inspira abbassandole.","Atme beim Hochziehen der Knie aus und beim Senken ein."],
  ["Tomá las manijas, apoyá bien la espalda y dejá colgar las piernas sin balanceo.","Grab the handles, press your back firmly against the pad and let your legs hang without swinging.","Segure as alças, apoie bem as costas e deixe as pernas penduradas sem balançar.","Saisis les poignées, plaque bien le dos et laisse pendre les jambes sans te balancer.","Afferra le maniglie, appoggia bene la schiena e lascia pendere le gambe senza dondolare.","Greif die Griffe, drück den Rücken fest an und lass die Beine ohne Schwingen hängen."],
  ["Elevá las rodillas hacia el pecho flexionando la cadera y enrollando un poco la pelvis.","Raise your knees toward your chest by bending your hips and slightly curling your pelvis.","Eleve os joelhos em direção ao peito flexionando o quadril e enrolando um pouco a pelve.","Monte les genoux vers la poitrine en fléchissant les hanches et en enroulant un peu le bassin.","Solleva le ginocchia verso il petto flettendo le anche e arrotolando un po’ il bacino.","Zieh die Knie zur Brust, indem du die Hüfte beugst und das Becken leicht einrollst."],
  ["Pausá un instante arriba sin despegar la espalda.","Pause for a moment at the top without lifting your back off the pad.","Pause um instante em cima sem descolar as costas.","Marque une courte pause en haut sans décoller le dos.","Fai una breve pausa in alto senza staccare la schiena.","Halte oben kurz, ohne den Rücken zu lösen."],
  ["Bajá las piernas despacio hasta la posición inicial.","Lower your legs slowly to the starting position.","Abaixe as pernas devagar até a posição inicial.","Redescends lentement les jambes jusqu’à la position de départ.","Abbassa lentamente le gambe fino alla posizione iniziale.","Senk die Beine langsam in die Ausgangsposition ab."],
  ["Balancear las piernas para subirlas.","Swinging your legs to raise them.","Balançar as pernas para subi-las.","Balancer les jambes pour les monter.","Far oscillare le gambe per sollevarle.","Mit den Beinen schwingen, um sie hochzubringen."],
  ["Arquear la espalda y separarla del respaldo.","Arching your back and moving it away from the backrest.","Arquear as costas e afastá-las do encosto.","Cambrer le dos et le décoller du dossier.","Inarcare la schiena e staccarla dallo schienale.","Ins Hohlkreuz gehen und den Rücken von der Lehne lösen."],
  ["Dejar caer las piernas en la bajada.","Letting your legs drop on the way down.","Deixar as pernas caírem na descida.","Laisser tomber les jambes à la descente.","Lasciar cadere le gambe in discesa.","Die Beine beim Absenken fallen lassen."],
  ["Enrollar la pelvis al final aumenta el trabajo del abdomen.","Curling your pelvis at the end increases the work for your abs.","Enrolar a pelve no final aumenta o trabalho do abdômen.","Enrouler le bassin à la fin augmente le travail des abdos.","Arrotolare il bacino alla fine aumenta il lavoro dell’addome.","Wenn du das Becken am Ende einrollst, arbeitet der Bauch stärker."],
  ["Mantené los hombros bajos, sin hundirte entre ellos.","Keep your shoulders down, without sinking between them.","Mantenha os ombros baixos, sem afundar entre eles.","Garde les épaules basses, sans t’enfoncer entre elles.","Mantieni le spalle basse, senza sprofondare tra di esse.","Halte die Schultern unten, ohne zwischen ihnen einzusinken."],
  ["Para progresar, extendé más las piernas cuando controles el movimiento.","To progress, extend your legs more once you control the movement.","Para progredir, estenda mais as pernas quando controlar o movimento.","Pour progresser, tends davantage les jambes quand tu maîtrises le mouvement.","Per progredire, distendi di più le gambe quando controlli il movimento.","Zum Steigern streck die Beine weiter, sobald du die Bewegung kontrollierst."],
  ["Oblicuos y flexores de cadera","Obliques and hip flexors","Oblíquos e flexores do quadril","Obliques et fléchisseurs de hanche","Obliqui e flessori dell’anca","Schräge Bauchmuskeln und Hüftbeuger"],
  ["Banco declinado con soporte para piernas","Decline bench with leg support","Banco declinado com apoio para as pernas","Banc décliné avec support pour les jambes","Panca declinata con supporto per le gambe","Negativbank mit Beinhalterung"],
  ["Acostate en el banco declinado con los pies trabados en los rodillos y las manos cruzadas sobre el pecho.","Lie on the decline bench with your feet hooked under the rollers and your hands crossed over your chest.","Deite-se no banco declinado com os pés travados nos rolos e as mãos cruzadas sobre o peito.","Allonge-toi sur le banc décliné, pieds bloqués sous les rouleaux et mains croisées sur la poitrine.","Sdraiati sulla panca declinata con i piedi bloccati sotto i rulli e le mani incrociate sul petto.","Leg dich auf die Negativbank, Füße unter den Rollen fixiert, Hände vor der Brust gekreuzt."],
  ["Trabá los pies y acostate con la espalda apoyada y la cabeza más baja que la cadera.","Lock your feet in and lie back with your back supported and your head lower than your hips.","Trave os pés e deite-se com as costas apoiadas e a cabeça mais baixa que o quadril.","Bloque les pieds et allonge-toi, dos en appui et tête plus basse que les hanches.","Blocca i piedi e sdraiati con la schiena appoggiata e la testa più in basso delle anche.","Fixier die Füße und leg dich hin, Rücken aufgelegt, Kopf tiefer als die Hüfte."],
  ["Enrollá el tronco elevando hombros y espalda alta, acercando las costillas a la pelvis.","Curl your trunk, lifting your shoulders and upper back, bringing your ribs toward your pelvis.","Enrole o tronco elevando os ombros e a parte alta das costas, aproximando as costelas da pelve.","Enroule le tronc en levant les épaules et le haut du dos, en rapprochant les côtes du bassin.","Arrotola il tronco sollevando spalle e parte alta della schiena, avvicinando le costole al bacino.","Roll den Rumpf ein, heb Schultern und oberen Rücken und bring die Rippen zum Becken."],
  ["Pausá un instante arriba sin tirar del cuello.","Pause for a moment at the top without pulling on your neck.","Pause um instante em cima sem puxar o pescoço.","Marque une courte pause en haut sans tirer sur la nuque.","Fai una breve pausa in alto senza tirare il collo.","Halte oben kurz, ohne am Nacken zu ziehen."],
  ["Bajá despacio vértebra por vértebra.","Lower slowly, vertebra by vertebra.","Desça devagar, vértebra por vértebra.","Redescends lentement, vertèbre par vertèbre.","Scendi lentamente, vertebra per vertebra.","Roll langsam Wirbel für Wirbel ab."],
  ["Tirar de la cabeza con las manos.","Pulling your head with your hands.","Puxar a cabeça com as mãos.","Tirer sur la tête avec les mains.","Tirare la testa con le mani.","Mit den Händen am Kopf ziehen."],
  ["Subir con impulso y caer rápido.","Coming up with momentum and dropping fast.","Subir com impulso e cair rápido.","Monter avec de l’élan et retomber vite.","Salire con slancio e ricadere veloce.","Mit Schwung hochkommen und schnell zurückfallen."],
  ["Hacer el movimiento solo con la cadera, sin enrollar la columna.","Doing the movement only from the hips, without curling your spine.","Fazer o movimento só com o quadril, sem enrolar a coluna.","Faire le mouvement uniquement avec les hanches, sans enrouler la colonne.","Fare il movimento solo con le anche, senza arrotolare la colonna.","Die Bewegung nur aus der Hüfte machen, ohne die Wirbelsäule einzurollen."],
  ["A mayor inclinación del banco, mayor dificultad.","The steeper the bench, the harder it gets.","Quanto maior a inclinação do banco, maior a dificuldade.","Plus le banc est incliné, plus c’est difficile.","Maggiore è l’inclinazione della panca, maggiore è la difficoltà.","Je steiler die Bank, desto schwerer."],
  ["Empezá con el banco poco inclinado.","Start with the bench at a slight angle.","Comece com o banco pouco inclinado.","Commence avec le banc peu incliné.","Inizia con la panca poco inclinata.","Beginne mit einer leicht geneigten Bank."],
  ["Mantené la barbilla a un puño del pecho.","Keep your chin a fist’s width from your chest.","Mantenha o queixo a um punho de distância do peito.","Garde le menton à un poing de la poitrine.","Tieni il mento a un pugno di distanza dal petto.","Halte das Kinn eine Faustbreite von der Brust entfernt."],
  ["Antebrazos (agarre), trapecio y musculatura del tronco","Forearms (grip), trapezius and trunk muscles","Antebraços (pegada), trapézio e musculatura do tronco","Avant-bras (préhension), trapèzes et muscles du tronc","Avambracci (presa), trapezio e muscolatura del tronco","Unterarme (Griff), Trapezmuskel und Rumpfmuskulatur"],
  ["Glúteo medio, cuádriceps y pantorrillas","Gluteus medius, quadriceps and calves","Glúteo médio, quadríceps e panturrilhas","Moyen fessier, quadriceps et mollets","Medio gluteo, quadricipiti e polpacci","Mittlerer Gesäßmuskel, Quadrizeps und Waden"],
  ["Dos mancuernas o pesas rusas y un espacio despejado","Two dumbbells or kettlebells and a clear space","Dois halteres ou kettlebells e um espaço livre","Deux haltères ou kettlebells et un espace dégagé","Due manubri o kettlebell e uno spazio libero","Zwei Kurzhanteln oder Kettlebells und freier Platz"],
  ["Parate entre dos mancuernas, levantalas con técnica de peso muerto y quedá erguido con una en cada mano a los costados.","Stand between two dumbbells, lift them with deadlift technique and stand tall with one in each hand at your sides.","Fique entre dois halteres, levante-os com técnica de levantamento terra e fique ereto com um em cada mão ao lado do corpo.","Place-toi entre deux haltères, soulève-les avec la technique du soulevé de terre et tiens-toi droit, un dans chaque main le long du corps.","Mettiti tra due manubri, sollevali con la tecnica dello stacco e resta eretto con uno per mano lungo i fianchi.","Stell dich zwischen zwei Kurzhanteln, heb sie mit Kreuzhebetechnik auf und steh aufrecht mit je einer Hantel seitlich."],
  ["Respirá de forma pareja y continua mientras caminás.","Breathe evenly and continuously while you walk.","Respire de forma regular e contínua enquanto caminha.","Respire de façon régulière et continue en marchant.","Respira in modo regolare e continuo mentre cammini.","Atme beim Gehen gleichmäßig und ohne Unterbrechung."],
  ["Levantá las cargas del suelo con la espalda neutra, flexionando cadera y rodillas.","Lift the weights off the floor with a neutral back, bending your hips and knees.","Levante as cargas do chão com as costas neutras, flexionando quadril e joelhos.","Soulève les charges du sol, dos neutre, en fléchissant hanches et genoux.","Solleva i carichi da terra con la schiena neutra, piegando anche e ginocchia.","Heb die Gewichte mit neutralem Rücken vom Boden, indem du Hüfte und Knie beugst."],
  ["Caminá con pasos cortos y firmes, hombros bajos y tronco erguido.","Walk with short, firm steps, shoulders down and torso upright.","Caminhe com passos curtos e firmes, ombros baixos e tronco ereto.","Marche à petits pas fermes, épaules basses et buste droit.","Cammina con passi corti e decisi, spalle basse e busto eretto.","Geh mit kurzen, festen Schritten, Schultern unten, Oberkörper aufrecht."],
  ["Mantené las cargas quietas a los costados sin que te inclinen.","Keep the weights still at your sides without letting them tip you over.","Mantenha as cargas paradas ao lado do corpo sem que elas te inclinem.","Garde les charges immobiles sur les côtés sans qu’elles te fassent pencher.","Tieni i carichi fermi ai fianchi senza che ti facciano inclinare.","Halte die Gewichte ruhig an den Seiten, ohne dass sie dich zur Seite ziehen."],
  ["Al terminar, apoyalas en el suelo con la misma técnica con que las levantaste.","When you finish, set them on the floor with the same technique you used to lift them.","Ao terminar, apoie-as no chão com a mesma técnica com que as levantou.","À la fin, repose-les au sol avec la même technique que pour les soulever.","Alla fine, appoggiali a terra con la stessa tecnica con cui li hai sollevati.","Setz sie am Ende mit derselben Technik ab, mit der du sie aufgehoben hast."],
  ["Inclinarse hacia un lado o hacia adelante.","Leaning to one side or forward.","Inclinar-se para um lado ou para frente.","Se pencher d’un côté ou vers l’avant.","Inclinarsi su un lato o in avanti.","Sich zur Seite oder nach vorn neigen."],
  ["Soltar las cargas de golpe al terminar.","Dropping the weights abruptly at the end.","Soltar as cargas de uma vez ao terminar.","Lâcher les charges d’un coup à la fin.","Lasciare i carichi di colpo alla fine.","Die Gewichte am Ende einfach fallen lassen."],
  ["Despejá el recorrido antes de empezar.","Clear your path before you start.","Libere o percurso antes de começar.","Dégage le parcours avant de commencer.","Libera il percorso prima di iniziare.","Räum den Weg frei, bevor du startest."],
  ["Mirá al frente y caminá a un ritmo controlado.","Look straight ahead and walk at a controlled pace.","Olhe para frente e caminhe em ritmo controlado.","Regarde devant toi et marche à un rythme contrôlé.","Guarda avanti e cammina a un ritmo controllato.","Schau nach vorn und geh in kontrolliertem Tempo."],
  ["Si el agarre falla, apoyá las cargas antes de que se te resbalen.","If your grip gives out, set the weights down before they slip.","Se a pegada falhar, apoie as cargas antes que escorreguem.","Si ta prise lâche, pose les charges avant qu’elles ne glissent.","Se la presa cede, appoggia i carichi prima che ti scivolino.","Wenn der Griff nachlässt, setz die Gewichte ab, bevor sie dir entgleiten."],
  ["Sistema cardiovascular; cuádriceps y glúteos","Cardiovascular system; quadriceps and glutes","Sistema cardiovascular; quadríceps e glúteos","Système cardiovasculaire ; quadriceps et fessiers","Sistema cardiovascolare; quadricipiti e glutei","Herz-Kreislauf-System; Quadrizeps und Gesäß"],
  ["Isquiotibiales y pantorrillas","Hamstrings and calves","Isquiotibiais e panturrilhas","Ischio-jambiers et mollets","Ischiocrurali e polpacci","Hintere Oberschenkel und Waden"],
  ["Bicicleta estática regulada a tu altura","Stationary bike adjusted to your height","Bicicleta ergométrica ajustada à sua altura","Vélo d’appartement réglé à ta taille","Cyclette regolata alla tua altezza","Ergometer, auf deine Größe eingestellt"],
  ["Sentate con el asiento a la altura de la cadera estando de pie, de modo que la rodilla quede apenas flexionada en el punto más bajo del pedal.","Sit with the seat at hip height when standing, so your knee stays slightly bent at the lowest point of the pedal stroke.","Sente-se com o selim na altura do quadril quando em pé, de modo que o joelho fique levemente flexionado no ponto mais baixo do pedal.","Assieds-toi avec la selle à hauteur de hanche debout, pour que le genou reste légèrement fléchi au point bas de la pédale.","Siediti con il sellino all’altezza dell’anca da in piedi, così che il ginocchio resti leggermente piegato nel punto più basso del pedale.","Stell den Sattel auf Hüfthöhe im Stand ein, sodass das Knie am tiefsten Pedalpunkt leicht gebeugt bleibt."],
  ["Respirá de forma rítmica; si no podés decir una frase corta, bajá la intensidad.","Breathe rhythmically; if you can’t say a short sentence, lower the intensity.","Respire de forma rítmica; se não conseguir dizer uma frase curta, reduza a intensidade.","Respire en rythme ; si tu ne peux pas dire une phrase courte, baisse l’intensité.","Respira in modo ritmico; se non riesci a dire una frase breve, abbassa l’intensità.","Atme rhythmisch; wenn du keinen kurzen Satz sagen kannst, senk die Intensität."],
  ["No aplica: bajá el ritmo gradualmente al terminar","Not applicable: slow down gradually at the end","Não se aplica: reduza o ritmo gradualmente ao terminar","Sans objet : ralentis progressivement à la fin","Non previsto: rallenta gradualmente alla fine","Entfällt: Am Ende langsam das Tempo reduzieren"],
  ["Ajustá el asiento y el manubrio; la espalda debe quedar estable y los hombros relajados.","Adjust the seat and handlebars; your back should stay stable and your shoulders relaxed.","Ajuste o selim e o guidão; as costas devem ficar estáveis e os ombros relaxados.","Règle la selle et le guidon ; le dos doit rester stable et les épaules détendues.","Regola sellino e manubrio; la schiena deve restare stabile e le spalle rilassate.","Stell Sattel und Lenker ein; der Rücken sollte stabil, die Schultern locker sein."],
  ["Empezá pedaleando suave unos minutos con resistencia baja para entrar en calor.","Start pedaling easily for a few minutes with low resistance to warm up.","Comece pedalando leve alguns minutos com resistência baixa para aquecer.","Commence à pédaler doucement quelques minutes avec une faible résistance pour t’échauffer.","Inizia pedalando piano per qualche minuto con resistenza bassa per scaldarti.","Tritt zum Aufwärmen ein paar Minuten locker mit niedrigem Widerstand."],
  ["Subí la resistencia o la cadencia hasta un esfuerzo en el que puedas hablar en frases cortas (prueba del habla).","Raise the resistance or cadence to an effort where you can talk in short sentences (talk test).","Aumente a resistência ou a cadência até um esforço em que consiga falar frases curtas (teste da fala).","Augmente la résistance ou la cadence jusqu’à un effort où tu peux parler par phrases courtes (test de la parole).","Aumenta la resistenza o la cadenza fino a uno sforzo in cui riesci a parlare a frasi brevi (test del parlato).","Erhöh Widerstand oder Trittfrequenz bis zu einer Belastung, bei der du in kurzen Sätzen sprechen kannst (Sprechtest)."],
  ["Mantené una cadencia pareja y bajá el ritmo gradualmente los últimos minutos.","Keep an even cadence and slow down gradually in the last few minutes.","Mantenha uma cadência regular e reduza o ritmo gradualmente nos últimos minutos.","Garde une cadence régulière et ralentis progressivement les dernières minutes.","Mantieni una cadenza costante e rallenta gradualmente negli ultimi minuti.","Halte eine gleichmäßige Trittfrequenz und reduzier in den letzten Minuten schrittweise."],
  ["Asiento demasiado bajo que obliga a flexionar mucho la rodilla.","A seat that is too low, forcing your knee to bend a lot.","Selim baixo demais que obriga a flexionar muito o joelho.","Une selle trop basse qui oblige à trop fléchir le genou.","Sellino troppo basso che costringe a piegare molto il ginocchio.","Ein zu tiefer Sattel, der das Knie stark beugen lässt."],
  ["Encorvar los hombros sobre el manubrio.","Hunching your shoulders over the handlebars.","Curvar os ombros sobre o guidão.","Voûter les épaules au-dessus du guidon.","Incurvare le spalle sul manubrio.","Mit runden Schultern über dem Lenker hängen."],
  ["Empezar con resistencia alta sin entrar en calor.","Starting with high resistance without warming up.","Começar com resistência alta sem aquecer.","Commencer avec une résistance élevée sans échauffement.","Iniziare con resistenza alta senza riscaldamento.","Ohne Aufwärmen mit hohem Widerstand starten."],
  ["Mantené las rodillas alineadas con los pies durante el pedaleo.","Keep your knees aligned with your feet as you pedal.","Mantenha os joelhos alinhados com os pés durante a pedalada.","Garde les genoux alignés avec les pieds pendant le pédalage.","Mantieni le ginocchia allineate con i piedi durante la pedalata.","Halte die Knie beim Treten in einer Linie mit den Füßen."],
  ["La prueba del habla es una guía simple: esfuerzo moderado es poder hablar pero no cantar.","The talk test is a simple guide: moderate effort means you can talk but not sing.","O teste da fala é um guia simples: esforço moderado é conseguir falar, mas não cantar.","Le test de la parole est un repère simple : un effort modéré, c’est pouvoir parler mais pas chanter.","Il test del parlato è una guida semplice: sforzo moderato significa riuscire a parlare ma non a cantare.","Der Sprechtest ist eine einfache Orientierung: Bei moderater Belastung kannst du sprechen, aber nicht singen."],
  ["Parar de golpe no es necesario: terminá pedaleando suave.","There is no need to stop abruptly: finish by pedaling easily.","Não é preciso parar de uma vez: termine pedalando leve.","Inutile de t’arrêter net : termine en pédalant doucement.","Non serve fermarsi di colpo: termina pedalando piano.","Du musst nicht abrupt aufhören: Tritt zum Schluss locker aus."],
  ["Sistema cardiovascular; glúteos, isquiotibiales y pantorrillas","Cardiovascular system; glutes, hamstrings and calves","Sistema cardiovascular; glúteos, isquiotibiais e panturrilhas","Système cardiovasculaire ; fessiers, ischio-jambiers et mollets","Sistema cardiovascolare; glutei, ischiocrurali e polpacci","Herz-Kreislauf-System; Gesäß, hintere Oberschenkel und Waden"],
  ["Cuádriceps y tronco estabilizador","Quadriceps and stabilizing trunk","Quadríceps e tronco estabilizador","Quadriceps et tronc stabilisateur","Quadricipiti e tronco stabilizzatore","Quadrizeps und stabilisierender Rumpf"],
  ["Cinta de correr con inclinación regulable y llave o clip de seguridad","Treadmill with adjustable incline and safety key or clip","Esteira com inclinação regulável e chave ou clipe de segurança","Tapis de course avec inclinaison réglable et clé ou pince de sécurité","Tapis roulante con inclinazione regolabile e chiave o clip di sicurezza","Laufband mit verstellbarer Steigung und Sicherheitsschlüssel oder -clip"],
  ["Subite a la cinta detenida, colocá el clip de seguridad y empezá a caminar a velocidad baja sin inclinación.","Step onto the stopped treadmill, attach the safety clip and start walking at a low speed with no incline.","Suba na esteira parada, prenda o clipe de segurança e comece a caminhar em velocidade baixa sem inclinação.","Monte sur le tapis à l’arrêt, accroche la pince de sécurité et commence à marcher lentement sans inclinaison.","Sali sul tapis roulant fermo, aggancia la clip di sicurezza e inizia a camminare a bassa velocità senza inclinazione.","Steig auf das stehende Laufband, befestige den Sicherheitsclip und geh ohne Steigung langsam los."],
  ["Respirá de forma rítmica y continua; si te falta el aire para hablar, reducí velocidad o inclinación.","Breathe rhythmically and continuously; if you are too out of breath to talk, reduce the speed or incline.","Respire de forma rítmica e contínua; se faltar ar para falar, reduza velocidade ou inclinação.","Respire de façon rythmée et continue ; si tu manques de souffle pour parler, réduis la vitesse ou l’inclinaison.","Respira in modo ritmico e continuo; se ti manca il fiato per parlare, riduci velocità o inclinazione.","Atme rhythmisch und gleichmäßig; wenn dir die Luft zum Sprechen fehlt, reduzier Tempo oder Steigung."],
  ["Sujetá el clip de seguridad a tu ropa y arrancá a velocidad lenta con los pies sobre la banda.","Attach the safety clip to your clothing and start at a slow speed with your feet on the belt.","Prenda o clipe de segurança na roupa e comece em velocidade lenta com os pés sobre a lona.","Accroche la pince de sécurité à tes vêtements et démarre lentement, pieds sur la bande.","Aggancia la clip di sicurezza ai vestiti e parti a velocità lenta con i piedi sul nastro.","Befestige den Sicherheitsclip an deiner Kleidung und starte langsam mit den Füßen auf dem Band."],
  ["Caminá unos minutos para entrar en calor y luego subí la inclinación de forma suave.","Walk for a few minutes to warm up, then raise the incline gradually.","Caminhe alguns minutos para aquecer e depois aumente a inclinação de forma suave.","Marche quelques minutes pour t’échauffer, puis augmente doucement l’inclinaison.","Cammina qualche minuto per scaldarti e poi aumenta gradualmente l’inclinazione.","Geh ein paar Minuten zum Aufwärmen und erhöh dann die Steigung behutsam."],
  ["Ajustá velocidad e inclinación para que puedas hablar en frases cortas (prueba del habla).","Adjust speed and incline so you can talk in short sentences (talk test).","Ajuste velocidade e inclinação para conseguir falar frases curtas (teste da fala).","Règle la vitesse et l’inclinaison pour pouvoir parler par phrases courtes (test de la parole).","Regola velocità e inclinazione in modo da riuscire a parlare a frasi brevi (test del parlato).","Stell Tempo und Steigung so ein, dass du in kurzen Sätzen sprechen kannst (Sprechtest)."],
  ["Al terminar, bajá la inclinación y la velocidad poco a poco antes de detener la cinta.","When you finish, lower the incline and speed gradually before stopping the treadmill.","Ao terminar, reduza a inclinação e a velocidade aos poucos antes de parar a esteira.","À la fin, baisse progressivement l’inclinaison et la vitesse avant d’arrêter le tapis.","Alla fine, riduci poco a poco inclinazione e velocità prima di fermare il tapis roulant.","Reduzier am Ende Steigung und Tempo nach und nach, bevor du das Laufband stoppst."],
  ["Agarrarse fuerte del manubrio y colgarse de él.","Gripping the handrail hard and hanging on it.","Segurar forte no apoio e se pendurar nele.","S’agripper fort aux poignées et s’y suspendre.","Aggrapparsi forte al corrimano e appendersi.","Sich fest an den Haltegriffen festklammern und daran hängen."],
  ["Subir mucho la inclinación de golpe.","Raising the incline a lot all at once.","Aumentar muito a inclinação de uma vez.","Augmenter fortement l’inclinaison d’un coup.","Aumentare molto l’inclinazione di colpo.","Die Steigung auf einmal stark erhöhen."],
  ["Bajarse con la banda en movimiento.","Stepping off while the belt is moving.","Descer com a lona em movimento.","Descendre pendant que la bande tourne.","Scendere con il nastro in movimento.","Absteigen, während das Band noch läuft."],
  ["Caminá erguido, con pasos naturales y brazos sueltos.","Walk tall, with natural steps and loose arms.","Caminhe ereto, com passos naturais e braços soltos.","Marche droit, à pas naturels et bras relâchés.","Cammina eretto, con passi naturali e braccia sciolte.","Geh aufrecht mit natürlichen Schritten und lockeren Armen."],
  ["Mantenete en el centro de la banda.","Stay in the center of the belt.","Mantenha-se no centro da lona.","Reste au centre de la bande.","Resta al centro del nastro.","Bleib in der Mitte des Bandes."],
  ["Una inclinación suave aumenta el esfuerzo sin necesidad de correr.","A gentle incline increases the effort without needing to run.","Uma inclinação suave aumenta o esforço sem precisar correr.","Une légère inclinaison augmente l’effort sans avoir besoin de courir.","Un’inclinazione leggera aumenta lo sforzo senza bisogno di correre.","Eine leichte Steigung erhöht die Belastung, ohne dass du laufen musst."],
  ["Isquiotibiales, pantorrillas, pecho, espalda y brazos si usás los manubrios móviles","Hamstrings, calves, chest, back and arms if you use the moving handles","Isquiotibiais, panturrilhas, peito, costas e braços se usar os apoios móveis","Ischio-jambiers, mollets, pectoraux, dos et bras si tu utilises les poignées mobiles","Ischiocrurali, polpacci, petto, schiena e braccia se usi le maniglie mobili","Hintere Oberschenkel, Waden, Brust, Rücken und Arme, wenn du die beweglichen Griffe nutzt"],
  ["Máquina elíptica","Elliptical trainer","Elíptico","Vélo elliptique","Ellittica","Crosstrainer"],
  ["Subite a la elíptica con los pies completos sobre los pedales y las manos en los manubrios, con el tronco erguido.","Step onto the elliptical with your whole feet on the pedals and hands on the handles, torso upright.","Suba no elíptico com os pés inteiros sobre os pedais e as mãos nos apoios, com o tronco ereto.","Monte sur l’elliptique, pieds entiers sur les pédales et mains sur les poignées, buste droit.","Sali sull’ellittica con i piedi interi sui pedali e le mani sulle maniglie, con il busto eretto.","Steig auf den Crosstrainer, ganze Füße auf den Pedalen, Hände an den Griffen, Oberkörper aufrecht."],
  ["Respirá de forma rítmica y pareja; usá la prueba del habla para regular la intensidad.","Breathe rhythmically and evenly; use the talk test to regulate the intensity.","Respire de forma rítmica e regular; use o teste da fala para regular a intensidade.","Respire en rythme et régulièrement ; utilise le test de la parole pour régler l’intensité.","Respira in modo ritmico e regolare; usa il test del parlato per regolare l’intensità.","Atme rhythmisch und gleichmäßig; nutze den Sprechtest, um die Intensität zu steuern."],
  ["Arrancá a ritmo lento con resistencia baja durante unos minutos.","Start at a slow pace with low resistance for a few minutes.","Comece em ritmo lento com resistência baixa por alguns minutos.","Commence à un rythme lent avec une faible résistance pendant quelques minutes.","Inizia a ritmo lento con resistenza bassa per qualche minuto.","Starte ein paar Minuten langsam mit niedrigem Widerstand."],
  ["Empujá y tirá de los manubrios de forma coordinada con las piernas, sin despegar los pies.","Push and pull the handles in coordination with your legs, without lifting your feet.","Empurre e puxe os apoios de forma coordenada com as pernas, sem tirar os pés.","Pousse et tire les poignées en coordination avec les jambes, sans décoller les pieds.","Spingi e tira le maniglie in coordinazione con le gambe, senza sollevare i piedi.","Drück und zieh die Griffe im Takt mit den Beinen, ohne die Füße abzuheben."],
  ["Ajustá resistencia y ritmo a un esfuerzo moderado en el que puedas hablar en frases cortas (prueba del habla).","Adjust resistance and pace to a moderate effort where you can talk in short sentences (talk test).","Ajuste resistência e ritmo a um esforço moderado em que consiga falar frases curtas (teste da fala).","Règle la résistance et le rythme sur un effort modéré où tu peux parler par phrases courtes (test de la parole).","Regola resistenza e ritmo su uno sforzo moderato in cui riesci a parlare a frasi brevi (test del parlato).","Stell Widerstand und Tempo auf eine moderate Belastung ein, bei der du in kurzen Sätzen sprechen kannst (Sprechtest)."],
  ["Bajá el ritmo gradualmente los últimos minutos antes de bajarte.","Slow down gradually in the last few minutes before stepping off.","Reduza o ritmo gradualmente nos últimos minutos antes de descer.","Ralentis progressivement les dernières minutes avant de descendre.","Rallenta gradualmente negli ultimi minuti prima di scendere.","Reduzier das Tempo in den letzten Minuten schrittweise, bevor du absteigst."],
  ["Apoyarse con todo el peso en los manubrios.","Leaning your full weight on the handles.","Apoiar todo o peso nos apoios.","S’appuyer de tout son poids sur les poignées.","Appoggiare tutto il peso sulle maniglie.","Sich mit dem ganzen Gewicht auf die Griffe stützen."],
  ["Levantar los talones y empujar solo con la punta del pie.","Lifting your heels and pushing only with your toes.","Levantar os calcanhares e empurrar só com a ponta do pé.","Lever les talons et pousser uniquement avec la pointe du pied.","Sollevare i talloni e spingere solo con la punta del piede.","Die Fersen anheben und nur mit den Zehen drücken."],
  ["Inclinar mucho el tronco hacia adelante.","Leaning your torso far forward.","Inclinar muito o tronco para frente.","Pencher fortement le buste vers l’avant.","Inclinare molto il busto in avanti.","Den Oberkörper stark nach vorn neigen."],
  ["Es una opción de bajo impacto porque los pies no golpean el suelo.","It is a low-impact option because your feet don’t strike the ground.","É uma opção de baixo impacto porque os pés não batem no chão.","C’est une option à faible impact car les pieds ne frappent pas le sol.","È un’opzione a basso impatto perché i piedi non colpiscono il suolo.","Es ist eine gelenkschonende Option, weil die Füße nicht auf den Boden aufschlagen."],
  ["Mantené las rodillas alineadas con los pies.","Keep your knees aligned with your feet.","Mantenha os joelhos alinhados com os pés.","Garde les genoux alignés avec les pieds.","Mantieni le ginocchia allineate con i piedi.","Halte die Knie in einer Linie mit den Füßen."],
  ["Esperá a que los pedales se detengan antes de bajarte.","Wait for the pedals to stop before stepping off.","Espere os pedais pararem antes de descer.","Attends que les pédales s’arrêtent avant de descendre.","Aspetta che i pedali si fermino prima di scendere.","Warte, bis die Pedale stillstehen, bevor du absteigst."],
  ["Sistema cardiovascular; cuádriceps, glúteos y dorsales","Cardiovascular system; quadriceps, glutes and lats","Sistema cardiovascular; quadríceps, glúteos e dorsais","Système cardiovasculaire ; quadriceps, fessiers et dorsaux","Sistema cardiovascolare; quadricipiti, glutei e dorsali","Herz-Kreislauf-System; Quadrizeps, Gesäß und Latissimus"],
  ["Isquiotibiales, bíceps, romboides y core","Hamstrings, biceps, rhomboids and core","Isquiotibiais, bíceps, romboides e core","Ischio-jambiers, biceps, rhomboïdes et sangle abdominale","Ischiocrurali, bicipiti, romboidi e core","Hintere Oberschenkel, Bizeps, Rautenmuskeln und Rumpf"],
  ["Remo ergómetro con apoyapiés regulados","Rowing machine with adjusted footrests","Remo ergômetro com apoios de pés ajustados","Rameur avec cale-pieds réglés","Vogatore con poggiapiedi regolati","Rudergerät mit eingestellten Fußstützen"],
  ["Principiante; requiere aprender la secuencia piernas-tronco-brazos","Beginner; requires learning the legs–trunk–arms sequence","Iniciante; exige aprender a sequência pernas-tronco-braços","Débutant ; demande d’apprendre la séquence jambes-tronc-bras","Principiante; richiede di imparare la sequenza gambe-tronco-braccia","Anfänger; erfordert das Erlernen der Abfolge Beine–Rumpf–Arme"],
  ["Sentate en el carro con los pies sujetos por las correas, rodillas flexionadas y la manija tomada con los brazos extendidos.","Sit on the seat with your feet strapped in, knees bent and the handle held with your arms extended.","Sente-se no carrinho com os pés presos pelas correias, joelhos flexionados e a manopla segura com os braços estendidos.","Assieds-toi sur le chariot, pieds sanglés, genoux fléchis et poignée tenue bras tendus.","Siediti sul carrello con i piedi fissati dalle cinghie, ginocchia piegate e la maniglia impugnata con le braccia distese.","Setz dich auf den Rollsitz, Füße festgeschnallt, Knie gebeugt, den Griff mit gestreckten Armen gefasst."],
  ["Exhalá durante la tracción e inhalá en el regreso, manteniendo un ritmo constante.","Exhale during the drive and inhale on the recovery, keeping a steady rhythm.","Expire durante a puxada e inspire no retorno, mantendo um ritmo constante.","Expire pendant la traction et inspire au retour, en gardant un rythme régulier.","Espira durante la trazione e inspira nel ritorno, mantenendo un ritmo costante.","Atme beim Durchzug aus und beim Zurückrollen ein, in gleichmäßigem Rhythmus."],
  ["Ajustá las correas sobre la parte ancha del pie y empezá con resistencia baja.","Fasten the straps over the widest part of your foot and start with low resistance.","Ajuste as correias sobre a parte larga do pé e comece com resistência baixa.","Serre les sangles sur la partie large du pied et commence avec une faible résistance.","Stringi le cinghie sulla parte larga del piede e inizia con resistenza bassa.","Zieh die Riemen über der breitesten Stelle des Fußes fest und starte mit niedrigem Widerstand."],
  ["En la tracción, empujá primero con las piernas, después inclinate apenas hacia atrás y por último llevá la manija al abdomen bajo.","On the drive, push first with your legs, then lean back slightly and finally pull the handle to your lower abdomen.","Na puxada, empurre primeiro com as pernas, depois incline-se levemente para trás e por último leve a manopla ao abdômen baixo.","Pendant la traction, pousse d’abord avec les jambes, puis penche-toi légèrement en arrière et enfin amène la poignée au bas de l’abdomen.","Nella trazione, spingi prima con le gambe, poi inclinati appena indietro e infine porta la maniglia al basso addome.","Drück beim Durchzug zuerst mit den Beinen, lehn dich dann leicht zurück und zieh zuletzt den Griff zum Unterbauch."],
  ["Volvé en orden inverso: brazos adelante, tronco al frente y luego flexioná las rodillas.","Return in reverse order: arms forward, torso forward and then bend your knees.","Volte na ordem inversa: braços à frente, tronco à frente e depois flexione os joelhos.","Reviens dans l’ordre inverse : bras devant, buste en avant, puis fléchis les genoux.","Torna in ordine inverso: braccia avanti, busto avanti e poi piega le ginocchia.","Kehr in umgekehrter Reihenfolge zurück: Arme nach vorn, Oberkörper nach vorn, dann die Knie beugen."],
  ["Mantené un ritmo suave en el que puedas hablar en frases cortas (prueba del habla) y bajá la intensidad al final.","Keep an easy pace where you can talk in short sentences (talk test) and lower the intensity at the end.","Mantenha um ritmo leve em que consiga falar frases curtas (teste da fala) e reduza a intensidade no final.","Garde un rythme facile où tu peux parler par phrases courtes (test de la parole) et baisse l’intensité à la fin.","Mantieni un ritmo leggero in cui riesci a parlare a frasi brevi (test del parlato) e abbassa l’intensità alla fine.","Halte ein lockeres Tempo, bei dem du in kurzen Sätzen sprechen kannst (Sprechtest), und senk am Ende die Intensität."],
  ["Tirar con los brazos antes de empujar con las piernas.","Pulling with your arms before pushing with your legs.","Puxar com os braços antes de empurrar com as pernas.","Tirer avec les bras avant de pousser avec les jambes.","Tirare con le braccia prima di spingere con le gambe.","Mit den Armen ziehen, bevor die Beine drücken."],
  ["Redondear la espalda al ir hacia adelante.","Rounding your back as you come forward.","Arredondar as costas ao ir para frente.","Arrondir le dos en revenant vers l’avant.","Arrotondare la schiena andando in avanti.","Den Rücken beim Vorrollen runden."],
  ["Inclinarse demasiado hacia atrás al final de la tracción.","Leaning too far back at the end of the drive.","Inclinar-se demais para trás no final da puxada.","Se pencher trop en arrière en fin de traction.","Inclinarsi troppo indietro alla fine della trazione.","Sich am Ende des Durchzugs zu weit nach hinten lehnen."],
  ["La fuerza sale mayormente de las piernas.","Most of the power comes from your legs.","A força vem principalmente das pernas.","La force vient surtout des jambes.","La forza viene soprattutto dalle gambe.","Die Kraft kommt größtenteils aus den Beinen."],
  ["El regreso es más lento que la tracción.","The recovery is slower than the drive.","O retorno é mais lento que a puxada.","Le retour est plus lent que la traction.","Il ritorno è più lento della trazione.","Das Zurückrollen ist langsamer als der Durchzug."],
  ["Mantené los hombros relajados y las muñecas rectas.","Keep your shoulders relaxed and your wrists straight.","Mantenha os ombros relaxados e os punhos retos.","Garde les épaules détendues et les poignets droits.","Mantieni le spalle rilassate e i polsi dritti.","Halte die Schultern locker und die Handgelenke gerade."],
  ["Sistema cardiovascular; glúteos y cuádriceps","Cardiovascular system; glutes and quadriceps","Sistema cardiovascular; glúteos e quadríceps","Système cardiovasculaire ; fessiers et quadriceps","Sistema cardiovascolare; glutei e quadricipiti","Herz-Kreislauf-System; Gesäß und Quadrizeps"],
  ["Máquina escaladora de escalones o de pedales","Stair climber or stepper machine","Simulador de escada ou de pedais","Simulateur d’escalier ou stepper","Macchina stair climber o stepper","Treppensteiger oder Stepper"],
  ["Subite a la máquina detenida, apoyá los pies completos en los escalones y tomá los pasamanos con suavidad.","Step onto the stopped machine, place your whole feet on the steps and hold the handrails lightly.","Suba na máquina parada, apoie os pés inteiros nos degraus e segure os corrimãos com suavidade.","Monte sur la machine à l’arrêt, pose les pieds entiers sur les marches et tiens légèrement les rampes.","Sali sulla macchina ferma, appoggia i piedi interi sui gradini e tieni i corrimano con leggerezza.","Steig auf das stehende Gerät, setz die ganzen Füße auf die Stufen und halte dich locker an den Griffen."],
  ["Respirá de forma rítmica y continua; si no podés hablar en frases cortas, bajá la velocidad.","Breathe rhythmically and continuously; if you can’t talk in short sentences, slow down.","Respire de forma rítmica e contínua; se não conseguir falar frases curtas, reduza a velocidade.","Respire en rythme et en continu ; si tu ne peux pas parler par phrases courtes, ralentis.","Respira in modo ritmico e continuo; se non riesci a parlare a frasi brevi, rallenta.","Atme rhythmisch und gleichmäßig; wenn du nicht in kurzen Sätzen sprechen kannst, werde langsamer."],
  ["Arrancá a velocidad baja y apoyá todo el pie en cada escalón.","Start at a low speed and place your whole foot on each step.","Comece em velocidade baixa e apoie o pé inteiro em cada degrau.","Commence à faible vitesse et pose tout le pied sur chaque marche.","Inizia a bassa velocità e appoggia tutto il piede su ogni gradino.","Starte langsam und setz auf jede Stufe den ganzen Fuß."],
  ["Subí con el tronco erguido, usando los pasamanos solo para el equilibrio.","Climb with your torso upright, using the handrails only for balance.","Suba com o tronco ereto, usando os corrimãos só para o equilíbrio.","Monte le buste droit, en utilisant les rampes seulement pour l’équilibre.","Sali con il busto eretto, usando i corrimano solo per l’equilibrio.","Steig mit aufrechtem Oberkörper und nutze die Griffe nur zum Gleichgewicht."],
  ["Regulá la velocidad a un esfuerzo en el que puedas hablar en frases cortas (prueba del habla).","Set the speed to an effort where you can talk in short sentences (talk test).","Regule a velocidade a um esforço em que consiga falar frases curtas (teste da fala).","Règle la vitesse sur un effort où tu peux parler par phrases courtes (test de la parole).","Regola la velocità su uno sforzo in cui riesci a parlare a frasi brevi (test del parlato).","Stell das Tempo auf eine Belastung ein, bei der du in kurzen Sätzen sprechen kannst (Sprechtest)."],
  ["Bajá la velocidad de a poco antes de detenerte y bajarte.","Slow down gradually before stopping and stepping off.","Reduza a velocidade aos poucos antes de parar e descer.","Ralentis progressivement avant de t’arrêter et de descendre.","Rallenta poco a poco prima di fermarti e scendere.","Werde nach und nach langsamer, bevor du anhältst und absteigst."],
  ["Colgarse de los pasamanos e inclinarse sobre la máquina.","Hanging on the handrails and leaning over the machine.","Pendurar-se nos corrimãos e inclinar-se sobre a máquina.","S’accrocher aux rampes et se pencher sur la machine.","Appendersi ai corrimano e inclinarsi sulla macchina.","Sich an die Griffe hängen und über das Gerät lehnen."],
  ["Pisar solo con la punta del pie.","Stepping only on your toes.","Pisar só com a ponta do pé.","Marcher uniquement sur la pointe des pieds.","Appoggiare solo la punta del piede.","Nur mit den Zehenspitzen auftreten."],
  ["Elegir una velocidad que no podés sostener con buena postura.","Choosing a speed you can’t sustain with good posture.","Escolher uma velocidade que você não consegue sustentar com boa postura.","Choisir une vitesse que tu ne peux pas tenir avec une bonne posture.","Scegliere una velocità che non riesci a sostenere con una buona postura.","Ein Tempo wählen, das du mit guter Haltung nicht halten kannst."],
  ["Pasos completos y estables rinden más que pasos cortos y rápidos.","Full, stable steps work better than short, fast ones.","Passos completos e estáveis rendem mais que passos curtos e rápidos.","Des pas complets et stables sont plus efficaces que des pas courts et rapides.","Passi completi e stabili rendono più di passi corti e veloci.","Volle, stabile Schritte bringen mehr als kurze, schnelle."],
  ["Bajate solo con la máquina detenida.","Step off only when the machine has stopped.","Desça só com a máquina parada.","Descends uniquement quand la machine est à l’arrêt.","Scendi solo con la macchina ferma.","Steig erst ab, wenn das Gerät stillsteht."],
  ["Peso corporal y una pared, mesa firme o respaldo estable para apoyar una mano","Bodyweight and a wall, sturdy table or stable chair back to rest one hand on","Peso corporal e uma parede, mesa firme ou encosto estável para apoiar uma mão","Poids du corps et un mur, une table solide ou un dossier stable pour poser une main","Corpo libero e una parete, un tavolo stabile o uno schienale fermo per appoggiare una mano","Körpergewicht und eine Wand, ein stabiler Tisch oder eine feste Stuhllehne zum Abstützen einer Hand"],
  ["Parate en posición de paso largo al lado de un apoyo firme, con una mano sobre él, un pie adelante y el otro atrás sobre la punta.","Stand in a long split stance next to a sturdy support, one hand on it, one foot forward and the other back on the ball of the foot.","Fique em posição de passada longa ao lado de um apoio firme, com uma mão sobre ele, um pé à frente e o outro atrás na ponta.","Place-toi en grande fente à côté d’un appui solide, une main dessus, un pied devant et l’autre derrière sur la pointe.","Mettiti in posizione di affondo lungo accanto a un appoggio stabile, con una mano sopra, un piede avanti e l’altro dietro sulla punta.","Stell dich in eine lange Schrittstellung neben eine feste Stütze, eine Hand darauf, ein Fuß vorn, der andere hinten auf dem Fußballen."],
  ["Elegí un apoyo que no pueda deslizarse ni volcar y separá los pies al ancho de cadera.","Choose a support that can’t slide or tip over and set your feet hip-width apart.","Escolha um apoio que não possa deslizar nem tombar e separe os pés na largura do quadril.","Choisis un appui qui ne peut ni glisser ni basculer et écarte les pieds à la largeur des hanches.","Scegli un appoggio che non possa scivolare né ribaltarsi e separa i piedi alla larghezza delle anche.","Wähle eine Stütze, die weder rutschen noch kippen kann, und stell die Füße hüftbreit."],
  ["Bajá en vertical flexionando ambas rodillas hasta un rango cómodo, usando la mano solo para el equilibrio.","Lower straight down by bending both knees to a comfortable range, using your hand only for balance.","Desça na vertical flexionando os dois joelhos até uma amplitude confortável, usando a mão só para o equilíbrio.","Descends à la verticale en fléchissant les deux genoux jusqu’à une amplitude confortable, en utilisant la main seulement pour l’équilibre.","Scendi in verticale piegando entrambe le ginocchia fino a un’ampiezza comoda, usando la mano solo per l’equilibrio.","Senk dich senkrecht durch Beugen beider Knie bis zu einem angenehmen Bewegungsumfang ab; die Hand dient nur dem Gleichgewicht."],
  ["Empujá con el pie de adelante para subir sin mover los pies.","Push through your front foot to rise without moving your feet.","Empurre com o pé da frente para subir sem mudar os pés de lugar.","Pousse sur le pied avant pour remonter sans déplacer les pieds.","Spingi con il piede anteriore per salire senza spostare i piedi.","Drück dich über den vorderen Fuß hoch, ohne die Füße zu versetzen."],
  ["Apoyarse con mucha fuerza en la mano y quitar trabajo a las piernas.","Leaning hard on your hand and taking work away from your legs.","Apoiar-se com muita força na mão e tirar trabalho das pernas.","S’appuyer fortement sur la main et retirer du travail aux jambes.","Appoggiarsi con forza sulla mano e togliere lavoro alle gambe.","Sich stark auf die Hand stützen und den Beinen Arbeit abnehmen."],
  ["Poner los pies en una misma línea.","Placing your feet in a single line.","Colocar os pés na mesma linha.","Placer les pieds sur une même ligne.","Mettere i piedi sulla stessa linea.","Die Füße auf eine Linie stellen."],
  ["El apoyo reduce la demanda de equilibrio, por eso es más fácil que la versión libre.","The support reduces the balance demand, so it is easier than the free version.","O apoio reduz a exigência de equilíbrio, por isso é mais fácil que a versão livre.","L’appui réduit la demande d’équilibre, c’est donc plus facile que la version libre.","L’appoggio riduce la richiesta di equilibrio, per questo è più facile della versione libera.","Die Stütze verringert die Gleichgewichtsanforderung, daher ist es leichter als die freie Variante."],
  ["Mantené el tronco erguido.","Keep your torso upright.","Mantenha o tronco ereto.","Garde le buste droit.","Mantieni il busto eretto.","Halte den Oberkörper aufrecht."],
  ["Cuando ganes estabilidad, usá menos la mano.","As you gain stability, use your hand less.","Quando ganhar estabilidade, use menos a mão.","À mesure que tu gagnes en stabilité, utilise moins la main.","Quando acquisisci stabilità, usa meno la mano.","Sobald du stabiler wirst, nutze die Hand weniger."],
  ["Dos mancuernas y espacio libre detrás","Two dumbbells and clear space behind you","Dois halteres e espaço livre atrás","Deux haltères et un espace dégagé derrière toi","Due manubri e spazio libero dietro","Zwei Kurzhanteln und freier Platz hinter dir"],
  ["Parate erguido con los pies al ancho de cadera y una mancuerna en cada mano a los costados.","Stand upright with your feet hip-width apart and a dumbbell in each hand at your sides.","Fique ereto com os pés na largura do quadril e um halter em cada mão ao lado do corpo.","Tiens-toi droit, pieds à la largeur des hanches, un haltère dans chaque main le long du corps.","Mettiti dritto con i piedi alla larghezza delle anche e un manubrio per mano lungo i fianchi.","Stell dich aufrecht hin, Füße hüftbreit, je eine Kurzhantel seitlich."],
  ["Inhalá al bajar y exhalá al volver a pararte.","Inhale as you lower and exhale as you stand back up.","Inspire ao descer e expire ao voltar a ficar em pé.","Inspire en descendant et expire en te relevant.","Inspira scendendo ed espira tornando in piedi.","Atme beim Absenken ein und beim Aufrichten aus."],
  ["Dá un paso largo hacia atrás apoyando la punta del pie trasero.","Take a long step back, landing on the ball of your back foot.","Dê um passo longo para trás apoiando a ponta do pé de trás.","Fais un grand pas en arrière en posant la pointe du pied arrière.","Fai un passo lungo indietro appoggiando la punta del piede posteriore.","Mach einen langen Schritt nach hinten und setz den hinteren Fuß auf dem Ballen auf."],
  ["Bajá flexionando ambas rodillas hasta que la rodilla trasera quede cerca del suelo, con el peso sobre el pie de adelante.","Lower by bending both knees until the back knee is close to the floor, with your weight on the front foot.","Desça flexionando os dois joelhos até o joelho de trás ficar perto do chão, com o peso sobre o pé da frente.","Descends en fléchissant les deux genoux jusqu’à ce que le genou arrière soit près du sol, le poids sur le pied avant.","Scendi piegando entrambe le ginocchia finché il ginocchio posteriore è vicino a terra, con il peso sul piede anteriore.","Senk dich durch Beugen beider Knie ab, bis das hintere Knie nah am Boden ist; das Gewicht liegt auf dem vorderen Fuß."],
  ["Empujá con el pie de adelante para volver a juntar los pies.","Push through your front foot to bring your feet back together.","Empurre com o pé da frente para voltar a juntar os pés.","Pousse sur le pied avant pour ramener les pieds ensemble.","Spingi con il piede anteriore per riunire i piedi.","Drück dich über den vorderen Fuß zurück, bis die Füße wieder zusammen sind."],
  ["Alterná piernas o completá un lado y después el otro.","Alternate legs or finish one side and then the other.","Alterne as pernas ou complete um lado e depois o outro.","Alterne les jambes ou termine un côté puis l’autre.","Alterna le gambe o completa un lato e poi l’altro.","Wechsle die Beine ab oder mach erst eine Seite und dann die andere."],
  ["Dar un paso tan corto que la rodilla de adelante se carga en exceso.","Taking such a short step that your front knee gets overloaded.","Dar um passo tão curto que o joelho da frente fica sobrecarregado.","Faire un pas si court que le genou avant est surchargé.","Fare un passo così corto da sovraccaricare il ginocchio anteriore.","Einen so kurzen Schritt machen, dass das vordere Knie überlastet wird."],
  ["Perder el equilibrio por pisar en la misma línea.","Losing balance by stepping in a single line.","Perder o equilíbrio por pisar na mesma linha.","Perdre l’équilibre en posant les pieds sur une même ligne.","Perdere l’equilibrio appoggiando i piedi sulla stessa linea.","Das Gleichgewicht verlieren, weil die Füße auf einer Linie stehen."],
  ["Ir hacia atrás suele ser más fácil de controlar que la zancada hacia adelante.","Stepping back is usually easier to control than the forward lunge.","Ir para trás costuma ser mais fácil de controlar que a passada para frente.","Reculer est généralement plus facile à contrôler que la fente avant.","Andare indietro di solito è più facile da controllare dell’affondo in avanti.","Nach hinten zu gehen ist meist leichter zu kontrollieren als der Ausfallschritt nach vorn."],
  ["Despejá el espacio detrás antes de empezar.","Clear the space behind you before you start.","Libere o espaço atrás de você antes de começar.","Dégage l’espace derrière toi avant de commencer.","Libera lo spazio dietro di te prima di iniziare.","Räum den Platz hinter dir frei, bevor du startest."],
  ["Usá mancuernas livianas hasta dominar el equilibrio.","Use light dumbbells until you master your balance.","Use halteres leves até dominar o equilíbrio.","Utilise des haltères légers jusqu’à maîtriser l’équilibre.","Usa manubri leggeri finché non domini l’equilibrio.","Nimm leichte Kurzhanteln, bis du das Gleichgewicht sicher beherrschst."],
  ["Isquiotibiales, pantorrillas y estabilizadores de cadera","Hamstrings, calves and hip stabilizers","Isquiotibiais, panturrilhas e estabilizadores do quadril","Ischio-jambiers, mollets et stabilisateurs de hanche","Ischiocrurali, polpacci e stabilizzatori dell’anca","Hintere Oberschenkel, Waden und Hüftstabilisatoren"],
  ["Escalón, cajón o banco firme y dos mancuernas","Sturdy step, box or bench and two dumbbells","Degrau, caixote ou banco firme e dois halteres","Marche, box ou banc solide et deux haltères","Gradino, box o panca stabile e due manubri","Stabile Stufe, Box oder Bank und zwei Kurzhanteln"],
  ["Parate frente a un escalón firme con una mancuerna en cada mano y apoyá un pie completo sobre él.","Stand facing a sturdy step with a dumbbell in each hand and place one whole foot on it.","Fique de frente para um degrau firme com um halter em cada mão e apoie um pé inteiro sobre ele.","Tiens-toi face à une marche solide, un haltère dans chaque main, et pose un pied entier dessus.","Mettiti di fronte a un gradino stabile con un manubrio per mano e appoggia un piede intero sopra.","Stell dich vor eine stabile Stufe, je eine Kurzhantel in der Hand, und setz einen ganzen Fuß darauf."],
  ["Verificá que el escalón no se mueva y apoyá todo el pie de trabajo sobre la superficie.","Check that the step doesn’t move and place your whole working foot on the surface.","Verifique que o degrau não se mova e apoie o pé de trabalho inteiro sobre a superfície.","Vérifie que la marche ne bouge pas et pose tout le pied de travail sur la surface.","Verifica che il gradino non si muova e appoggia tutto il piede di lavoro sulla superficie.","Prüfe, dass die Stufe nicht wackelt, und setz den ganzen Arbeitsfuß auf."],
  ["Empujá con el pie de arriba para subir hasta quedar de pie sobre el escalón, sin impulsarte con la pierna de abajo.","Push through your top foot to step up until you are standing on the step, without pushing off with your bottom leg.","Empurre com o pé de cima para subir até ficar em pé sobre o degrau, sem dar impulso com a perna de baixo.","Pousse sur le pied du haut pour monter jusqu’à être debout sur la marche, sans t’aider de la jambe du bas.","Spingi con il piede in alto per salire fino a stare in piedi sul gradino, senza darti slancio con la gamba in basso.","Drück dich über den oberen Fuß hoch, bis du auf der Stufe stehst, ohne dich mit dem unteren Bein abzustoßen."],
  ["Bajá con control apoyando primero el pie que estaba abajo.","Step down with control, placing the foot that was on the floor down first.","Desça com controle apoiando primeiro o pé que estava embaixo.","Redescends en contrôle en posant d’abord le pied qui était en bas.","Scendi con controllo appoggiando prima il piede che era in basso.","Steig kontrolliert ab und setz zuerst den Fuß auf, der unten war."],
  ["Impulsarse con el pie de abajo.","Pushing off with your bottom foot.","Dar impulso com o pé de baixo.","Prendre appui sur le pied du bas pour s’élancer.","Darsi slancio con il piede in basso.","Sich mit dem unteren Fuß abstoßen."],
  ["Usar un escalón tan alto que la cadera queda muy por debajo de la rodilla.","Using a step so high that your hip ends up well below your knee.","Usar um degrau tão alto que o quadril fica muito abaixo do joelho.","Utiliser une marche si haute que la hanche se retrouve bien plus bas que le genou.","Usare un gradino così alto che l’anca resta molto sotto il ginocchio.","Eine so hohe Stufe nehmen, dass die Hüfte deutlich unter dem Knie ist."],
  ["Dejar que la rodilla se cierre hacia adentro al subir.","Letting your knee cave inward as you step up.","Deixar o joelho se fechar para dentro ao subir.","Laisser le genou rentrer vers l’intérieur en montant.","Lasciare che il ginocchio si chiuda verso l’interno in salita.","Das Knie beim Hochsteigen nach innen fallen lassen."],
  ["Empezá con un escalón bajo y subí la altura de a poco.","Start with a low step and raise the height gradually.","Comece com um degrau baixo e aumente a altura aos poucos.","Commence avec une marche basse et augmente la hauteur progressivement.","Inizia con un gradino basso e aumenta l’altezza poco a poco.","Beginne mit einer niedrigen Stufe und erhöh die Höhe nach und nach."],
  ["Mantené el tronco erguido con las mancuernas a los costados.","Keep your torso upright with the dumbbells at your sides.","Mantenha o tronco ereto com os halteres ao lado do corpo.","Garde le buste droit, haltères le long du corps.","Mantieni il busto eretto con i manubri ai fianchi.","Halte den Oberkörper aufrecht, die Kurzhanteln seitlich."],
  ["Bajá despacio: la bajada también entrena.","Lower slowly: the descent trains you too.","Desça devagar: a descida também treina.","Descends lentement : la descente travaille aussi.","Scendi lentamente: anche la discesa allena.","Steig langsam ab: Auch das Absteigen trainiert."],
  ["Glúteo medio, erectores espinales y estabilizadores de tobillo","Gluteus medius, spinal erectors and ankle stabilizers","Glúteo médio, eretores da espinha e estabilizadores do tornozelo","Moyen fessier, érecteurs du rachis et stabilisateurs de la cheville","Medio gluteo, erettori spinali e stabilizzatori della caviglia","Mittlerer Gesäßmuskel, Rückenstrecker und Sprunggelenkstabilisatoren"],
  ["Una mancuerna o pesa rusa; opcionalmente una pared o mesa firme cerca para el equilibrio","A dumbbell or kettlebell; optionally a wall or sturdy table nearby for balance","Um halter ou kettlebell; opcionalmente uma parede ou mesa firme perto para o equilíbrio","Un haltère ou un kettlebell ; éventuellement un mur ou une table solide à proximité pour l’équilibre","Un manubrio o un kettlebell; facoltativamente una parete o un tavolo stabile vicino per l’equilibrio","Eine Kurzhantel oder Kettlebell; optional eine Wand oder ein stabiler Tisch in der Nähe für das Gleichgewicht"],
  ["Intermedio; exige equilibrio","Intermediate; demands balance","Intermediário; exige equilíbrio","Intermédiaire ; demande de l’équilibre","Intermedio; richiede equilibrio","Fortgeschritten; erfordert Gleichgewicht"],
  ["Parate sobre una pierna con la rodilla suave y la carga en la mano contraria, con la otra pierna apenas apoyada atrás.","Stand on one leg with a soft knee and the weight in the opposite hand, the other leg barely touching the floor behind you.","Fique sobre uma perna com o joelho solto e a carga na mão contrária, com a outra perna levemente apoiada atrás.","Tiens-toi sur une jambe, genou souple, la charge dans la main opposée, l’autre jambe à peine posée derrière.","Mettiti su una gamba con il ginocchio morbido e il carico nella mano opposta, con l’altra gamba appena appoggiata dietro.","Stell dich auf ein Bein mit weichem Knie, das Gewicht in der gegenüberliegenden Hand, das andere Bein berührt hinten nur leicht den Boden."],
  ["Afirmá el pie de apoyo y mantené la espalda neutra.","Plant your standing foot firmly and keep your back neutral.","Firme o pé de apoio e mantenha as costas neutras.","Ancre bien le pied d’appui et garde le dos neutre.","Pianta bene il piede d’appoggio e mantieni la schiena neutra.","Stell den Standfuß fest auf und halte den Rücken neutral."],
  ["Inclinate desde la cadera llevando la pierna libre hacia atrás, de modo que tronco y pierna formen una línea.","Hinge from the hips, bringing your free leg back so that torso and leg form one line.","Incline-se a partir do quadril levando a perna livre para trás, de modo que tronco e perna formem uma linha.","Penche-toi depuis les hanches en amenant la jambe libre vers l’arrière, pour que buste et jambe forment une ligne.","Inclinati dalle anche portando indietro la gamba libera, così che busto e gamba formino una linea.","Beug dich aus der Hüfte nach vorn und führ das freie Bein nach hinten, sodass Oberkörper und Bein eine Linie bilden."],
  ["Bajá la carga cerca de la pierna de apoyo hasta sentir estiramiento en la parte posterior del muslo.","Lower the weight close to your standing leg until you feel a stretch in the back of your thigh.","Abaixe a carga perto da perna de apoio até sentir alongamento na parte de trás da coxa.","Descends la charge près de la jambe d’appui jusqu’à sentir un étirement à l’arrière de la cuisse.","Abbassa il carico vicino alla gamba d’appoggio fino a sentire allungamento nella parte posteriore della coscia.","Senk das Gewicht nah am Standbein ab, bis du eine Dehnung hinten im Oberschenkel spürst."],
  ["Volvé empujando la cadera adelante; completá un lado y después el otro.","Return by driving your hips forward; finish one side and then the other.","Volte empurrando o quadril para frente; complete um lado e depois o outro.","Reviens en poussant les hanches vers l’avant ; termine un côté puis l’autre.","Torna spingendo le anche in avanti; completa un lato e poi l’altro.","Komm zurück, indem du die Hüfte nach vorn schiebst; mach erst eine Seite, dann die andere."],
  ["Abrir la cadera y girar la pelvis hacia un costado.","Opening your hip and rotating your pelvis to one side.","Abrir o quadril e girar a pelve para um lado.","Ouvrir la hanche et faire pivoter le bassin sur le côté.","Aprire l’anca e ruotare il bacino di lato.","Die Hüfte aufdrehen und das Becken zur Seite drehen."],
  ["Redondear la espalda para llegar más abajo.","Rounding your back to get lower.","Arredondar as costas para descer mais.","Arrondir le dos pour descendre plus bas.","Arrotondare la schiena per scendere di più.","Den Rücken runden, um tiefer zu kommen."],
  ["Flexionar mucho la rodilla de apoyo.","Bending your standing knee a lot.","Flexionar muito o joelho de apoio.","Trop fléchir le genou d’appui.","Piegare molto il ginocchio d’appoggio.","Das Standbein stark beugen."],
  ["Mantené ambas caderas mirando al suelo.","Keep both hips facing the floor.","Mantenha os dois lados do quadril voltados para o chão.","Garde les deux hanches orientées vers le sol.","Mantieni entrambe le anche rivolte verso il pavimento.","Halte beide Hüftseiten zum Boden ausgerichtet."],
  ["Si perdés el equilibrio, tocá una pared con la mano libre.","If you lose balance, touch a wall with your free hand.","Se perder o equilíbrio, toque uma parede com a mão livre.","Si tu perds l’équilibre, touche un mur avec la main libre.","Se perdi l’equilibrio, tocca una parete con la mano libera.","Wenn du das Gleichgewicht verlierst, berühr mit der freien Hand eine Wand."],
  ["No hace falta que la carga toque el suelo.","The weight doesn’t need to touch the floor.","Não é preciso que a carga toque o chão.","La charge n’a pas besoin de toucher le sol.","Non serve che il carico tocchi terra.","Das Gewicht muss den Boden nicht berühren."],
  ["Peso corporal","Bodyweight","Peso corporal","Poids du corps","Corpo libero","Körpergewicht"],
  ["Principiante; ideal para aprender la bisagra de cadera","Beginner; ideal for learning the hip hinge","Iniciante; ideal para aprender a dobradiça de quadril","Débutant ; idéal pour apprendre la charnière de hanche","Principiante; ideale per imparare la cerniera d’anca","Anfänger; ideal, um das Hüftbeugen (Hip Hinge) zu lernen"],
  ["Parate con los pies al ancho de cadera, rodillas suaves y manos cruzadas sobre el pecho o detrás de la cabeza sin tirar del cuello.","Stand with your feet hip-width apart, knees soft and hands crossed over your chest or behind your head without pulling on your neck.","Fique com os pés na largura do quadril, joelhos soltos e mãos cruzadas sobre o peito ou atrás da cabeça sem puxar o pescoço.","Tiens-toi pieds à la largeur des hanches, genoux souples, mains croisées sur la poitrine ou derrière la tête sans tirer sur la nuque.","Mettiti con i piedi alla larghezza delle anche, ginocchia morbide e mani incrociate sul petto o dietro la testa senza tirare il collo.","Stell dich hüftbreit hin, Knie weich, Hände vor der Brust gekreuzt oder hinter dem Kopf, ohne am Nacken zu ziehen."],
  ["Inhalá al inclinarte y exhalá al volver.","Inhale as you hinge forward and exhale as you return.","Inspire ao inclinar e expire ao voltar.","Inspire en te penchant et expire en revenant.","Inspira inclinandoti ed espira tornando.","Atme beim Vorbeugen ein und beim Aufrichten aus."],
  ["Afirmá el abdomen y mantené la espalda neutra.","Brace your abs and keep your back neutral.","Firme o abdômen e mantenha as costas neutras.","Gaine les abdos et garde le dos neutre.","Contrai l’addome e mantieni la schiena neutra.","Spann den Bauch an und halte den Rücken neutral."],
  ["Llevá la cadera hacia atrás inclinando el torso hacia adelante, con la espalda recta.","Push your hips back, tilting your torso forward with a straight back.","Leve o quadril para trás inclinando o tronco para frente, com as costas retas.","Recule les hanches en inclinant le buste vers l’avant, dos droit.","Porta le anche indietro inclinando il busto in avanti, con la schiena dritta.","Schieb die Hüfte nach hinten und neig den Oberkörper mit geradem Rücken nach vorn."],
  ["Bajá hasta sentir estiramiento en la parte posterior del muslo.","Lower until you feel a stretch in the back of your thighs.","Desça até sentir alongamento na parte de trás da coxa.","Descends jusqu’à sentir un étirement à l’arrière des cuisses.","Scendi fino a sentire allungamento nella parte posteriore della coscia.","Geh runter, bis du eine Dehnung hinten im Oberschenkel spürst."],
  ["Empujá la cadera adelante para volver a quedar erguido.","Drive your hips forward to return to standing.","Empurre o quadril para frente para voltar à posição ereta.","Pousse les hanches vers l’avant pour revenir debout.","Spingi le anche in avanti per tornare in posizione eretta.","Schieb die Hüfte nach vorn, um dich wieder aufzurichten."],
  ["Redondear la espalda para bajar más.","Rounding your back to go lower.","Arredondar as costas para descer mais.","Arrondir le dos pour descendre plus bas.","Arrotondare la schiena per scendere di più.","Den Rücken runden, um tiefer zu kommen."],
  ["Flexionar mucho las rodillas.","Bending your knees a lot.","Flexionar muito os joelhos.","Trop fléchir les genoux.","Piegare molto le ginocchia.","Die Knie stark beugen."],
  ["Un palo de escoba apoyado sobre la espalda ayuda a sentir si la columna se mantiene recta.","A broomstick along your back helps you feel whether your spine stays straight.","Um cabo de vassoura apoiado nas costas ajuda a sentir se a coluna se mantém reta.","Un manche à balai posé le long du dos aide à sentir si la colonne reste droite.","Un manico di scopa appoggiato sulla schiena aiuta a sentire se la colonna resta dritta.","Ein Besenstiel am Rücken hilft dir zu spüren, ob die Wirbelsäule gerade bleibt."],
  ["El rango termina donde la espalda deja de estar neutra.","The range ends where your back stops being neutral.","A amplitude termina onde as costas deixam de estar neutras.","L’amplitude s’arrête là où le dos n’est plus neutre.","L’ampiezza finisce dove la schiena smette di essere neutra.","Der Bewegungsumfang endet dort, wo der Rücken nicht mehr neutral ist."],
  ["Banda elástica anclada a baja altura en un punto firme","Resistance band anchored low to a sturdy point","Elástico preso a baixa altura em um ponto firme","Bande élastique ancrée bas à un point solide","Elastico ancorato in basso a un punto stabile","Widerstandsband, tief an einem festen Punkt verankert"],
  ["Parate de espaldas al anclaje, con la banda pasando entre las piernas y tomada con ambas manos, pies algo más abiertos que la cadera.","Stand with your back to the anchor, the band running between your legs and held with both hands, feet slightly wider than hip-width.","Fique de costas para a ancoragem, com o elástico passando entre as pernas e seguro com as duas mãos, pés um pouco mais abertos que o quadril.","Tiens-toi dos au point d’ancrage, la bande passant entre les jambes et tenue à deux mains, pieds un peu plus écartés que les hanches.","Mettiti di spalle all’ancoraggio, con l’elastico che passa tra le gambe impugnato con entrambe le mani, piedi poco più larghi delle anche.","Stell dich mit dem Rücken zur Verankerung, das Band läuft zwischen den Beinen und ist mit beiden Händen gefasst, Füße etwas breiter als hüftbreit."],
  ["Anclá la banda a un punto bajo y firme que no pueda soltarse, y alejate hasta tensarla.","Anchor the band to a low, sturdy point that can’t come loose, and step away until it is taut.","Prenda o elástico em um ponto baixo e firme que não possa se soltar e afaste-se até tensioná-lo.","Ancre la bande à un point bas et solide qui ne peut pas se détacher, puis éloigne-toi jusqu’à la tendre.","Ancora l’elastico a un punto basso e stabile che non possa staccarsi e allontanati fino a tenderlo.","Veranker das Band an einem tiefen, festen Punkt, der sich nicht lösen kann, und geh weg, bis es gespannt ist."],
  ["Llevá la cadera atrás con rodillas suaves, dejando que las manos pasen entre las piernas.","Push your hips back with soft knees, letting your hands pass between your legs.","Leve o quadril para trás com os joelhos soltos, deixando as mãos passarem entre as pernas.","Recule les hanches, genoux souples, en laissant les mains passer entre les jambes.","Porta le anche indietro con le ginocchia morbide, lasciando passare le mani tra le gambe.","Schieb die Hüfte mit weichen Knien nach hinten und lass die Hände zwischen den Beinen durchgehen."],
  ["Empujá la cadera adelante para pararte, apretando los glúteos.","Drive your hips forward to stand up, squeezing your glutes.","Empurre o quadril para frente para ficar em pé, contraindo os glúteos.","Pousse les hanches vers l’avant pour te redresser en serrant les fessiers.","Spingi le anche in avanti per alzarti, contraendo i glutei.","Schieb die Hüfte nach vorn, um dich aufzurichten, und spann das Gesäß an."],
  ["Anclar la banda en un lugar que puede soltarse.","Anchoring the band somewhere it can come loose.","Prender o elástico em um lugar que pode se soltar.","Ancrer la bande à un endroit d’où elle peut se détacher.","Ancorare l’elastico in un punto da cui può staccarsi.","Das Band an einer Stelle verankern, an der es sich lösen kann."],
  ["Tirar de la banda con los brazos.","Pulling the band with your arms.","Puxar o elástico com os braços.","Tirer la bande avec les bras.","Tirare l’elastico con le braccia.","Mit den Armen am Band ziehen."],
  ["Hiperextender la espalda al final.","Hyperextending your back at the end.","Hiperestender as costas no final.","Hyperétendre le dos à la fin.","Iperestendere la schiena alla fine.","Den Rücken am Ende überstrecken."],
  ["Revisá que la banda no tenga cortes ni desgaste.","Check that the band has no cuts or wear.","Verifique se o elástico não tem cortes nem desgaste.","Vérifie que la bande ne présente ni coupure ni usure.","Controlla che l’elastico non abbia tagli né usura.","Prüf, dass das Band keine Risse oder Abnutzung hat."],
  ["Los brazos solo sostienen: el trabajo es de la cadera.","Your arms only hold on: the work comes from your hips.","Os braços só seguram: o trabalho é do quadril.","Les bras ne font que tenir : le travail vient des hanches.","Le braccia tengono soltanto: il lavoro è delle anche.","Die Arme halten nur: Die Arbeit kommt aus der Hüfte."],
  ["Más distancia al anclaje aumenta la resistencia.","More distance from the anchor increases the resistance.","Mais distância da ancoragem aumenta a resistência.","Plus tu t’éloignes du point d’ancrage, plus la résistance augmente.","Più distanza dall’ancoraggio aumenta la resistenza.","Mehr Abstand zur Verankerung erhöht den Widerstand."],
  ["Isquiotibiales, aductores y tronco estabilizador","Hamstrings, adductors and stabilizing trunk","Isquiotibiais, adutores e tronco estabilizador","Ischio-jambiers, adducteurs et tronc stabilisateur","Ischiocrurali, adduttori e tronco stabilizzatore","Hintere Oberschenkel, Adduktoren und stabilisierender Rumpf"],
  ["Sofá firme y pesado apoyado contra una pared; opcionalmente una mancuerna sobre la cadera","Sturdy, heavy sofa set against a wall; optionally a dumbbell on your hips","Sofá firme e pesado encostado em uma parede; opcionalmente um halter sobre o quadril","Canapé solide et lourd calé contre un mur ; éventuellement un haltère sur les hanches","Divano stabile e pesante appoggiato a una parete; facoltativamente un manubrio sulle anche","Stabiles, schweres Sofa an einer Wand; optional eine Kurzhantel auf der Hüfte"],
  ["Sentate en el suelo con la parte alta de la espalda apoyada en el borde del sofá, rodillas flexionadas y pies apoyados.","Sit on the floor with your upper back against the edge of the sofa, knees bent and feet flat.","Sente-se no chão com a parte alta das costas apoiada na borda do sofá, joelhos flexionados e pés apoiados.","Assieds-toi au sol, le haut du dos contre le bord du canapé, genoux fléchis et pieds à plat.","Siediti a terra con la parte alta della schiena appoggiata al bordo del divano, ginocchia piegate e piedi appoggiati.","Setz dich auf den Boden, den oberen Rücken an der Sofakante, Knie gebeugt, Füße aufgestellt."],
  ["Exhalá al subir la cadera e inhalá al bajarla.","Exhale as you lift your hips and inhale as you lower them.","Expire ao subir o quadril e inspire ao abaixá-lo.","Expire en montant les hanches et inspire en les abaissant.","Espira sollevando le anche e inspira abbassandole.","Atme beim Heben der Hüfte aus und beim Senken ein."],
  ["Verificá que el sofá no se deslice; ubicalo contra una pared si es necesario.","Check that the sofa doesn’t slide; place it against a wall if necessary.","Verifique que o sofá não deslize; coloque-o contra uma parede se necessário.","Vérifie que le canapé ne glisse pas ; cale-le contre un mur si nécessaire.","Verifica che il divano non scivoli; mettilo contro una parete se serve.","Prüf, dass das Sofa nicht rutscht; stell es bei Bedarf an eine Wand."],
  ["Apoyá la parte baja de los omóplatos en el borde y los pies al ancho de cadera.","Rest the lower part of your shoulder blades on the edge and set your feet hip-width apart.","Apoie a parte baixa das escápulas na borda e os pés na largura do quadril.","Pose le bas des omoplates sur le bord et les pieds à la largeur des hanches.","Appoggia la parte bassa delle scapole sul bordo e i piedi alla larghezza delle anche.","Leg die unteren Schulterblätter auf die Kante und stell die Füße hüftbreit."],
  ["Empujá con los talones para elevar la cadera hasta que el tronco quede alineado con los muslos.","Push through your heels to raise your hips until your torso is in line with your thighs.","Empurre com os calcanhares para elevar o quadril até o tronco ficar alinhado com as coxas.","Pousse sur les talons pour monter les hanches jusqu’à ce que le buste soit aligné avec les cuisses.","Spingi con i talloni per sollevare le anche finché il busto è allineato con le cosce.","Drück über die Fersen und heb die Hüfte, bis der Oberkörper in einer Linie mit den Oberschenkeln ist."],
  ["Pausá un instante apretando los glúteos y bajá con control.","Pause for a moment squeezing your glutes and lower with control.","Pause um instante contraindo os glúteos e desça com controle.","Marque une courte pause en serrant les fessiers et redescends en contrôle.","Fai una breve pausa stringendo i glutei e scendi con controllo.","Halte kurz mit angespanntem Gesäß und senk kontrolliert ab."],
  ["Usar un sofá liviano o con ruedas que se puede mover.","Using a light sofa or one on wheels that can move.","Usar um sofá leve ou com rodinhas que pode se mover.","Utiliser un canapé léger ou à roulettes qui peut bouger.","Usare un divano leggero o con ruote che può muoversi.","Ein leichtes Sofa oder eines mit Rollen nutzen, das sich verschieben kann."],
  ["Arquear la zona lumbar en lugar de extender la cadera.","Arching your lower back instead of extending your hips.","Arquear a lombar em vez de estender o quadril.","Cambrer le bas du dos au lieu de tendre les hanches.","Inarcare la zona lombare invece di estendere le anche.","Ins Hohlkreuz gehen, statt die Hüfte zu strecken."],
  ["Empujar con la punta de los pies.","Pushing with your toes.","Empurrar com a ponta dos pés.","Pousser avec la pointe des pieds.","Spingere con la punta dei piedi.","Mit den Zehenspitzen drücken."],
  ["Mantené la barbilla levemente hacia el pecho para no arquear la espalda.","Keep your chin slightly tucked toward your chest so you don’t arch your back.","Mantenha o queixo levemente em direção ao peito para não arquear as costas.","Garde le menton légèrement rentré vers la poitrine pour ne pas cambrer le dos.","Tieni il mento leggermente verso il petto per non inarcare la schiena.","Halte das Kinn leicht zur Brust, damit du nicht ins Hohlkreuz gehst."],
  ["Arriba, las tibias deberían quedar cerca de verticales.","At the top, your shins should be close to vertical.","Em cima, as canelas devem ficar perto da vertical.","En haut, les tibias devraient être presque verticaux.","In alto, le tibie dovrebbero essere quasi verticali.","Oben sollten die Schienbeine etwa senkrecht stehen."],
  ["Si usás carga, sostenela con las manos sobre la cadera.","If you use a load, hold it with your hands on your hips.","Se usar carga, segure-a com as mãos sobre o quadril.","Si tu utilises une charge, tiens-la avec les mains sur les hanches.","Se usi un carico, tienilo con le mani sulle anche.","Wenn du Gewicht nutzt, halte es mit den Händen auf der Hüfte."],
  ["Colchoneta","Mat","Colchonete","Tapis","Tappetino","Matte"],
  ["Ponete en cuadrupedia con las manos bajo los hombros, rodillas bajo la cadera y espalda neutra.","Get on all fours with your hands under your shoulders, knees under your hips and back neutral.","Fique em quatro apoios com as mãos sob os ombros, joelhos sob o quadril e costas neutras.","Mets-toi à quatre pattes, mains sous les épaules, genoux sous les hanches et dos neutre.","Mettiti a quattro zampe con le mani sotto le spalle, ginocchia sotto le anche e schiena neutra.","Geh in den Vierfüßlerstand, Hände unter den Schultern, Knie unter der Hüfte, Rücken neutral."],
  ["Exhalá al subir la pierna e inhalá al bajarla.","Exhale as you lift your leg and inhale as you lower it.","Expire ao subir a perna e inspire ao abaixá-la.","Expire en montant la jambe et inspire en l’abaissant.","Espira sollevando la gamba e inspira abbassandola.","Atme beim Heben des Beins aus und beim Senken ein."],
  ["Afirmá el abdomen para que la espalda no se mueva.","Brace your abs so your back doesn’t move.","Firme o abdômen para as costas não se moverem.","Gaine les abdos pour que le dos ne bouge pas.","Contrai l’addome perché la schiena non si muova.","Spann den Bauch an, damit sich der Rücken nicht bewegt."],
  ["Elevá una pierna hacia atrás y arriba con la rodilla flexionada, empujando la planta hacia el techo.","Lift one leg back and up with your knee bent, pushing the sole of your foot toward the ceiling.","Eleve uma perna para trás e para cima com o joelho flexionado, empurrando a sola do pé em direção ao teto.","Monte une jambe vers l’arrière et le haut, genou fléchi, en poussant la plante du pied vers le plafond.","Solleva una gamba indietro e in alto con il ginocchio piegato, spingendo la pianta del piede verso il soffitto.","Heb ein Bein mit gebeugtem Knie nach hinten oben und drück die Fußsohle Richtung Decke."],
  ["Subí hasta que el muslo quede alineado con el tronco, sin arquear la espalda.","Lift until your thigh is in line with your torso, without arching your back.","Suba até a coxa ficar alinhada com o tronco, sem arquear as costas.","Monte jusqu’à ce que la cuisse soit alignée avec le buste, sans cambrer le dos.","Sali finché la coscia è allineata con il busto, senza inarcare la schiena.","Heb, bis der Oberschenkel in einer Linie mit dem Oberkörper ist, ohne ins Hohlkreuz zu gehen."],
  ["Bajá con control y completá un lado antes de cambiar al otro.","Lower with control and finish one side before switching to the other.","Desça com controle e complete um lado antes de trocar para o outro.","Redescends en contrôle et termine un côté avant de passer à l’autre.","Scendi con controllo e completa un lato prima di passare all’altro.","Senk kontrolliert ab und beende eine Seite, bevor du wechselst."],
  ["Arquear la zona lumbar para subir más la pierna.","Arching your lower back to lift your leg higher.","Arquear a lombar para subir mais a perna.","Cambrer le bas du dos pour monter la jambe plus haut.","Inarcare la zona lombare per sollevare di più la gamba.","Ins Hohlkreuz gehen, um das Bein höher zu heben."],
  ["Girar la cadera hacia un costado.","Rotating your hip to one side.","Girar o quadril para um lado.","Faire pivoter la hanche sur le côté.","Ruotare l’anca di lato.","Die Hüfte zur Seite drehen."],
  ["Hacer el movimiento rápido y con impulso.","Doing the movement fast and with momentum.","Fazer o movimento rápido e com impulso.","Faire le mouvement vite et avec de l’élan.","Fare il movimento veloce e con slancio.","Die Bewegung schnell und mit Schwung ausführen."],
  ["Imaginá un vaso apoyado sobre la espalda que no debe caerse.","Imagine a glass resting on your back that must not fall.","Imagine um copo apoiado nas costas que não pode cair.","Imagine un verre posé sur ton dos qui ne doit pas tomber.","Immagina un bicchiere appoggiato sulla schiena che non deve cadere.","Stell dir ein Glas auf deinem Rücken vor, das nicht herunterfallen darf."],
  ["Una pausa arriba ayuda a sentir el glúteo.","A pause at the top helps you feel your glutes.","Uma pausa em cima ajuda a sentir o glúteo.","Une pause en haut aide à sentir les fessiers.","Una pausa in alto aiuta a sentire i glutei.","Eine Pause oben hilft dir, das Gesäß zu spüren."],
  ["Tensor de la fascia lata y estabilizadores del tronco","Tensor fasciae latae and trunk stabilizers","Tensor da fáscia lata e estabilizadores do tronco","Tenseur du fascia lata et stabilisateurs du tronc","Tensore della fascia lata e stabilizzatori del tronco","Schenkelbindenspanner und Rumpfstabilisatoren"],
  ["Acostate de costado con las piernas extendidas una sobre otra, la cabeza apoyada en el brazo de abajo y el cuerpo en línea recta.","Lie on your side with your legs extended one on top of the other, your head resting on your lower arm and your body in a straight line.","Deite-se de lado com as pernas estendidas uma sobre a outra, a cabeça apoiada no braço de baixo e o corpo em linha reta.","Allonge-toi sur le côté, jambes tendues l’une sur l’autre, tête posée sur le bras du dessous et corps aligné.","Sdraiati su un fianco con le gambe distese una sull’altra, la testa appoggiata sul braccio in basso e il corpo in linea retta.","Leg dich auf die Seite, Beine gestreckt übereinander, Kopf auf dem unteren Arm, Körper in einer geraden Linie."],
  ["Alineá cabeza, tronco y piernas; podés flexionar la rodilla de abajo para tener más estabilidad.","Align your head, torso and legs; you can bend your bottom knee for more stability.","Alinhe cabeça, tronco e pernas; você pode flexionar o joelho de baixo para ter mais estabilidade.","Aligne tête, buste et jambes ; tu peux fléchir le genou du dessous pour plus de stabilité.","Allinea testa, busto e gambe; puoi piegare il ginocchio in basso per avere più stabilità.","Bring Kopf, Oberkörper und Beine in eine Linie; für mehr Stabilität kannst du das untere Knie beugen."],
  ["Elevá la pierna de arriba hacia el techo con la rodilla extendida y la punta del pie mirando al frente.","Raise your top leg toward the ceiling with your knee straight and your toes pointing forward.","Eleve a perna de cima em direção ao teto com o joelho estendido e a ponta do pé voltada para frente.","Monte la jambe du dessus vers le plafond, genou tendu et pointe du pied vers l’avant.","Solleva la gamba in alto verso il soffitto con il ginocchio disteso e la punta del piede rivolta in avanti.","Heb das obere Bein mit gestrecktem Knie Richtung Decke, die Fußspitze zeigt nach vorn."],
  ["Subí hasta un rango cómodo sin girar la cadera hacia atrás.","Lift to a comfortable range without rotating your hip back.","Suba até uma amplitude confortável sem girar o quadril para trás.","Monte jusqu’à une amplitude confortable sans faire pivoter la hanche vers l’arrière.","Sali fino a un’ampiezza comoda senza ruotare l’anca indietro.","Heb bis zu einem angenehmen Bewegungsumfang, ohne die Hüfte nach hinten zu drehen."],
  ["Bajá despacio y completá un lado antes de cambiar al otro.","Lower slowly and finish one side before switching to the other.","Desça devagar e complete um lado antes de trocar para o outro.","Redescends lentement et termine un côté avant de passer à l’autre.","Scendi lentamente e completa un lato prima di passare all’altro.","Senk langsam ab und beende eine Seite, bevor du wechselst."],
  ["Rotar la pierna para que la punta del pie mire hacia arriba.","Rotating your leg so your toes point up.","Girar a perna para a ponta do pé apontar para cima.","Faire pivoter la jambe pour que la pointe du pied regarde vers le haut.","Ruotare la gamba in modo che la punta del piede guardi in alto.","Das Bein so drehen, dass die Fußspitze nach oben zeigt."],
  ["Llevar la pierna hacia adelante en lugar de subirla de costado.","Bringing your leg forward instead of raising it to the side.","Levar a perna para frente em vez de subi-la de lado.","Amener la jambe vers l’avant au lieu de la monter sur le côté.","Portare la gamba in avanti invece di sollevarla di lato.","Das Bein nach vorn führen, statt es seitlich zu heben."],
  ["Subir con impulso y dejarla caer.","Lifting with momentum and letting it drop.","Subir com impulso e deixar cair.","Monter avec de l’élan et la laisser retomber.","Salire con slancio e lasciarla cadere.","Mit Schwung heben und das Bein fallen lassen."],
  ["Llevá el talón levemente hacia atrás para sentir mejor el glúteo medio.","Move your heel slightly back to feel your gluteus medius better.","Leve o calcanhar levemente para trás para sentir melhor o glúteo médio.","Recule légèrement le talon pour mieux sentir le moyen fessier.","Porta il tallone leggermente indietro per sentire meglio il medio gluteo.","Schieb die Ferse leicht nach hinten, um den mittleren Gesäßmuskel besser zu spüren."],
  ["El rango suele ser corto; no hace falta subir mucho.","The range is usually short; you don’t need to lift high.","A amplitude costuma ser curta; não é preciso subir muito.","L’amplitude est généralement courte ; inutile de monter haut.","L’ampiezza di solito è breve; non serve salire molto.","Der Bewegungsumfang ist meist klein; du musst nicht hoch heben."],
  ["Mantené la cadera de arriba apilada sobre la de abajo.","Keep your top hip stacked over your bottom hip.","Mantenha o quadril de cima alinhado sobre o de baixo.","Garde la hanche du dessus alignée au-dessus de celle du dessous.","Mantieni l’anca in alto allineata sopra quella in basso.","Halte die obere Hüfte senkrecht über der unteren."],
  ["Glúteo mayor, tensor de la fascia lata y cuádriceps","Gluteus maximus, tensor fasciae latae and quadriceps","Glúteo máximo, tensor da fáscia lata e quadríceps","Grand fessier, tenseur du fascia lata et quadriceps","Grande gluteo, tensore della fascia lata e quadricipiti","Großer Gesäßmuskel, Schenkelbindenspanner und Quadrizeps"],
  ["Banda elástica circular (mini banda)","Loop resistance band (mini band)","Mini band (elástico circular)","Mini-bande élastique","Mini band (elastico ad anello)","Mini-Band (Loop-Band)"],
  ["Colocá la mini banda justo por encima de las rodillas y parate con los pies al ancho de cadera, rodillas y cadera levemente flexionadas.","Place the mini band just above your knees and stand with your feet hip-width apart, knees and hips slightly bent.","Coloque a mini band logo acima dos joelhos e fique com os pés na largura do quadril, joelhos e quadril levemente flexionados.","Place la mini-bande juste au-dessus des genoux et tiens-toi pieds à la largeur des hanches, genoux et hanches légèrement fléchis.","Metti la mini band appena sopra le ginocchia e mettiti con i piedi alla larghezza delle anche, ginocchia e anche leggermente piegate.","Leg das Mini-Band knapp über die Knie und stell dich hüftbreit hin, Knie und Hüfte leicht gebeugt."],
  ["Respirá de forma pareja durante los pasos.","Breathe evenly as you step.","Respire de forma regular durante os passos.","Respire régulièrement pendant les pas.","Respira in modo regolare durante i passi.","Atme bei den Schritten gleichmäßig."],
  ["Adoptá una media sentadilla corta con el tronco erguido y la banda tensa.","Get into a shallow half squat with your torso upright and the band taut.","Faça uma meia agachada curta com o tronco ereto e o elástico tenso.","Place-toi en demi-squat peu profond, buste droit et bande tendue.","Mettiti in un mezzo squat poco profondo con il busto eretto e l’elastico teso.","Geh in eine flache halbe Kniebeuge, Oberkörper aufrecht, Band gespannt."],
  ["Dá un paso al costado con un pie, manteniendo las rodillas alineadas con los pies.","Step to the side with one foot, keeping your knees aligned with your feet.","Dê um passo para o lado com um pé, mantendo os joelhos alinhados com os pés.","Fais un pas sur le côté avec un pied en gardant les genoux alignés avec les pieds.","Fai un passo di lato con un piede, mantenendo le ginocchia allineate con i piedi.","Mach mit einem Fuß einen Schritt zur Seite, Knie in einer Linie mit den Füßen."],
  ["Acercá el otro pie sin dejar que la banda pierda toda la tensión.","Bring the other foot in without letting the band lose all its tension.","Aproxime o outro pé sem deixar o elástico perder toda a tensão.","Rapproche l’autre pied sans laisser la bande perdre toute sa tension.","Avvicina l’altro piede senza lasciare che l’elastico perda tutta la tensione.","Zieh den anderen Fuß nach, ohne dass das Band die ganze Spannung verliert."],
  ["Hacé los pasos hacia un lado y después regresá hacia el otro.","Take your steps to one side and then come back toward the other.","Faça os passos para um lado e depois volte para o outro.","Fais tes pas d’un côté puis reviens de l’autre.","Fai i passi verso un lato e poi torna verso l’altro.","Mach die Schritte in eine Richtung und geh dann in die andere zurück."],
  ["Dejar que las rodillas se cierren hacia adentro.","Letting your knees cave inward.","Deixar os joelhos se fecharem para dentro.","Laisser les genoux rentrer vers l’intérieur.","Lasciare che le ginocchia si chiudano verso l’interno.","Die Knie nach innen fallen lassen."],
  ["Subir y bajar el cuerpo en cada paso.","Bobbing your body up and down with each step.","Subir e descer o corpo a cada passo.","Monter et descendre le corps à chaque pas.","Alzare e abbassare il corpo a ogni passo.","Bei jedem Schritt mit dem Körper auf und ab gehen."],
  ["Juntar los pies del todo y soltar la tensión.","Bringing your feet fully together and releasing the tension.","Juntar totalmente os pés e soltar a tensão.","Rapprocher complètement les pieds et relâcher la tension.","Unire del tutto i piedi e rilasciare la tensione.","Die Füße ganz zusammenführen und die Spannung lösen."],
  ["Pasos cortos y controlados mantienen mejor la tensión.","Short, controlled steps keep the tension better.","Passos curtos e controlados mantêm melhor a tensão.","Des pas courts et contrôlés maintiennent mieux la tension.","Passi corti e controllati mantengono meglio la tensione.","Kurze, kontrollierte Schritte halten die Spannung besser."],
  ["Revisá que la banda no tenga cortes.","Check that the band has no cuts.","Verifique se o elástico não tem cortes.","Vérifie que la bande n’a pas de coupure.","Controlla che l’elastico non abbia tagli.","Prüf, dass das Band keine Risse hat."],
  ["Una banda más dura o más baja aumenta la dificultad.","A stiffer band or placing it lower increases the difficulty.","Um elástico mais forte ou posicionado mais baixo aumenta a dificuldade.","Une bande plus dure ou placée plus bas augmente la difficulté.","Un elastico più duro o posizionato più in basso aumenta la difficoltà.","Ein stärkeres oder tiefer platziertes Band erhöht die Schwierigkeit."],
  ["Isquiotibiales","Hamstrings","Isquiotibiais","Ischio-jambiers","Ischiocrurali","Hintere Oberschenkel"],
  ["Glúteo mayor y pantorrillas","Gluteus maximus and calves","Glúteo máximo e panturrilhas","Grand fessier et mollets","Grande gluteo e polpacci","Großer Gesäßmuskel und Waden"],
  ["Toalla y piso liso (madera, cerámica o porcelanato), o deslizadores","Towel and a smooth floor (wood, tile or porcelain), or sliders","Toalha e piso liso (madeira, cerâmica ou porcelanato), ou discos deslizantes","Serviette et sol lisse (parquet, carrelage ou grès), ou disques de glisse","Asciugamano e pavimento liscio (legno, ceramica o gres), oppure dischi scorrevoli","Handtuch und glatter Boden (Holz, Fliesen oder Feinsteinzeug) oder Gleitscheiben"],
  ["Acostate boca arriba con las rodillas flexionadas y los talones sobre una toalla en un piso liso.","Lie on your back with your knees bent and your heels on a towel on a smooth floor.","Deite-se de barriga para cima com os joelhos flexionados e os calcanhares sobre uma toalha em piso liso.","Allonge-toi sur le dos, genoux fléchis, talons sur une serviette sur un sol lisse.","Sdraiati a pancia in su con le ginocchia piegate e i talloni su un asciugamano su un pavimento liscio.","Leg dich auf den Rücken, Knie gebeugt, Fersen auf einem Handtuch auf glattem Boden."],
  ["Inhalá al extender las piernas y exhalá al traer los talones.","Inhale as you extend your legs and exhale as you pull your heels in.","Inspire ao estender as pernas e expire ao trazer os calcanhares.","Inspire en tendant les jambes et expire en ramenant les talons.","Inspira distendendo le gambe ed espira riportando i talloni.","Atme beim Strecken der Beine ein und beim Heranziehen der Fersen aus."],
  ["Apoyá los talones sobre la toalla y elevá la cadera en posición de puente.","Place your heels on the towel and lift your hips into a bridge position.","Apoie os calcanhares sobre a toalha e eleve o quadril em posição de ponte.","Pose les talons sur la serviette et monte les hanches en position de pont.","Appoggia i talloni sull’asciugamano e solleva le anche in posizione di ponte.","Setz die Fersen auf das Handtuch und heb die Hüfte in die Brückenposition."],
  ["Deslizá los talones hacia adelante extendiendo las rodillas sin dejar caer la cadera.","Slide your heels forward, extending your knees without letting your hips drop.","Deslize os calcanhares para frente estendendo os joelhos sem deixar o quadril cair.","Fais glisser les talons vers l’avant en tendant les genoux sans laisser tomber les hanches.","Fai scivolare i talloni in avanti distendendo le ginocchia senza far cadere le anche.","Schieb die Fersen nach vorn und streck die Knie, ohne die Hüfte absinken zu lassen."],
  ["Llevá los talones de vuelta hacia la cadera flexionando las rodillas.","Pull your heels back toward your hips by bending your knees.","Traga os calcanhares de volta em direção ao quadril flexionando os joelhos.","Ramène les talons vers les hanches en fléchissant les genoux.","Riporta i talloni verso le anche piegando le ginocchia.","Zieh die Fersen durch Beugen der Knie wieder zur Hüfte."],
  ["Si la cadera baja o los isquiotibiales se acalambran, apoyá la cadera y hacé un rango más corto.","If your hips drop or your hamstrings cramp, lower your hips and use a shorter range.","Se o quadril cair ou os isquiotibiais tiverem cãibra, apoie o quadril e faça uma amplitude menor.","Si les hanches descendent ou si les ischio-jambiers crampent, pose les hanches et réduis l’amplitude.","Se le anche scendono o gli ischiocrurali hanno i crampi, appoggia le anche e fai un’ampiezza più corta.","Wenn die Hüfte absinkt oder die hinteren Oberschenkel krampfen, leg die Hüfte ab und verkürz den Bewegungsumfang."],
  ["Dejar que la cadera toque el suelo durante la serie.","Letting your hips touch the floor during the set.","Deixar o quadril tocar o chão durante a série.","Laisser les hanches toucher le sol pendant la série.","Lasciare che le anche tocchino terra durante la serie.","Die Hüfte während des Satzes den Boden berühren lassen."],
  ["Hacerlo en una alfombra que no permite deslizar.","Doing it on a rug that doesn’t let you slide.","Fazer em um tapete que não permite deslizar.","Le faire sur un tapis qui ne permet pas de glisser.","Farlo su un tappeto che non permette di scivolare.","Es auf einem Teppich machen, auf dem nichts gleitet."],
  ["Arquear la zona lumbar para mantener la cadera arriba.","Arching your lower back to keep your hips up.","Arquear a lombar para manter o quadril em cima.","Cambrer le bas du dos pour garder les hanches en haut.","Inarcare la zona lombare per tenere le anche in alto.","Ins Hohlkreuz gehen, um die Hüfte oben zu halten."],
  ["Empezá extendiendo solo hasta donde puedas volver.","Start by extending only as far as you can come back from.","Comece estendendo só até onde conseguir voltar.","Commence par tendre seulement jusqu’où tu peux revenir.","Inizia distendendo solo fin dove riesci a tornare.","Streck anfangs nur so weit, wie du wieder zurückkommst."],
  ["La versión con ambas piernas es la base; con una pierna es más difícil.","The two-leg version is the base; with one leg it is harder.","A versão com as duas pernas é a base; com uma perna é mais difícil.","La version à deux jambes est la base ; sur une jambe, c’est plus difficile.","La versione a due gambe è la base; con una gamba è più difficile.","Die beidbeinige Variante ist die Basis; einbeinig ist es schwerer."],
  ["Usá una superficie lisa pero limpia y seca para controlar el deslizamiento.","Use a smooth but clean and dry surface to control the slide.","Use uma superfície lisa, mas limpa e seca, para controlar o deslizamento.","Utilise une surface lisse mais propre et sèche pour contrôler la glisse.","Usa una superficie liscia ma pulita e asciutta per controllare lo scivolamento.","Nutze eine glatte, aber saubere und trockene Fläche, um das Gleiten zu kontrollieren."],
  ["Sóleo y estabilizadores del tobillo","Soleus and ankle stabilizers","Sóleo e estabilizadores do tornozelo","Soléaire et stabilisateurs de la cheville","Soleo e stabilizzatori della caviglia","Schollenmuskel (Soleus) und Sprunggelenkstabilisatoren"],
  ["Pared, mesa firme o respaldo estable; opcionalmente un escalón","Wall, sturdy table or stable chair back; optionally a step","Parede, mesa firme ou encosto estável; opcionalmente um degrau","Mur, table solide ou dossier stable ; éventuellement une marche","Parete, tavolo stabile o schienale fermo; facoltativamente un gradino","Wand, stabiler Tisch oder feste Stuhllehne; optional eine Stufe"],
  ["Parate sobre un pie frente a una pared o apoyo firme, con las manos apoyadas y la otra pierna flexionada sin tocar el suelo.","Stand on one foot facing a wall or sturdy support, hands on it and the other leg bent without touching the floor.","Fique sobre um pé de frente para uma parede ou apoio firme, com as mãos apoiadas e a outra perna flexionada sem tocar o chão.","Tiens-toi sur un pied face à un mur ou un appui solide, mains posées, l’autre jambe fléchie sans toucher le sol.","Mettiti su un piede di fronte a una parete o a un appoggio stabile, con le mani appoggiate e l’altra gamba piegata senza toccare terra.","Stell dich auf einen Fuß vor eine Wand oder feste Stütze, Hände daran, das andere Bein gebeugt ohne Bodenkontakt."],
  ["Apoyá las manos en una superficie estable solo para mantener el equilibrio.","Rest your hands on a stable surface only to keep your balance.","Apoie as mãos em uma superfície estável só para manter o equilíbrio.","Pose les mains sur une surface stable uniquement pour garder l’équilibre.","Appoggia le mani su una superficie stabile solo per mantenere l’equilibrio.","Stütz die Hände nur zum Gleichgewicht auf eine stabile Fläche."],
  ["Subí el talón lo más alto posible, empujando con la base de los dedos.","Raise your heel as high as possible, pushing through the ball of your foot.","Suba o calcanhar o mais alto possível, empurrando com a base dos dedos.","Monte le talon le plus haut possible en poussant avec la base des orteils.","Solleva il tallone il più in alto possibile, spingendo con la base delle dita.","Heb die Ferse so hoch wie möglich und drück über den Fußballen."],
  ["Empujar con las manos para ayudarte a subir.","Pushing with your hands to help yourself up.","Empurrar com as mãos para ajudar a subir.","Pousser avec les mains pour t’aider à monter.","Spingere con le mani per aiutarti a salire.","Mit den Händen drücken, um beim Hochkommen nachzuhelfen."],
  ["Flexionar la rodilla de apoyo.","Bending your standing knee.","Flexionar o joelho de apoio.","Fléchir le genou d’appui.","Piegare il ginocchio d’appoggio.","Das Standbein beugen."],
  ["Hacer repeticiones rápidas y cortas.","Doing fast, short reps.","Fazer repetições rápidas e curtas.","Faire des répétitions rapides et courtes.","Fare ripetizioni veloci e corte.","Schnelle, kurze Wiederholungen machen."],
  ["El apoyo da equilibrio sin restar el trabajo de la pantorrilla.","The support gives balance without taking work away from your calf.","O apoio dá equilíbrio sem tirar trabalho da panturrilha.","L’appui donne de l’équilibre sans retirer de travail au mollet.","L’appoggio dà equilibrio senza togliere lavoro al polpaccio.","Die Stütze gibt Gleichgewicht, ohne der Wade Arbeit abzunehmen."],
  ["Para más rango, hacelo con el antepié sobre un escalón firme.","For more range, do it with the front of your foot on a sturdy step.","Para mais amplitude, faça com a parte da frente do pé sobre um degrau firme.","Pour plus d’amplitude, fais-le avec l’avant du pied sur une marche solide.","Per più ampiezza, fallo con l’avampiede su un gradino stabile.","Für mehr Bewegungsumfang mach es mit dem Vorfuß auf einer stabilen Stufe."],
  ["Mantené el peso sobre la línea del dedo gordo y el segundo dedo.","Keep your weight over the line of your big toe and second toe.","Mantenha o peso sobre a linha do dedão e do segundo dedo.","Garde le poids sur la ligne du gros orteil et du deuxième orteil.","Mantieni il peso sulla linea dell’alluce e del secondo dito.","Halte das Gewicht auf der Linie von großem und zweitem Zeh."],
  ["Pectoral mayor y tríceps","Pectoralis major and triceps","Peitoral maior e tríceps","Grand pectoral et triceps","Grande pettorale e tricipiti","Großer Brustmuskel und Trizeps"],
  ["Dos mancuernas y colchoneta","Two dumbbells and a mat","Dois halteres e colchonete","Deux haltères et un tapis","Due manubri e tappetino","Zwei Kurzhanteln und eine Matte"],
  ["Acostate boca arriba en el suelo con las rodillas flexionadas, pies apoyados y una mancuerna en cada mano sobre el pecho.","Lie on your back on the floor with your knees bent, feet flat and a dumbbell in each hand over your chest.","Deite-se de barriga para cima no chão com os joelhos flexionados, pés apoiados e um halter em cada mão sobre o peito.","Allonge-toi sur le dos au sol, genoux fléchis, pieds à plat et un haltère dans chaque main au-dessus de la poitrine.","Sdraiati a pancia in su a terra con le ginocchia piegate, piedi appoggiati e un manubrio per mano sopra il petto.","Leg dich rücklings auf den Boden, Knie gebeugt, Füße aufgestellt, je eine Kurzhantel über der Brust."],
  ["Inhalá al bajar y exhalá al empujar.","Inhale as you lower and exhale as you press.","Inspire ao descer e expire ao empurrar.","Inspire en descendant et expire en poussant.","Inspira scendendo ed espira spingendo.","Atme beim Absenken ein und beim Drücken aus."],
  ["Llevá las mancuernas arriba del pecho con los brazos extendidos y las palmas hacia los pies o enfrentadas.","Bring the dumbbells above your chest with your arms extended and palms facing your feet or each other.","Leve os halteres acima do peito com os braços estendidos e as palmas voltadas para os pés ou uma para a outra.","Amène les haltères au-dessus de la poitrine, bras tendus et paumes vers les pieds ou face à face.","Porta i manubri sopra il petto con le braccia distese e i palmi verso i piedi o rivolti l’uno verso l’altro.","Bring die Kurzhanteln mit gestreckten Armen über die Brust, Handflächen zu den Füßen oder zueinander."],
  ["Bajá las mancuernas hasta que la parte trasera de los brazos toque suavemente el suelo, con los codos a unos 45 grados del cuerpo.","Lower the dumbbells until the backs of your arms gently touch the floor, elbows at about 45 degrees from your body.","Abaixe os halteres até a parte de trás dos braços tocar suavemente o chão, com os cotovelos a cerca de 45 graus do corpo.","Descends les haltères jusqu’à ce que l’arrière des bras touche doucement le sol, coudes à environ 45 degrés du corps.","Abbassa i manubri finché la parte posteriore delle braccia tocca dolcemente terra, con i gomiti a circa 45 gradi dal corpo.","Senk die Kurzhanteln, bis die Oberarmrückseiten sanft den Boden berühren, Ellbogen etwa 45 Grad vom Körper."],
  ["Pausá un instante sin relajar los brazos en el suelo.","Pause for a moment without relaxing your arms on the floor.","Pause um instante sem relaxar os braços no chão.","Marque une courte pause sans relâcher les bras au sol.","Fai una breve pausa senza rilassare le braccia a terra.","Halte kurz, ohne die Arme auf dem Boden abzulegen."],
  ["Empujá hacia arriba hasta extender los brazos.","Press up until your arms are extended.","Empurre para cima até estender os braços.","Pousse vers le haut jusqu’à tendre les bras.","Spingi verso l’alto fino a distendere le braccia.","Drück nach oben, bis die Arme gestreckt sind."],
  ["Golpear los codos contra el suelo.","Banging your elbows on the floor.","Bater os cotovelos no chão.","Cogner les coudes contre le sol.","Sbattere i gomiti a terra.","Die Ellbogen auf den Boden schlagen."],
  ["Abrir los codos a 90 grados del tronco.","Flaring your elbows to 90 degrees from your torso.","Abrir os cotovelos a 90 graus do tronco.","Écarter les coudes à 90 degrés du buste.","Aprire i gomiti a 90 gradi dal busto.","Die Ellbogen 90 Grad vom Oberkörper abspreizen."],
  ["Dejar que las muñecas se doblen hacia atrás.","Letting your wrists bend back.","Deixar os punhos dobrarem para trás.","Laisser les poignets plier vers l’arrière.","Lasciare che i polsi si pieghino all’indietro.","Die Handgelenke nach hinten abknicken lassen."],
  ["El suelo limita el rango, lo que suele resultar cómodo para los hombros.","The floor limits the range, which tends to feel comfortable for the shoulders.","O chão limita a amplitude, o que costuma ser confortável para os ombros.","Le sol limite l’amplitude, ce qui est souvent confortable pour les épaules.","Il pavimento limita l’ampiezza, cosa che di solito è comoda per le spalle.","Der Boden begrenzt den Bewegungsumfang, was meist angenehm für die Schultern ist."],
  ["Para tomar las mancuernas, apoyalas sobre los muslos y llevalas al pecho al acostarte.","To pick up the dumbbells, rest them on your thighs and bring them to your chest as you lie back.","Para pegar os halteres, apoie-os sobre as coxas e leve-os ao peito ao se deitar.","Pour prendre les haltères, pose-les sur les cuisses et amène-les à la poitrine en t’allongeant.","Per prendere i manubri, appoggiali sulle cosce e portali al petto mentre ti sdrai.","Leg die Kurzhanteln zum Aufnehmen auf die Oberschenkel und bring sie beim Hinlegen zur Brust."],
  ["Mantené los pies firmes y la cadera apoyada.","Keep your feet planted and your hips down.","Mantenha os pés firmes e o quadril apoiado.","Garde les pieds ancrés et les hanches au sol.","Mantieni i piedi ben piantati e le anche appoggiate.","Halte die Füße fest am Boden und die Hüfte abgelegt."],
  ["Tríceps, deltoides anterior y estabilizadores del tronco","Triceps, front deltoid and trunk stabilizers","Tríceps, deltoide anterior e estabilizadores do tronco","Triceps, deltoïde antérieur et stabilisateurs du tronc","Tricipiti, deltoide anteriore e stabilizzatori del tronco","Trizeps, vorderer Deltamuskel und Rumpfstabilisatoren"],
  ["Colchoneta o superficie acolchada","Mat or padded surface","Colchonete ou superfície acolchoada","Tapis ou surface rembourrée","Tappetino o superficie imbottita","Matte oder gepolsterter Untergrund"],
  ["Apoyá las manos en el suelo algo más abiertas que los hombros y las rodillas en la colchoneta, con el cuerpo alineado de rodillas a cabeza.","Place your hands on the floor slightly wider than your shoulders and your knees on the mat, body aligned from knees to head.","Apoie as mãos no chão um pouco mais abertas que os ombros e os joelhos no colchonete, com o corpo alinhado dos joelhos à cabeça.","Pose les mains au sol un peu plus écartées que les épaules et les genoux sur le tapis, corps aligné des genoux à la tête.","Appoggia le mani a terra poco più larghe delle spalle e le ginocchia sul tappetino, con il corpo allineato dalle ginocchia alla testa.","Setz die Hände etwas breiter als schulterbreit auf den Boden, die Knie auf die Matte, Körper von den Knien bis zum Kopf in einer Linie."],
  ["45–90 segundos","45–90 seconds","45–90 segundos","45–90 secondes","45–90 secondi","45–90 Sekunden"],
  ["Colocá las rodillas detrás de la cadera para que el tronco quede en línea recta, no en cuadrupedia.","Place your knees behind your hips so your torso is in a straight line, not on all fours.","Coloque os joelhos atrás do quadril para o tronco ficar em linha reta, não em quatro apoios.","Place les genoux derrière les hanches pour que le buste soit aligné, pas à quatre pattes.","Metti le ginocchia dietro le anche perché il busto sia in linea retta, non a quattro zampe.","Setz die Knie hinter die Hüfte, damit der Oberkörper eine gerade Linie bildet und nicht im Vierfüßlerstand ist."],
  ["Flexioná los codos en diagonal hacia atrás y bajá el pecho hacia el suelo.","Bend your elbows diagonally back and lower your chest toward the floor.","Flexione os cotovelos na diagonal para trás e abaixe o peito em direção ao chão.","Fléchis les coudes en diagonale vers l’arrière et descends la poitrine vers le sol.","Piega i gomiti in diagonale all’indietro e abbassa il petto verso il pavimento.","Beuge die Ellbogen schräg nach hinten und senk die Brust zum Boden."],
  ["Mantené la cadera alineada, sin que quede arriba ni se hunda.","Keep your hips in line, neither raised nor sagging.","Mantenha o quadril alinhado, sem ficar alto nem afundar.","Garde les hanches alignées, ni trop hautes ni affaissées.","Mantieni le anche allineate, né alte né cedute.","Halte die Hüfte in der Linie, weder zu hoch noch durchhängend."],
  ["Empujá el suelo hasta extender los brazos.","Push the floor away until your arms are extended.","Empurre o chão até estender os braços.","Pousse le sol jusqu’à tendre les bras.","Spingi il pavimento fino a distendere le braccia.","Drück dich vom Boden weg, bis die Arme gestreckt sind."],
  ["Dejar la cadera atrás, en posición de cuadrupedia.","Leaving your hips back, in an all-fours position.","Deixar o quadril para trás, em posição de quatro apoios.","Laisser les hanches en arrière, en position à quatre pattes.","Lasciare le anche indietro, in posizione a quattro zampe.","Die Hüfte hinten lassen, im Vierfüßlerstand."],
  ["Abrir los codos a 90 grados del cuerpo.","Flaring your elbows to 90 degrees from your body.","Abrir os cotovelos a 90 graus do corpo.","Écarter les coudes à 90 degrés du corps.","Aprire i gomiti a 90 gradi dal corpo.","Die Ellbogen 90 Grad vom Körper abspreizen."],
  ["Bajar solo la cabeza sin bajar el pecho.","Dropping only your head without lowering your chest.","Abaixar só a cabeça sem abaixar o peito.","Baisser seulement la tête sans descendre la poitrine.","Abbassare solo la testa senza abbassare il petto.","Nur den Kopf senken, ohne die Brust abzusenken."],
  ["Apoyar las rodillas acorta la palanca y reduce el peso que movés, por eso es más fácil que la flexión clásica.","Resting on your knees shortens the lever and reduces the weight you move, which is why it is easier than a standard push-up.","Apoiar os joelhos encurta a alavanca e reduz o peso que você move, por isso é mais fácil que a flexão clássica.","Poser les genoux raccourcit le levier et réduit le poids déplacé, c’est pourquoi c’est plus facile que la pompe classique.","Appoggiare le ginocchia accorcia la leva e riduce il peso che sposti, per questo è più facile del piegamento classico.","Die Knie aufzusetzen verkürzt den Hebel und verringert das bewegte Gewicht; deshalb ist es leichter als der klassische Liegestütz."],
  ["Progresá a flexiones clásicas cuando hagas las repeticiones con buena forma.","Progress to standard push-ups once you can do the reps with good form.","Avance para flexões clássicas quando fizer as repetições com boa forma.","Passe aux pompes classiques quand tu fais les répétitions avec une bonne forme.","Passa ai piegamenti classici quando fai le ripetizioni con una buona forma.","Wechsle zu klassischen Liegestützen, sobald du die Wiederholungen sauber schaffst."],
  ["Banda elástica con manijas, pasada por detrás de la espalda o anclada en un punto firme a la altura del pecho","Resistance band with handles, wrapped behind your back or anchored to a sturdy point at chest height","Elástico com alças, passado por trás das costas ou preso em um ponto firme na altura do peito","Bande élastique avec poignées, passée derrière le dos ou ancrée à un point solide à hauteur de poitrine","Elastico con maniglie, passato dietro la schiena o ancorato a un punto stabile all’altezza del petto","Widerstandsband mit Griffen, hinter dem Rücken geführt oder auf Brusthöhe an einem festen Punkt verankert"],
  ["Parate con la banda pasando por la espalda a la altura de los omóplatos, una manija en cada mano junto al pecho y un pie adelantado.","Stand with the band across your back at shoulder-blade height, a handle in each hand by your chest and one foot forward.","Fique com o elástico passando pelas costas na altura das escápulas, uma alça em cada mão junto ao peito e um pé à frente.","Tiens-toi avec la bande passée dans le dos à hauteur des omoplates, une poignée dans chaque main près de la poitrine et un pied en avant.","Mettiti con l’elastico che passa sulla schiena all’altezza delle scapole, una maniglia per mano vicino al petto e un piede avanti.","Stell dich hin, das Band auf Schulterblatthöhe hinter dem Rücken, je einen Griff an der Brust, ein Fuß vorn."],
  ["Ajustá la tensión acortando la banda en las manos o alejándote del anclaje.","Adjust the tension by shortening the band in your hands or stepping away from the anchor.","Ajuste a tensão encurtando o elástico nas mãos ou se afastando da ancoragem.","Règle la tension en raccourcissant la bande dans tes mains ou en t’éloignant du point d’ancrage.","Regola la tensione accorciando l’elastico nelle mani o allontanandoti dall’ancoraggio.","Pass die Spannung an, indem du das Band in den Händen kürzer fasst oder von der Verankerung weggehst."],
  ["Empujá las manos al frente hasta extender los brazos a la altura del pecho.","Press your hands forward until your arms are extended at chest height.","Empurre as mãos à frente até estender os braços na altura do peito.","Pousse les mains devant toi jusqu’à tendre les bras à hauteur de poitrine.","Spingi le mani in avanti fino a distendere le braccia all’altezza del petto.","Drück die Hände nach vorn, bis die Arme auf Brusthöhe gestreckt sind."],
  ["Pausá un instante sin bloquear los codos.","Pause for a moment without locking your elbows.","Pause um instante sem travar os cotovelos.","Marque une courte pause sans verrouiller les coudes.","Fai una breve pausa senza bloccare i gomiti.","Halte kurz, ohne die Ellbogen durchzudrücken."],
  ["Volvé despacio hasta que las manos queden junto al pecho.","Return slowly until your hands are by your chest.","Volte devagar até as mãos ficarem junto ao peito.","Reviens lentement jusqu’à ce que les mains soient près de la poitrine.","Torna lentamente finché le mani sono vicino al petto.","Führ langsam zurück, bis die Hände an der Brust sind."],
  ["Encoger los hombros al empujar.","Shrugging your shoulders as you press.","Encolher os ombros ao empurrar.","Hausser les épaules en poussant.","Sollevare le spalle mentre spingi.","Beim Drücken die Schultern hochziehen."],
  ["Dejar que la banda vuelva de golpe.","Letting the band snap back.","Deixar o elástico voltar de uma vez.","Laisser la bande revenir d’un coup.","Lasciare che l’elastico torni di colpo.","Das Band zurückschnellen lassen."],
  ["Revisá la banda antes de usarla; si tiene cortes, reemplazala.","Check the band before using it; if it has cuts, replace it.","Verifique o elástico antes de usar; se tiver cortes, substitua-o.","Vérifie la bande avant de l’utiliser ; si elle présente des coupures, remplace-la.","Controlla l’elastico prima di usarlo; se ha tagli, sostituiscilo.","Prüf das Band vor der Nutzung; wenn es Risse hat, ersetz es."],
  ["La resistencia aumenta al final del recorrido: controlá esa parte.","Resistance increases at the end of the movement: control that part.","A resistência aumenta no final do movimento: controle essa parte.","La résistance augmente en fin de mouvement : contrôle cette partie.","La resistenza aumenta alla fine del movimento: controlla quella parte.","Der Widerstand steigt am Ende der Bewegung: Kontrolliere diesen Teil."],
  ["Si la anclás, usá un punto firme como una puerta bien cerrada con el accesorio adecuado.","If you anchor it, use a sturdy point such as a firmly closed door with the right attachment.","Se for prender, use um ponto firme como uma porta bem fechada com o acessório adequado.","Si tu l’ancres, utilise un point solide comme une porte bien fermée avec l’accessoire adapté.","Se lo ancori, usa un punto stabile come una porta ben chiusa con l’accessorio adatto.","Wenn du es verankerst, nutze einen festen Punkt wie eine gut geschlossene Tür mit passendem Türanker."],
  ["Pectoral mayor, con más énfasis en la porción clavicular","Pectoralis major, with more emphasis on the clavicular portion","Peitoral maior, com mais ênfase na porção clavicular","Grand pectoral, avec davantage d’accent sur le faisceau claviculaire","Grande pettorale, con più enfasi sulla porzione clavicolare","Großer Brustmuskel mit stärkerem Fokus auf den Schlüsselbeinanteil"],
  ["Banco, escalón o caja firme para apoyar los pies","Bench, step or sturdy box to rest your feet on","Banco, degrau ou caixa firme para apoiar os pés","Banc, marche ou box solide pour poser les pieds","Panca, gradino o box stabile per appoggiare i piedi","Bank, Stufe oder stabile Box für die Füße"],
  ["Intermedio-avanzado","Intermediate–advanced","Intermediário-avançado","Intermédiaire-avancé","Intermedio-avanzato","Fortgeschritten bis sehr fortgeschritten"],
  ["Apoyá las manos en el suelo algo más abiertas que los hombros y los pies sobre un banco o escalón firme, con el cuerpo en línea recta.","Place your hands on the floor slightly wider than your shoulders and your feet on a sturdy bench or step, body in a straight line.","Apoie as mãos no chão um pouco mais abertas que os ombros e os pés sobre um banco ou degrau firme, com o corpo em linha reta.","Pose les mains au sol un peu plus écartées que les épaules et les pieds sur un banc ou une marche solide, corps aligné.","Appoggia le mani a terra poco più larghe delle spalle e i piedi su una panca o un gradino stabile, con il corpo in linea retta.","Setz die Hände etwas breiter als schulterbreit auf den Boden und die Füße auf eine stabile Bank oder Stufe, Körper in einer geraden Linie."],
  ["Verificá que la superficie de los pies no se mueva y alineá cabeza, tronco y cadera.","Check that the surface under your feet doesn’t move and align your head, torso and hips.","Verifique que a superfície dos pés não se mova e alinhe cabeça, tronco e quadril.","Vérifie que la surface sous tes pieds ne bouge pas et aligne tête, buste et hanches.","Verifica che la superficie dei piedi non si muova e allinea testa, busto e anche.","Prüf, dass die Fläche unter den Füßen nicht wackelt, und bring Kopf, Oberkörper und Hüfte in eine Linie."],
  ["Flexioná los codos y bajá el pecho hacia el suelo sin dejar caer la cadera.","Bend your elbows and lower your chest toward the floor without letting your hips drop.","Flexione os cotovelos e abaixe o peito em direção ao chão sem deixar o quadril cair.","Fléchis les coudes et descends la poitrine vers le sol sans laisser tomber les hanches.","Piega i gomiti e abbassa il petto verso il pavimento senza far cadere le anche.","Beuge die Ellbogen und senk die Brust zum Boden, ohne die Hüfte durchhängen zu lassen."],
  ["Llegá a un rango cómodo sin apoyar la cabeza.","Go to a comfortable range without resting your head.","Vá até uma amplitude confortável sem apoiar a cabeça.","Va jusqu’à une amplitude confortable sans poser la tête.","Arriva a un’ampiezza comoda senza appoggiare la testa.","Geh bis zu einem angenehmen Bewegungsumfang, ohne den Kopf abzulegen."],
  ["Hundir la cadera o elevarla en pico.","Letting your hips sag or piking them up.","Afundar o quadril ou elevá-lo em pico.","Laisser les hanches s’affaisser ou les monter en pointe.","Far cedere le anche o sollevarle a punta.","Die Hüfte durchhängen lassen oder spitz nach oben schieben."],
  ["Usar una superficie inestable para los pies.","Using an unstable surface for your feet.","Usar uma superfície instável para os pés.","Utiliser une surface instable pour les pieds.","Usare una superficie instabile per i piedi.","Eine instabile Fläche für die Füße nutzen."],
  ["Bajar con la cabeza adelante en lugar del pecho.","Leading with your head instead of your chest.","Descer com a cabeça na frente em vez do peito.","Descendre la tête en avant au lieu de la poitrine.","Scendere con la testa in avanti invece del petto.","Mit dem Kopf voran statt mit der Brust absenken."],
  ["Cuanto más alta la superficie de los pies, mayor la dificultad.","The higher the surface under your feet, the harder it gets.","Quanto mais alta a superfície dos pés, maior a dificuldade.","Plus la surface sous les pieds est haute, plus c’est difficile.","Più alta è la superficie dei piedi, maggiore è la difficoltà.","Je höher die Fläche unter den Füßen, desto schwerer."],
  ["Dominá las flexiones clásicas antes de esta variante.","Master standard push-ups before this variation.","Domine as flexões clássicas antes desta variação.","Maîtrise les pompes classiques avant cette variante.","Padroneggia i piegamenti classici prima di questa variante.","Beherrsch klassische Liegestütze, bevor du diese Variante machst."],
  ["Mantené el abdomen y los glúteos firmes.","Keep your abs and glutes tight.","Mantenha o abdômen e os glúteos firmes.","Garde les abdos et les fessiers serrés.","Mantieni addome e glutei contratti.","Halte Bauch und Gesäß fest."],
  ["Dos mancuernas livianas y colchoneta","Two light dumbbells and a mat","Dois halteres leves e colchonete","Deux haltères légers et un tapis","Due manubri leggeri e tappetino","Zwei leichte Kurzhanteln und eine Matte"],
  ["Acostate boca arriba en el suelo con las rodillas flexionadas y las mancuernas arriba del pecho, palmas enfrentadas y codos apenas flexionados.","Lie on your back on the floor with your knees bent and the dumbbells above your chest, palms facing each other and elbows slightly bent.","Deite-se de barriga para cima no chão com os joelhos flexionados e os halteres acima do peito, palmas voltadas uma para a outra e cotovelos levemente flexionados.","Allonge-toi sur le dos au sol, genoux fléchis, haltères au-dessus de la poitrine, paumes face à face et coudes légèrement fléchis.","Sdraiati a pancia in su a terra con le ginocchia piegate e i manubri sopra il petto, palmi rivolti l’uno verso l’altro e gomiti leggermente piegati.","Leg dich rücklings auf den Boden, Knie gebeugt, Kurzhanteln über der Brust, Handflächen zueinander, Ellbogen leicht gebeugt."],
  ["Fijá un leve ángulo en los codos que vas a mantener en toda la serie.","Set a slight bend in your elbows that you will keep for the whole set.","Fixe um leve ângulo nos cotovelos que você vai manter durante toda a série.","Fixe un léger angle aux coudes que tu garderas toute la série.","Fissa una leggera flessione dei gomiti che manterrai per tutta la serie.","Leg eine leichte Ellbogenbeugung fest, die du den ganzen Satz hältst."],
  ["Abrí los brazos en arco hacia los costados hasta que la parte trasera de los brazos toque suavemente el suelo.","Open your arms out to the sides in an arc until the backs of your arms gently touch the floor.","Abra os braços em arco para os lados até a parte de trás dos braços tocar suavemente o chão.","Ouvre les bras en arc sur les côtés jusqu’à ce que l’arrière des bras touche doucement le sol.","Apri le braccia ad arco verso i lati finché la parte posteriore delle braccia tocca dolcemente terra.","Öffne die Arme in einem Bogen zur Seite, bis die Oberarmrückseiten sanft den Boden berühren."],
  ["Pausá sin relajar los brazos en el suelo.","Pause without relaxing your arms on the floor.","Pause sem relaxar os braços no chão.","Marque une pause sans relâcher les bras au sol.","Fai una pausa senza rilassare le braccia a terra.","Halte kurz, ohne die Arme auf dem Boden abzulegen."],
  ["Cerrá el arco hasta juntar las mancuernas sobre el pecho.","Close the arc until the dumbbells meet over your chest.","Feche o arco até juntar os halteres sobre o peito.","Referme l’arc jusqu’à rapprocher les haltères au-dessus de la poitrine.","Chiudi l’arco fino a unire i manubri sopra il petto.","Schließ den Bogen, bis sich die Kurzhanteln über der Brust treffen."],
  ["Dejar caer los brazos contra el suelo.","Letting your arms drop onto the floor.","Deixar os braços caírem contra o chão.","Laisser tomber les bras au sol.","Lasciar cadere le braccia a terra.","Die Arme auf den Boden fallen lassen."],
  ["El suelo marca el final del recorrido y evita abrir de más el hombro.","The floor marks the end of the range and keeps you from overstretching your shoulder.","O chão marca o fim do movimento e evita abrir demais o ombro.","Le sol marque la fin de l’amplitude et évite d’ouvrir trop l’épaule.","Il pavimento segna la fine del movimento ed evita di aprire troppo la spalla.","Der Boden markiert das Ende der Bewegung und verhindert, dass du die Schulter zu weit öffnest."],
  ["Mantené la espalda y la cadera apoyadas.","Keep your back and hips on the floor.","Mantenha as costas e o quadril apoiados.","Garde le dos et les hanches au sol.","Mantieni schiena e anche appoggiate.","Halte Rücken und Hüfte am Boden."],
  ["Bíceps, deltoides posterior y erectores como estabilizadores","Biceps, rear deltoid and spinal erectors as stabilizers","Bíceps, deltoide posterior e eretores como estabilizadores","Biceps, deltoïde postérieur et érecteurs comme stabilisateurs","Bicipiti, deltoide posteriore ed erettori come stabilizzatori","Bizeps, hinterer Deltamuskel und Rückenstrecker als Stabilisatoren"],
  ["Banda elástica con o sin manijas y colchoneta","Resistance band with or without handles and a mat","Elástico com ou sem alças e colchonete","Bande élastique avec ou sans poignées et tapis","Elastico con o senza maniglie e tappetino","Widerstandsband mit oder ohne Griffe und eine Matte"],
  ["Sentate en el suelo con las piernas extendidas o apenas flexionadas, la banda pasada por la planta de los pies y un extremo en cada mano.","Sit on the floor with your legs straight or slightly bent, the band around the soles of your feet and one end in each hand.","Sente-se no chão com as pernas estendidas ou levemente flexionadas, o elástico passado pela sola dos pés e uma ponta em cada mão.","Assieds-toi au sol, jambes tendues ou légèrement fléchies, la bande passée sous la plante des pieds et une extrémité dans chaque main.","Siediti a terra con le gambe distese o appena piegate, l’elastico passato sotto la pianta dei piedi e un’estremità in ogni mano.","Setz dich mit gestreckten oder leicht gebeugten Beinen auf den Boden, das Band um die Fußsohlen, je ein Ende in einer Hand."],
  ["Sentate erguido con la banda tensa y los brazos extendidos al frente.","Sit tall with the band taut and your arms extended in front of you.","Sente-se ereto com o elástico tenso e os braços estendidos à frente.","Assieds-toi droit, bande tendue et bras tendus devant toi.","Siediti dritto con l’elastico teso e le braccia distese in avanti.","Setz dich aufrecht hin, das Band gespannt, die Arme nach vorn gestreckt."],
  ["Tirá de los extremos hacia el abdomen llevando los codos atrás, cerca del cuerpo.","Pull the ends toward your abdomen, driving your elbows back close to your body.","Puxe as pontas em direção ao abdômen levando os cotovelos para trás, perto do corpo.","Tire les extrémités vers l’abdomen en amenant les coudes vers l’arrière, près du corps.","Tira le estremità verso l’addome portando i gomiti indietro, vicino al corpo.","Zieh die Enden zum Bauch, die Ellbogen gehen nah am Körper nach hinten."],
  ["Volvé despacio hasta extender los brazos sin redondear la espalda.","Return slowly until your arms are extended, without rounding your back.","Volte devagar até estender os braços sem arredondar as costas.","Reviens lentement jusqu’à tendre les bras sans arrondir le dos.","Torna lentamente fino a distendere le braccia senza arrotondare la schiena.","Führ langsam zurück, bis die Arme gestreckt sind, ohne den Rücken zu runden."],
  ["Inclinarse hacia atrás para tensar la banda.","Leaning back to tension the band.","Inclinar-se para trás para tensionar o elástico.","Se pencher en arrière pour tendre la bande.","Inclinarsi indietro per tendere l’elastico.","Sich nach hinten lehnen, um das Band zu spannen."],
  ["Encoger los hombros.","Shrugging your shoulders.","Encolher os ombros.","Hausser les épaules.","Sollevare le spalle.","Die Schultern hochziehen."],
  ["Dejar que la banda se suelte de los pies.","Letting the band slip off your feet.","Deixar o elástico escapar dos pés.","Laisser la bande glisser des pieds.","Lasciare che l’elastico scivoli dai piedi.","Das Band von den Füßen rutschen lassen."],
  ["Si te cuesta sentarte erguido, flexioná las rodillas o sentate sobre un almohadón.","If it is hard to sit tall, bend your knees or sit on a cushion.","Se for difícil sentar ereto, flexione os joelhos ou sente-se sobre uma almofada.","S’il est difficile de rester assis droit, fléchis les genoux ou assieds-toi sur un coussin.","Se fai fatica a sederti dritto, piega le ginocchia o siediti su un cuscino.","Wenn dir das aufrechte Sitzen schwerfällt, beug die Knie oder setz dich auf ein Kissen."],
  ["Revisá que la banda no tenga cortes y que quede bien pasada por los pies.","Check that the band has no cuts and is securely around your feet.","Verifique se o elástico não tem cortes e está bem passado pelos pés.","Vérifie que la bande n’a pas de coupure et qu’elle est bien passée sous les pieds.","Controlla che l’elastico non abbia tagli e sia ben passato sotto i piedi.","Prüf, dass das Band keine Risse hat und sicher um die Füße liegt."],
  ["Cruzar los extremos aumenta la resistencia.","Crossing the ends increases the resistance.","Cruzar as pontas aumenta a resistência.","Croiser les extrémités augmente la résistance.","Incrociare le estremità aumenta la resistenza.","Wenn du die Enden kreuzt, steigt der Widerstand."],
  ["Bíceps, deltoides posterior y estabilizadores del tronco","Biceps, rear deltoid and trunk stabilizers","Bíceps, deltoide posterior e estabilizadores do tronco","Biceps, deltoïde postérieur et stabilisateurs du tronc","Bicipiti, deltoide posteriore e stabilizzatori del tronco","Bizeps, hinterer Deltamuskel und Rumpfstabilisatoren"],
  ["Mochila resistente con carga estable (libros o botellas) y una mesa o silla firme para apoyar una mano","Sturdy backpack with a stable load (books or bottles) and a sturdy table or chair to rest one hand on","Mochila resistente com carga estável (livros ou garrafas) e uma mesa ou cadeira firme para apoiar uma mão","Sac à dos solide avec une charge stable (livres ou bouteilles) et une table ou chaise solide pour poser une main","Zaino resistente con carico stabile (libri o bottiglie) e un tavolo o una sedia stabile per appoggiare una mano","Stabiler Rucksack mit fester Last (Bücher oder Flaschen) und ein stabiler Tisch oder Stuhl zum Abstützen einer Hand"],
  ["Apoyá una mano y la rodilla del mismo lado sobre una superficie firme, con la mochila tomada de la manija o las correas en la otra mano.","Rest one hand and the knee on the same side on a sturdy surface, holding the backpack by its handle or straps in your other hand.","Apoie uma mão e o joelho do mesmo lado sobre uma superfície firme, com a mochila segura pela alça ou pelas correias na outra mão.","Pose une main et le genou du même côté sur une surface solide, le sac tenu par la poignée ou les bretelles dans l’autre main.","Appoggia una mano e il ginocchio dello stesso lato su una superficie stabile, con lo zaino tenuto per la maniglia o gli spallacci nell’altra mano.","Stütz eine Hand und das Knie derselben Seite auf eine feste Fläche, den Rucksack am Griff oder an den Trägern in der anderen Hand."],
  ["Exhalá al tirar e inhalá al bajar.","Exhale as you pull and inhale as you lower.","Expire ao puxar e inspire ao descer.","Expire en tirant et inspire en redescendant.","Espira tirando e inspira scendendo.","Atme beim Ziehen aus und beim Absenken ein."],
  ["Cargá la mochila con objetos que no se muevan, cerrala bien y revisá que las costuras y correas estén firmes.","Load the backpack with items that won’t shift, close it well and check that the seams and straps are solid.","Carregue a mochila com objetos que não se mexam, feche-a bem e verifique se as costuras e correias estão firmes.","Remplis le sac d’objets qui ne bougent pas, ferme-le bien et vérifie que les coutures et les bretelles sont solides.","Riempi lo zaino con oggetti che non si muovano, chiudilo bene e controlla che cuciture e spallacci siano solidi.","Füll den Rucksack mit Dingen, die nicht verrutschen, schließ ihn gut und prüf, ob Nähte und Träger halten."],
  ["Con la espalda neutra, dejá colgar la mochila con el brazo extendido.","With a neutral back, let the backpack hang with your arm extended.","Com as costas neutras, deixe a mochila pendurada com o braço estendido.","Dos neutre, laisse pendre le sac bras tendu.","Con la schiena neutra, lascia pendere lo zaino con il braccio disteso.","Lass den Rucksack mit neutralem Rücken am gestreckten Arm hängen."],
  ["Tirá de la mochila hacia la cadera llevando el codo atrás, cerca del cuerpo.","Pull the backpack toward your hip, driving your elbow back close to your body.","Puxe a mochila em direção ao quadril levando o cotovelo para trás, perto do corpo.","Tire le sac vers la hanche en amenant le coude vers l’arrière, près du corps.","Tira lo zaino verso l’anca portando il gomito indietro, vicino al corpo.","Zieh den Rucksack zur Hüfte, der Ellbogen geht nah am Körper nach hinten."],
  ["Bajá con control; completá un lado y después el otro.","Lower with control; finish one side and then the other.","Desça com controle; complete um lado e depois o outro.","Redescends en contrôle ; termine un côté puis l’autre.","Scendi con controllo; completa un lato e poi l’altro.","Senk kontrolliert ab; mach erst eine Seite, dann die andere."],
  ["Usar una mochila con correas gastadas o carga suelta que se desplaza.","Using a backpack with worn straps or a loose load that shifts.","Usar uma mochila com correias gastas ou carga solta que se desloca.","Utiliser un sac aux bretelles usées ou une charge mal calée qui bouge.","Usare uno zaino con spallacci consumati o un carico libero che si sposta.","Einen Rucksack mit abgenutzten Trägern oder loser, verrutschender Last nutzen."],
  ["Girar el tronco para subir la mochila.","Rotating your torso to lift the backpack.","Girar o tronco para subir a mochila.","Faire pivoter le buste pour monter le sac.","Ruotare il busto per sollevare lo zaino.","Den Oberkörper drehen, um den Rucksack hochzubringen."],
  ["Apoyarse en una silla liviana que se mueve.","Leaning on a light chair that moves.","Apoiar-se em uma cadeira leve que se move.","S’appuyer sur une chaise légère qui bouge.","Appoggiarsi a una sedia leggera che si muove.","Sich auf einen leichten Stuhl stützen, der wegrutscht."],
  ["Distribuí la carga en el fondo de la mochila para que no se balancee.","Distribute the load at the bottom of the backpack so it doesn’t swing.","Distribua a carga no fundo da mochila para ela não balançar.","Répartis la charge au fond du sac pour qu’il ne se balance pas.","Distribuisci il carico sul fondo dello zaino perché non oscilli.","Verteil die Last unten im Rucksack, damit er nicht pendelt."],
  ["Empezá con poco peso y agregá de a poco.","Start with a light weight and add gradually.","Comece com pouco peso e acrescente aos poucos.","Commence avec peu de poids et ajoute progressivement.","Inizia con poco peso e aggiungine poco alla volta.","Beginne mit wenig Gewicht und steigere nach und nach."],
  ["Mantené el cuello alineado con la espalda.","Keep your neck in line with your back.","Mantenha o pescoço alinhado com as costas.","Garde la nuque dans l’alignement du dos.","Mantieni il collo allineato con la schiena.","Halte den Nacken in Verlängerung des Rückens."],
  ["Dorsal ancho y pectoral mayor","Latissimus dorsi and pectoralis major","Grande dorsal e peitoral maior","Grand dorsal et grand pectoral","Gran dorsale e grande pettorale","Breiter Rückenmuskel und großer Brustmuskel"],
  ["Redondo mayor, porción larga del tríceps y serrato anterior","Teres major, long head of the triceps and serratus anterior","Redondo maior, porção longa do tríceps e serrátil anterior","Grand rond, chef long du triceps et dentelé antérieur","Grande rotondo, capo lungo del tricipite e dentato anteriore","Großer Rundmuskel, langer Trizepskopf und vorderer Sägemuskel"],
  ["Una mancuerna y colchoneta","One dumbbell and a mat","Um halter e colchonete","Un haltère et un tapis","Un manubrio e tappetino","Eine Kurzhantel und eine Matte"],
  ["Acostate boca arriba en el suelo con las rodillas flexionadas y una mancuerna tomada con ambas manos sobre el pecho, brazos extendidos.","Lie on your back on the floor with your knees bent and a dumbbell held with both hands over your chest, arms extended.","Deite-se de barriga para cima no chão com os joelhos flexionados e um halter seguro com as duas mãos sobre o peito, braços estendidos.","Allonge-toi sur le dos au sol, genoux fléchis, un haltère tenu à deux mains au-dessus de la poitrine, bras tendus.","Sdraiati a pancia in su a terra con le ginocchia piegate e un manubrio tenuto con entrambe le mani sopra il petto, braccia distese.","Leg dich rücklings auf den Boden, Knie gebeugt, eine Kurzhantel mit beiden Händen über der Brust, Arme gestreckt."],
  ["Inhalá al llevar la mancuerna atrás y exhalá al volver.","Inhale as you take the dumbbell back and exhale as you return.","Inspire ao levar o halter para trás e expire ao voltar.","Inspire en amenant l’haltère vers l’arrière et expire en revenant.","Inspira portando il manubrio indietro ed espira tornando.","Atme beim Zurückführen der Kurzhantel über den Kopf ein und beim Zurückkommen aus."],
  ["Tomá la mancuerna por un extremo con ambas manos y llevala arriba del pecho con codos apenas flexionados.","Hold one end of the dumbbell with both hands and bring it above your chest with your elbows slightly bent.","Segure o halter por uma ponta com as duas mãos e leve-o acima do peito com os cotovelos levemente flexionados.","Tiens l’haltère par une extrémité à deux mains et amène-le au-dessus de la poitrine, coudes légèrement fléchis.","Afferra il manubrio da un’estremità con entrambe le mani e portalo sopra il petto con i gomiti leggermente piegati.","Fass die Kurzhantel an einem Ende mit beiden Händen und bring sie mit leicht gebeugten Ellbogen über die Brust."],
  ["Llevá la mancuerna en arco por detrás de la cabeza hasta un rango cómodo o hasta que toque suavemente el suelo.","Take the dumbbell in an arc behind your head to a comfortable range or until it gently touches the floor.","Leve o halter em arco por trás da cabeça até uma amplitude confortável ou até tocar suavemente o chão.","Amène l’haltère en arc derrière la tête jusqu’à une amplitude confortable ou jusqu’à toucher doucement le sol.","Porta il manubrio ad arco dietro la testa fino a un’ampiezza comoda o finché tocca dolcemente terra.","Führ die Kurzhantel in einem Bogen hinter den Kopf, bis zu einem angenehmen Bewegungsumfang oder bis sie sanft den Boden berührt."],
  ["Mantené las costillas abajo y la zona lumbar apoyada.","Keep your ribs down and your lower back on the floor.","Mantenha as costelas para baixo e a lombar apoiada.","Garde les côtes basses et le bas du dos au sol.","Tieni le costole basse e la zona lombare appoggiata.","Halte die Rippen unten und den unteren Rücken am Boden."],
  ["Volvé por el mismo arco hasta tener la mancuerna sobre el pecho.","Return along the same arc until the dumbbell is over your chest.","Volte pelo mesmo arco até ter o halter sobre o peito.","Reviens par le même arc jusqu’à avoir l’haltère au-dessus de la poitrine.","Torna lungo lo stesso arco fino ad avere il manubrio sopra il petto.","Führ sie auf demselben Bogen zurück, bis die Kurzhantel über der Brust ist."],
  ["Arquear la espalda para llegar más lejos.","Arching your back to reach farther.","Arquear as costas para ir mais longe.","Cambrer le dos pour aller plus loin.","Inarcare la schiena per arrivare più lontano.","Ins Hohlkreuz gehen, um weiter zu kommen."],
  ["Usar una mancuerna pesada que no podés sostener con seguridad sobre la cara.","Using a heavy dumbbell you can’t safely hold over your face.","Usar um halter pesado que você não consegue segurar com segurança sobre o rosto.","Utiliser un haltère lourd que tu ne peux pas tenir en sécurité au-dessus du visage.","Usare un manubrio pesante che non riesci a tenere in sicurezza sopra il viso.","Eine schwere Kurzhantel nehmen, die du nicht sicher über dem Gesicht halten kannst."],
  ["El suelo limita el rango y protege el hombro de estirarse de más.","The floor limits the range and protects your shoulder from overstretching.","O chão limita a amplitude e protege o ombro de alongar demais.","Le sol limite l’amplitude et protège l’épaule d’un étirement excessif.","Il pavimento limita l’ampiezza e protegge la spalla da un allungamento eccessivo.","Der Boden begrenzt den Bewegungsumfang und schützt die Schulter vor Überdehnung."],
  ["Sujetá la mancuerna con firmeza: pasa sobre la cara.","Hold the dumbbell firmly: it passes over your face.","Segure o halter com firmeza: ele passa sobre o rosto.","Tiens l’haltère fermement : il passe au-dessus de ton visage.","Tieni saldamente il manubrio: passa sopra il viso.","Halte die Kurzhantel fest: Sie bewegt sich über deinem Gesicht."],
  ["Si el hombro molesta, acortá el recorrido.","If your shoulder bothers you, shorten the range.","Se o ombro incomodar, encurte o movimento.","Si ton épaule te gêne, réduis l’amplitude.","Se la spalla dà fastidio, accorcia il movimento.","Wenn die Schulter zwickt, verkürz den Bewegungsweg."],
  ["Glúteo mayor, deltoides posterior y trapecio inferior","Gluteus maximus, rear deltoid and lower trapezius","Glúteo máximo, deltoide posterior e trapézio inferior","Grand fessier, deltoïde postérieur et trapèze inférieur","Grande gluteo, deltoide posteriore e trapezio inferiore","Großer Gesäßmuskel, hinterer Deltamuskel und unterer Trapezmuskel"],
  ["Acostate boca abajo con los brazos extendidos al frente, las piernas extendidas y la frente apoyada o mirando al suelo.","Lie face down with your arms extended in front, legs extended and forehead resting on the floor or eyes on the floor.","Deite-se de bruços com os braços estendidos à frente, as pernas estendidas e a testa apoiada ou olhando para o chão.","Allonge-toi sur le ventre, bras tendus devant, jambes tendues et front posé ou regard vers le sol.","Sdraiati a pancia in giù con le braccia distese in avanti, le gambe distese e la fronte appoggiata o lo sguardo verso il pavimento.","Leg dich bäuchlings hin, Arme nach vorn gestreckt, Beine gestreckt, Stirn abgelegt oder Blick zum Boden."],
  ["Exhalá al elevar e inhalá al bajar.","Exhale as you lift and inhale as you lower.","Expire ao elevar e inspire ao abaixar.","Expire en levant et inspire en abaissant.","Espira sollevando e inspira abbassando.","Atme beim Anheben aus und beim Senken ein."],
  ["30–60 segundos","30–60 seconds","30–60 segundos","30–60 secondes","30–60 secondi","30–60 Sekunden"],
  ["Afirmá el abdomen y los glúteos con el cuello neutro.","Brace your abs and glutes with your neck neutral.","Firme o abdômen e os glúteos com o pescoço neutro.","Gaine les abdos et les fessiers, nuque neutre.","Contrai addome e glutei con il collo neutro.","Spann Bauch und Gesäß an, Nacken neutral."],
  ["Elevá a la vez el brazo derecho y la pierna izquierda unos centímetros del suelo.","Lift your right arm and left leg a few centimeters off the floor at the same time.","Eleve ao mesmo tempo o braço direito e a perna esquerda alguns centímetros do chão.","Lève en même temps le bras droit et la jambe gauche de quelques centimètres.","Solleva insieme il braccio destro e la gamba sinistra di qualche centimetro da terra.","Heb gleichzeitig den rechten Arm und das linke Bein ein paar Zentimeter vom Boden."],
  ["Sostené un instante y bajá con control.","Hold for a moment and lower with control.","Sustente um instante e abaixe com controle.","Tiens un instant et redescends en contrôle.","Mantieni un istante e abbassa con controllo.","Halte kurz und senk kontrolliert ab."],
  ["Repetí con el brazo izquierdo y la pierna derecha, alternando lados.","Repeat with your left arm and right leg, alternating sides.","Repita com o braço esquerdo e a perna direita, alternando os lados.","Recommence avec le bras gauche et la jambe droite, en alternant les côtés.","Ripeti con il braccio sinistro e la gamba destra, alternando i lati.","Wiederhol es mit linkem Arm und rechtem Bein und wechsle die Seiten ab."],
  ["Levantar la cabeza y mirar al frente.","Lifting your head and looking forward.","Levantar a cabeça e olhar para frente.","Relever la tête et regarder devant.","Sollevare la testa e guardare avanti.","Den Kopf heben und nach vorn schauen."],
  ["Subir demasiado y arquear la zona lumbar.","Lifting too high and arching your lower back.","Subir demais e arquear a lombar.","Monter trop haut et cambrer le bas du dos.","Salire troppo e inarcare la zona lombare.","Zu hoch heben und ins Hohlkreuz gehen."],
  ["Moverse rápido sin pausar.","Moving fast without pausing.","Mover-se rápido sem pausar.","Bouger vite sans marquer de pause.","Muoversi veloce senza pause.","Schnell ohne Pause bewegen."],
  ["Pensá en estirarte hacia adelante y atrás más que hacia arriba.","Think about lengthening forward and back more than lifting up.","Pense em se alongar para frente e para trás mais do que para cima.","Pense à t’allonger vers l’avant et l’arrière plutôt que vers le haut.","Pensa ad allungarti in avanti e indietro più che verso l’alto.","Denk eher daran, dich nach vorn und hinten lang zu machen, als nach oben zu heben."],
  ["Pocos centímetros de elevación son suficientes.","A few centimeters of lift are enough.","Poucos centímetros de elevação são suficientes.","Quelques centimètres d’élévation suffisent.","Pochi centimetri di sollevamento sono sufficienti.","Ein paar Zentimeter Höhe reichen."],
  ["Alternar lados hace que sea más fácil que el superman con ambos brazos y piernas.","Alternating sides makes it easier than the superman with both arms and legs.","Alternar os lados torna o exercício mais fácil que o super-homem com braços e pernas juntos.","Alterner les côtés rend l’exercice plus facile que le superman avec les deux bras et les deux jambes.","Alternare i lati lo rende più facile del superman con entrambe le braccia e le gambe.","Durch das Abwechseln ist es leichter als der Superman mit beiden Armen und Beinen."],
  ["Deltoides anterior y medio","Front and middle deltoid","Deltoide anterior e médio","Deltoïde antérieur et moyen","Deltoide anteriore e medio","Vorderer und mittlerer Deltamuskel"],
  ["Tríceps, trapecio superior y serrato anterior","Triceps, upper trapezius and serratus anterior","Tríceps, trapézio superior e serrátil anterior","Triceps, trapèze supérieur et dentelé antérieur","Tricipiti, trapezio superiore e dentato anteriore","Trizeps, oberer Trapezmuskel und vorderer Sägemuskel"],
  ["Dos mancuernas livianas; opcionalmente una silla firme","Two light dumbbells; optionally a sturdy chair","Dois halteres leves; opcionalmente uma cadeira firme","Deux haltères légers ; éventuellement une chaise solide","Due manubri leggeri; facoltativamente una sedia stabile","Zwei leichte Kurzhanteln; optional ein stabiler Stuhl"],
  ["Sentate erguido en una silla firme o parate con los pies al ancho de cadera, con una mancuerna en cada mano a la altura de los hombros.","Sit tall on a sturdy chair or stand with your feet hip-width apart, a dumbbell in each hand at shoulder height.","Sente-se ereto em uma cadeira firme ou fique em pé com os pés na largura do quadril, com um halter em cada mão na altura dos ombros.","Assieds-toi droit sur une chaise solide ou tiens-toi debout pieds à la largeur des hanches, un haltère dans chaque main à hauteur des épaules.","Siediti dritto su una sedia stabile o stai in piedi con i piedi alla larghezza delle anche, con un manubrio per mano all’altezza delle spalle.","Setz dich aufrecht auf einen stabilen Stuhl oder stell dich hüftbreit hin, je eine Kurzhantel auf Schulterhöhe."],
  ["Exhalá al empujar e inhalá al bajar.","Exhale as you press and inhale as you lower.","Expire ao empurrar e inspire ao descer.","Expire en poussant et inspire en redescendant.","Espira spingendo e inspira scendendo.","Atme beim Drücken aus und beim Absenken ein."],
  ["Ubicá las mancuernas a la altura de los hombros, palmas al frente o enfrentadas, con los codos bajo las muñecas.","Position the dumbbells at shoulder height, palms forward or facing each other, with your elbows under your wrists.","Posicione os halteres na altura dos ombros, palmas para frente ou voltadas uma para a outra, com os cotovelos sob os punhos.","Place les haltères à hauteur des épaules, paumes vers l’avant ou face à face, coudes sous les poignets.","Posiziona i manubri all’altezza delle spalle, palmi in avanti o rivolti l’uno verso l’altro, con i gomiti sotto i polsi.","Bring die Kurzhanteln auf Schulterhöhe, Handflächen nach vorn oder zueinander, Ellbogen unter den Handgelenken."],
  ["Empujá las mancuernas hacia arriba hasta extender los brazos sin chocarlas.","Press the dumbbells up until your arms are extended, without clashing them.","Empurre os halteres para cima até estender os braços, sem batê-los.","Pousse les haltères vers le haut jusqu’à tendre les bras, sans les entrechoquer.","Spingi i manubri verso l’alto fino a distendere le braccia, senza farli sbattere.","Drück die Kurzhanteln nach oben, bis die Arme gestreckt sind, ohne sie aneinanderzuschlagen."],
  ["Mantené las costillas abajo sin arquear la espalda.","Keep your ribs down without arching your back.","Mantenha as costelas para baixo sem arquear as costas.","Garde les côtes basses sans cambrer le dos.","Tieni le costole basse senza inarcare la schiena.","Halte die Rippen unten, ohne ins Hohlkreuz zu gehen."],
  ["Bajá con control hasta la altura de los hombros.","Lower with control to shoulder height.","Desça com controle até a altura dos ombros.","Redescends en contrôle jusqu’à hauteur des épaules.","Scendi con controllo fino all’altezza delle spalle.","Senk kontrolliert bis auf Schulterhöhe ab."],
  ["Arquear la zona lumbar al subir.","Arching your lower back as you press.","Arquear a lombar ao subir.","Cambrer le bas du dos en poussant.","Inarcare la zona lombare salendo.","Beim Drücken ins Hohlkreuz gehen."],
  ["Adelantar la cabeza o encoger los hombros.","Pushing your head forward or shrugging your shoulders.","Projetar a cabeça para frente ou encolher os ombros.","Avancer la tête ou hausser les épaules.","Spingere la testa in avanti o sollevare le spalle.","Den Kopf nach vorn schieben oder die Schultern hochziehen."],
  ["Bajar las mancuernas por debajo de un rango cómodo.","Lowering the dumbbells below a comfortable range.","Abaixar os halteres além de uma amplitude confortável.","Descendre les haltères en dessous d’une amplitude confortable.","Abbassare i manubri sotto un’ampiezza comoda.","Die Kurzhanteln unter einen angenehmen Bewegungsumfang absenken."],
  ["Un peso liviano permite aprender la trayectoria sin compensar.","A light weight lets you learn the path without compensating.","Um peso leve permite aprender a trajetória sem compensar.","Une charge légère permet d’apprendre la trajectoire sans compenser.","Un peso leggero permette di imparare la traiettoria senza compensare.","Mit leichtem Gewicht lernst du die Bewegungsbahn ohne Ausweichbewegungen."],
  ["Sentado en una silla firme reducís la demanda de equilibrio.","Sitting on a sturdy chair reduces the balance demand.","Sentado em uma cadeira firme você reduz a exigência de equilíbrio.","Assis sur une chaise solide, tu réduis la demande d’équilibre.","Seduto su una sedia stabile riduci la richiesta di equilibrio.","Im Sitzen auf einem stabilen Stuhl verringerst du die Gleichgewichtsanforderung."],
  ["Mantené las muñecas rectas, alineadas con los antebrazos.","Keep your wrists straight, aligned with your forearms.","Mantenha os punhos retos, alinhados com os antebraços.","Garde les poignets droits, alignés avec les avant-bras.","Mantieni i polsi dritti, allineati con gli avambracci.","Halte die Handgelenke gerade in einer Linie mit den Unterarmen."],
  ["Tríceps, trapecio y serrato anterior","Triceps, trapezius and serratus anterior","Tríceps, trapézio e serrátil anterior","Triceps, trapèzes et dentelé antérieur","Tricipiti, trapezio e dentato anteriore","Trizeps, Trapezmuskel und vorderer Sägemuskel"],
  ["Banco con respaldo o silla firme y dos mancuernas","Bench with backrest or sturdy chair and two dumbbells","Banco com encosto ou cadeira firme e dois halteres","Banc avec dossier ou chaise solide et deux haltères","Panca con schienale o sedia stabile e due manubri","Bank mit Lehne oder stabiler Stuhl und zwei Kurzhanteln"],
  ["Sentate con la espalda apoyada y las mancuernas frente a los hombros, palmas mirando hacia vos y codos al frente.","Sit with your back supported and the dumbbells in front of your shoulders, palms facing you and elbows forward.","Sente-se com as costas apoiadas e os halteres na frente dos ombros, palmas voltadas para você e cotovelos à frente.","Assieds-toi le dos en appui, haltères devant les épaules, paumes vers toi et coudes devant.","Siediti con la schiena appoggiata e i manubri davanti alle spalle, palmi verso di te e gomiti in avanti.","Setz dich mit angelehntem Rücken hin, Kurzhanteln vor den Schultern, Handflächen zu dir, Ellbogen nach vorn."],
  ["Empezá con las mancuernas a la altura del mentón, palmas hacia la cara.","Start with the dumbbells at chin height, palms facing your face.","Comece com os halteres na altura do queixo, palmas voltadas para o rosto.","Commence avec les haltères à hauteur du menton, paumes vers le visage.","Inizia con i manubri all’altezza del mento, palmi verso il viso.","Beginne mit den Kurzhanteln auf Kinnhöhe, Handflächen zum Gesicht."],
  ["Mientras empujás hacia arriba, girá las palmas hacia afuera y abrí los codos.","As you press up, rotate your palms outward and open your elbows.","Enquanto empurra para cima, gire as palmas para fora e abra os cotovelos.","En poussant vers le haut, tourne les paumes vers l’extérieur et ouvre les coudes.","Mentre spingi verso l’alto, ruota i palmi verso l’esterno e apri i gomiti.","Dreh beim Hochdrücken die Handflächen nach außen und öffne die Ellbogen."],
  ["Terminá con los brazos extendidos y las palmas al frente, sin chocar las mancuernas.","Finish with your arms extended and palms forward, without clashing the dumbbells.","Termine com os braços estendidos e as palmas para frente, sem bater os halteres.","Termine bras tendus et paumes vers l’avant, sans entrechoquer les haltères.","Termina con le braccia distese e i palmi in avanti, senza far sbattere i manubri.","Beende die Bewegung mit gestreckten Armen und Handflächen nach vorn, ohne die Kurzhanteln aneinanderzuschlagen."],
  ["Bajá invirtiendo el giro hasta volver a la posición inicial.","Lower by reversing the rotation until you are back in the starting position.","Desça invertendo o giro até voltar à posição inicial.","Redescends en inversant la rotation jusqu’à la position de départ.","Scendi invertendo la rotazione fino a tornare alla posizione iniziale.","Senk ab und kehr die Drehung um, bis du wieder in der Ausgangsposition bist."],
  ["Hacer el giro y el empuje por separado, de forma brusca.","Doing the rotation and the press separately and abruptly.","Fazer o giro e o empurrão separados, de forma brusca.","Faire la rotation et la poussée séparément, de façon brusque.","Fare la rotazione e la spinta separatamente, in modo brusco.","Drehung und Drücken getrennt und ruckartig ausführen."],
  ["Arquear la espalda y despegarla del respaldo.","Arching your back and lifting it off the backrest.","Arquear as costas e descolá-las do encosto.","Cambrer le dos et le décoller du dossier.","Inarcare la schiena e staccarla dallo schienale.","Ins Hohlkreuz gehen und den Rücken von der Lehne lösen."],
  ["Usar mancuernas demasiado pesadas para controlar la rotación.","Using dumbbells too heavy to control the rotation.","Usar halteres pesados demais para controlar a rotação.","Utiliser des haltères trop lourds pour contrôler la rotation.","Usare manubri troppo pesanti per controllare la rotazione.","Zu schwere Kurzhanteln nehmen, um die Drehung zu kontrollieren."],
  ["La rotación debe ser fluida y acompañar el empuje.","The rotation should be smooth and go along with the press.","A rotação deve ser fluida e acompanhar o empurrão.","La rotation doit être fluide et accompagner la poussée.","La rotazione deve essere fluida e accompagnare la spinta.","Die Drehung sollte fließend sein und das Drücken begleiten."],
  ["Usá menos peso que en un press de hombros común.","Use less weight than in a regular shoulder press.","Use menos peso que em um desenvolvimento comum.","Utilise moins de poids que pour un développé épaules classique.","Usa meno peso che in una normale distensione per le spalle.","Nimm weniger Gewicht als beim normalen Schulterdrücken."],
  ["Si el giro molesta el hombro, volvé al press clásico.","If the rotation bothers your shoulder, go back to the classic press.","Se o giro incomodar o ombro, volte ao desenvolvimento clássico.","Si la rotation gêne ton épaule, reviens au développé classique.","Se la rotazione dà fastidio alla spalla, torna alla distensione classica.","Wenn die Drehung die Schulter stört, geh zurück zum klassischen Drücken."],
  ["Deltoides posterior y romboides","Rear deltoid and rhomboids","Deltoide posterior e romboides","Deltoïde postérieur et rhomboïdes","Deltoide posteriore e romboidi","Hinterer Deltamuskel und Rautenmuskeln"],
  ["Trapecio medio e inferior y rotadores externos del hombro","Middle and lower trapezius and shoulder external rotators","Trapézio médio e inferior e rotadores externos do ombro","Trapèze moyen et inférieur et rotateurs externes de l’épaule","Trapezio medio e inferiore ed extrarotatori della spalla","Mittlerer und unterer Trapezmuskel und Außenrotatoren der Schulter"],
  ["Banda elástica liviana","Light resistance band","Elástico leve","Bande élastique légère","Elastico leggero","Leichtes Widerstandsband"],
  ["Parate erguido con la banda tomada con ambas manos al ancho de hombros y los brazos extendidos al frente a la altura del pecho.","Stand tall holding the band with both hands at shoulder width and your arms extended in front at chest height.","Fique ereto com o elástico seguro com as duas mãos na largura dos ombros e os braços estendidos à frente na altura do peito.","Tiens-toi droit, bande tenue à deux mains à la largeur des épaules, bras tendus devant toi à hauteur de poitrine.","Mettiti dritto con l’elastico impugnato con entrambe le mani alla larghezza delle spalle e le braccia distese in avanti all’altezza del petto.","Stell dich aufrecht hin, das Band schulterbreit mit beiden Händen gefasst, Arme auf Brusthöhe nach vorn gestreckt."],
  ["Exhalá al separar las manos e inhalá al volver.","Exhale as you pull your hands apart and inhale as you return.","Expire ao separar as mãos e inspire ao voltar.","Expire en écartant les mains et inspire en revenant.","Espira separando le mani e inspira tornando.","Atme beim Auseinanderziehen der Hände aus und beim Zurückführen ein."],
  ["Tomá la banda con las palmas hacia abajo y los codos apenas flexionados.","Hold the band with your palms down and your elbows slightly bent.","Segure o elástico com as palmas para baixo e os cotovelos levemente flexionados.","Tiens la bande paumes vers le bas, coudes légèrement fléchis.","Tieni l’elastico con i palmi in basso e i gomiti leggermente piegati.","Halte das Band mit Handflächen nach unten und leicht gebeugten Ellbogen."],
  ["Separá las manos hacia los costados estirando la banda hasta que toque el pecho o casi.","Pull your hands apart to the sides, stretching the band until it touches or nearly touches your chest.","Separe as mãos para os lados esticando o elástico até ele tocar o peito ou quase.","Écarte les mains sur les côtés en étirant la bande jusqu’à ce qu’elle touche presque la poitrine.","Separa le mani verso i lati tendendo l’elastico finché tocca o quasi il petto.","Zieh die Hände zur Seite auseinander, bis das Band die Brust berührt oder fast berührt."],
  ["Volvé despacio al frente sin soltar la tensión de golpe.","Return slowly to the front without releasing the tension abruptly.","Volte devagar à frente sem soltar a tensão de uma vez.","Reviens lentement devant sans relâcher la tension d’un coup.","Torna lentamente in avanti senza rilasciare la tensione di colpo.","Führ langsam nach vorn zurück, ohne die Spannung abrupt zu lösen."],
  ["Arquear la zona lumbar para abrir más.","Arching your lower back to open wider.","Arquear a lombar para abrir mais.","Cambrer le bas du dos pour ouvrir davantage.","Inarcare la zona lombare per aprire di più.","Ins Hohlkreuz gehen, um weiter zu öffnen."],
  ["Usar una banda demasiado dura que obliga a flexionar los codos.","Using a band so stiff it forces you to bend your elbows.","Usar um elástico forte demais que obriga a flexionar os cotovelos.","Utiliser une bande si dure qu’elle oblige à fléchir les coudes.","Usare un elastico così duro da costringerti a piegare i gomiti.","Ein so starkes Band nehmen, dass du die Ellbogen beugen musst."],
  ["Agarrar la banda más cerca entre manos aumenta la dificultad.","Gripping the band with your hands closer together increases the difficulty.","Segurar o elástico com as mãos mais próximas aumenta a dificuldade.","Saisir la bande avec les mains plus rapprochées augmente la difficulté.","Impugnare l’elastico con le mani più vicine aumenta la difficoltà.","Wenn du das Band enger fasst, wird es schwerer."],
  ["Mantené las costillas abajo y el cuello largo.","Keep your ribs down and your neck long.","Mantenha as costelas para baixo e o pescoço alongado.","Garde les côtes basses et la nuque longue.","Tieni le costole basse e il collo lungo.","Halte die Rippen unten und den Nacken lang."],
  ["Banco o silla firme y dos mancuernas","Bench or sturdy chair and two dumbbells","Banco ou cadeira firme e dois halteres","Banc ou chaise solide et deux haltères","Panca o sedia stabile e due manubri","Bank oder stabiler Stuhl und zwei Kurzhanteln"],
  ["Sentate erguido en el borde de un banco o silla firme, con una mancuerna en cada mano a los costados y palmas enfrentadas.","Sit tall on the edge of a bench or sturdy chair, a dumbbell in each hand at your sides and palms facing each other.","Sente-se ereto na borda de um banco ou cadeira firme, com um halter em cada mão ao lado do corpo e as palmas voltadas uma para a outra.","Assieds-toi droit au bord d’un banc ou d’une chaise solide, un haltère dans chaque main le long du corps, paumes face à face.","Siediti dritto sul bordo di una panca o di una sedia stabile, con un manubrio per mano lungo i fianchi e i palmi rivolti l’uno verso l’altro.","Setz dich aufrecht auf die Kante einer Bank oder eines stabilen Stuhls, je eine Kurzhantel seitlich, Handflächen zueinander."],
  ["Pegá los codos a los costados y mantené la espalda recta.","Tuck your elbows to your sides and keep your back straight.","Cole os cotovelos ao corpo e mantenha as costas retas.","Colle les coudes au corps et garde le dos droit.","Tieni i gomiti aderenti ai fianchi e la schiena dritta.","Leg die Ellbogen an den Körper und halte den Rücken gerade."],
  ["Subí una mancuerna flexionando el codo y girando la palma hacia arriba durante el recorrido.","Raise one dumbbell by bending your elbow and rotating your palm up along the way.","Suba um halter flexionando o cotovelo e girando a palma para cima durante o movimento.","Monte un haltère en fléchissant le coude et en tournant la paume vers le haut pendant le mouvement.","Solleva un manubrio piegando il gomito e ruotando il palmo verso l’alto durante il movimento.","Heb eine Kurzhantel durch Beugen des Ellbogens und dreh dabei die Handfläche nach oben."],
  ["Pausá un instante arriba y bajá con control.","Pause for a moment at the top and lower with control.","Pause um instante em cima e desça com controle.","Marque une courte pause en haut et redescends en contrôle.","Fai una breve pausa in alto e scendi con controllo.","Halte oben kurz und senk kontrolliert ab."],
  ["Repetí con el otro brazo, alternando lados.","Repeat with the other arm, alternating sides.","Repita com o outro braço, alternando os lados.","Recommence avec l’autre bras, en alternant les côtés.","Ripeti con l’altro braccio, alternando i lati.","Wiederhol es mit dem anderen Arm und wechsle die Seiten ab."],
  ["Balancear el tronco hacia atrás.","Swinging your torso back.","Balançar o tronco para trás.","Balancer le buste vers l’arrière.","Far oscillare il busto indietro.","Den Oberkörper nach hinten schwingen."],
  ["Adelantar el codo al final del recorrido.","Bringing your elbow forward at the end of the movement.","Levar o cotovelo para frente no final do movimento.","Avancer le coude en fin de mouvement.","Portare avanti il gomito alla fine del movimento.","Am Ende der Bewegung den Ellbogen nach vorn schieben."],
  ["Bajar rápido sin controlar la mancuerna.","Lowering fast without controlling the dumbbell.","Descer rápido sem controlar o halter.","Descendre vite sans contrôler l’haltère.","Scendere veloce senza controllare il manubrio.","Schnell absenken, ohne die Kurzhantel zu kontrollieren."],
  ["Sentado se reduce el impulso de las piernas y la cadera.","Sitting reduces momentum from your legs and hips.","Sentado, reduz-se o impulso das pernas e do quadril.","En position assise, l’élan des jambes et des hanches est réduit.","Da seduto si riduce lo slancio di gambe e anche.","Im Sitzen fällt der Schwung aus Beinen und Hüfte weg."],
  ["Mantené el brazo que descansa quieto a un costado.","Keep the resting arm still at your side.","Mantenha o braço que descansa parado ao lado do corpo.","Garde le bras au repos immobile le long du corps.","Tieni fermo lungo il fianco il braccio che riposa.","Halte den ruhenden Arm still an der Seite."],
  ["Banda elástica con o sin manijas","Resistance band with or without handles","Elástico com ou sem alças","Bande élastique avec ou sans poignées","Elastico con o senza maniglie","Widerstandsband mit oder ohne Griffe"],
  ["Parate con ambos pies sobre el centro de la banda, al ancho de cadera, con un extremo en cada mano y palmas hacia adelante.","Stand with both feet on the middle of the band, hip-width apart, with one end in each hand and palms facing forward.","Fique com os dois pés sobre o centro do elástico, na largura do quadril, com uma ponta em cada mão e as palmas para frente.","Tiens-toi les deux pieds au centre de la bande, à la largeur des hanches, une extrémité dans chaque main et paumes vers l’avant.","Mettiti con entrambi i piedi al centro dell’elastico, alla larghezza delle anche, con un’estremità in ogni mano e i palmi in avanti.","Stell dich mit beiden Füßen hüftbreit auf die Bandmitte, je ein Ende in einer Hand, Handflächen nach vorn."],
  ["Pisá firme la banda y pegá los codos a los costados.","Step firmly on the band and tuck your elbows to your sides.","Pise firme no elástico e cole os cotovelos ao corpo.","Appuie fermement sur la bande et colle les coudes au corps.","Calpesta bene l’elastico e tieni i gomiti aderenti ai fianchi.","Steh fest auf dem Band und leg die Ellbogen an den Körper."],
  ["Flexioná los codos llevando las manos hacia los hombros.","Bend your elbows, bringing your hands toward your shoulders.","Flexione os cotovelos levando as mãos em direção aos ombros.","Fléchis les coudes en amenant les mains vers les épaules.","Piega i gomiti portando le mani verso le spalle.","Beuge die Ellbogen und führ die Hände zu den Schultern."],
  ["Pausá un instante arriba, donde la banda está más tensa.","Pause for a moment at the top, where the band is tightest.","Pause um instante em cima, onde o elástico está mais tenso.","Marque une courte pause en haut, là où la bande est la plus tendue.","Fai una breve pausa in alto, dove l’elastico è più teso.","Halte oben kurz, wo das Band am stärksten gespannt ist."],
  ["Bajá despacio sin dejar que la banda te tire los brazos.","Lower slowly without letting the band pull your arms down.","Desça devagar sem deixar o elástico puxar seus braços.","Redescends lentement sans laisser la bande tirer tes bras.","Scendi lentamente senza lasciare che l’elastico ti tiri le braccia.","Senk langsam ab, ohne dass das Band dir die Arme runterzieht."],
  ["Pisar la banda solo con la punta del pie y que se escape.","Stepping on the band with only the ball of your foot so it slips out.","Pisar o elástico só com a ponta do pé e deixá-lo escapar.","Marcher sur la bande avec la pointe du pied seulement et la laisser s’échapper.","Calpestare l’elastico solo con la punta del piede e farlo scappare.","Nur mit dem Vorfuß auf dem Band stehen, sodass es wegrutscht."],
  ["Separar los codos del cuerpo.","Moving your elbows away from your body.","Afastar os cotovelos do corpo.","Écarter les coudes du corps.","Staccare i gomiti dal corpo.","Die Ellbogen vom Körper lösen."],
  ["Soltar la tensión de golpe al bajar.","Releasing the tension abruptly on the way down.","Soltar a tensão de uma vez ao descer.","Relâcher la tension d’un coup à la descente.","Rilasciare la tensione di colpo in discesa.","Beim Absenken die Spannung abrupt lösen."],
  ["Revisá que la banda no tenga cortes y que quede bien sujeta bajo los pies.","Check that the band has no cuts and stays secure under your feet.","Verifique se o elástico não tem cortes e se fica bem preso sob os pés.","Vérifie que la bande n’a pas de coupure et qu’elle est bien maintenue sous les pieds.","Controlla che l’elastico non abbia tagli e resti ben fermo sotto i piedi.","Prüf, dass das Band keine Risse hat und sicher unter den Füßen liegt."],
  ["Separar más los pies aumenta la resistencia.","Placing your feet wider increases the resistance.","Afastar mais os pés aumenta a resistência.","Écarter davantage les pieds augmente la résistance.","Allargare di più i piedi aumenta la resistenza.","Ein breiterer Stand erhöht den Widerstand."],
  ["Una mancuerna; opcionalmente silla o banco con respaldo","One dumbbell; optionally a chair or bench with backrest","Um halter; opcionalmente cadeira ou banco com encosto","Un haltère ; éventuellement une chaise ou un banc avec dossier","Un manubrio; facoltativamente una sedia o una panca con schienale","Eine Kurzhantel; optional ein Stuhl oder eine Bank mit Lehne"],
  ["Sentate o parate erguido sosteniendo una mancuerna con ambas manos por encima de la cabeza, brazos extendidos.","Sit or stand tall holding one dumbbell with both hands above your head, arms extended.","Sente-se ou fique em pé ereto segurando um halter com as duas mãos acima da cabeça, braços estendidos.","Assieds-toi ou tiens-toi droit en tenant un haltère à deux mains au-dessus de la tête, bras tendus.","Siediti o stai in piedi dritto tenendo un manubrio con entrambe le mani sopra la testa, braccia distese.","Setz oder stell dich aufrecht hin und halte eine Kurzhantel mit beiden Händen über dem Kopf, Arme gestreckt."],
  ["Inhalá al bajar y exhalá al extender.","Inhale as you lower and exhale as you extend.","Inspire ao descer e expire ao estender.","Inspire en descendant et expire en tendant les bras.","Inspira scendendo ed espira distendendo.","Atme beim Absenken ein und beim Strecken aus."],
  ["Tomá la mancuerna por un extremo con ambas manos y llevala arriba de la cabeza.","Hold one end of the dumbbell with both hands and bring it above your head.","Segure o halter por uma ponta com as duas mãos e leve-o acima da cabeça.","Tiens l’haltère par une extrémité à deux mains et amène-le au-dessus de la tête.","Afferra il manubrio da un’estremità con entrambe le mani e portalo sopra la testa.","Fass die Kurzhantel an einem Ende mit beiden Händen und bring sie über den Kopf."],
  ["Flexioná los codos bajando la mancuerna por detrás de la cabeza, con los codos apuntando hacia adelante.","Bend your elbows, lowering the dumbbell behind your head with your elbows pointing forward.","Flexione os cotovelos abaixando o halter por trás da cabeça, com os cotovelos apontando para frente.","Fléchis les coudes en descendant l’haltère derrière la tête, coudes pointés vers l’avant.","Piega i gomiti abbassando il manubrio dietro la testa, con i gomiti rivolti in avanti.","Beuge die Ellbogen und senk die Kurzhantel hinter den Kopf, die Ellbogen zeigen nach vorn."],
  ["Bajá hasta un estiramiento cómodo del tríceps sin abrir los codos.","Lower to a comfortable triceps stretch without flaring your elbows.","Desça até um alongamento confortável do tríceps sem abrir os cotovelos.","Descends jusqu’à un étirement confortable des triceps sans écarter les coudes.","Scendi fino a un allungamento comodo del tricipite senza aprire i gomiti.","Senk ab bis zu einer angenehmen Trizepsdehnung, ohne die Ellbogen auszustellen."],
  ["Extendé los codos para volver arriba.","Extend your elbows to return to the top.","Estenda os cotovelos para voltar para cima.","Tends les coudes pour revenir en haut.","Distendi i gomiti per tornare in alto.","Streck die Ellbogen, um wieder nach oben zu kommen."],
  ["Bajar la mancuerna rápido detrás de la cabeza.","Lowering the dumbbell quickly behind your head.","Abaixar o halter rápido atrás da cabeça.","Descendre l’haltère rapidement derrière la tête.","Abbassare il manubrio velocemente dietro la testa.","Die Kurzhantel schnell hinter den Kopf absenken."],
  ["Sujetá la mancuerna con firmeza: pasa detrás de la cabeza.","Hold the dumbbell firmly: it passes behind your head.","Segure o halter com firmeza: ele passa atrás da cabeça.","Tiens l’haltère fermement : il passe derrière ta tête.","Tieni saldamente il manubrio: passa dietro la testa.","Halte die Kurzhantel fest: Sie bewegt sich hinter deinem Kopf."],
  ["Sentado con respaldo es más fácil mantener la espalda neutra.","Sitting with a backrest makes it easier to keep your back neutral.","Sentado com encosto é mais fácil manter as costas neutras.","Assis avec un dossier, il est plus facile de garder le dos neutre.","Seduto con schienale è più facile mantenere la schiena neutra.","Im Sitzen mit Lehne hältst du den Rücken leichter neutral."],
  ["Si el hombro molesta, probá la versión con banda o en polea hacia abajo.","If your shoulder bothers you, try the band version or the cable pushdown.","Se o ombro incomodar, teste a versão com elástico ou na polia para baixo.","Si ton épaule te gêne, essaie la version à l’élastique ou à la poulie vers le bas.","Se la spalla dà fastidio, prova la versione con elastico o al cavo verso il basso.","Wenn die Schulter zwickt, probier die Variante mit Band oder am Kabelzug nach unten."],
  ["Deltoides posterior como estabilizador","Rear deltoid as a stabilizer","Deltoide posterior como estabilizador","Deltoïde postérieur comme stabilisateur","Deltoide posteriore come stabilizzatore","Hinterer Deltamuskel als Stabilisator"],
  ["Una mancuerna y un banco o superficie firme para apoyarte","One dumbbell and a bench or sturdy surface to lean on","Um halter e um banco ou superfície firme para se apoiar","Un haltère et un banc ou une surface solide pour t’appuyer","Un manubrio e una panca o una superficie stabile per appoggiarti","Eine Kurzhantel und eine Bank oder feste Fläche zum Abstützen"],
  ["Apoyá una mano y la rodilla del mismo lado en un banco, con el tronco casi paralelo al suelo y la mancuerna en la otra mano.","Rest one hand and the knee on the same side on a bench, torso almost parallel to the floor and the dumbbell in your other hand.","Apoie uma mão e o joelho do mesmo lado em um banco, com o tronco quase paralelo ao chão e o halter na outra mão.","Pose une main et le genou du même côté sur un banc, buste presque parallèle au sol et haltère dans l’autre main.","Appoggia una mano e il ginocchio dello stesso lato su una panca, con il busto quasi parallelo al pavimento e il manubrio nell’altra mano.","Stütz eine Hand und das Knie derselben Seite auf eine Bank, Oberkörper fast parallel zum Boden, die Kurzhantel in der anderen Hand."],
  ["Llevá el codo atrás hasta que el brazo quede pegado al costado y paralelo al tronco, con el codo flexionado.","Bring your elbow back until your upper arm is tight to your side and parallel to your torso, elbow bent.","Leve o cotovelo para trás até o braço ficar colado ao corpo e paralelo ao tronco, com o cotovelo flexionado.","Amène le coude vers l’arrière jusqu’à ce que le bras soit collé au flanc et parallèle au buste, coude fléchi.","Porta il gomito indietro finché il braccio è aderente al fianco e parallelo al busto, con il gomito piegato.","Führ den Ellbogen nach hinten, bis der Oberarm am Körper anliegt und parallel zum Oberkörper ist, Ellbogen gebeugt."],
  ["Extendé el codo llevando la mancuerna hacia atrás hasta estirar el brazo.","Extend your elbow, moving the dumbbell back until your arm is straight.","Estenda o cotovelo levando o halter para trás até esticar o braço.","Tends le coude en amenant l’haltère vers l’arrière jusqu’à ce que le bras soit tendu.","Distendi il gomito portando il manubrio indietro fino a stendere il braccio.","Streck den Ellbogen und führ die Kurzhantel nach hinten, bis der Arm gestreckt ist."],
  ["Pausá un instante sin mover la parte superior del brazo.","Pause for a moment without moving your upper arm.","Pause um instante sem mover a parte superior do braço.","Marque une courte pause sans bouger le haut du bras.","Fai una breve pausa senza muovere la parte superiore del braccio.","Halte kurz, ohne den Oberarm zu bewegen."],
  ["Dejar caer el codo y mover el hombro.","Letting your elbow drop and moving your shoulder.","Deixar o cotovelo cair e mover o ombro.","Laisser tomber le coude et bouger l’épaule.","Lasciar cadere il gomito e muovere la spalla.","Den Ellbogen absinken lassen und die Schulter bewegen."],
  ["Balancear la mancuerna con impulso.","Swinging the dumbbell with momentum.","Balançar o halter com impulso.","Balancer l’haltère avec de l’élan.","Far oscillare il manubrio con slancio.","Die Kurzhantel mit Schwung bewegen."],
  ["Redondear la espalda.","Rounding your back.","Arredondar as costas.","Arrondir le dos.","Arrotondare la schiena.","Den Rücken runden."],
  ["Usá poco peso: la palanca es exigente al final.","Use a light weight: the lever is demanding at the end.","Use pouco peso: a alavanca é exigente no final.","Utilise une charge légère : le levier est exigeant en fin de mouvement.","Usa poco peso: la leva è impegnativa alla fine.","Nimm wenig Gewicht: Der Hebel ist am Ende anspruchsvoll."],
  ["Mantené el codo como bisagra fija.","Keep your elbow as a fixed hinge.","Mantenha o cotovelo como uma dobradiça fixa.","Garde le coude comme une charnière fixe.","Mantieni il gomito come una cerniera fissa.","Halte den Ellbogen als festes Scharnier."],
  ["Mirá al suelo para mantener el cuello alineado.","Look at the floor to keep your neck aligned.","Olhe para o chão para manter o pescoço alinhado.","Regarde le sol pour garder la nuque alignée.","Guarda il pavimento per mantenere il collo allineato.","Schau zum Boden, damit der Nacken gerade bleibt."],
  ["Banda elástica anclada en un punto alto y firme (por ejemplo, el marco de una puerta con anclaje adecuado)","Resistance band anchored to a high, sturdy point (for example, a door frame with a proper anchor)","Elástico preso em um ponto alto e firme (por exemplo, o batente de uma porta com ancoragem adequada)","Bande élastique ancrée à un point haut et solide (par exemple, un cadre de porte avec un ancrage adapté)","Elastico ancorato a un punto alto e stabile (ad esempio, il telaio di una porta con un ancoraggio adeguato)","Widerstandsband, an einem hohen, festen Punkt verankert (zum Beispiel am Türrahmen mit passendem Türanker)"],
  ["Parate frente al anclaje alto con un extremo de la banda en cada mano, codos pegados a los costados y flexionados a 90 grados.","Stand facing the high anchor with one end of the band in each hand, elbows tucked to your sides and bent to 90 degrees.","Fique de frente para a ancoragem alta com uma ponta do elástico em cada mão, cotovelos colados ao corpo e flexionados a 90 graus.","Tiens-toi face à l’ancrage haut, une extrémité de la bande dans chaque main, coudes collés au corps et fléchis à 90 degrés.","Mettiti di fronte all’ancoraggio alto con un’estremità dell’elastico in ogni mano, gomiti aderenti ai fianchi e piegati a 90 gradi.","Stell dich vor die hohe Verankerung, je ein Bandende in einer Hand, Ellbogen am Körper und im 90-Grad-Winkel gebeugt."],
  ["Verificá que el anclaje esté firme y que la puerta quede cerrada hacia el lado contrario.","Check that the anchor is secure and that the door closes away from you.","Verifique se a ancoragem está firme e se a porta fecha para o lado contrário.","Vérifie que l’ancrage est solide et que la porte se ferme du côté opposé.","Verifica che l’ancoraggio sia stabile e che la porta si chiuda dal lato opposto.","Prüf, dass die Verankerung fest sitzt und die Tür zur anderen Seite hin geschlossen ist."],
  ["Extendé los codos llevando las manos hacia abajo hasta estirar los brazos.","Extend your elbows, bringing your hands down until your arms are straight.","Estenda os cotovelos levando as mãos para baixo até esticar os braços.","Tends les coudes en descendant les mains jusqu’à ce que les bras soient tendus.","Distendi i gomiti portando le mani in basso fino a stendere le braccia.","Streck die Ellbogen und führ die Hände nach unten, bis die Arme gestreckt sind."],
  ["Volvé despacio hasta la posición inicial sin despegar los codos del cuerpo.","Return slowly to the starting position without moving your elbows away from your body.","Volte devagar até a posição inicial sem descolar os cotovelos do corpo.","Reviens lentement à la position de départ sans décoller les coudes du corps.","Torna lentamente alla posizione iniziale senza staccare i gomiti dal corpo.","Kehr langsam in die Ausgangsposition zurück, ohne die Ellbogen vom Körper zu lösen."],
  ["Mover los codos hacia adelante.","Moving your elbows forward.","Mover os cotovelos para frente.","Avancer les coudes.","Spostare i gomiti in avanti.","Die Ellbogen nach vorn schieben."],
  ["Inclinar el tronco sobre la banda.","Leaning your torso over the band.","Inclinar o tronco sobre o elástico.","Pencher le buste au-dessus de la bande.","Inclinare il busto sopra l’elastico.","Den Oberkörper über das Band lehnen."],
  ["Revisá que la banda no tenga cortes antes de cada uso.","Check that the band has no cuts before each use.","Verifique se o elástico não tem cortes antes de cada uso.","Vérifie que la bande n’a pas de coupure avant chaque utilisation.","Controlla che l’elastico non abbia tagli prima di ogni uso.","Prüf das Band vor jeder Nutzung auf Risse."],
  ["Alejarte del anclaje aumenta la tensión.","Stepping away from the anchor increases the tension.","Afastar-se da ancoragem aumenta a tensão.","T’éloigner du point d’ancrage augmente la tension.","Allontanarti dall’ancoraggio aumenta la tensione.","Wenn du dich von der Verankerung entfernst, steigt die Spannung."],
  ["Pectoral mayor, deltoides anterior y estabilizadores del tronco","Pectoralis major, front deltoid and trunk stabilizers","Peitoral maior, deltoide anterior e estabilizadores do tronco","Grand pectoral, deltoïde antérieur et stabilisateurs du tronc","Grande pettorale, deltoide anteriore e stabilizzatori del tronco","Großer Brustmuskel, vorderer Deltamuskel und Rumpfstabilisatoren"],
  ["Peso corporal y superficie firme","Bodyweight and a firm surface","Peso corporal e superfície firme","Poids du corps et surface ferme","Corpo libero e superficie stabile","Körpergewicht und fester Untergrund"],
  ["Ponete en posición de plancha alta con las manos juntas bajo el pecho, formando un rombo con pulgares e índices.","Get into a high plank with your hands together under your chest, forming a diamond with your thumbs and index fingers.","Fique em prancha alta com as mãos juntas sob o peito, formando um losango com polegares e indicadores.","Place-toi en planche haute, mains rapprochées sous la poitrine, en formant un losange avec les pouces et les index.","Mettiti in plank alto con le mani unite sotto il petto, formando un rombo con pollici e indici.","Geh in den hohen Stütz, Hände unter der Brust zusammen, Daumen und Zeigefinger bilden eine Raute."],
  ["Juntá las manos bajo el esternón y extendé las piernas, con el cuerpo en línea recta.","Bring your hands together under your breastbone and extend your legs, body in a straight line.","Junte as mãos sob o esterno e estenda as pernas, com o corpo em linha reta.","Rapproche les mains sous le sternum et tends les jambes, corps aligné.","Unisci le mani sotto lo sterno e distendi le gambe, con il corpo in linea retta.","Bring die Hände unter dem Brustbein zusammen und streck die Beine, Körper in einer geraden Linie."],
  ["Bajá el pecho hacia las manos con los codos cerca del cuerpo, apuntando hacia atrás.","Lower your chest toward your hands with your elbows close to your body, pointing back.","Abaixe o peito em direção às mãos com os cotovelos perto do corpo, apontando para trás.","Descends la poitrine vers les mains, coudes près du corps et pointés vers l’arrière.","Abbassa il petto verso le mani con i gomiti vicini al corpo, rivolti all’indietro.","Senk die Brust zu den Händen, Ellbogen nah am Körper und nach hinten gerichtet."],
  ["Mantené la cadera alineada sin hundirse.","Keep your hips in line without sagging.","Mantenha o quadril alinhado sem afundar.","Garde les hanches alignées sans t’affaisser.","Mantieni le anche allineate senza cedere.","Halte die Hüfte in der Linie, ohne durchzuhängen."],
  ["Hundir la cadera.","Letting your hips sag.","Afundar o quadril.","Laisser les hanches s’affaisser.","Far cedere le anche.","Die Hüfte durchhängen lassen."],
  ["Cargar en exceso las muñecas sin entrada en calor.","Overloading your wrists without warming up.","Sobrecarregar os punhos sem aquecimento.","Surcharger les poignets sans échauffement.","Sovraccaricare i polsi senza riscaldamento.","Die Handgelenke ohne Aufwärmen überlasten."],
  ["Si las muñecas molestan, separá un poco las manos.","If your wrists bother you, move your hands slightly apart.","Se os punhos incomodarem, afaste um pouco as mãos.","Si tes poignets te gênent, écarte un peu les mains.","Se i polsi danno fastidio, allarga un po’ le mani.","Wenn die Handgelenke zwicken, setz die Hände etwas weiter auseinander."],
  ["Si no llegás al rango con buena forma, hacelas desde rodillas.","If you can’t reach the range with good form, do them from your knees.","Se não chegar à amplitude com boa forma, faça com os joelhos apoiados.","Si tu n’atteins pas l’amplitude avec une bonne forme, fais-les sur les genoux.","Se non raggiungi l’ampiezza con una buona forma, falli sulle ginocchia.","Wenn du den Bewegungsumfang nicht sauber schaffst, mach sie auf den Knien."],
  ["Mantené el cuello neutro mirando al suelo.","Keep your neck neutral, looking at the floor.","Mantenha o pescoço neutro olhando para o chão.","Garde la nuque neutre en regardant le sol.","Mantieni il collo neutro guardando il pavimento.","Halte den Nacken neutral und schau zum Boden."],
  ["Recto abdominal y transverso del abdomen","Rectus abdominis and transversus abdominis","Reto abdominal e transverso do abdômen","Grand droit et transverse de l’abdomen","Retto addominale e trasverso dell’addome","Gerader und querer Bauchmuskel"],
  ["Flexores de cadera, oblicuos, hombros y serrato anterior","Hip flexors, obliques, shoulders and serratus anterior","Flexores do quadril, oblíquos, ombros e serrátil anterior","Fléchisseurs de hanche, obliques, épaules et dentelé antérieur","Flessori dell’anca, obliqui, spalle e dentato anteriore","Hüftbeuger, schräge Bauchmuskeln, Schultern und vorderer Sägemuskel"],
  ["Ponete en plancha alta con las manos bajo los hombros y el cuerpo en línea recta de cabeza a talones.","Get into a high plank with your hands under your shoulders and your body in a straight line from head to heels.","Fique em prancha alta com as mãos sob os ombros e o corpo em linha reta da cabeça aos calcanhares.","Place-toi en planche haute, mains sous les épaules et corps aligné de la tête aux talons.","Mettiti in plank alto con le mani sotto le spalle e il corpo in linea retta dalla testa ai talloni.","Geh in den hohen Stütz, Hände unter den Schultern, Körper in einer geraden Linie vom Kopf bis zu den Fersen."],
  ["Exhalá al llevar la rodilla al pecho e inhalá al volver.","Exhale as you bring your knee to your chest and inhale as you return.","Expire ao levar o joelho ao peito e inspire ao voltar.","Expire en amenant le genou vers la poitrine et inspire en revenant.","Espira portando il ginocchio al petto e inspira tornando.","Atme beim Heranziehen des Knies zur Brust aus und beim Zurückführen ein."],
  ["Afirmá abdomen y glúteos y empujá el suelo con las manos.","Brace your abs and glutes and push the floor away with your hands.","Firme abdômen e glúteos e empurre o chão com as mãos.","Gaine les abdos et les fessiers et pousse le sol avec les mains.","Contrai addome e glutei e spingi il pavimento con le mani.","Spann Bauch und Gesäß an und drück dich mit den Händen vom Boden weg."],
  ["Llevá una rodilla hacia el pecho despacio, sin que la cadera suba ni se hunda.","Bring one knee slowly toward your chest without your hips rising or sagging.","Leve um joelho em direção ao peito devagar, sem o quadril subir nem afundar.","Amène lentement un genou vers la poitrine sans que les hanches montent ou s’affaissent.","Porta lentamente un ginocchio verso il petto senza che le anche salgano o cedano.","Zieh ein Knie langsam zur Brust, ohne dass die Hüfte steigt oder durchhängt."],
  ["Devolvé el pie a su lugar con control.","Return your foot to its place with control.","Volte o pé ao lugar com controle.","Remets le pied à sa place en contrôle.","Riporta il piede al suo posto con controllo.","Setz den Fuß kontrolliert zurück."],
  ["Repetí con la otra pierna, alternando lados.","Repeat with the other leg, alternating sides.","Repita com a outra perna, alternando os lados.","Recommence avec l’autre jambe, en alternant les côtés.","Ripeti con l’altra gamba, alternando i lati.","Wiederhol es mit dem anderen Bein und wechsle die Seiten ab."],
  ["Subir la cadera en pico al traer la rodilla.","Piking your hips up as you bring your knee in.","Subir o quadril em pico ao trazer o joelho.","Monter les hanches en pointe en ramenant le genou.","Sollevare le anche a punta portando il ginocchio.","Beim Heranziehen des Knies die Hüfte spitz nach oben schieben."],
  ["Hundir la zona lumbar.","Letting your lower back sag.","Afundar a lombar.","Laisser le bas du dos s’affaisser.","Far cedere la zona lombare.","Den unteren Rücken durchhängen lassen."],
  ["Acelerar y convertirlo en un salto.","Speeding up and turning it into a jump.","Acelerar e transformar em salto.","Accélérer et en faire un saut.","Accelerare e trasformarlo in un salto.","Schneller werden und einen Sprung daraus machen."],
  ["Lento y controlado es más exigente para el core que rápido.","Slow and controlled is more demanding for your core than fast.","Lento e controlado é mais exigente para o core que rápido.","Lent et contrôlé est plus exigeant pour la sangle abdominale que rapide.","Lento e controllato è più impegnativo per il core che veloce.","Langsam und kontrolliert fordert den Rumpf mehr als schnell."],
  ["Si cuesta, apoyá las manos sobre una superficie firme y elevada.","If it is hard, place your hands on a sturdy, raised surface.","Se for difícil, apoie as mãos em uma superfície firme e elevada.","Si c’est difficile, pose les mains sur une surface solide et surélevée.","Se è difficile, appoggia le mani su una superficie stabile e rialzata.","Wenn es schwerfällt, stütz die Hände auf eine stabile, erhöhte Fläche."],
  ["Mantené los hombros sobre las manos.","Keep your shoulders over your hands.","Mantenha os ombros sobre as mãos.","Garde les épaules au-dessus des mains.","Mantieni le spalle sopra le mani.","Halte die Schultern über den Händen."],
  ["Acostate de costado con el antebrazo bajo el hombro y las rodillas flexionadas hacia atrás, apiladas una sobre otra.","Lie on your side with your forearm under your shoulder and your knees bent back, stacked on top of each other.","Deite-se de lado com o antebraço sob o ombro e os joelhos flexionados para trás, um sobre o outro.","Allonge-toi sur le côté, avant-bras sous l’épaule et genoux fléchis vers l’arrière, l’un sur l’autre.","Sdraiati su un fianco con l’avambraccio sotto la spalla e le ginocchia piegate all’indietro, una sopra l’altra.","Leg dich auf die Seite, Unterarm unter der Schulter, Knie nach hinten gebeugt und übereinander."],
  ["Respirá de forma pareja durante todo el sostén.","Breathe evenly throughout the hold.","Respire de forma regular durante toda a sustentação.","Respire régulièrement pendant tout le maintien.","Respira in modo regolare per tutta la tenuta.","Atme während des ganzen Haltens gleichmäßig."],
  ["30–45 segundos entre lados","30–45 seconds between sides","30–45 segundos entre lados","30–45 secondes entre les côtés","30–45 secondi tra i lati","30–45 Sekunden zwischen den Seiten"],
  ["Colocá el codo justo bajo el hombro y alineá rodillas, cadera y cabeza.","Place your elbow directly under your shoulder and align your knees, hips and head.","Coloque o cotovelo logo abaixo do ombro e alinhe joelhos, quadril e cabeça.","Place le coude juste sous l’épaule et aligne genoux, hanches et tête.","Metti il gomito proprio sotto la spalla e allinea ginocchia, anche e testa.","Setz den Ellbogen direkt unter die Schulter und bring Knie, Hüfte und Kopf in eine Linie."],
  ["Elevá la cadera hasta formar una línea recta de rodillas a cabeza.","Lift your hips until you form a straight line from knees to head.","Eleve o quadril até formar uma linha reta dos joelhos à cabeça.","Monte les hanches jusqu’à former une ligne droite des genoux à la tête.","Solleva le anche fino a formare una linea retta dalle ginocchia alla testa.","Heb die Hüfte, bis eine gerade Linie von den Knien bis zum Kopf entsteht."],
  ["Sostené la posición sin dejar caer la cadera, respirando con calma.","Hold the position without letting your hips drop, breathing calmly.","Sustente a posição sem deixar o quadril cair, respirando com calma.","Tiens la position sans laisser tomber les hanches, en respirant calmement.","Mantieni la posizione senza far cadere le anche, respirando con calma.","Halte die Position, ohne die Hüfte absinken zu lassen, und atme ruhig."],
  ["Dejar caer la cadera.","Letting your hips drop.","Deixar o quadril cair.","Laisser tomber les hanches.","Lasciar cadere le anche.","Die Hüfte absinken lassen."],
  ["Llevar la cadera hacia atrás.","Pushing your hips back.","Levar o quadril para trás.","Reculer les hanches.","Portare le anche indietro.","Die Hüfte nach hinten schieben."],
  ["Encoger el hombro de apoyo.","Shrugging your supporting shoulder.","Encolher o ombro de apoio.","Hausser l’épaule d’appui.","Sollevare la spalla d’appoggio.","Die Stützschulter hochziehen."],
  ["Apoyar las rodillas acorta la palanca, por eso es más fácil que la plancha lateral completa.","Resting on your knees shortens the lever, which is why it is easier than the full side plank.","Apoiar os joelhos encurta a alavanca, por isso é mais fácil que a prancha lateral completa.","Poser les genoux raccourcit le levier, c’est pourquoi c’est plus facile que la planche latérale complète.","Appoggiare le ginocchia accorcia la leva, per questo è più facile del plank laterale completo.","Die Knie aufzusetzen verkürzt den Hebel; deshalb ist es leichter als der volle Seitstütz."],
  ["Empujá el suelo con el antebrazo.","Push the floor away with your forearm.","Empurre o chão com o antebraço.","Pousse le sol avec l’avant-bras.","Spingi il pavimento con l’avambraccio.","Drück dich mit dem Unterarm vom Boden weg."],
  ["Progresá a la plancha lateral completa cuando sostengas el tiempo con buena forma.","Progress to the full side plank once you can hold the time with good form.","Avance para a prancha lateral completa quando sustentar o tempo com boa forma.","Passe à la planche latérale complète quand tu tiens le temps avec une bonne forme.","Passa al plank laterale completo quando mantieni il tempo con una buona forma.","Wechsle zum vollen Seitstütz, sobald du die Zeit mit guter Technik hältst."],
  ["Oblicuos, transverso del abdomen y recto abdominal","Obliques, transversus abdominis and rectus abdominis","Oblíquos, transverso do abdômen e reto abdominal","Obliques, transverse de l’abdomen et grand droit","Obliqui, trasverso dell’addome e retto addominale","Schräge Bauchmuskeln, querer und gerader Bauchmuskel"],
  ["Deltoides, serrato anterior y glúteos","Deltoids, serratus anterior and glutes","Deltoides, serrátil anterior e glúteos","Deltoïdes, dentelé antérieur et fessiers","Deltoidi, dentato anteriore e glutei","Deltamuskeln, vorderer Sägemuskel und Gesäß"],
  ["Ponete en plancha alta con las rodillas apoyadas, manos bajo los hombros y el cuerpo alineado de rodillas a cabeza.","Get into a high plank on your knees, hands under your shoulders and body aligned from knees to head.","Fique em prancha alta com os joelhos apoiados, mãos sob os ombros e o corpo alinhado dos joelhos à cabeça.","Place-toi en planche haute sur les genoux, mains sous les épaules et corps aligné des genoux à la tête.","Mettiti in plank alto con le ginocchia appoggiate, mani sotto le spalle e corpo allineato dalle ginocchia alla testa.","Geh in den hohen Stütz auf den Knien, Hände unter den Schultern, Körper von den Knien bis zum Kopf in einer Linie."],
  ["Respirá de forma pareja, exhalando en cada toque.","Breathe evenly, exhaling on each tap.","Respire de forma regular, expirando a cada toque.","Respire régulièrement en expirant à chaque touche.","Respira in modo regolare, espirando a ogni tocco.","Atme gleichmäßig und bei jeder Berührung aus."],
  ["Separá un poco las rodillas para ampliar la base y afirmá el abdomen.","Spread your knees slightly to widen your base and brace your abs.","Afaste um pouco os joelhos para ampliar a base e firme o abdômen.","Écarte un peu les genoux pour élargir ta base et gaine les abdos.","Allarga un po’ le ginocchia per ampliare la base e contrai l’addome.","Setz die Knie etwas weiter auseinander für eine breitere Basis und spann den Bauch an."],
  ["Levantá una mano y tocá el hombro contrario sin que la cadera gire.","Lift one hand and touch the opposite shoulder without your hips rotating.","Levante uma mão e toque o ombro oposto sem o quadril girar.","Lève une main et touche l’épaule opposée sans que les hanches pivotent.","Solleva una mano e tocca la spalla opposta senza che le anche ruotino.","Heb eine Hand und berühr die gegenüberliegende Schulter, ohne dass sich die Hüfte dreht."],
  ["Volvé a apoyar la mano con control.","Place your hand back down with control.","Volte a apoiar a mão com controle.","Repose la main en contrôle.","Riappoggia la mano con controllo.","Setz die Hand kontrolliert wieder ab."],
  ["Alterná lados manteniendo la cadera quieta.","Alternate sides keeping your hips still.","Alterne os lados mantendo o quadril parado.","Alterne les côtés en gardant les hanches immobiles.","Alterna i lati mantenendo le anche ferme.","Wechsle die Seiten und halte die Hüfte ruhig."],
  ["Balancear la cadera de lado a lado.","Swaying your hips from side to side.","Balançar o quadril de um lado para o outro.","Balancer les hanches d’un côté à l’autre.","Far oscillare le anche da un lato all’altro.","Die Hüfte von Seite zu Seite schwingen lassen."],
  ["Hacer los toques rápido y sin control.","Doing the taps fast and without control.","Fazer os toques rápido e sem controle.","Faire les touches vite et sans contrôle.","Fare i tocchi veloci e senza controllo.","Die Berührungen schnell und unkontrolliert ausführen."],
  ["Dejar la cadera atrás en posición de cuadrupedia.","Leaving your hips back in an all-fours position.","Deixar o quadril para trás em posição de quatro apoios.","Laisser les hanches en arrière en position à quatre pattes.","Lasciare le anche indietro in posizione a quattro zampe.","Die Hüfte hinten im Vierfüßlerstand lassen."],
  ["Apoyar las rodillas reduce la carga, por eso es más fácil que la versión con piernas extendidas.","Resting on your knees reduces the load, which is why it is easier than the version with straight legs.","Apoiar os joelhos reduz a carga, por isso é mais fácil que a versão com pernas estendidas.","Poser les genoux réduit la charge, c’est pourquoi c’est plus facile que la version jambes tendues.","Appoggiare le ginocchia riduce il carico, per questo è più facile della versione a gambe distese.","Die Knie aufzusetzen verringert die Last; deshalb ist es leichter als die Variante mit gestreckten Beinen."],
  ["Cuanto más separadas las rodillas, más estable.","The wider your knees, the more stable you are.","Quanto mais afastados os joelhos, mais estável.","Plus les genoux sont écartés, plus tu es stable.","Più sono distanti le ginocchia, più sei stabile.","Je weiter die Knie auseinander, desto stabiler."],
  ["Imaginá un vaso de agua sobre la espalda baja.","Imagine a glass of water on your lower back.","Imagine um copo de água sobre a lombar.","Imagine un verre d’eau posé sur le bas de ton dos.","Immagina un bicchiere d’acqua sulla zona lombare.","Stell dir ein Glas Wasser auf deinem unteren Rücken vor."],
  ["Acostate boca arriba con las rodillas flexionadas, pies apoyados y manos sobre el pecho o junto a las sienes.","Lie on your back with your knees bent, feet flat and hands on your chest or by your temples.","Deite-se de barriga para cima com os joelhos flexionados, pés apoiados e mãos sobre o peito ou junto às têmporas.","Allonge-toi sur le dos, genoux fléchis, pieds à plat et mains sur la poitrine ou près des tempes.","Sdraiati a pancia in su con le ginocchia piegate, piedi appoggiati e mani sul petto o vicino alle tempie.","Leg dich auf den Rücken, Knie gebeugt, Füße aufgestellt, Hände auf der Brust oder an den Schläfen."],
  ["Apoyá la zona lumbar de forma natural y llevá la barbilla levemente hacia el pecho.","Let your lower back rest naturally and tuck your chin slightly toward your chest.","Apoie a lombar de forma natural e leve o queixo levemente em direção ao peito.","Laisse le bas du dos reposer naturellement et rentre légèrement le menton vers la poitrine.","Appoggia la zona lombare in modo naturale e porta il mento leggermente verso il petto.","Lass den unteren Rücken natürlich aufliegen und zieh das Kinn leicht zur Brust."],
  ["Elevá la cabeza y los hombros enrollando la parte alta del tronco hacia la pelvis.","Lift your head and shoulders, curling your upper torso toward your pelvis.","Eleve a cabeça e os ombros enrolando a parte alta do tronco em direção à pelve.","Lève la tête et les épaules en enroulant le haut du buste vers le bassin.","Solleva testa e spalle arrotolando la parte alta del busto verso il bacino.","Heb Kopf und Schultern und roll den oberen Rumpf Richtung Becken ein."],
  ["Bajá despacio hasta apoyar los hombros.","Lower slowly until your shoulders are back on the floor.","Desça devagar até apoiar os ombros.","Redescends lentement jusqu’à reposer les épaules.","Scendi lentamente fino ad appoggiare le spalle.","Senk langsam ab, bis die Schultern wieder aufliegen."],
  ["Subir con impulso hasta sentarse.","Using momentum to come all the way up to sitting.","Subir com impulso até se sentar.","Monter avec de l’élan jusqu’à s’asseoir.","Salire con slancio fino a sedersi.","Mit Schwung bis zum Sitzen hochkommen."],
  ["Despegar los pies del suelo.","Lifting your feet off the floor.","Tirar os pés do chão.","Décoller les pieds du sol.","Sollevare i piedi da terra.","Die Füße vom Boden abheben."],
  ["El recorrido es corto: los omóplatos apenas se despegan del suelo.","The range is short: your shoulder blades barely leave the floor.","O movimento é curto: as escápulas mal saem do chão.","L’amplitude est courte : les omoplates se décollent à peine du sol.","Il movimento è breve: le scapole si staccano appena da terra.","Der Bewegungsweg ist kurz: Die Schulterblätter lösen sich kaum vom Boden."],
  ["Mantené un espacio de un puño entre barbilla y pecho.","Keep a fist’s width between your chin and chest.","Mantenha um espaço de um punho entre o queixo e o peito.","Garde l’espace d’un poing entre le menton et la poitrine.","Mantieni lo spazio di un pugno tra mento e petto.","Halte eine Faustbreite Abstand zwischen Kinn und Brust."],
  ["Priorizá la calidad sobre la cantidad de repeticiones.","Prioritize quality over number of reps.","Priorize a qualidade sobre a quantidade de repetições.","Privilégie la qualité plutôt que le nombre de répétitions.","Dai priorità alla qualità rispetto al numero di ripetizioni.","Qualität geht vor der Anzahl der Wiederholungen."],
  ["Recto abdominal (porción inferior) y flexores de cadera","Rectus abdominis (lower portion) and hip flexors","Reto abdominal (porção inferior) e flexores do quadril","Grand droit de l’abdomen (partie inférieure) et fléchisseurs de hanche","Retto addominale (porzione inferiore) e flessori dell’anca","Gerader Bauchmuskel (unterer Teil) und Hüftbeuger"],
  ["Acostate boca arriba con las manos a los costados o bajo la cadera y las rodillas flexionadas con los pies apenas elevados del suelo.","Lie on your back with your hands at your sides or under your hips and your knees bent, feet slightly off the floor.","Deite-se de barriga para cima com as mãos ao lado do corpo ou sob o quadril e os joelhos flexionados, com os pés levemente elevados do chão.","Allonge-toi sur le dos, mains le long du corps ou sous les hanches, genoux fléchis et pieds légèrement décollés du sol.","Sdraiati a pancia in su con le mani lungo i fianchi o sotto le anche e le ginocchia piegate, con i piedi appena sollevati da terra.","Leg dich auf den Rücken, Hände neben dem Körper oder unter der Hüfte, Knie gebeugt, Füße knapp über dem Boden."],
  ["Exhalá al llevar las rodillas al pecho e inhalá al bajarlas.","Exhale as you bring your knees to your chest and inhale as you lower them.","Expire ao levar os joelhos ao peito e inspire ao abaixá-los.","Expire en amenant les genoux vers la poitrine et inspire en les abaissant.","Espira portando le ginocchia al petto e inspira abbassandole.","Atme beim Heranziehen der Knie zur Brust aus und beim Senken ein."],
  ["Apoyá la zona lumbar y afirmá el abdomen antes de mover las piernas.","Rest your lower back on the floor and brace your abs before moving your legs.","Apoie a lombar e firme o abdômen antes de mover as pernas.","Pose le bas du dos au sol et gaine les abdos avant de bouger les jambes.","Appoggia la zona lombare e contrai l’addome prima di muovere le gambe.","Leg den unteren Rücken ab und spann den Bauch an, bevor du die Beine bewegst."],
  ["Llevá las rodillas hacia el pecho, enrollando apenas la pelvis al final.","Bring your knees toward your chest, curling your pelvis slightly at the end.","Leve os joelhos em direção ao peito, enrolando levemente a pelve no final.","Amène les genoux vers la poitrine en enroulant légèrement le bassin à la fin.","Porta le ginocchia verso il petto, arrotolando appena il bacino alla fine.","Zieh die Knie zur Brust und roll das Becken am Ende leicht ein."],
  ["Bajá las piernas despacio hasta que los pies queden cerca del suelo, sin arquear la espalda.","Lower your legs slowly until your feet are close to the floor, without arching your back.","Abaixe as pernas devagar até os pés ficarem perto do chão, sem arquear as costas.","Redescends lentement les jambes jusqu’à ce que les pieds soient près du sol, sans cambrer le dos.","Abbassa lentamente le gambe finché i piedi sono vicini a terra, senza inarcare la schiena.","Senk die Beine langsam, bis die Füße nah am Boden sind, ohne ins Hohlkreuz zu gehen."],
  ["Arquear la zona lumbar al bajar las piernas.","Arching your lower back as you lower your legs.","Arquear a lombar ao abaixar as pernas.","Cambrer le bas du dos en abaissant les jambes.","Inarcare la zona lombare abbassando le gambe.","Beim Senken der Beine ins Hohlkreuz gehen."],
  ["Usar impulso para subir.","Using momentum to lift.","Usar impulso para subir.","Utiliser l’élan pour monter.","Usare lo slancio per salire.","Mit Schwung hochkommen."],
  ["Dejar caer las piernas al suelo entre repeticiones.","Letting your legs drop to the floor between reps.","Deixar as pernas caírem no chão entre as repetições.","Laisser tomber les jambes au sol entre les répétitions.","Lasciar cadere le gambe a terra tra una ripetizione e l’altra.","Die Beine zwischen den Wiederholungen auf den Boden fallen lassen."],
  ["Las rodillas flexionadas acortan la palanca y reducen la carga sobre la zona lumbar.","Bent knees shorten the lever and reduce the load on your lower back.","Os joelhos flexionados encurtam a alavanca e reduzem a carga sobre a lombar.","Les genoux fléchis raccourcissent le levier et réduisent la charge sur le bas du dos.","Le ginocchia piegate accorciano la leva e riducono il carico sulla zona lombare.","Gebeugte Knie verkürzen den Hebel und entlasten den unteren Rücken."],
  ["Si la espalda se arquea, no bajes tanto las piernas.","If your back arches, don’t lower your legs as far.","Se as costas arquearem, não abaixe tanto as pernas.","Si ton dos se cambre, ne descends pas autant les jambes.","Se la schiena si inarca, non abbassare così tanto le gambe.","Wenn der Rücken ins Hohlkreuz geht, senk die Beine nicht so weit."],
  ["Mantené la cabeza y los hombros apoyados.","Keep your head and shoulders on the floor.","Mantenha a cabeça e os ombros apoiados.","Garde la tête et les épaules au sol.","Mantieni testa e spalle appoggiate.","Lass Kopf und Schultern am Boden."],
  ["Sistema cardiovascular; flexores de cadera, cuádriceps y pantorrillas","Cardiovascular system; hip flexors, quadriceps and calves","Sistema cardiovascular; flexores do quadril, quadríceps e panturrilhas","Système cardiovasculaire ; fléchisseurs de hanche, quadriceps et mollets","Sistema cardiovascolare; flessori dell’anca, quadricipiti e polpacci","Herz-Kreislauf-System; Hüftbeuger, Quadrizeps und Waden"],
  ["Glúteos y tronco estabilizador","Glutes and stabilizing trunk","Glúteos e tronco estabilizador","Fessiers et tronc stabilisateur","Glutei e tronco stabilizzatore","Gesäß und stabilisierender Rumpf"],
  ["Peso corporal y espacio despejado","Bodyweight and a clear space","Peso corporal e espaço livre","Poids du corps et espace dégagé","Corpo libero e spazio libero","Körpergewicht und freier Platz"],
  ["Parate erguido con los pies al ancho de cadera, hombros relajados y brazos a los costados.","Stand tall with your feet hip-width apart, shoulders relaxed and arms at your sides.","Fique ereto com os pés na largura do quadril, ombros relaxados e braços ao lado do corpo.","Tiens-toi droit, pieds à la largeur des hanches, épaules détendues et bras le long du corps.","Mettiti dritto con i piedi alla larghezza delle anche, spalle rilassate e braccia lungo i fianchi.","Stell dich aufrecht hin, Füße hüftbreit, Schultern locker, Arme seitlich."],
  ["Respirá de forma rítmica; si no podés decir una frase, bajá el ritmo.","Breathe rhythmically; if you can’t say a sentence, slow the pace.","Respire de forma rítmica; se não conseguir dizer uma frase, reduza o ritmo.","Respire en rythme ; si tu ne peux pas dire une phrase, ralentis.","Respira in modo ritmico; se non riesci a dire una frase, rallenta.","Atme rhythmisch; wenn du keinen Satz sagen kannst, werde langsamer."],
  ["Empezá a marchar levantando un pie y luego el otro, apoyando de forma suave.","Start marching by lifting one foot and then the other, landing softly.","Comece a marchar levantando um pé e depois o outro, apoiando de forma suave.","Commence à marcher sur place en levant un pied puis l’autre, en reposant doucement.","Inizia a marciare sollevando un piede e poi l’altro, appoggiando con delicatezza.","Beginne zu marschieren, heb erst einen Fuß, dann den anderen, und setz sanft auf."],
  ["Acompañá con los brazos de manera natural, alternados con las piernas.","Swing your arms naturally, alternating with your legs.","Acompanhe com os braços de forma natural, alternados com as pernas.","Accompagne avec les bras de façon naturelle, en alternance avec les jambes.","Accompagna con le braccia in modo naturale, alternate alle gambe.","Schwing die Arme natürlich im Wechsel mit den Beinen mit."],
  ["Ajustá la altura de las rodillas y la velocidad a un esfuerzo en el que puedas hablar en frases cortas (prueba del habla).","Adjust knee height and speed to an effort where you can talk in short sentences (talk test).","Ajuste a altura dos joelhos e a velocidade a um esforço em que consiga falar frases curtas (teste da fala).","Ajuste la hauteur des genoux et la vitesse à un effort où tu peux parler par phrases courtes (test de la parole).","Regola altezza delle ginocchia e velocità su uno sforzo in cui riesci a parlare a frasi brevi (test del parlato).","Pass Kniehöhe und Tempo an eine Belastung an, bei der du in kurzen Sätzen sprechen kannst (Sprechtest)."],
  ["Bajá el ritmo gradualmente durante el último minuto.","Slow the pace gradually during the last minute.","Reduza o ritmo gradualmente durante o último minuto.","Ralentis progressivement pendant la dernière minute.","Rallenta gradualmente durante l’ultimo minuto.","Werde in der letzten Minute nach und nach langsamer."],
  ["Encorvarse hacia adelante.","Hunching forward.","Curvar-se para frente.","Se voûter vers l’avant.","Incurvarsi in avanti.","Nach vorn zusammensacken."],
  ["Apoyar los pies con golpes fuertes.","Stomping your feet down hard.","Apoiar os pés com batidas fortes.","Frapper fort le sol avec les pieds.","Battere forte i piedi a terra.","Mit den Füßen hart aufstampfen."],
  ["Empezar demasiado rápido y cansarse en pocos minutos.","Starting too fast and getting tired within a few minutes.","Começar rápido demais e se cansar em poucos minutos.","Partir trop vite et se fatiguer en quelques minutes.","Partire troppo veloce e stancarsi in pochi minuti.","Zu schnell starten und nach wenigen Minuten erschöpft sein."],
  ["Un calzado cómodo y un piso que no resbale ayudan a moverte con seguridad.","Comfortable shoes and a non-slip floor help you move safely.","Calçado confortável e um piso que não escorrega ajudam a se mover com segurança.","Des chaussures confortables et un sol antidérapant t’aident à bouger en sécurité.","Scarpe comode e un pavimento che non scivola ti aiutano a muoverti in sicurezza.","Bequeme Schuhe und ein rutschfester Boden helfen dir, dich sicher zu bewegen."],
  ["Podés marchar cerca de una pared o mesa firme si necesitás apoyo.","You can march near a wall or sturdy table if you need support.","Você pode marchar perto de uma parede ou mesa firme se precisar de apoio.","Tu peux marcher près d’un mur ou d’une table solide si tu as besoin d’appui.","Puoi marciare vicino a una parete o a un tavolo stabile se ti serve un appoggio.","Du kannst nah an einer Wand oder einem stabilen Tisch marschieren, wenn du Halt brauchst."],
  ["Subí la intensidad elevando más las rodillas, no saltando.","Increase the intensity by lifting your knees higher, not by jumping.","Aumente a intensidade elevando mais os joelhos, não saltando.","Augmente l’intensité en montant davantage les genoux, pas en sautant.","Aumenta l’intensità sollevando di più le ginocchia, non saltando.","Steigere die Intensität, indem du die Knie höher hebst, nicht durch Springen."],
  ["Sistema cardiovascular; glúteos, cuádriceps y pantorrillas","Cardiovascular system; glutes, quadriceps and calves","Sistema cardiovascular; glúteos, quadríceps e panturrilhas","Système cardiovasculaire ; fessiers, quadriceps et mollets","Sistema cardiovascolare; glutei, quadricipiti e polpacci","Herz-Kreislauf-System; Gesäß, Quadrizeps und Waden"],
  ["Isquiotibiales y tronco estabilizador","Hamstrings and stabilizing trunk","Isquiotibiais e tronco estabilizador","Ischio-jambiers et tronc stabilisateur","Ischiocrurali e tronco stabilizzatore","Hintere Oberschenkel und stabilisierender Rumpf"],
  ["Calzado cómodo y un recorrido seguro, interior o exterior","Comfortable shoes and a safe route, indoors or outdoors","Calçado confortável e um percurso seguro, interno ou externo","Chaussures confortables et un parcours sûr, en intérieur ou en extérieur","Scarpe comode e un percorso sicuro, al chiuso o all’aperto","Bequeme Schuhe und eine sichere Strecke, drinnen oder draußen"],
  ["Parate erguido con la mirada al frente, hombros relajados y brazos sueltos a los costados.","Stand tall looking straight ahead, shoulders relaxed and arms loose at your sides.","Fique ereto com o olhar à frente, ombros relaxados e braços soltos ao lado do corpo.","Tiens-toi droit, regard devant, épaules détendues et bras relâchés le long du corps.","Mettiti dritto con lo sguardo avanti, spalle rilassate e braccia sciolte lungo i fianchi.","Stell dich aufrecht hin, Blick nach vorn, Schultern locker, Arme hängen entspannt."],
  ["Respirá de forma natural y continua; deberías poder conversar sin quedarte sin aire.","Breathe naturally and continuously; you should be able to chat without running out of breath.","Respire de forma natural e contínua; você deve conseguir conversar sem ficar sem ar.","Respire naturellement et en continu ; tu devrais pouvoir discuter sans être à bout de souffle.","Respira in modo naturale e continuo; dovresti riuscire a chiacchierare senza restare senza fiato.","Atme natürlich und gleichmäßig; du solltest dich unterhalten können, ohne außer Atem zu kommen."],
  ["Empezá a caminar despacio unos minutos para entrar en calor.","Start walking slowly for a few minutes to warm up.","Comece a caminhar devagar alguns minutos para aquecer.","Commence à marcher lentement quelques minutes pour t’échauffer.","Inizia a camminare piano per qualche minuto per scaldarti.","Geh zum Aufwärmen ein paar Minuten langsam."],
  ["Mantené pasos naturales, apoyando el talón y rodando hacia la punta, con los brazos acompañando.","Keep natural steps, landing on your heel and rolling to your toes, with your arms swinging along.","Mantenha passos naturais, apoiando o calcanhar e rolando até a ponta, com os braços acompanhando.","Garde des pas naturels, en attaquant par le talon et en déroulant jusqu’à la pointe, bras en mouvement.","Mantieni passi naturali, appoggiando il tallone e rullando verso la punta, con le braccia che accompagnano.","Geh mit natürlichen Schritten, setz mit der Ferse auf und roll zur Fußspitze ab, die Arme schwingen mit."],
  ["Ajustá el ritmo a un esfuerzo cómodo en el que puedas conversar con frases completas (prueba del habla).","Adjust your pace to a comfortable effort where you can chat in full sentences (talk test).","Ajuste o ritmo a um esforço confortável em que consiga conversar com frases completas (teste da fala).","Ajuste ton rythme à un effort confortable où tu peux discuter par phrases complètes (test de la parole).","Regola il ritmo su uno sforzo comodo in cui riesci a chiacchierare con frasi complete (test del parlato).","Pass das Tempo an eine angenehme Belastung an, bei der du dich in ganzen Sätzen unterhalten kannst (Sprechtest)."],
  ["Bajá la velocidad durante los últimos minutos antes de detenerte.","Slow down during the last few minutes before stopping.","Reduza a velocidade durante os últimos minutos antes de parar.","Ralentis pendant les dernières minutes avant de t’arrêter.","Rallenta negli ultimi minuti prima di fermarti.","Werde in den letzten Minuten langsamer, bevor du stehen bleibst."],
  ["Mirar el suelo todo el tiempo y encorvar la espalda.","Looking at the ground the whole time and hunching your back.","Olhar para o chão o tempo todo e curvar as costas.","Regarder le sol tout le temps et voûter le dos.","Guardare sempre a terra e incurvare la schiena.","Die ganze Zeit auf den Boden schauen und einen runden Rücken machen."],
  ["Dar pasos demasiado largos.","Taking steps that are too long.","Dar passos longos demais.","Faire des pas trop longs.","Fare passi troppo lunghi.","Zu lange Schritte machen."],
  ["Arrancar a un ritmo que no podés sostener.","Starting at a pace you can’t sustain.","Começar em um ritmo que você não consegue sustentar.","Partir à un rythme que tu ne peux pas tenir.","Partire a un ritmo che non riesci a sostenere.","In einem Tempo starten, das du nicht halten kannst."],
  ["Elegí un recorrido sin obstáculos y bien iluminado.","Choose a well-lit route without obstacles.","Escolha um percurso sem obstáculos e bem iluminado.","Choisis un parcours sans obstacles et bien éclairé.","Scegli un percorso senza ostacoli e ben illuminato.","Wähle eine gut beleuchtete Strecke ohne Hindernisse."],
  ["Si querés más esfuerzo, aumentá la velocidad de a poco o sumá una pendiente suave.","If you want more effort, increase the speed gradually or add a gentle slope.","Se quiser mais esforço, aumente a velocidade aos poucos ou inclua uma subida suave.","Si tu veux plus d’effort, augmente la vitesse progressivement ou ajoute une légère pente.","Se vuoi più sforzo, aumenta la velocità poco a poco o aggiungi una leggera pendenza.","Für mehr Belastung erhöh das Tempo nach und nach oder nimm eine leichte Steigung dazu."],
  ["Llevá agua si la caminata es larga o hace calor.","Bring water if the walk is long or it’s hot.","Leve água se a caminhada for longa ou estiver calor.","Emporte de l’eau si la marche est longue ou s’il fait chaud.","Porta dell’acqua se la camminata è lunga o fa caldo.","Nimm Wasser mit, wenn der Spaziergang lang ist oder es heiß ist."],
  ["Sistema cardiovascular; cuádriceps, glúteos y pantorrillas","Cardiovascular system; quadriceps, glutes and calves","Sistema cardiovascular; quadríceps, glúteos e panturrilhas","Système cardiovasculaire ; quadriceps, fessiers et mollets","Sistema cardiovascolare; quadricipiti, glutei e polpacci","Herz-Kreislauf-System; Quadrizeps, Gesäß und Waden"],
  ["Espacio interior despejado (pasillo o habitación) y calzado cómodo","A clear indoor space (hallway or room) and comfortable shoes","Espaço interno livre (corredor ou cômodo) e calçado confortável","Un espace intérieur dégagé (couloir ou pièce) et des chaussures confortables","Uno spazio interno libero (corridoio o stanza) e scarpe comode","Freier Platz drinnen (Flur oder Zimmer) und bequeme Schuhe"],
  ["Ubicate en un espacio libre de obstáculos, erguido y con los brazos relajados.","Position yourself in a space free of obstacles, standing tall with your arms relaxed.","Posicione-se em um espaço sem obstáculos, ereto e com os braços relaxados.","Place-toi dans un espace sans obstacles, droit et bras détendus.","Posizionati in uno spazio libero da ostacoli, dritto e con le braccia rilassate.","Stell dich aufrecht in einen Bereich ohne Hindernisse, Arme locker."],
  ["Respirá de forma rítmica; en los tramos rápidos podés hablar en frases cortas y en los suaves, conversar.","Breathe rhythmically; in the fast stretches you can talk in short sentences and in the easy ones, chat.","Respire de forma rítmica; nos trechos rápidos você consegue falar frases curtas e nos leves, conversar.","Respire en rythme ; dans les portions rapides, tu peux parler par phrases courtes et dans les portions faciles, discuter.","Respira in modo ritmico; nei tratti veloci riesci a parlare a frasi brevi e in quelli leggeri a chiacchierare.","Atme rhythmisch; in den schnellen Abschnitten kannst du in kurzen Sätzen sprechen, in den lockeren dich unterhalten."],
  ["Caminá unos minutos a ritmo suave para entrar en calor.","Walk for a few minutes at an easy pace to warm up.","Caminhe alguns minutos em ritmo leve para aquecer.","Marche quelques minutes à un rythme facile pour t’échauffer.","Cammina qualche minuto a ritmo leggero per scaldarti.","Geh zum Aufwärmen ein paar Minuten locker."],
  ["Alterná tramos de caminata más rápida, en los que solo puedas hablar en frases cortas, con tramos suaves en los que puedas conversar (prueba del habla).","Alternate stretches of faster walking, where you can only talk in short sentences, with easy stretches where you can chat (talk test).","Alterne trechos de caminhada mais rápida, em que só consiga falar frases curtas, com trechos leves em que consiga conversar (teste da fala).","Alterne des portions de marche plus rapide, où tu ne peux parler que par phrases courtes, avec des portions faciles où tu peux discuter (test de la parole).","Alterna tratti di camminata più veloce, in cui riesci solo a parlare a frasi brevi, con tratti leggeri in cui riesci a chiacchierare (test del parlato).","Wechsle schnellere Gehabschnitte, in denen du nur kurze Sätze sprechen kannst, mit lockeren ab, in denen du dich unterhalten kannst (Sprechtest)."],
  ["Por ejemplo, 1 minuto más rápido y 1 a 2 minutos suave, ajustando a tu nivel.","For example, 1 minute faster and 1 to 2 minutes easy, adjusting to your level.","Por exemplo, 1 minuto mais rápido e 1 a 2 minutos leve, ajustando ao seu nível.","Par exemple, 1 minute plus rapide et 1 à 2 minutes facile, en adaptant à ton niveau.","Ad esempio, 1 minuto più veloce e 1–2 minuti leggeri, adattando al tuo livello.","Zum Beispiel 1 Minute schneller und 1 bis 2 Minuten locker, angepasst an dein Level."],
  ["Terminá con unos minutos a ritmo suave.","Finish with a few minutes at an easy pace.","Termine com alguns minutos em ritmo leve.","Termine par quelques minutes à un rythme facile.","Termina con qualche minuto a ritmo leggero.","Beende das Training mit ein paar lockeren Minuten."],
  ["Correr o saltar en un espacio reducido.","Running or jumping in a small space.","Correr ou saltar em um espaço pequeno.","Courir ou sauter dans un espace réduit.","Correre o saltare in uno spazio ridotto.","In einem engen Raum laufen oder springen."],
  ["Girar bruscamente en los extremos del recorrido.","Turning sharply at the ends of your route.","Girar bruscamente nas extremidades do percurso.","Faire des demi-tours brusques aux extrémités du parcours.","Girare bruscamente alle estremità del percorso.","An den Enden der Strecke abrupt wenden."],
  ["Hacer los tramos rápidos tan intensos que no te recuperás en los suaves.","Making the fast stretches so intense that you can’t recover in the easy ones.","Fazer os trechos rápidos tão intensos que você não se recupera nos leves.","Rendre les portions rapides si intenses que tu ne récupères pas dans les portions faciles.","Rendere i tratti veloci così intensi da non recuperare in quelli leggeri.","Die schnellen Abschnitte so intensiv machen, dass du dich in den lockeren nicht erholst."],
  ["Retirá alfombras sueltas y objetos del piso antes de empezar.","Remove loose rugs and objects from the floor before you start.","Retire tapetes soltos e objetos do chão antes de começar.","Retire les tapis mal fixés et les objets du sol avant de commencer.","Togli tappeti non fissati e oggetti dal pavimento prima di iniziare.","Räum lose Teppiche und Gegenstände vom Boden, bevor du startest."],
  ["En los giros, bajá la velocidad y girá con pasos cortos.","On turns, slow down and turn with short steps.","Nas viradas, reduza a velocidade e gire com passos curtos.","Dans les virages, ralentis et tourne à petits pas.","Nelle svolte, rallenta e gira con passi corti.","Werde beim Wenden langsamer und dreh dich mit kleinen Schritten."],
  ["Usá un reloj o temporizador para marcar los intervalos.","Use a watch or timer to mark the intervals.","Use um relógio ou cronômetro para marcar os intervalos.","Utilise une montre ou un minuteur pour marquer les intervalles.","Usa un orologio o un timer per segnare gli intervalli.","Nutze eine Uhr oder einen Timer, um die Intervalle zu markieren."],
  ["Pantorrillas, isquiotibiales y estabilizadores de cadera","Calves, hamstrings and hip stabilizers","Panturrilhas, isquiotibiais e estabilizadores do quadril","Mollets, ischio-jambiers et stabilisateurs de hanche","Polpacci, ischiocrurali e stabilizzatori dell’anca","Waden, hintere Oberschenkel und Hüftstabilisatoren"],
  ["Escalón firme y bajo (el primer escalón de una escalera o un step) con baranda o pared cerca","Sturdy, low step (the first step of a staircase or an aerobic step) with a handrail or wall nearby","Degrau firme e baixo (o primeiro degrau de uma escada ou um step) com corrimão ou parede perto","Marche solide et basse (la première marche d’un escalier ou un step) avec une rampe ou un mur à proximité","Gradino stabile e basso (il primo gradino di una scala o uno step) con corrimano o parete vicino","Stabile, niedrige Stufe (die erste Treppenstufe oder ein Step) mit Geländer oder Wand in der Nähe"],
  ["Parate frente al escalón con los pies al ancho de cadera y una mano cerca de la baranda o la pared.","Stand facing the step with your feet hip-width apart and one hand near the handrail or wall.","Fique de frente para o degrau com os pés na largura do quadril e uma mão perto do corrimão ou da parede.","Tiens-toi face à la marche, pieds à la largeur des hanches et une main près de la rampe ou du mur.","Mettiti di fronte al gradino con i piedi alla larghezza delle anche e una mano vicino al corrimano o alla parete.","Stell dich hüftbreit vor die Stufe, eine Hand nahe am Geländer oder an der Wand."],
  ["Respirá de forma rítmica; si no podés hablar en frases cortas, bajá el ritmo.","Breathe rhythmically; if you can’t talk in short sentences, slow the pace.","Respire de forma rítmica; se não conseguir falar frases curtas, reduza o ritmo.","Respire en rythme ; si tu ne peux pas parler par phrases courtes, ralentis.","Respira in modo ritmico; se non riesci a parlare a frasi brevi, rallenta.","Atme rhythmisch; wenn du nicht in kurzen Sätzen sprechen kannst, werde langsamer."],
  ["Verificá que el escalón no se mueva y que la superficie no resbale.","Check that the step doesn’t move and that the surface isn’t slippery.","Verifique que o degrau não se mova e que a superfície não escorregue.","Vérifie que la marche ne bouge pas et que la surface ne glisse pas.","Verifica che il gradino non si muova e che la superficie non scivoli.","Prüf, dass die Stufe nicht wackelt und die Oberfläche nicht rutschig ist."],
  ["Subí con un pie apoyando la planta completa, luego subí el otro; bajá en el mismo orden.","Step up with one foot placing your whole sole down, then bring up the other; step down in the same order.","Suba com um pé apoiando a planta inteira, depois suba o outro; desça na mesma ordem.","Monte un pied en posant toute la plante, puis l’autre ; redescends dans le même ordre.","Sali con un piede appoggiando tutta la pianta, poi sali con l’altro; scendi nello stesso ordine.","Steig mit einem Fuß mit voller Sohle auf, dann mit dem anderen; steig in derselben Reihenfolge ab."],
  ["Mantené un ritmo constante en el que puedas hablar en frases cortas (prueba del habla).","Keep a steady pace where you can talk in short sentences (talk test).","Mantenha um ritmo constante em que consiga falar frases curtas (teste da fala).","Garde un rythme régulier où tu peux parler par phrases courtes (test de la parole).","Mantieni un ritmo costante in cui riesci a parlare a frasi brevi (test del parlato).","Halte ein gleichmäßiges Tempo, bei dem du in kurzen Sätzen sprechen kannst (Sprechtest)."],
  ["Cambiá la pierna que inicia cada uno o dos minutos y bajá el ritmo al final.","Switch the leading leg every one or two minutes and slow down at the end.","Troque a perna que inicia a cada um ou dois minutos e reduza o ritmo no final.","Change de jambe d’attaque toutes les une ou deux minutes et ralentis à la fin.","Cambia la gamba che inizia ogni uno o due minuti e rallenta alla fine.","Wechsle alle ein bis zwei Minuten das Startbein und werde am Ende langsamer."],
  ["Apoyar solo la punta del pie en el escalón.","Placing only the ball of your foot on the step.","Apoiar só a ponta do pé no degrau.","Poser seulement la pointe du pied sur la marche.","Appoggiare solo la punta del piede sul gradino.","Nur den Vorfuß auf die Stufe setzen."],
  ["Usar un escalón alto o inestable.","Using a high or unstable step.","Usar um degrau alto ou instável.","Utiliser une marche haute ou instable.","Usare un gradino alto o instabile.","Eine hohe oder instabile Stufe nutzen."],
  ["Bajar de espaldas sin mirar.","Stepping down backward without looking.","Descer de costas sem olhar.","Descendre à reculons sans regarder.","Scendere all’indietro senza guardare.","Rückwärts absteigen, ohne hinzuschauen."],
  ["Un escalón bajo es suficiente para elevar el pulso.","A low step is enough to raise your heart rate.","Um degrau baixo é suficiente para elevar o pulso.","Une marche basse suffit pour faire monter le cœur.","Un gradino basso basta per alzare il battito.","Eine niedrige Stufe reicht, um den Puls zu erhöhen."],
  ["Usá la baranda si necesitás equilibrio.","Use the handrail if you need balance.","Use o corrimão se precisar de equilíbrio.","Utilise la rampe si tu as besoin d’équilibre.","Usa il corrimano se ti serve equilibrio.","Nutze das Geländer, wenn du Halt brauchst."],
  ["Mantené el tronco erguido y la mirada al frente.","Keep your torso upright and look straight ahead.","Mantenha o tronco ereto e o olhar à frente.","Garde le buste droit et le regard devant.","Mantieni il busto eretto e lo sguardo avanti.","Halte den Oberkörper aufrecht und schau nach vorn."],
  ["Sistema cardiovascular; piernas y glúteos","Cardiovascular system; legs and glutes","Sistema cardiovascular; pernas e glúteos","Système cardiovasculaire ; jambes et fessiers","Sistema cardiovascolare; gambe e glutei","Herz-Kreislauf-System; Beine und Gesäß"],
  ["Hombros, brazos y tronco estabilizador","Shoulders, arms and stabilizing trunk","Ombros, braços e tronco estabilizador","Épaules, bras et tronc stabilisateur","Spalle, braccia e tronco stabilizzatore","Schultern, Arme und stabilisierender Rumpf"],
  ["Espacio despejado, calzado cómodo y música opcional","Clear space, comfortable shoes and optional music","Espaço livre, calçado confortável e música opcional","Espace dégagé, chaussures confortables et musique en option","Spazio libero, scarpe comode e musica facoltativa","Freier Platz, bequeme Schuhe und optional Musik"],
  ["Parate en un espacio libre de obstáculos, con los pies al ancho de cadera y el cuerpo relajado.","Stand in a space free of obstacles, with your feet hip-width apart and your body relaxed.","Fique em um espaço sem obstáculos, com os pés na largura do quadril e o corpo relaxado.","Tiens-toi dans un espace sans obstacles, pieds à la largeur des hanches et corps détendu.","Mettiti in uno spazio libero da ostacoli, con i piedi alla larghezza delle anche e il corpo rilassato.","Stell dich in einen Bereich ohne Hindernisse, Füße hüftbreit, Körper locker."],
  ["Respirá de forma rítmica y continua; si no podés hablar, reducí el ritmo.","Breathe rhythmically and continuously; if you can’t talk, lower the pace.","Respire de forma rítmica e contínua; se não conseguir falar, reduza o ritmo.","Respire en rythme et en continu ; si tu ne peux pas parler, ralentis.","Respira in modo ritmico e continuo; se non riesci a parlare, riduci il ritmo.","Atme rhythmisch und gleichmäßig; wenn du nicht sprechen kannst, reduzier das Tempo."],
  ["Empezá con pasos simples y suaves, como pasos laterales o marcha, para entrar en calor.","Start with simple, gentle steps, such as side steps or marching, to warm up.","Comece com passos simples e suaves, como passos laterais ou marcha, para aquecer.","Commence par des pas simples et doux, comme des pas chassés ou de la marche, pour t’échauffer.","Inizia con passi semplici e leggeri, come passi laterali o marcia, per scaldarti.","Beginne zum Aufwärmen mit einfachen, sanften Schritten wie Seitschritten oder Marschieren."],
  ["Sumá movimientos de brazos y cambios de dirección manteniendo siempre un pie en contacto con el suelo.","Add arm movements and changes of direction, always keeping one foot on the floor.","Inclua movimentos de braços e mudanças de direção mantendo sempre um pé em contato com o chão.","Ajoute des mouvements de bras et des changements de direction en gardant toujours un pied au sol.","Aggiungi movimenti delle braccia e cambi di direzione mantenendo sempre un piede a contatto con il suolo.","Nimm Armbewegungen und Richtungswechsel dazu und behalte dabei immer einen Fuß am Boden."],
  ["Ajustá el ritmo a un esfuerzo en el que puedas hablar en frases cortas (prueba del habla).","Adjust your pace to an effort where you can talk in short sentences (talk test).","Ajuste o ritmo a um esforço em que consiga falar frases curtas (teste da fala).","Ajuste ton rythme à un effort où tu peux parler par phrases courtes (test de la parole).","Regola il ritmo su uno sforzo in cui riesci a parlare a frasi brevi (test del parlato).","Pass das Tempo an eine Belastung an, bei der du in kurzen Sätzen sprechen kannst (Sprechtest)."],
  ["Bajá la intensidad los últimos minutos con pasos más lentos.","Lower the intensity in the last few minutes with slower steps.","Reduza a intensidade nos últimos minutos com passos mais lentos.","Baisse l’intensité les dernières minutes avec des pas plus lents.","Abbassa l’intensità negli ultimi minuti con passi più lenti.","Senk die Intensität in den letzten Minuten mit langsameren Schritten."],
  ["Saltar o girar bruscamente sobre un pie.","Jumping or pivoting sharply on one foot.","Saltar ou girar bruscamente sobre um pé.","Sauter ou pivoter brusquement sur un pied.","Saltare o girare bruscamente su un piede.","Springen oder abrupt auf einem Fuß drehen."],
  ["Moverse en un espacio con objetos o alfombras sueltas.","Moving in a space with objects or loose rugs.","Mover-se em um espaço com objetos ou tapetes soltos.","Bouger dans un espace encombré d’objets ou de tapis mal fixés.","Muoversi in uno spazio con oggetti o tappeti non fissati.","Sich in einem Raum mit Gegenständen oder losen Teppichen bewegen."],
  ["Arrancar a máxima intensidad.","Starting at maximum intensity.","Começar na intensidade máxima.","Commencer à intensité maximale.","Partire alla massima intensità.","Mit maximaler Intensität starten."],
  ["Bajo impacto significa evitar saltos: siempre hay un pie apoyado.","Low impact means avoiding jumps: one foot is always on the floor.","Baixo impacto significa evitar saltos: sempre há um pé apoiado.","Faible impact signifie éviter les sauts : un pied est toujours au sol.","Basso impatto significa evitare i salti: c’è sempre un piede appoggiato.","Gelenkschonend heißt ohne Sprünge: Ein Fuß ist immer am Boden."],
  ["Elegí música con un ritmo que puedas seguir con comodidad.","Choose music with a beat you can follow comfortably.","Escolha músicas com um ritmo que você consiga acompanhar com conforto.","Choisis une musique avec un rythme que tu peux suivre confortablement.","Scegli musica con un ritmo che riesci a seguire comodamente.","Wähle Musik mit einem Takt, dem du bequem folgen kannst."],
  ["Lo importante es moverte de forma continua y disfrutarlo.","What matters is moving continuously and enjoying it.","O importante é se mover de forma contínua e curtir.","L’important, c’est de bouger en continu et d’y prendre plaisir.","L’importante è muoversi in modo continuo e divertirsi.","Wichtig ist, dass du dich durchgehend bewegst und Spaß hast."],
  ["Sistema cardiovascular; hombros y brazos","Cardiovascular system; shoulders and arms","Sistema cardiovascular; ombros e braços","Système cardiovasculaire ; épaules et bras","Sistema cardiovascolare; spalle e braccia","Herz-Kreislauf-System; Schultern und Arme"],
  ["Core, oblicuos y piernas","Core, obliques and legs","Core, oblíquos e pernas","Sangle abdominale, obliques et jambes","Core, obliqui e gambe","Rumpf, schräge Bauchmuskeln und Beine"],
  ["Parate en guardia con un pie levemente adelantado, rodillas suaves, manos a la altura de la cara y codos cerca del cuerpo.","Get into a guard stance with one foot slightly forward, knees soft, hands at face height and elbows close to your body.","Fique em guarda com um pé levemente à frente, joelhos soltos, mãos na altura do rosto e cotovelos perto do corpo.","Mets-toi en garde, un pied légèrement en avant, genoux souples, mains à hauteur du visage et coudes près du corps.","Mettiti in guardia con un piede leggermente avanti, ginocchia morbide, mani all’altezza del viso e gomiti vicini al corpo.","Geh in die Deckung, ein Fuß leicht vorn, Knie weich, Hände auf Gesichtshöhe, Ellbogen nah am Körper."],
  ["Exhalá con cada golpe y respirá de forma continua entre combinaciones.","Exhale with each punch and breathe continuously between combinations.","Expire a cada golpe e respire de forma contínua entre as combinações.","Expire à chaque coup et respire en continu entre les enchaînements.","Espira a ogni colpo e respira in modo continuo tra le combinazioni.","Atme bei jedem Schlag aus und zwischen den Kombinationen gleichmäßig weiter."],
  ["Mové los pies con pasos cortos, sin saltar, manteniendo la guardia.","Move your feet with short steps, without jumping, keeping your guard up.","Mova os pés com passos curtos, sem saltar, mantendo a guarda.","Déplace-toi à petits pas, sans sauter, en gardant ta garde.","Muovi i piedi con passi corti, senza saltare, mantenendo la guardia.","Beweg die Füße mit kleinen Schritten, ohne zu springen, und halte die Deckung."],
  ["Lanzá golpes rectos y ganchos al aire con control, girando apenas el tronco y la cadera.","Throw straight punches and hooks into the air with control, rotating your torso and hips slightly.","Lance jabs, diretos e ganchos no ar com controle, girando levemente o tronco e o quadril.","Lance des directs et des crochets dans le vide en contrôle, en faisant légèrement pivoter le buste et les hanches.","Tira diretti e ganci a vuoto con controllo, ruotando appena busto e anche.","Schlag kontrolliert Geraden und Haken in die Luft und dreh dabei Oberkörper und Hüfte leicht mit."],
  ["No extiendas los codos por completo ni de golpe al final de cada golpe.","Don’t fully or abruptly extend your elbows at the end of each punch.","Não estenda os cotovelos por completo nem de uma vez no final de cada golpe.","Ne tends pas complètement ni brusquement les coudes à la fin de chaque coup.","Non distendere i gomiti del tutto né di colpo alla fine di ogni colpo.","Streck die Ellbogen am Ende eines Schlags nicht vollständig oder ruckartig durch."],
  ["Mantené un ritmo en el que puedas hablar en frases cortas (prueba del habla) y bajá la intensidad al final.","Keep a pace where you can talk in short sentences (talk test) and lower the intensity at the end.","Mantenha um ritmo em que consiga falar frases curtas (teste da fala) e reduza a intensidade no final.","Garde un rythme où tu peux parler par phrases courtes (test de la parole) et baisse l’intensité à la fin.","Mantieni un ritmo in cui riesci a parlare a frasi brevi (test del parlato) e abbassa l’intensità alla fine.","Halte ein Tempo, bei dem du in kurzen Sätzen sprechen kannst (Sprechtest), und senk am Ende die Intensität."],
  ["Bloquear los codos con fuerza al extender los golpes.","Forcefully locking your elbows as you extend your punches.","Travar os cotovelos com força ao estender os golpes.","Verrouiller les coudes en force en tendant les coups.","Bloccare con forza i gomiti distendendo i colpi.","Die Ellbogen beim Schlagen kräftig durchdrücken."],
  ["Bajar la guardia y encorvar los hombros.","Dropping your guard and hunching your shoulders.","Baixar a guarda e curvar os ombros.","Baisser la garde et voûter les épaules.","Abbassare la guardia e incurvare le spalle.","Die Deckung fallen lassen und die Schultern hochziehen."],
  ["Saltar sobre la punta de los pies todo el tiempo.","Bouncing on your toes the whole time.","Saltar na ponta dos pés o tempo todo.","Sautiller sur la pointe des pieds tout le temps.","Saltellare sulle punte tutto il tempo.","Die ganze Zeit auf den Fußballen hüpfen."],
  ["La velocidad viene del giro del tronco, no de lanzar el brazo sin control.","Speed comes from rotating your torso, not from throwing your arm without control.","A velocidade vem do giro do tronco, não de lançar o braço sem controle.","La vitesse vient de la rotation du buste, pas d’un bras lancé sans contrôle.","La velocità viene dalla rotazione del busto, non dal lanciare il braccio senza controllo.","Die Geschwindigkeit kommt aus der Oberkörperdrehung, nicht aus unkontrolliertem Armschwung."],
  ["Volvé siempre las manos a la guardia después de cada golpe.","Always bring your hands back to your guard after each punch.","Volte sempre as mãos à guarda depois de cada golpe.","Ramène toujours les mains en garde après chaque coup.","Riporta sempre le mani in guardia dopo ogni colpo.","Bring die Hände nach jedem Schlag immer zurück in die Deckung."],
  ["Alterná el pie adelantado cada uno o dos minutos.","Switch your lead foot every one or two minutes.","Alterne o pé da frente a cada um ou dois minutos.","Change de pied avant toutes les une ou deux minutes.","Alterna il piede avanti ogni uno o due minuti.","Wechsle alle ein bis zwei Minuten den vorderen Fuß."],
  ["Rotadores internos y externos de la cadera","Internal and external hip rotators","Rotadores internos e externos do quadril","Rotateurs internes et externes de la hanche","Rotatori interni ed esterni dell’anca","Innen- und Außenrotatoren der Hüfte"],
  ["Glúteos, aductores y flexores de cadera","Glutes, adductors and hip flexors","Glúteos, adutores e flexores do quadril","Fessiers, adducteurs et fléchisseurs de hanche","Glutei, adduttori e flessori dell’anca","Gesäß, Adduktoren und Hüftbeuger"],
  ["Sentate en el suelo con las rodillas flexionadas, los pies apoyados algo más abiertos que la cadera y las manos apoyadas detrás.","Sit on the floor with your knees bent, feet flat slightly wider than your hips and hands on the floor behind you.","Sente-se no chão com os joelhos flexionados, os pés apoiados um pouco mais abertos que o quadril e as mãos apoiadas atrás.","Assieds-toi au sol, genoux fléchis, pieds à plat un peu plus écartés que les hanches et mains posées derrière toi.","Siediti a terra con le ginocchia piegate, i piedi appoggiati poco più larghi delle anche e le mani appoggiate dietro.","Setz dich mit gebeugten Knien auf den Boden, Füße etwas breiter als hüftbreit aufgestellt, Hände hinter dir abgestützt."],
  ["Respirá lento y profundo, exhalando al llegar a cada lado.","Breathe slowly and deeply, exhaling as you reach each side.","Respire lenta e profundamente, expirando ao chegar a cada lado.","Respire lentement et profondément, en expirant en arrivant de chaque côté.","Respira lentamente e profondamente, espirando quando arrivi a ogni lato.","Atme langsam und tief und atme aus, wenn du auf jeder Seite ankommst."],
  ["Sin pausa obligatoria","No set rest needed","Sem pausa obrigatória","Pas de pause obligatoire","Nessuna pausa obbligatoria","Keine feste Pause nötig"],
  ["Apoyá las manos atrás para sostener el tronco erguido.","Rest your hands behind you to support your torso upright.","Apoie as mãos atrás para sustentar o tronco ereto.","Pose les mains derrière toi pour garder le buste droit.","Appoggia le mani dietro per sostenere il busto eretto.","Stütz die Hände hinter dir ab, um den Oberkörper aufrecht zu halten."],
  ["Bajá despacio ambas rodillas hacia un lado, como limpiaparabrisas, hasta un rango cómodo.","Slowly lower both knees to one side, like windshield wipers, to a comfortable range.","Abaixe devagar os dois joelhos para um lado, como um limpador de para-brisa, até uma amplitude confortável.","Abaisse lentement les deux genoux d’un côté, comme des essuie-glaces, jusqu’à une amplitude confortable.","Abbassa lentamente entrambe le ginocchia da un lato, come un tergicristallo, fino a un’ampiezza comoda.","Senk beide Knie langsam wie Scheibenwischer zu einer Seite, bis zu einem angenehmen Bewegungsumfang."],
  ["Volvé al centro y llevá las rodillas hacia el otro lado con la misma lentitud.","Return to the center and take your knees to the other side just as slowly.","Volte ao centro e leve os joelhos para o outro lado com a mesma lentidão.","Reviens au centre et amène les genoux de l’autre côté tout aussi lentement.","Torna al centro e porta le ginocchia dall’altro lato con la stessa lentezza.","Komm zur Mitte zurück und führ die Knie genauso langsam zur anderen Seite."],
  ["Repetí de forma continua y controlada, sin rebotes ni dolor.","Repeat continuously and with control, without bouncing or pain.","Repita de forma contínua e controlada, sem quicar nem sentir dor.","Répète en continu et en contrôle, sans rebond ni douleur.","Ripeti in modo continuo e controllato, senza rimbalzi né dolore.","Wiederhol die Bewegung fließend und kontrolliert, ohne Federn und ohne Schmerz."],
  ["Forzar las rodillas hacia el suelo con rebotes.","Forcing your knees toward the floor with bounces.","Forçar os joelhos em direção ao chão com quiques.","Forcer les genoux vers le sol avec des rebonds.","Forzare le ginocchia verso il pavimento con rimbalzi.","Die Knie federnd zum Boden drücken."],
  ["Moverse rápido sin control.","Moving fast without control.","Mover-se rápido sem controle.","Bouger vite sans contrôle.","Muoversi veloce senza controllo.","Sich schnell und unkontrolliert bewegen."],
  ["Seguir si aparece dolor en la cadera o la rodilla.","Continuing if you feel pain in your hip or knee.","Continuar se aparecer dor no quadril ou no joelho.","Continuer si une douleur apparaît à la hanche ou au genou.","Continuare se compare dolore all’anca o al ginocchio.","Weitermachen, obwohl Hüfte oder Knie schmerzen."],
  ["El rango crece solo con la repetición suave; no lo fuerces.","Range improves on its own with gentle repetition; don’t force it.","A amplitude aumenta sozinha com a repetição suave; não force.","L’amplitude augmente d’elle-même avec une répétition douce ; ne force pas.","L’ampiezza cresce da sola con la ripetizione delicata; non forzarla.","Der Bewegungsumfang wächst durch sanftes Wiederholen von allein; erzwing nichts."],
  ["Si las manos atrás molestan, apoyate sobre los antebrazos.","If your hands behind you are uncomfortable, lean back on your forearms.","Se as mãos atrás incomodarem, apoie-se nos antebraços.","Si les mains derrière te gênent, appuie-toi sur les avant-bras.","Se le mani dietro danno fastidio, appoggiati sugli avambracci.","Wenn die Hände hinter dir unangenehm sind, stütz dich auf die Unterarme."],
  ["Podés hacer una pausa breve en cada lado para respirar.","You can pause briefly on each side to breathe.","Você pode fazer uma pausa breve em cada lado para respirar.","Tu peux faire une courte pause de chaque côté pour respirer.","Puoi fare una breve pausa su ogni lato per respirare.","Du kannst auf jeder Seite kurz innehalten, um zu atmen."],
  ["Psoas ilíaco y recto femoral","Iliopsoas and rectus femoris","Iliopsoas e reto femoral","Psoas iliaque et droit fémoral","Ileopsoas e retto femorale","Hüftlendenmuskel (Iliopsoas) und gerader Oberschenkelmuskel"],
  ["Glúteo del lado que estira y tronco estabilizador","Glute on the stretching side and stabilizing trunk","Glúteo do lado que alonga e tronco estabilizador","Fessier du côté étiré et tronc stabilisateur","Gluteo del lato che allunga e tronco stabilizzatore","Gesäß der gedehnten Seite und stabilisierender Rumpf"],
  ["Colchoneta o almohadón para la rodilla; opcionalmente una silla firme para apoyar la mano","Mat or cushion for the knee; optionally a sturdy chair to rest your hand on","Colchonete ou almofada para o joelho; opcionalmente uma cadeira firme para apoiar a mão","Tapis ou coussin pour le genou ; éventuellement une chaise solide pour poser la main","Tappetino o cuscino per il ginocchio; facoltativamente una sedia stabile per appoggiare la mano","Matte oder Kissen fürs Knie; optional ein stabiler Stuhl zum Abstützen der Hand"],
  ["Arrodillate en posición de media zancada, con una rodilla apoyada sobre un almohadón y el otro pie adelante con la rodilla a 90 grados.","Kneel in a half-lunge position, one knee on a cushion and the other foot forward with the knee at 90 degrees.","Ajoelhe-se em posição de meia passada, com um joelho apoiado sobre uma almofada e o outro pé à frente com o joelho a 90 graus.","Mets-toi à genoux en demi-fente, un genou sur un coussin et l’autre pied devant, genou à 90 degrés.","Inginocchiati in posizione di mezzo affondo, con un ginocchio appoggiato su un cuscino e l’altro piede avanti con il ginocchio a 90 gradi.","Geh in den halben Kniestand, ein Knie auf einem Kissen, der andere Fuß vorn mit dem Knie im 90-Grad-Winkel."],
  ["Respirá lento y profundo durante todo el estiramiento.","Breathe slowly and deeply throughout the stretch.","Respire lenta e profundamente durante todo o alongamento.","Respire lentement et profondément pendant tout l’étirement.","Respira lentamente e profondamente per tutto l’allungamento.","Atme während der ganzen Dehnung langsam und tief."],
  ["Apoyá la rodilla de atrás sobre un almohadón y el tronco erguido; si necesitás, sostenete de una silla firme.","Rest your back knee on a cushion with your torso upright; if you need to, hold on to a sturdy chair.","Apoie o joelho de trás sobre uma almofada com o tronco ereto; se precisar, segure-se em uma cadeira firme.","Pose le genou arrière sur un coussin, buste droit ; si besoin, tiens-toi à une chaise solide.","Appoggia il ginocchio posteriore su un cuscino con il busto eretto; se serve, tieniti a una sedia stabile.","Leg das hintere Knie auf ein Kissen, Oberkörper aufrecht; halt dich bei Bedarf an einem stabilen Stuhl fest."],
  ["Apretá el glúteo del lado de atrás y llevá la pelvis levemente hacia adelante y abajo, sin arquear la espalda.","Squeeze the glute on your back side and move your pelvis slightly forward and down, without arching your back.","Contraia o glúteo do lado de trás e leve a pelve levemente para frente e para baixo, sem arquear as costas.","Serre le fessier du côté arrière et amène le bassin légèrement vers l’avant et le bas, sans cambrer le dos.","Contrai il gluteo del lato posteriore e porta il bacino leggermente in avanti e in basso, senza inarcare la schiena.","Spann das Gesäß der hinteren Seite an und schieb das Becken leicht nach vorn unten, ohne ins Hohlkreuz zu gehen."],
  ["Sostené el estiramiento de forma suave mientras respirás, sin rebotar ni sentir dolor.","Hold the stretch gently while you breathe, without bouncing or feeling pain.","Sustente o alongamento de forma suave enquanto respira, sem quicar nem sentir dor.","Maintiens l’étirement en douceur en respirant, sans rebond ni douleur.","Mantieni l’allungamento con delicatezza mentre respiri, senza rimbalzi né dolore.","Halte die Dehnung sanft und atme dabei, ohne zu federn oder Schmerz zu spüren."],
  ["Salí de la posición despacio y repetí del otro lado.","Come out of the position slowly and repeat on the other side.","Saia da posição devagar e repita do outro lado.","Sors lentement de la position et recommence de l’autre côté.","Esci lentamente dalla posizione e ripeti dall’altro lato.","Löse die Position langsam und wiederhol es auf der anderen Seite."],
  ["Arquear la zona lumbar en lugar de mover la pelvis.","Arching your lower back instead of moving your pelvis.","Arquear a lombar em vez de mover a pelve.","Cambrer le bas du dos au lieu de bouger le bassin.","Inarcare la zona lombare invece di muovere il bacino.","Ins Hohlkreuz gehen, statt das Becken zu bewegen."],
  ["Inclinarse muy adelante cargando la rodilla de adelante.","Leaning far forward and loading your front knee.","Inclinar-se muito para frente sobrecarregando o joelho da frente.","Se pencher trop en avant en chargeant le genou avant.","Inclinarsi molto in avanti caricando il ginocchio anteriore.","Sich weit nach vorn lehnen und das vordere Knie belasten."],
  ["Rebotar para estirar más.","Bouncing to stretch further.","Quicar para alongar mais.","Rebondir pour s’étirer davantage.","Rimbalzare per allungare di più.","Federn, um weiter zu dehnen."],
  ["Con el glúteo apretado el estiramiento se siente más en la cadera que en la espalda.","With your glute squeezed, you feel the stretch more in your hip than in your back.","Com o glúteo contraído, o alongamento é sentido mais no quadril do que nas costas.","Fessier serré, l’étirement se ressent davantage dans la hanche que dans le dos.","Con il gluteo contratto, l’allungamento si sente più nell’anca che nella schiena.","Mit angespanntem Gesäß spürst du die Dehnung mehr in der Hüfte als im Rücken."],
  ["Elevar el brazo del lado de atrás intensifica el estiramiento.","Raising the arm on your back side intensifies the stretch.","Elevar o braço do lado de trás intensifica o alongamento.","Lever le bras du côté arrière intensifie l’étirement.","Sollevare il braccio del lato posteriore intensifica l’allungamento.","Wenn du den Arm der hinteren Seite hebst, wird die Dehnung intensiver."],
  ["Un estiramiento suave y sostenido es suficiente.","A gentle, sustained stretch is enough.","Um alongamento suave e sustentado é suficiente.","Un étirement doux et maintenu suffit.","Un allungamento delicato e mantenuto è sufficiente.","Eine sanfte, gehaltene Dehnung reicht."],
  ["Musculatura de la columna (erectores y abdominales)","Spinal muscles (erectors and abdominals)","Musculatura da coluna (eretores e abdominais)","Muscles de la colonne (érecteurs et abdominaux)","Muscolatura della colonna (erettori e addominali)","Wirbelsäulenmuskulatur (Rückenstrecker und Bauchmuskeln)"],
  ["Estabilizadores escapulares y cuello","Scapular stabilizers and neck","Estabilizadores escapulares e pescoço","Stabilisateurs de l’omoplate et cou","Stabilizzatori scapolari e collo","Schulterblattstabilisatoren und Nacken"],
  ["Ponete en cuadrupedia con las manos bajo los hombros, rodillas bajo la cadera y la espalda neutra.","Get on all fours with your hands under your shoulders, knees under your hips and back neutral.","Fique em quatro apoios com as mãos sob os ombros, joelhos sob o quadril e as costas neutras.","Mets-toi à quatre pattes, mains sous les épaules, genoux sous les hanches et dos neutre.","Mettiti a quattro zampe con le mani sotto le spalle, ginocchia sotto le anche e schiena neutra.","Geh in den Vierfüßlerstand, Hände unter den Schultern, Knie unter der Hüfte, Rücken neutral."],
  ["Exhalá al redondear la espalda e inhalá al arquearla.","Exhale as you round your back and inhale as you arch it.","Expire ao arredondar as costas e inspire ao arqueá-las.","Expire en arrondissant le dos et inspire en le creusant.","Espira arrotondando la schiena e inspira inarcandola.","Atme beim Runden des Rückens aus und beim Hohlkreuz ein."],
  ["Empezá con la espalda neutra y la mirada al suelo.","Start with a neutral back and your gaze on the floor.","Comece com as costas neutras e o olhar no chão.","Commence le dos neutre et le regard vers le sol.","Inizia con la schiena neutra e lo sguardo a terra.","Beginne mit neutralem Rücken und Blick zum Boden."],
  ["Redondeá la espalda hacia el techo, llevando la barbilla y la pelvis hacia adentro (gato).","Round your back toward the ceiling, tucking your chin and pelvis (cat).","Arredonde as costas em direção ao teto, levando o queixo e a pelve para dentro (gato).","Arrondis le dos vers le plafond en rentrant le menton et le bassin (chat).","Arrotonda la schiena verso il soffitto, portando dentro mento e bacino (gatto).","Mach einen runden Rücken zur Decke und zieh Kinn und Becken ein (Katze)."],
  ["Volvé despacio y arqueá suavemente la espalda, llevando el pecho adelante y la mirada apenas al frente (vaca).","Return slowly and gently arch your back, bringing your chest forward and your gaze slightly ahead (cow).","Volte devagar e arqueie suavemente as costas, levando o peito à frente e o olhar levemente para frente (vaca).","Reviens lentement et creuse doucement le dos, poitrine vers l’avant et regard légèrement devant (vache).","Torna lentamente e inarca dolcemente la schiena, portando il petto in avanti e lo sguardo appena avanti (mucca).","Komm langsam zurück, geh sanft ins Hohlkreuz, Brust nach vorn, Blick leicht nach vorn (Kuh)."],
  ["Alterná entre ambas posiciones de forma lenta y fluida, sin forzar ni sentir dolor.","Alternate between both positions slowly and smoothly, without forcing or feeling pain.","Alterne entre as duas posições de forma lenta e fluida, sem forçar nem sentir dor.","Alterne entre les deux positions lentement et de façon fluide, sans forcer ni ressentir de douleur.","Alterna tra le due posizioni in modo lento e fluido, senza forzare né sentire dolore.","Wechsle langsam und fließend zwischen beiden Positionen, ohne zu forcieren oder Schmerz zu spüren."],
  ["Mover solo el cuello sin movilizar la columna.","Moving only your neck without mobilizing your spine.","Mover só o pescoço sem mobilizar a coluna.","Bouger seulement la nuque sans mobiliser la colonne.","Muovere solo il collo senza mobilizzare la colonna.","Nur den Nacken bewegen, ohne die Wirbelsäule zu mobilisieren."],
  ["Arquear de forma exagerada la zona lumbar.","Arching your lower back excessively.","Arquear de forma exagerada a lombar.","Cambrer exagérément le bas du dos.","Inarcare in modo esagerato la zona lombare.","Übermäßig ins Hohlkreuz gehen."],
  ["Hacerlo rápido y con rebotes.","Doing it fast and bouncing.","Fazer rápido e com quiques.","Le faire vite et avec des rebonds.","Farlo veloce e con rimbalzi.","Es schnell und federnd ausführen."],
  ["Pensá en mover la columna vértebra por vértebra.","Think about moving your spine vertebra by vertebra.","Pense em mover a coluna vértebra por vértebra.","Pense à bouger la colonne vertèbre par vertèbre.","Pensa di muovere la colonna vertebra per vertebra.","Stell dir vor, du bewegst die Wirbelsäule Wirbel für Wirbel."],
  ["Usá un rango cómodo; no hace falta llegar al máximo.","Use a comfortable range; you don’t need to reach the maximum.","Use uma amplitude confortável; não é preciso chegar ao máximo.","Utilise une amplitude confortable ; inutile d’aller au maximum.","Usa un’ampiezza comoda; non serve arrivare al massimo.","Nutze einen angenehmen Bewegungsumfang; du musst nicht ans Maximum gehen."],
  ["Si las muñecas molestan, apoyá los puños o los antebrazos.","If your wrists bother you, rest on your fists or forearms.","Se os punhos incomodarem, apoie os punhos fechados ou os antebraços.","Si tes poignets te gênent, appuie-toi sur les poings ou les avant-bras.","Se i polsi danno fastidio, appoggia i pugni o gli avambracci.","Wenn die Handgelenke zwicken, stütz dich auf die Fäuste oder Unterarme."],
  ["Glúteo mayor, aductores y pantorrillas","Gluteus maximus, adductors and calves","Glúteo máximo, adutores e panturrilhas","Grand fessier, adducteurs et mollets","Grande gluteo, adduttori e polpacci","Großer Gesäßmuskel, Adduktoren und Waden"],
  ["Pared lisa y firme; calzado que no resbale","Smooth, solid wall; non-slip shoes","Parede lisa e firme; calçado que não escorregue","Mur lisse et solide ; chaussures antidérapantes","Parete liscia e stabile; scarpe che non scivolino","Glatte, feste Wand; rutschfeste Schuhe"],
  ["Apoyá la espalda contra una pared con los pies separados al ancho de cadera y unos 40–60 cm por delante.","Rest your back against a wall with your feet hip-width apart and about 40–60 cm in front of you.","Apoie as costas contra uma parede com os pés na largura do quadril e cerca de 40–60 cm à frente.","Appuie le dos contre un mur, pieds à la largeur des hanches et à environ 40–60 cm devant toi.","Appoggia la schiena contro una parete con i piedi alla larghezza delle anche e a circa 40–60 cm in avanti.","Lehn dich mit dem Rücken an eine Wand, Füße hüftbreit und etwa 40–60 cm davor."],
  ["Con la espalda apoyada, deslizate hacia abajo flexionando las rodillas hasta un ángulo cómodo, sin pasar de 90 grados.","With your back against the wall, slide down by bending your knees to a comfortable angle, no deeper than 90 degrees.","Com as costas apoiadas, deslize para baixo flexionando os joelhos até um ângulo confortável, sem passar de 90 graus.","Dos contre le mur, glisse vers le bas en fléchissant les genoux jusqu’à un angle confortable, sans dépasser 90 degrés.","Con la schiena appoggiata, scivola verso il basso piegando le ginocchia fino a un angolo comodo, senza superare i 90 gradi.","Rutsch mit dem Rücken an der Wand nach unten, bis die Knie einen angenehmen Winkel haben, höchstens 90 Grad."],
  ["Sostené la posición con las rodillas sobre los tobillos, alineadas con los pies, y la espalda apoyada.","Hold the position with your knees over your ankles, aligned with your feet, and your back against the wall.","Sustente a posição com os joelhos sobre os tornozelos, alinhados com os pés, e as costas apoiadas.","Tiens la position, genoux au-dessus des chevilles et alignés avec les pieds, dos contre le mur.","Mantieni la posizione con le ginocchia sopra le caviglie, allineate con i piedi, e la schiena appoggiata.","Halte die Position, Knie über den Sprunggelenken und in einer Linie mit den Füßen, Rücken an der Wand."],
  ["Mantené el peso repartido en toda la planta y respirá con calma.","Keep your weight spread over your whole foot and breathe calmly.","Mantenha o peso distribuído em toda a planta do pé e respire com calma.","Garde le poids réparti sur tout le pied et respire calmement.","Mantieni il peso distribuito su tutta la pianta e respira con calma.","Verteil das Gewicht auf den ganzen Fuß und atme ruhig."],
  ["Para salir, deslizate hacia arriba empujando con las piernas, o apoyá las manos en los muslos para ayudarte.","To come out, slide back up by pushing with your legs, or put your hands on your thighs to help.","Para sair, deslize para cima empurrando com as pernas, ou apoie as mãos nas coxas para ajudar.","Pour sortir, remonte en glissant et en poussant avec les jambes, ou pose les mains sur les cuisses pour t’aider.","Per uscire, scivola verso l’alto spingendo con le gambe, oppure appoggia le mani sulle cosce per aiutarti.","Zum Beenden rutsch mit Beinkraft wieder hoch oder stütz die Hände auf die Oberschenkel."],
  ["Colocar los pies demasiado cerca de la pared y llevar las rodillas por delante de los pies.","Placing your feet too close to the wall and letting your knees travel past your feet.","Colocar os pés muito perto da parede e levar os joelhos à frente dos pés.","Placer les pieds trop près du mur et faire dépasser les genoux devant les pieds.","Mettere i piedi troppo vicini alla parete e portare le ginocchia oltre i piedi.","Die Füße zu nah an die Wand stellen und die Knie über die Füße hinausschieben."],
  ["Apoyar las manos en los muslos para descargar el peso durante el sostén.","Resting your hands on your thighs to take weight off during the hold.","Apoiar as mãos nas coxas para descarregar o peso durante a sustentação.","Poser les mains sur les cuisses pour se soulager pendant le maintien.","Appoggiare le mani sulle cosce per scaricare il peso durante la tenuta.","Die Hände während des Haltens auf die Oberschenkel stützen, um Gewicht abzugeben."],
  ["Usar calzado o piso resbaladizo.","Using slippery shoes or flooring.","Usar calçado ou piso escorregadio.","Utiliser des chaussures ou un sol glissants.","Usare scarpe o pavimento scivolosi.","Rutschige Schuhe oder rutschigen Boden nutzen."],
  ["Un ángulo de rodilla más abierto (menos flexión) hace el ejercicio más fácil.","A more open knee angle (less bend) makes the exercise easier.","Um ângulo de joelho mais aberto (menos flexão) deixa o exercício mais fácil.","Un angle de genou plus ouvert (moins de flexion) rend l’exercice plus facile.","Un angolo del ginocchio più aperto (meno flessione) rende l’esercizio più facile.","Ein offenerer Kniewinkel (weniger Beugung) macht die Übung leichter."],
  ["Terminá cuando ya no puedas sostener la alineación.","Stop when you can no longer hold the alignment.","Termine quando já não conseguir sustentar o alinhamento.","Arrête quand tu ne peux plus tenir l’alignement.","Termina quando non riesci più a mantenere l’allineamento.","Hör auf, wenn du die Ausrichtung nicht mehr halten kannst."],
  ["Mantené la cabeza y los hombros apoyados en la pared.","Keep your head and shoulders against the wall.","Mantenha a cabeça e os ombros apoiados na parede.","Garde la tête et les épaules contre le mur.","Mantieni testa e spalle appoggiate alla parete.","Halte Kopf und Schultern an der Wand."],
  ["Cuádriceps, glúteo mayor y aductores","Quadriceps, gluteus maximus and adductors","Quadríceps, glúteo máximo e adutores","Quadriceps, grand fessier et adducteurs","Quadricipiti, grande gluteo e adduttori","Quadrizeps, großer Gesäßmuskel und Adduktoren"],
  ["Glúteo medio e isquiotibiales","Gluteus medius and hamstrings","Glúteo médio e isquiotibiais","Moyen fessier et ischio-jambiers","Medio gluteo e ischiocrurali","Mittlerer Gesäßmuskel und hintere Oberschenkel"],
  ["Peso corporal y un apoyo firme al frente (mesa estable, respaldo pesado o marco de puerta)","Bodyweight and a sturdy support in front of you (stable table, heavy chair back or door frame)","Peso corporal e um apoio firme à frente (mesa estável, encosto pesado ou batente de porta)","Poids du corps et un appui solide devant toi (table stable, dossier lourd ou cadre de porte)","Corpo libero e un appoggio stabile davanti (tavolo fermo, schienale pesante o telaio della porta)","Körpergewicht und eine feste Stütze vor dir (stabiler Tisch, schwere Stuhllehne oder Türrahmen)"],
  ["Parate frente a un apoyo firme, con las manos sobre él y los pies juntos.","Stand facing a sturdy support, hands on it and feet together.","Fique de frente para um apoio firme, com as mãos sobre ele e os pés juntos.","Tiens-toi face à un appui solide, mains posées dessus et pieds joints.","Mettiti di fronte a un appoggio stabile, con le mani sopra e i piedi uniti.","Stell dich vor eine feste Stütze, Hände darauf, Füße geschlossen."],
  ["Inhalá al bajar y exhalá al volver al centro.","Inhale as you lower and exhale as you return to the center.","Inspire ao descer e expire ao voltar ao centro.","Inspire en descendant et expire en revenant au centre.","Inspira scendendo ed espira tornando al centro.","Atme beim Absenken ein und beim Zurückkehren zur Mitte aus."],
  ["Dá un paso amplio hacia un costado con las puntas de los pies mirando al frente.","Take a wide step to the side with your toes pointing forward.","Dê um passo amplo para o lado com as pontas dos pés voltadas para frente.","Fais un grand pas sur le côté, pointes de pied vers l’avant.","Fai un ampio passo di lato con le punte dei piedi rivolte in avanti.","Mach einen weiten Schritt zur Seite, die Fußspitzen zeigen nach vorn."],
  ["Flexioná la rodilla del lado del paso llevando la cadera atrás, con la otra pierna extendida y ambos pies apoyados.","Bend the knee on the stepping side, pushing your hips back, with the other leg straight and both feet flat.","Flexione o joelho do lado do passo levando o quadril para trás, com a outra perna estendida e os dois pés apoiados.","Fléchis le genou du côté du pas en reculant les hanches, l’autre jambe tendue et les deux pieds à plat.","Piega il ginocchio dal lato del passo portando le anche indietro, con l’altra gamba distesa ed entrambi i piedi appoggiati.","Beuge das Knie auf der Schrittseite und schieb die Hüfte nach hinten, das andere Bein bleibt gestreckt, beide Füße am Boden."],
  ["Empujá con el pie que dio el paso para volver al centro.","Push through the foot that stepped out to return to the center.","Empurre com o pé que deu o passo para voltar ao centro.","Pousse sur le pied qui a fait le pas pour revenir au centre.","Spingi con il piede che ha fatto il passo per tornare al centro.","Drück dich über den Schrittfuß zurück zur Mitte."],
  ["Alterná lados o completá un lado y después el otro, usando las manos solo para el equilibrio.","Alternate sides or finish one side and then the other, using your hands only for balance.","Alterne os lados ou complete um lado e depois o outro, usando as mãos só para o equilíbrio.","Alterne les côtés ou termine un côté puis l’autre, en utilisant les mains seulement pour l’équilibre.","Alterna i lati o completa un lato e poi l’altro, usando le mani solo per l’equilibrio.","Wechsle die Seiten ab oder mach erst eine, dann die andere; die Hände dienen nur dem Gleichgewicht."],
  ["Dejar que la rodilla flexionada se cierre hacia adentro.","Letting the bent knee cave inward.","Deixar o joelho flexionado se fechar para dentro.","Laisser le genou fléchi rentrer vers l’intérieur.","Lasciare che il ginocchio piegato si chiuda verso l’interno.","Das gebeugte Knie nach innen fallen lassen."],
  ["Levantar el talón de la pierna que flexiona.","Lifting the heel of the bending leg.","Levantar o calcanhar da perna que flexiona.","Décoller le talon de la jambe qui fléchit.","Sollevare il tallone della gamba che si piega.","Die Ferse des gebeugten Beins anheben."],
  ["Apoyarse en una superficie que se puede deslizar.","Leaning on a surface that can slide.","Apoiar-se em uma superfície que pode deslizar.","S’appuyer sur une surface qui peut glisser.","Appoggiarsi a una superficie che può scivolare.","Sich auf eine Fläche stützen, die wegrutschen kann."],
  ["El apoyo reduce la demanda de equilibrio y permite concentrarte en la técnica, por eso es más fácil que la versión libre.","The support reduces the balance demand and lets you focus on technique, which is why it is easier than the free version.","O apoio reduz a exigência de equilíbrio e permite se concentrar na técnica, por isso é mais fácil que a versão livre.","L’appui réduit la demande d’équilibre et te permet de te concentrer sur la technique, c’est pourquoi c’est plus facile que la version libre.","L’appoggio riduce la richiesta di equilibrio e ti permette di concentrarti sulla tecnica, per questo è più facile della versione libera.","Die Stütze verringert die Gleichgewichtsanforderung und lässt dich auf die Technik konzentrieren; deshalb ist es leichter als die freie Variante."],
  ["Bajá solo hasta donde sientas un estiramiento cómodo en la cara interna del muslo.","Lower only as far as you feel a comfortable stretch on your inner thigh.","Desça só até sentir um alongamento confortável na parte interna da coxa.","Descends seulement jusqu’à sentir un étirement confortable à l’intérieur de la cuisse.","Scendi solo fin dove senti un allungamento comodo nell’interno coscia.","Geh nur so tief, bis du eine angenehme Dehnung an der Oberschenkelinnenseite spürst."],
  ["Mantené el pecho abierto y la espalda recta.","Keep your chest open and your back straight.","Mantenha o peito aberto e as costas retas.","Garde la poitrine ouverte et le dos droit.","Mantieni il petto aperto e la schiena dritta.","Halte die Brust offen und den Rücken gerade."],
  ["Isquiotibiales, transverso del abdomen y oblicuos","Hamstrings, transversus abdominis and obliques","Isquiotibiais, transverso do abdômen e oblíquos","Ischio-jambiers, transverse de l’abdomen et obliques","Ischiocrurali, trasverso dell’addome e obliqui","Hintere Oberschenkel, querer Bauchmuskel und schräge Bauchmuskeln"],
  ["Acostate boca arriba con las rodillas flexionadas, pies apoyados al ancho de cadera y brazos a los costados.","Lie on your back with your knees bent, feet flat hip-width apart and arms at your sides.","Deite-se de barriga para cima com os joelhos flexionados, pés apoiados na largura do quadril e braços ao lado do corpo.","Allonge-toi sur le dos, genoux fléchis, pieds à plat à la largeur des hanches et bras le long du corps.","Sdraiati a pancia in su con le ginocchia piegate, piedi appoggiati alla larghezza delle anche e braccia lungo i fianchi.","Leg dich auf den Rücken, Knie gebeugt, Füße hüftbreit aufgestellt, Arme seitlich."],
  ["Respirá de forma pareja, exhalando en cada elevación de pie.","Breathe evenly, exhaling each time you lift a foot.","Respire de forma regular, expirando a cada elevação do pé.","Respire régulièrement en expirant à chaque levée de pied.","Respira in modo regolare, espirando a ogni sollevamento del piede.","Atme gleichmäßig und bei jedem Anheben des Fußes aus."],
  ["Empujá con los talones y elevá la cadera hasta formar una línea de hombros a rodillas.","Push through your heels and lift your hips until you form a line from shoulders to knees.","Empurre com os calcanhares e eleve o quadril até formar uma linha dos ombros aos joelhos.","Pousse sur les talons et monte les hanches jusqu’à former une ligne des épaules aux genoux.","Spingi con i talloni e solleva le anche fino a formare una linea dalle spalle alle ginocchia.","Drück über die Fersen und heb die Hüfte, bis eine Linie von den Schultern bis zu den Knien entsteht."],
  ["Con la cadera arriba, levantá un pie unos centímetros del suelo sin dejar caer la pelvis.","With your hips up, lift one foot a few centimeters off the floor without letting your pelvis drop.","Com o quadril em cima, levante um pé alguns centímetros do chão sem deixar a pelve cair.","Hanches en haut, lève un pied de quelques centimètres sans laisser tomber le bassin.","Con le anche in alto, solleva un piede di qualche centimetro da terra senza far cadere il bacino.","Heb mit oben gehaltener Hüfte einen Fuß ein paar Zentimeter vom Boden, ohne das Becken absinken zu lassen."],
  ["Apoyá ese pie y levantá el otro, alternando como una marcha lenta.","Set that foot down and lift the other, alternating like a slow march.","Apoie esse pé e levante o outro, alternando como uma marcha lenta.","Repose ce pied et lève l’autre, en alternant comme une marche lente.","Appoggia quel piede e solleva l’altro, alternando come una marcia lenta.","Setz den Fuß ab und heb den anderen, im Wechsel wie ein langsamer Marsch."],
  ["Al terminar las repeticiones, bajá la cadera despacio al suelo.","When you finish the reps, lower your hips slowly to the floor.","Ao terminar as repetições, abaixe o quadril devagar até o chão.","Après les répétitions, redescends lentement les hanches au sol.","Finite le ripetizioni, abbassa lentamente le anche a terra.","Senk nach den Wiederholungen die Hüfte langsam zum Boden ab."],
  ["Dejar que la cadera caiga o gire hacia el lado del pie que se levanta.","Letting your hips drop or rotate toward the side of the lifted foot.","Deixar o quadril cair ou girar para o lado do pé que se levanta.","Laisser les hanches tomber ou pivoter du côté du pied levé.","Lasciare che le anche cadano o ruotino verso il lato del piede sollevato.","Die Hüfte absinken oder zur Seite des angehobenen Fußes kippen lassen."],
  ["Arquear la zona lumbar para mantener la altura.","Arching your lower back to keep the height.","Arquear a lombar para manter a altura.","Cambrer le bas du dos pour garder la hauteur.","Inarcare la zona lombare per mantenere l’altezza.","Ins Hohlkreuz gehen, um die Höhe zu halten."],
  ["Hacer la marcha rápida y sin control.","Marching fast and without control.","Fazer a marcha rápida e sem controle.","Faire la marche rapidement et sans contrôle.","Fare la marcia veloce e senza controllo.","Schnell und unkontrolliert marschieren."],
  ["Si la cadera baja, reducí la altura del pie que se eleva.","If your hips drop, lower the height of the lifted foot.","Se o quadril cair, reduza a altura do pé que se eleva.","Si les hanches descendent, réduis la hauteur du pied levé.","Se le anche scendono, riduci l’altezza del piede sollevato.","Wenn die Hüfte absinkt, heb den Fuß weniger hoch."],
  ["Mantené las caderas niveladas, como si tuvieras una barra apoyada sobre ellas.","Keep your hips level, as if a bar were resting on them.","Mantenha o quadril nivelado, como se houvesse uma barra apoiada sobre ele.","Garde les hanches à niveau, comme si une barre reposait dessus.","Mantieni le anche in piano, come se avessi una barra appoggiata sopra.","Halte die Hüfte waagerecht, als läge eine Stange darauf."],
  ["Dominá el puente de glúteos antes de esta variante.","Master the glute bridge before this variation.","Domine a ponte de glúteos antes desta variação.","Maîtrise le pont fessier avant cette variante.","Padroneggia il ponte per i glutei prima di questa variante.","Beherrsch die Glute Bridge, bevor du diese Variante machst."],
  ["Isquiotibiales, glúteo medio y estabilizadores del tronco","Hamstrings, gluteus medius and trunk stabilizers","Isquiotibiais, glúteo médio e estabilizadores do tronco","Ischio-jambiers, moyen fessier et stabilisateurs du tronc","Ischiocrurali, medio gluteo e stabilizzatori del tronco","Hintere Oberschenkel, mittlerer Gesäßmuskel und Rumpfstabilisatoren"],
  ["Acostate boca arriba con las rodillas flexionadas, pies apoyados y brazos a los costados con las palmas en el suelo.","Lie on your back with your knees bent, feet flat and arms at your sides with palms on the floor.","Deite-se de barriga para cima com os joelhos flexionados, pés apoiados e braços ao lado do corpo com as palmas no chão.","Allonge-toi sur le dos, genoux fléchis, pieds à plat et bras le long du corps, paumes au sol.","Sdraiati a pancia in su con le ginocchia piegate, piedi appoggiati e braccia lungo i fianchi con i palmi a terra.","Leg dich auf den Rücken, Knie gebeugt, Füße aufgestellt, Arme seitlich, Handflächen am Boden."],
  ["Apoyá firme un pie y dejá el otro apenas apoyado sobre el talón para que asista.","Plant one foot firmly and leave the other lightly resting on its heel so it can assist.","Apoie firme um pé e deixe o outro levemente apoiado no calcanhar para ajudar.","Ancre bien un pied et laisse l’autre légèrement posé sur le talon pour qu’il t’aide.","Pianta bene un piede e lascia l’altro appena appoggiato sul tallone perché ti assista.","Setz einen Fuß fest auf und lass den anderen nur leicht auf der Ferse stehen, damit er unterstützt."],
  ["Empujá principalmente con el pie de trabajo y elevá la cadera hasta alinear hombros, cadera y rodilla.","Push mainly through your working foot and lift your hips until your shoulders, hips and knee are aligned.","Empurre principalmente com o pé de trabalho e eleve o quadril até alinhar ombros, quadril e joelho.","Pousse principalement sur le pied de travail et monte les hanches jusqu’à aligner épaules, hanches et genou.","Spingi soprattutto con il piede di lavoro e solleva le anche fino ad allineare spalle, anche e ginocchio.","Drück hauptsächlich über den Arbeitsfuß und heb die Hüfte, bis Schultern, Hüfte und Knie in einer Linie sind."],
  ["Pausá un instante arriba sin girar la pelvis.","Pause for a moment at the top without rotating your pelvis.","Pause um instante em cima sem girar a pelve.","Marque une courte pause en haut sans faire pivoter le bassin.","Fai una breve pausa in alto senza ruotare il bacino.","Halte oben kurz, ohne das Becken zu drehen."],
  ["Cargar todo el peso en el pie asistente.","Putting all your weight on the assisting foot.","Colocar todo o peso no pé que ajuda.","Mettre tout le poids sur le pied d’aide.","Caricare tutto il peso sul piede di assistenza.","Das ganze Gewicht auf den Hilfsfuß legen."],
  ["Dejar que la cadera se incline hacia un costado.","Letting your hips tilt to one side.","Deixar o quadril se inclinar para um lado.","Laisser les hanches pencher d’un côté.","Lasciare che le anche si inclinino da un lato.","Die Hüfte zur Seite kippen lassen."],
  ["Arquear la espalda arriba.","Arching your back at the top.","Arquear as costas em cima.","Cambrer le dos en haut.","Inarcare la schiena in alto.","Oben ins Hohlkreuz gehen."],
  ["El pie asistente da estabilidad y reduce la carga, por eso es un paso intermedio hacia el puente a una pierna completo.","The assisting foot adds stability and reduces the load, which makes it an intermediate step toward the full single-leg bridge.","O pé que ajuda dá estabilidade e reduz a carga, por isso é um passo intermediário para a ponte unilateral completa.","Le pied d’aide apporte de la stabilité et réduit la charge, c’est donc une étape intermédiaire vers le pont sur une jambe complet.","Il piede di assistenza dà stabilità e riduce il carico, per questo è un passo intermedio verso il ponte a una gamba completo.","Der Hilfsfuß gibt Stabilität und verringert die Last; so ist es eine Zwischenstufe zur vollen einbeinigen Brücke."],
  ["Usá los brazos apoyados para mantener el equilibrio.","Use your arms on the floor to keep your balance.","Use os braços apoiados para manter o equilíbrio.","Utilise les bras au sol pour garder l’équilibre.","Usa le braccia appoggiate per mantenere l’equilibrio.","Nutze die aufgelegten Arme, um das Gleichgewicht zu halten."],
  ["Con el tiempo, apoyá cada vez menos el pie asistente.","Over time, rely less and less on the assisting foot.","Com o tempo, apoie cada vez menos o pé que ajuda.","Avec le temps, appuie-toi de moins en moins sur le pied d’aide.","Col tempo, appoggia sempre meno il piede di assistenza.","Belaste den Hilfsfuß mit der Zeit immer weniger."],
  ["Pared firme y piso que no resbale","Sturdy wall and a non-slip floor","Parede firme e piso que não escorregue","Mur solide et sol antidérapant","Parete stabile e pavimento che non scivoli","Feste Wand und rutschfester Boden"],
  ["Parate frente a una pared a un paso de distancia, con las manos apoyadas a la altura del pecho y algo más abiertas que los hombros.","Stand facing a wall one step away, with your hands on it at chest height and slightly wider than your shoulders.","Fique de frente para uma parede a um passo de distância, com as mãos apoiadas na altura do peito e um pouco mais abertas que os ombros.","Tiens-toi face à un mur, à un pas de distance, mains posées à hauteur de poitrine et un peu plus écartées que les épaules.","Mettiti di fronte a una parete a un passo di distanza, con le mani appoggiate all’altezza del petto e poco più larghe delle spalle.","Stell dich einen Schritt vor eine Wand, Hände auf Brusthöhe etwas breiter als schulterbreit daran."],
  ["Inhalá al acercarte a la pared y exhalá al empujar.","Inhale as you move toward the wall and exhale as you push.","Inspire ao se aproximar da parede e expire ao empurrar.","Inspire en te rapprochant du mur et expire en poussant.","Inspira avvicinandoti alla parete ed espira spingendo.","Atme beim Annähern an die Wand ein und beim Wegdrücken aus."],
  ["Apoyá las manos en la pared y alejá los pies hasta quedar levemente inclinado, con el cuerpo en línea recta.","Place your hands on the wall and step your feet back until you are leaning slightly, body in a straight line.","Apoie as mãos na parede e afaste os pés até ficar levemente inclinado, com o corpo em linha reta.","Pose les mains sur le mur et recule les pieds jusqu’à être légèrement incliné, corps aligné.","Appoggia le mani alla parete e allontana i piedi fino a essere leggermente inclinato, con il corpo in linea retta.","Leg die Hände an die Wand und geh mit den Füßen zurück, bis du leicht geneigt bist, Körper in einer geraden Linie."],
  ["Flexioná los codos en diagonal hacia atrás y acercá el pecho a la pared.","Bend your elbows diagonally back and bring your chest toward the wall.","Flexione os cotovelos na diagonal para trás e aproxime o peito da parede.","Fléchis les coudes en diagonale vers l’arrière et rapproche la poitrine du mur.","Piega i gomiti in diagonale all’indietro e avvicina il petto alla parete.","Beuge die Ellbogen schräg nach hinten und bring die Brust zur Wand."],
  ["Mantené talones, cadera y cabeza alineados.","Keep your heels, hips and head aligned.","Mantenha calcanhares, quadril e cabeça alinhados.","Garde les talons, les hanches et la tête alignés.","Mantieni talloni, anche e testa allineati.","Halte Fersen, Hüfte und Kopf in einer Linie."],
  ["Empujá la pared hasta extender los brazos.","Push the wall away until your arms are extended.","Empurre a parede até estender os braços.","Pousse le mur jusqu’à tendre les bras.","Spingi la parete fino a distendere le braccia.","Drück dich von der Wand weg, bis die Arme gestreckt sind."],
  ["Doblar la cadera y dejarla atrás.","Bending at the hips and leaving them behind.","Dobrar o quadril e deixá-lo para trás.","Plier les hanches et les laisser en arrière.","Piegare le anche e lasciarle indietro.","In der Hüfte abknicken und sie hinten lassen."],
  ["Ponerse sobre un piso resbaladizo con medias.","Standing on a slippery floor in socks.","Ficar em um piso escorregadio de meias.","Se mettre en chaussettes sur un sol glissant.","Stare su un pavimento scivoloso con i calzini.","Mit Socken auf rutschigem Boden stehen."],
  ["Al estar casi de pie, movés una parte pequeña de tu peso, por eso es más fácil que otras flexiones; la pared no se desliza y da un apoyo seguro.","Since you are almost upright, you move a small part of your weight, which is why it is easier than other push-ups; the wall doesn’t slide and gives secure support.","Como você fica quase em pé, move uma parte pequena do seu peso, por isso é mais fácil que outras flexões; a parede não desliza e dá um apoio seguro.","Comme tu es presque debout, tu déplaces une petite partie de ton poids, c’est pourquoi c’est plus facile que d’autres pompes ; le mur ne glisse pas et offre un appui sûr.","Stando quasi in piedi sposti una piccola parte del tuo peso, per questo è più facile di altri piegamenti; la parete non scivola e dà un appoggio sicuro.","Da du fast aufrecht stehst, bewegst du nur einen kleinen Teil deines Gewichts; deshalb ist es leichter als andere Liegestütze, und die Wand rutscht nicht weg."],
  ["Alejar los pies aumenta la dificultad.","Moving your feet farther back increases the difficulty.","Afastar mais os pés aumenta a dificuldade.","Reculer davantage les pieds augmente la difficulté.","Allontanare di più i piedi aumenta la difficoltà.","Je weiter die Füße zurückstehen, desto schwerer wird es."],
  ["Cuando te resulte fácil, pasá a una mesa firme.","When it feels easy, move on to a sturdy table.","Quando ficar fácil, passe para uma mesa firme.","Quand ça devient facile, passe à une table solide.","Quando ti risulta facile, passa a un tavolo stabile.","Wenn es dir leichtfällt, wechsle zu einem stabilen Tisch."],
  ["Apoyá las rodillas en la colchoneta y las manos juntas bajo el pecho formando un rombo, con el cuerpo alineado de rodillas a cabeza.","Rest your knees on the mat and your hands together under your chest forming a diamond, body aligned from knees to head.","Apoie os joelhos no colchonete e as mãos juntas sob o peito formando um losango, com o corpo alinhado dos joelhos à cabeça.","Pose les genoux sur le tapis et les mains rapprochées sous la poitrine en losange, corps aligné des genoux à la tête.","Appoggia le ginocchia sul tappetino e le mani unite sotto il petto a formare un rombo, con il corpo allineato dalle ginocchia alla testa.","Setz die Knie auf die Matte und die Hände als Raute unter der Brust zusammen, Körper von den Knien bis zum Kopf in einer Linie."],
  ["Juntá las manos bajo el esternón y ubicá las rodillas detrás de la cadera para que el tronco quede recto.","Bring your hands together under your breastbone and place your knees behind your hips so your torso stays straight.","Junte as mãos sob o esterno e posicione os joelhos atrás do quadril para o tronco ficar reto.","Rapproche les mains sous le sternum et place les genoux derrière les hanches pour que le buste reste droit.","Unisci le mani sotto lo sterno e posiziona le ginocchia dietro le anche perché il busto resti dritto.","Bring die Hände unter dem Brustbein zusammen und setz die Knie hinter die Hüfte, damit der Oberkörper gerade bleibt."],
  ["Mantené la cadera alineada, sin dejarla atrás.","Keep your hips in line, without leaving them behind.","Mantenha o quadril alinhado, sem deixá-lo para trás.","Garde les hanches alignées, sans les laisser en arrière.","Mantieni le anche allineate, senza lasciarle indietro.","Halte die Hüfte in der Linie, ohne sie hinten zu lassen."],
  ["Dejar la cadera atrás en cuadrupedia.","Leaving your hips back in an all-fours position.","Deixar o quadril para trás em quatro apoios.","Laisser les hanches en arrière à quatre pattes.","Lasciare le anche indietro a quattro zampe.","Die Hüfte hinten im Vierfüßlerstand lassen."],
  ["Apoyar las rodillas sobre un piso duro sin protección.","Resting your knees on a hard floor without protection.","Apoiar os joelhos em piso duro sem proteção.","Poser les genoux sur un sol dur sans protection.","Appoggiare le ginocchia su un pavimento duro senza protezione.","Die Knie ohne Polster auf harten Boden setzen."],
  ["Apoyar las rodillas reduce la carga, por eso es más fácil que la flexión diamante completa.","Resting on your knees reduces the load, which is why it is easier than the full diamond push-up.","Apoiar os joelhos reduz a carga, por isso é mais fácil que a flexão diamante completa.","Poser les genoux réduit la charge, c’est pourquoi c’est plus facile que la pompe diamant complète.","Appoggiare le ginocchia riduce il carico, per questo è più facile del piegamento a diamante completo.","Die Knie aufzusetzen verringert die Last; deshalb ist es leichter als der volle Diamant-Liegestütz."],
  ["Pasá a la versión completa cuando completes las repeticiones con buena forma.","Move on to the full version once you complete the reps with good form.","Passe para a versão completa quando completar as repetições com boa forma.","Passe à la version complète quand tu réussis les répétitions avec une bonne forme.","Passa alla versione completa quando completi le ripetizioni con una buona forma.","Wechsle zur vollen Variante, sobald du die Wiederholungen sauber schaffst."],
  ["Deltoides anterior y pectoral mayor","Front deltoid and pectoralis major","Deltoide anterior e peitoral maior","Deltoïde antérieur et grand pectoral","Deltoide anteriore e grande pettorale","Vorderer Deltamuskel und großer Brustmuskel"],
  ["Silla firme sin ruedas, apoyada contra una pared","Sturdy chair without wheels, set against a wall","Cadeira firme sem rodinhas, encostada em uma parede","Chaise solide sans roulettes, calée contre un mur","Sedia stabile senza ruote, appoggiata a una parete","Stabiler Stuhl ohne Rollen, an eine Wand gestellt"],
  ["Principiante-intermedio; evitar si el hombro molesta en la parte baja","Beginner–intermediate; avoid if your shoulder hurts at the bottom","Iniciante-intermediário; evite se o ombro incomodar na parte baixa","Débutant-intermédiaire ; à éviter si l’épaule te gêne en bas du mouvement","Principiante-intermedio; evitalo se la spalla dà fastidio nella parte bassa","Anfänger bis Fortgeschrittene; vermeiden, wenn die Schulter unten zwickt"],
  ["Sentate en el borde de la silla con las manos apoyadas junto a la cadera, dedos hacia adelante, y deslizá la cadera fuera del asiento.","Sit on the edge of the chair with your hands next to your hips, fingers forward, and slide your hips off the seat.","Sente-se na borda da cadeira com as mãos apoiadas ao lado do quadril, dedos para frente, e deslize o quadril para fora do assento.","Assieds-toi au bord de la chaise, mains à côté des hanches, doigts vers l’avant, et fais glisser les hanches hors de l’assise.","Siediti sul bordo della sedia con le mani appoggiate accanto alle anche, dita in avanti, e fai scivolare le anche fuori dal sedile.","Setz dich auf die Stuhlkante, Hände neben der Hüfte, Finger nach vorn, und schieb die Hüfte vom Sitz."],
  ["Apoyá la silla contra una pared para que no pueda deslizarse y colocá los pies en el suelo con las rodillas flexionadas.","Set the chair against a wall so it can’t slide and place your feet on the floor with your knees bent.","Encoste a cadeira em uma parede para ela não deslizar e coloque os pés no chão com os joelhos flexionados.","Cale la chaise contre un mur pour qu’elle ne glisse pas et pose les pieds au sol, genoux fléchis.","Appoggia la sedia a una parete perché non scivoli e metti i piedi a terra con le ginocchia piegate.","Stell den Stuhl an eine Wand, damit er nicht rutscht, und setz die Füße mit gebeugten Knien auf den Boden."],
  ["Flexioná los codos hacia atrás bajando la cadera cerca de la silla, hasta un rango cómodo para el hombro.","Bend your elbows back, lowering your hips close to the chair to a range that is comfortable for your shoulder.","Flexione os cotovelos para trás abaixando o quadril perto da cadeira, até uma amplitude confortável para o ombro.","Fléchis les coudes vers l’arrière en descendant les hanches près de la chaise, jusqu’à une amplitude confortable pour l’épaule.","Piega i gomiti all’indietro abbassando le anche vicino alla sedia, fino a un’ampiezza comoda per la spalla.","Beuge die Ellbogen nach hinten und senk die Hüfte nah am Stuhl ab, so weit es für die Schulter angenehm ist."],
  ["Empujá con las palmas para extender los codos y subir.","Push through your palms to extend your elbows and rise.","Empurre com as palmas para estender os cotovelos e subir.","Pousse avec les paumes pour tendre les coudes et remonter.","Spingi con i palmi per distendere i gomiti e salire.","Drück dich über die Handflächen hoch und streck die Ellbogen."],
  ["Al terminar, volvé a sentarte en la silla antes de soltar las manos.","When you finish, sit back on the chair before letting go with your hands.","Ao terminar, volte a se sentar na cadeira antes de soltar as mãos.","À la fin, rassieds-toi sur la chaise avant de lâcher les mains.","Alla fine, torna a sederti sulla sedia prima di lasciare le mani.","Setz dich am Ende wieder auf den Stuhl, bevor du die Hände löst."],
  ["Usar una silla con ruedas o que se mueve.","Using a chair with wheels or one that moves.","Usar uma cadeira com rodinhas ou que se move.","Utiliser une chaise à roulettes ou qui bouge.","Usare una sedia con ruote o che si muove.","Einen Stuhl mit Rollen oder einen wackligen Stuhl nutzen."],
  ["Bajar tanto que el hombro se adelanta y molesta.","Going so low that your shoulder rolls forward and hurts.","Descer tanto que o ombro avança e incomoda.","Descendre si bas que l’épaule part vers l’avant et fait mal.","Scendere così tanto che la spalla va in avanti e dà fastidio.","So tief gehen, dass die Schulter nach vorn kippt und schmerzt."],
  ["Con rodillas flexionadas es más fácil; con piernas extendidas, más difícil.","With your knees bent it is easier; with your legs straight, harder.","Com os joelhos flexionados é mais fácil; com as pernas estendidas, mais difícil.","Genoux fléchis, c’est plus facile ; jambes tendues, plus difficile.","Con le ginocchia piegate è più facile; con le gambe distese, più difficile.","Mit gebeugten Knien ist es leichter, mit gestreckten Beinen schwerer."],
  ["Mantené la espalda cerca de la silla.","Keep your back close to the chair.","Mantenha as costas perto da cadeira.","Garde le dos près de la chaise.","Mantieni la schiena vicina alla sedia.","Halte den Rücken nah am Stuhl."],
  ["Detené la bajada antes de que aparezca molestia en el frente del hombro.","Stop the descent before you feel discomfort at the front of your shoulder.","Pare a descida antes de surgir incômodo na frente do ombro.","Arrête la descente avant de ressentir une gêne à l’avant de l’épaule.","Ferma la discesa prima che compaia fastidio nella parte anteriore della spalla.","Stopp das Absenken, bevor vorn in der Schulter Beschwerden auftreten."],
  ["Bíceps, deltoides posterior y agarre","Biceps, rear deltoid and grip","Bíceps, deltoide posterior e pegada","Biceps, deltoïde postérieur et préhension","Bicipiti, deltoide posteriore e presa","Bizeps, hinterer Deltamuskel und Griffkraft"],
  ["Toalla resistente pasada alrededor de un poste o columna firme, o bajo los pies","Sturdy towel looped around a solid post or column, or under your feet","Toalha resistente passada em volta de um poste ou coluna firme, ou sob os pés","Serviette résistante passée autour d’un poteau ou d’une colonne solide, ou sous les pieds","Asciugamano resistente passato attorno a un palo o a una colonna stabile, oppure sotto i piedi","Reißfestes Handtuch um einen festen Pfosten oder eine Säule gelegt oder unter den Füßen"],
  ["Parate o sentate con la toalla pasada alrededor de un punto fijo firme, tomando un extremo con cada mano y los codos flexionados.","Stand or sit with the towel looped around a solid fixed point, holding one end in each hand with your elbows bent.","Fique em pé ou sente-se com a toalha passada em volta de um ponto fixo firme, segurando uma ponta em cada mão com os cotovelos flexionados.","Tiens-toi debout ou assieds-toi, la serviette passée autour d’un point fixe solide, une extrémité dans chaque main, coudes fléchis.","Stai in piedi o siediti con l’asciugamano passato attorno a un punto fisso stabile, tenendo un’estremità per mano con i gomiti piegati.","Steh oder sitz mit dem Handtuch um einen festen Fixpunkt, je ein Ende in einer Hand, Ellbogen gebeugt."],
  ["Pasá la toalla alrededor de un poste, columna o baranda que no se mueva, o sentate con la toalla bajo los pies.","Loop the towel around a post, column or railing that won’t move, or sit with the towel under your feet.","Passe a toalha em volta de um poste, coluna ou corrimão que não se mova, ou sente-se com a toalha sob os pés.","Passe la serviette autour d’un poteau, d’une colonne ou d’une rampe qui ne bouge pas, ou assieds-toi avec la serviette sous les pieds.","Passa l’asciugamano attorno a un palo, una colonna o un corrimano che non si muova, oppure siediti con l’asciugamano sotto i piedi.","Leg das Handtuch um einen Pfosten, eine Säule oder ein Geländer, das sich nicht bewegt, oder setz dich mit dem Handtuch unter den Füßen hin."],
  ["Tirá de los extremos llevando los codos atrás y juntando las escápulas, hasta generar tensión sin moverte.","Pull the ends, driving your elbows back and squeezing your shoulder blades, until you create tension without moving.","Puxe as pontas levando os cotovelos para trás e juntando as escápulas, até gerar tensão sem se mover.","Tire les extrémités en amenant les coudes vers l’arrière et en serrant les omoplates, jusqu’à créer de la tension sans bouger.","Tira le estremità portando i gomiti indietro e stringendo le scapole, fino a creare tensione senza muoverti.","Zieh an den Enden, Ellbogen nach hinten, Schulterblätter zusammen, bis Spannung entsteht, ohne dass du dich bewegst."],
  ["Sostené la contracción con los hombros bajos y el tronco erguido, respirando con calma.","Hold the contraction with your shoulders down and your torso upright, breathing calmly.","Sustente a contração com os ombros baixos e o tronco ereto, respirando com calma.","Maintiens la contraction, épaules basses et buste droit, en respirant calmement.","Mantieni la contrazione con le spalle basse e il busto eretto, respirando con calma.","Halte die Spannung mit tiefen Schultern und aufrechtem Oberkörper und atme ruhig."],
  ["Soltá la tensión de forma gradual, sin soltar la toalla de golpe.","Release the tension gradually, without letting go of the towel suddenly.","Solte a tensão de forma gradual, sem largar a toalha de uma vez.","Relâche la tension progressivement, sans lâcher la serviette d’un coup.","Rilascia la tensione gradualmente, senza mollare l’asciugamano di colpo.","Lass die Spannung allmählich nach, ohne das Handtuch abrupt loszulassen."],
  ["Usar un punto de anclaje que puede moverse o romperse.","Using an anchor point that can move or break.","Usar um ponto de ancoragem que pode se mover ou quebrar.","Utiliser un point d’ancrage qui peut bouger ou casser.","Usare un punto di ancoraggio che può muoversi o rompersi.","Einen Ankerpunkt nutzen, der sich bewegen oder brechen kann."],
  ["Inclinarse hacia atrás con todo el peso: si la toalla se suelta, podés caer.","Leaning back with your full weight: if the towel slips, you could fall.","Inclinar-se para trás com todo o peso: se a toalha soltar, você pode cair.","Se pencher en arrière de tout son poids : si la serviette lâche, tu peux tomber.","Inclinarsi indietro con tutto il peso: se l’asciugamano si sfila, puoi cadere.","Sich mit vollem Gewicht nach hinten lehnen: Wenn das Handtuch nachgibt, kannst du fallen."],
  ["La fuerza la regulás vos: empezá con tensión moderada.","You control the force: start with moderate tension.","Você regula a força: comece com tensão moderada.","C’est toi qui doses la force : commence avec une tension modérée.","La forza la regoli tu: inizia con una tensione moderata.","Du bestimmst die Kraft: Beginne mit mäßiger Spannung."],
  ["Revisá que la toalla no esté rasgada.","Check that the towel isn’t torn.","Verifique se a toalha não está rasgada.","Vérifie que la serviette n’est pas déchirée.","Controlla che l’asciugamano non sia strappato.","Prüf, dass das Handtuch nicht eingerissen ist."],
  ["Pensá en llevar los codos hacia los bolsillos de atrás.","Think about driving your elbows toward your back pockets.","Pense em levar os cotovelos em direção aos bolsos de trás.","Pense à amener les coudes vers tes poches arrière.","Pensa di portare i gomiti verso le tasche posteriori.","Stell dir vor, du ziehst die Ellbogen zu den Gesäßtaschen."],
  ["Glúteo mayor, isquiotibiales y deltoides posterior","Gluteus maximus, hamstrings and rear deltoid","Glúteo máximo, isquiotibiais e deltoide posterior","Grand fessier, ischio-jambiers et deltoïde postérieur","Grande gluteo, ischiocrurali e deltoide posteriore","Großer Gesäßmuskel, hintere Oberschenkel und hinterer Deltamuskel"],
  ["Acostate boca abajo con los brazos extendidos al frente y las piernas extendidas, con el cuello neutro.","Lie face down with your arms extended in front and your legs extended, neck neutral.","Deite-se de bruços com os braços estendidos à frente e as pernas estendidas, com o pescoço neutro.","Allonge-toi sur le ventre, bras tendus devant et jambes tendues, nuque neutre.","Sdraiati a pancia in giù con le braccia distese in avanti e le gambe distese, con il collo neutro.","Leg dich bäuchlings hin, Arme nach vorn gestreckt, Beine gestreckt, Nacken neutral."],
  ["Afirmá abdomen y glúteos antes de moverte.","Brace your abs and glutes before you move.","Firme abdômen e glúteos antes de se mover.","Gaine les abdos et les fessiers avant de bouger.","Contrai addome e glutei prima di muoverti.","Spann Bauch und Gesäß an, bevor du dich bewegst."],
  ["Elevá a la vez brazos, pecho y piernas unos centímetros del suelo, mirando hacia abajo.","Lift your arms, chest and legs a few centimeters off the floor at the same time, looking down.","Eleve ao mesmo tempo braços, peito e pernas alguns centímetros do chão, olhando para baixo.","Lève en même temps les bras, la poitrine et les jambes de quelques centimètres, en regardant vers le bas.","Solleva insieme braccia, petto e gambe di qualche centimetro da terra, guardando in basso.","Heb Arme, Brust und Beine gleichzeitig ein paar Zentimeter vom Boden und schau nach unten."],
  ["Sostené la posición estirándote hacia adelante y atrás, respirando con calma.","Hold the position, lengthening forward and back, breathing calmly.","Sustente a posição se alongando para frente e para trás, respirando com calma.","Tiens la position en t’allongeant vers l’avant et l’arrière, en respirant calmement.","Mantieni la posizione allungandoti in avanti e indietro, respirando con calma.","Halte die Position, mach dich nach vorn und hinten lang und atme ruhig."],
  ["Bajá despacio brazos y piernas al suelo para terminar.","Slowly lower your arms and legs to the floor to finish.","Abaixe devagar braços e pernas até o chão para terminar.","Redescends lentement bras et jambes au sol pour finir.","Abbassa lentamente braccia e gambe a terra per finire.","Senk zum Abschluss Arme und Beine langsam auf den Boden."],
  ["Levantar la cabeza y comprimir el cuello.","Lifting your head and compressing your neck.","Levantar a cabeça e comprimir o pescoço.","Relever la tête et comprimer la nuque.","Sollevare la testa e comprimere il collo.","Den Kopf heben und den Nacken stauchen."],
  ["Subir de más y arquear con fuerza la zona lumbar.","Lifting too high and arching your lower back hard.","Subir demais e arquear com força a lombar.","Monter trop haut et cambrer fortement le bas du dos.","Salire troppo e inarcare con forza la zona lombare.","Zu hoch heben und stark ins Hohlkreuz gehen."],
  ["Contener la respiración.","Holding your breath.","Prender a respiração.","Retenir sa respiration.","Trattenere il respiro.","Die Luft anhalten."],
  ["Si cuesta, elevá solo los brazos o solo las piernas.","If it is hard, lift only your arms or only your legs.","Se for difícil, eleve só os braços ou só as pernas.","Si c’est difficile, lève seulement les bras ou seulement les jambes.","Se è difficile, solleva solo le braccia o solo le gambe.","Wenn es schwerfällt, heb nur die Arme oder nur die Beine."],
  ["Terminá cuando ya no puedas sostener la posición sin tensar el cuello.","Stop when you can no longer hold the position without straining your neck.","Termine quando já não conseguir sustentar a posição sem tensionar o pescoço.","Arrête quand tu ne peux plus tenir la position sans crisper la nuque.","Termina quando non riesci più a mantenere la posizione senza tendere il collo.","Hör auf, wenn du die Position nicht mehr ohne Nackenspannung halten kannst."],
  ["Trapecio inferior y medio","Lower and middle trapezius","Trapézio inferior e médio","Trapèze inférieur et moyen","Trapezio inferiore e medio","Unterer und mittlerer Trapezmuskel"],
  ["Deltoides posterior, romboides y erectores espinales","Rear deltoid, rhomboids and spinal erectors","Deltoide posterior, romboides e eretores da espinha","Deltoïde postérieur, rhomboïdes et érecteurs du rachis","Deltoide posteriore, romboidi ed erettori spinali","Hinterer Deltamuskel, Rautenmuskeln und Rückenstrecker"],
  ["Acostate boca abajo con la frente apoyada sobre una toalla doblada y los brazos extendidos por encima de la cabeza formando una Y.","Lie face down with your forehead on a folded towel and your arms extended overhead in a Y shape.","Deite-se de bruços com a testa apoiada sobre uma toalha dobrada e os braços estendidos acima da cabeça formando um Y.","Allonge-toi sur le ventre, front posé sur une serviette pliée, bras tendus au-dessus de la tête en forme de Y.","Sdraiati a pancia in giù con la fronte appoggiata su un asciugamano piegato e le braccia distese sopra la testa a formare una Y.","Leg dich bäuchlings hin, die Stirn auf einem gefalteten Handtuch, die Arme in Y-Form über den Kopf gestreckt."],
  ["Exhalá al elevar los brazos e inhalá al bajarlos.","Exhale as you lift your arms and inhale as you lower them.","Expire ao elevar os braços e inspire ao abaixá-los.","Expire en levant les bras et inspire en les abaissant.","Espira sollevando le braccia e inspira abbassandole.","Atme beim Heben der Arme aus und beim Senken ein."],
  ["Colocá los brazos en diagonal formando una Y, con los pulgares hacia el techo.","Place your arms diagonally in a Y, thumbs pointing to the ceiling.","Coloque os braços na diagonal formando um Y, com os polegares para o teto.","Place les bras en diagonale en forme de Y, pouces vers le plafond.","Metti le braccia in diagonale a formare una Y, con i pollici verso il soffitto.","Leg die Arme schräg in Y-Form, die Daumen zeigen zur Decke."],
  ["Llevá las escápulas hacia atrás y abajo y elevá los brazos unos centímetros del suelo.","Draw your shoulder blades back and down and lift your arms a few centimeters off the floor.","Leve as escápulas para trás e para baixo e eleve os braços alguns centímetros do chão.","Ramène les omoplates vers l’arrière et le bas et lève les bras de quelques centimètres.","Porta le scapole indietro e in basso e solleva le braccia di qualche centimetro da terra.","Zieh die Schulterblätter nach hinten unten und heb die Arme ein paar Zentimeter vom Boden."],
  ["Pausá un instante arriba sin levantar la cabeza.","Pause for a moment at the top without lifting your head.","Pause um instante em cima sem levantar a cabeça.","Marque une courte pause en haut sans relever la tête.","Fai una breve pausa in alto senza sollevare la testa.","Halte oben kurz, ohne den Kopf zu heben."],
  ["Bajá los brazos con control.","Lower your arms with control.","Abaixe os braços com controle.","Redescends les bras en contrôle.","Abbassa le braccia con controllo.","Senk die Arme kontrolliert ab."],
  ["Levantar el pecho y arquear la espalda en lugar de mover los brazos.","Lifting your chest and arching your back instead of moving your arms.","Levantar o peito e arquear as costas em vez de mover os braços.","Soulever la poitrine et cambrer le dos au lieu de bouger les bras.","Sollevare il petto e inarcare la schiena invece di muovere le braccia.","Die Brust heben und ins Hohlkreuz gehen, statt die Arme zu bewegen."],
  ["Levantar la cabeza.","Lifting your head.","Levantar a cabeça.","Relever la tête.","Sollevare la testa.","Den Kopf heben."],
  ["El rango es pequeño: la clave es que las escápulas bajen.","The range is small: the key is for your shoulder blades to move down.","A amplitude é pequena: o segredo é as escápulas descerem.","L’amplitude est petite : l’essentiel est que les omoplates descendent.","L’ampiezza è piccola: la chiave è che le scapole scendano.","Der Bewegungsumfang ist klein: Entscheidend ist, dass die Schulterblätter nach unten gehen."],
  ["Los pulgares hacia arriba suelen hacer el movimiento más cómodo para el hombro.","Thumbs up usually make the movement more comfortable for the shoulder.","Os polegares para cima costumam deixar o movimento mais confortável para o ombro.","Les pouces vers le haut rendent généralement le mouvement plus confortable pour l’épaule.","I pollici verso l’alto di solito rendono il movimento più comodo per la spalla.","Mit den Daumen nach oben ist die Bewegung meist angenehmer für die Schulter."],
  ["Sumá una pausa de uno o dos segundos arriba para más dificultad.","Add a one- or two-second pause at the top for more difficulty.","Inclua uma pausa de um ou dois segundos em cima para mais dificuldade.","Ajoute une pause d’une ou deux secondes en haut pour plus de difficulté.","Aggiungi una pausa di uno o due secondi in alto per aumentare la difficoltà.","Für mehr Schwierigkeit halte oben ein bis zwei Sekunden."],
  ["Trapecio medio e inferior y romboides","Middle and lower trapezius and rhomboids","Trapézio médio e inferior e romboides","Trapèze moyen et inférieur et rhomboïdes","Trapezio medio e inferiore e romboidi","Mittlerer und unterer Trapezmuskel und Rautenmuskeln"],
  ["Deltoides posterior y rotadores externos del hombro","Rear deltoid and shoulder external rotators","Deltoide posterior e rotadores externos do ombro","Deltoïde postérieur et rotateurs externes de l’épaule","Deltoide posteriore ed extrarotatori della spalla","Hinterer Deltamuskel und Außenrotatoren der Schulter"],
  ["Acostate boca abajo con la frente apoyada sobre una toalla doblada y los brazos extendidos por encima de la cabeza.","Lie face down with your forehead on a folded towel and your arms extended overhead.","Deite-se de bruços com a testa apoiada sobre uma toalha dobrada e os braços estendidos acima da cabeça.","Allonge-toi sur le ventre, front posé sur une serviette pliée et bras tendus au-dessus de la tête.","Sdraiati a pancia in giù con la fronte appoggiata su un asciugamano piegato e le braccia distese sopra la testa.","Leg dich bäuchlings hin, die Stirn auf einem gefalteten Handtuch, die Arme über den Kopf gestreckt."],
  ["Exhalá al elevar los brazos e inhalá al bajarlos en cada forma.","Exhale as you lift your arms and inhale as you lower them in each shape.","Expire ao elevar os braços e inspire ao abaixá-los em cada forma.","Expire en levant les bras et inspire en les abaissant dans chaque forme.","Espira sollevando le braccia e inspira abbassandole in ogni forma.","Atme in jeder Form beim Heben der Arme aus und beim Senken ein."],
  ["Y: con los brazos en diagonal y pulgares hacia arriba, elevalos unos centímetros llevando las escápulas atrás y abajo; bajá y repetí.","Y: with your arms diagonal and thumbs up, lift them a few centimeters while drawing your shoulder blades back and down; lower and repeat.","Y: com os braços na diagonal e os polegares para cima, eleve-os alguns centímetros levando as escápulas para trás e para baixo; abaixe e repita.","Y : bras en diagonale et pouces vers le haut, lève-les de quelques centimètres en ramenant les omoplates vers l’arrière et le bas ; redescends et recommence.","Y: con le braccia in diagonale e i pollici in alto, sollevale di qualche centimetro portando le scapole indietro e in basso; abbassa e ripeti.","Y: Arme schräg, Daumen nach oben, ein paar Zentimeter anheben und die Schulterblätter nach hinten unten ziehen; absenken und wiederholen."],
  ["T: abrí los brazos hacia los costados a la altura de los hombros y elevalos juntando las escápulas; bajá y repetí.","T: open your arms out to the sides at shoulder height and lift them while squeezing your shoulder blades; lower and repeat.","T: abra os braços para os lados na altura dos ombros e eleve-os juntando as escápulas; abaixe e repita.","T : ouvre les bras sur les côtés à hauteur des épaules et lève-les en serrant les omoplates ; redescends et recommence.","T: apri le braccia lateralmente all’altezza delle spalle e sollevale stringendo le scapole; abbassa e ripeti.","T: Arme auf Schulterhöhe zur Seite öffnen und anheben, dabei die Schulterblätter zusammenziehen; absenken und wiederholen."],
  ["W: flexioná los codos y llevalos hacia los costados del cuerpo, elevando brazos y antebrazos mientras apretás las escápulas.","W: bend your elbows and bring them toward the sides of your body, lifting your arms and forearms while squeezing your shoulder blades.","W: flexione os cotovelos e leve-os em direção às laterais do corpo, elevando braços e antebraços enquanto contrai as escápulas.","W : fléchis les coudes et amène-les vers les côtés du corps, en levant bras et avant-bras tout en serrant les omoplates.","W: piega i gomiti e portali verso i lati del corpo, sollevando braccia e avambracci mentre stringi le scapole.","W: Ellbogen beugen und seitlich zum Körper führen, Ober- und Unterarme anheben und die Schulterblätter zusammenziehen."],
  ["Completá las repeticiones de cada forma antes de pasar a la siguiente y bajá con control al terminar.","Complete the reps of each shape before moving on to the next and lower with control when you finish.","Complete as repetições de cada forma antes de passar para a seguinte e abaixe com controle ao terminar.","Termine les répétitions de chaque forme avant de passer à la suivante et redescends en contrôle à la fin.","Completa le ripetizioni di ogni forma prima di passare alla successiva e abbassa con controllo alla fine.","Mach alle Wiederholungen einer Form, bevor du zur nächsten wechselst, und senk am Ende kontrolliert ab."],
  ["Arquear la zona lumbar para levantar más los brazos.","Arching your lower back to lift your arms higher.","Arquear a lombar para levantar mais os braços.","Cambrer le bas du dos pour lever les bras plus haut.","Inarcare la zona lombare per sollevare di più le braccia.","Ins Hohlkreuz gehen, um die Arme höher zu heben."],
  ["Hacer las repeticiones rápido sin pausa.","Doing the reps fast without pausing.","Fazer as repetições rápido sem pausa.","Faire les répétitions vite sans pause.","Fare le ripetizioni veloci senza pause.","Die Wiederholungen schnell ohne Pause machen."],
  ["El rango de cada forma es pequeño: priorizá el control de las escápulas.","The range of each shape is small: prioritize control of your shoulder blades.","A amplitude de cada forma é pequena: priorize o controle das escápulas.","L’amplitude de chaque forme est petite : privilégie le contrôle des omoplates.","L’ampiezza di ogni forma è piccola: dai priorità al controllo delle scapole.","Der Bewegungsumfang jeder Form ist klein: Konzentrier dich auf die Kontrolle der Schulterblätter."],
  ["Mantené el cuello neutro y la frente apoyada.","Keep your neck neutral and your forehead down.","Mantenha o pescoço neutro e a testa apoiada.","Garde la nuque neutre et le front posé.","Mantieni il collo neutro e la fronte appoggiata.","Halte den Nacken neutral und die Stirn abgelegt."],
  ["Si alguna forma molesta el hombro, reducí el rango o salteala.","If any shape bothers your shoulder, reduce the range or skip it.","Se alguma forma incomodar o ombro, reduza a amplitude ou pule-a.","Si une forme gêne ton épaule, réduis l’amplitude ou saute-la.","Se una forma dà fastidio alla spalla, riduci l’ampiezza o saltala.","Wenn eine Form die Schulter stört, verkleinere den Bewegungsumfang oder lass sie aus."],
  ["Serrato anterior","Serratus anterior","Serrátil anterior","Dentelé antérieur","Dentato anteriore","Vorderer Sägemuskel"],
  ["Romboides, trapecio medio y estabilizadores del tronco","Rhomboids, middle trapezius and trunk stabilizers","Romboides, trapézio médio e estabilizadores do tronco","Rhomboïdes, trapèze moyen et stabilisateurs du tronc","Romboidi, trapezio medio e stabilizzatori del tronco","Rautenmuskeln, mittlerer Trapezmuskel und Rumpfstabilisatoren"],
  ["Pared firme","Sturdy wall","Parede firme","Mur solide","Parete stabile","Feste Wand"],
  ["Parate frente a una pared con las manos apoyadas a la altura de los hombros y los brazos extendidos, cuerpo levemente inclinado.","Stand facing a wall with your hands on it at shoulder height and your arms extended, body leaning slightly.","Fique de frente para uma parede com as mãos apoiadas na altura dos ombros e os braços estendidos, corpo levemente inclinado.","Tiens-toi face à un mur, mains posées à hauteur des épaules et bras tendus, corps légèrement incliné.","Mettiti di fronte a una parete con le mani appoggiate all’altezza delle spalle e le braccia distese, corpo leggermente inclinato.","Stell dich vor eine Wand, Hände auf Schulterhöhe daran, Arme gestreckt, Körper leicht geneigt."],
  ["Inhalá al juntar las escápulas y exhalá al separarlas.","Inhale as you squeeze your shoulder blades together and exhale as you spread them.","Inspire ao juntar as escápulas e expire ao separá-las.","Inspire en rapprochant les omoplates et expire en les écartant.","Inspira avvicinando le scapole ed espira separandole.","Atme beim Zusammenziehen der Schulterblätter ein und beim Auseinanderschieben aus."],
  ["Apoyá las manos en la pared con los codos extendidos sin bloquear.","Place your hands on the wall with your elbows straight but not locked.","Apoie as mãos na parede com os cotovelos estendidos sem travar.","Pose les mains sur le mur, coudes tendus sans les verrouiller.","Appoggia le mani alla parete con i gomiti distesi senza bloccarli.","Leg die Hände an die Wand, Ellbogen gestreckt, aber nicht durchgedrückt."],
  ["Sin flexionar los codos, dejá que el pecho se acerque apenas a la pared juntando las escápulas.","Without bending your elbows, let your chest move slightly toward the wall by squeezing your shoulder blades together.","Sem flexionar os cotovelos, deixe o peito se aproximar levemente da parede juntando as escápulas.","Sans fléchir les coudes, laisse la poitrine se rapprocher légèrement du mur en serrant les omoplates.","Senza piegare i gomiti, lascia che il petto si avvicini appena alla parete stringendo le scapole.","Lass die Brust, ohne die Ellbogen zu beugen, leicht zur Wand sinken, indem du die Schulterblätter zusammenziehst."],
  ["Empujá la pared separando las escápulas hasta que la parte alta de la espalda se redondee levemente.","Push the wall away by spreading your shoulder blades until your upper back rounds slightly.","Empurre a parede separando as escápulas até a parte alta das costas arredondar levemente.","Pousse le mur en écartant les omoplates jusqu’à ce que le haut du dos s’arrondisse légèrement.","Spingi la parete separando le scapole finché la parte alta della schiena si arrotonda leggermente.","Drück dich von der Wand weg und schieb die Schulterblätter auseinander, bis sich der obere Rücken leicht rundet."],
  ["Repetí el movimiento de forma lenta, manteniendo los brazos rectos.","Repeat the movement slowly, keeping your arms straight.","Repita o movimento de forma lenta, mantendo os braços retos.","Répète le mouvement lentement, en gardant les bras tendus.","Ripeti il movimento lentamente, mantenendo le braccia dritte.","Wiederhol die Bewegung langsam mit gestreckten Armen."],
  ["Flexionar los codos y convertirlo en una flexión común.","Bending your elbows and turning it into a regular push-up.","Flexionar os cotovelos e transformar em uma flexão comum.","Fléchir les coudes et en faire une pompe classique.","Piegare i gomiti e trasformarlo in un normale piegamento.","Die Ellbogen beugen und einen normalen Liegestütz daraus machen."],
  ["El movimiento es pequeño y sale solo de las escápulas.","The movement is small and comes only from your shoulder blades.","O movimento é pequeno e sai só das escápulas.","Le mouvement est petit et vient uniquement des omoplates.","Il movimento è piccolo e parte solo dalle scapole.","Die Bewegung ist klein und kommt nur aus den Schulterblättern."],
  ["La pared da un apoyo estable que no se desliza y reduce la carga.","The wall gives stable support that doesn’t slide and reduces the load.","A parede dá um apoio estável que não desliza e reduz a carga.","Le mur offre un appui stable qui ne glisse pas et réduit la charge.","La parete dà un appoggio stabile che non scivola e riduce il carico.","Die Wand gibt stabilen Halt, der nicht rutscht, und verringert die Last."],
  ["Pensá en alejar la pared en la fase de empuje.","Think about pushing the wall away during the push phase.","Pense em afastar a parede na fase de empurrão.","Pense à éloigner le mur pendant la phase de poussée.","Pensa di allontanare la parete nella fase di spinta.","Stell dir in der Drückphase vor, du schiebst die Wand weg."],
  ["Trapecio inferior y deltoides posterior","Lower trapezius and rear deltoid","Trapézio inferior e deltoide posterior","Trapèze inférieur et deltoïde postérieur","Trapezio inferiore e deltoide posteriore","Unterer Trapezmuskel und hinterer Deltamuskel"],
  ["Parate erguido con los pies al ancho de cadera y los brazos a los costados o con los codos flexionados a 90 grados.","Stand tall with your feet hip-width apart and your arms at your sides or with your elbows bent to 90 degrees.","Fique ereto com os pés na largura do quadril e os braços ao lado do corpo ou com os cotovelos flexionados a 90 graus.","Tiens-toi droit, pieds à la largeur des hanches, bras le long du corps ou coudes fléchis à 90 degrés.","Mettiti dritto con i piedi alla larghezza delle anche e le braccia lungo i fianchi o con i gomiti piegati a 90 gradi.","Stell dich aufrecht hin, Füße hüftbreit, Arme seitlich oder Ellbogen im 90-Grad-Winkel gebeugt."],
  ["Exhalá al juntar las escápulas e inhalá al soltarlas.","Exhale as you squeeze your shoulder blades together and inhale as you release them.","Expire ao juntar as escápulas e inspire ao soltá-las.","Expire en serrant les omoplates et inspire en les relâchant.","Espira stringendo le scapole e inspira rilasciandole.","Atme beim Zusammenziehen der Schulterblätter aus und beim Lösen ein."],
  ["Sin pausa obligatoria; 30 segundos si lo hacés en series","No set rest needed; 30 seconds if you do it in sets","Sem pausa obrigatória; 30 segundos se fizer em séries","Pas de pause obligatoire ; 30 secondes si tu le fais en séries","Nessuna pausa obbligatoria; 30 secondi se lo fai in serie","Keine feste Pause nötig; 30 Sekunden, wenn du es in Sätzen machst"],
  ["Crecé hacia arriba con el cuello largo y los hombros relajados.","Grow tall with a long neck and relaxed shoulders.","Cresça para cima com o pescoço alongado e os ombros relaxados.","Grandis-toi, nuque longue et épaules détendues.","Allungati verso l’alto con il collo lungo e le spalle rilassate.","Mach dich groß, Nacken lang, Schultern locker."],
  ["Llevá las escápulas hacia atrás y abajo, como si quisieras guardarlas en los bolsillos de atrás.","Draw your shoulder blades back and down, as if tucking them into your back pockets.","Leve as escápulas para trás e para baixo, como se quisesse guardá-las nos bolsos de trás.","Ramène les omoplates vers l’arrière et le bas, comme pour les ranger dans tes poches arrière.","Porta le scapole indietro e in basso, come se volessi metterle nelle tasche posteriori.","Zieh die Schulterblätter nach hinten unten, als wolltest du sie in die Gesäßtaschen stecken."],
  ["Sostené uno o dos segundos sin arquear la espalda ni levantar los hombros.","Hold for one or two seconds without arching your back or raising your shoulders.","Sustente um ou dois segundos sem arquear as costas nem levantar os ombros.","Tiens une ou deux secondes sans cambrer le dos ni lever les épaules.","Mantieni uno o due secondi senza inarcare la schiena né sollevare le spalle.","Halte ein bis zwei Sekunden, ohne ins Hohlkreuz zu gehen oder die Schultern zu heben."],
  ["Soltá despacio hasta la posición inicial.","Release slowly back to the starting position.","Solte devagar até a posição inicial.","Relâche lentement jusqu’à la position de départ.","Rilascia lentamente fino alla posizione iniziale.","Lös die Spannung langsam bis zur Ausgangsposition."],
  ["Encoger los hombros en lugar de llevarlos atrás.","Shrugging your shoulders instead of drawing them back.","Encolher os ombros em vez de levá-los para trás.","Hausser les épaules au lieu de les ramener vers l’arrière.","Sollevare le spalle invece di portarle indietro.","Die Schultern hochziehen, statt sie nach hinten zu führen."],
  ["Sacar las costillas y arquear la zona lumbar.","Flaring your ribs and arching your lower back.","Projetar as costelas e arquear a lombar.","Sortir les côtes et cambrer le bas du dos.","Sporgere le costole e inarcare la zona lombare.","Die Rippen herausstrecken und ins Hohlkreuz gehen."],
  ["Adelantar la cabeza.","Pushing your head forward.","Projetar a cabeça para frente.","Avancer la tête.","Spingere la testa in avanti.","Den Kopf nach vorn schieben."],
  ["Es un buen ejercicio para hacer en pausas durante el día.","It is a good exercise to do during breaks throughout the day.","É um bom exercício para fazer em pausas ao longo do dia.","C’est un bon exercice à faire pendant les pauses de la journée.","È un buon esercizio da fare nelle pause durante la giornata.","Eine gute Übung für kurze Pausen im Laufe des Tages."],
  ["Mantené las costillas abajo y el abdomen suave.","Keep your ribs down and your abs soft.","Mantenha as costelas para baixo e o abdômen relaxado.","Garde les côtes basses et le ventre détendu.","Tieni le costole basse e l’addome morbido.","Halte die Rippen unten und den Bauch locker."],
  ["Podés hacerlo frente a un espejo para controlar la postura.","You can do it in front of a mirror to check your posture.","Você pode fazer diante de um espelho para controlar a postura.","Tu peux le faire devant un miroir pour contrôler ta posture.","Puoi farlo davanti a uno specchio per controllare la postura.","Du kannst es vor einem Spiegel machen, um deine Haltung zu kontrollieren."],
  ["Glúteos, serrato anterior y estabilizadores del hombro","Glutes, serratus anterior and shoulder stabilizers","Glúteos, serrátil anterior e estabilizadores do ombro","Fessiers, dentelé antérieur et stabilisateurs de l’épaule","Glutei, dentato anteriore e stabilizzatori della spalla","Gesäß, vorderer Sägemuskel und Schulterstabilisatoren"],
  ["Mesa muy estable o mesada que no pueda deslizarse ni volcar","Very stable table or countertop that can’t slide or tip over","Mesa muito estável ou bancada que não possa deslizar nem tombar","Table très stable ou plan de travail qui ne peut ni glisser ni basculer","Tavolo molto stabile o piano di lavoro che non possa scivolare né ribaltarsi","Sehr stabiler Tisch oder Arbeitsplatte, die weder rutschen noch kippen kann"],
  ["Apoyá los antebrazos o las manos sobre el borde de una mesa firme y caminá los pies hacia atrás hasta que el cuerpo quede en línea recta.","Rest your forearms or hands on the edge of a sturdy table and walk your feet back until your body is in a straight line.","Apoie os antebraços ou as mãos na borda de uma mesa firme e caminhe com os pés para trás até o corpo ficar em linha reta.","Pose les avant-bras ou les mains sur le bord d’une table solide et recule les pieds jusqu’à ce que le corps soit aligné.","Appoggia gli avambracci o le mani sul bordo di un tavolo stabile e cammina con i piedi all’indietro finché il corpo è in linea retta.","Stütz Unterarme oder Hände auf die Kante eines stabilen Tischs und geh mit den Füßen zurück, bis dein Körper eine gerade Linie bildet."],
  ["Verificá que la mesa no se mueva; si es necesario, apoyala contra una pared.","Check that the table doesn’t move; if necessary, set it against a wall.","Verifique se a mesa não se move; se necessário, encoste-a em uma parede.","Vérifie que la table ne bouge pas ; si nécessaire, cale-la contre un mur.","Verifica che il tavolo non si muova; se serve, appoggialo a una parete.","Prüf, dass der Tisch nicht wackelt; stell ihn bei Bedarf an eine Wand."],
  ["Colocá los codos bajo los hombros y alineá talones, cadera y cabeza.","Place your elbows under your shoulders and align your heels, hips and head.","Coloque os cotovelos sob os ombros e alinhe calcanhares, quadril e cabeça.","Place les coudes sous les épaules et aligne talons, hanches et tête.","Metti i gomiti sotto le spalle e allinea talloni, anche e testa.","Setz die Ellbogen unter die Schultern und bring Fersen, Hüfte und Kopf in eine Linie."],
  ["Sostené la posición apretando abdomen y glúteos, sin hundir la cadera, mientras respirás con calma.","Hold the position, tightening your abs and glutes without letting your hips sag, while breathing calmly.","Sustente a posição contraindo abdômen e glúteos, sem afundar o quadril, enquanto respira com calma.","Tiens la position en serrant abdos et fessiers, sans laisser les hanches s’affaisser, tout en respirant calmement.","Mantieni la posizione contraendo addome e glutei, senza far cedere le anche, mentre respiri con calma.","Halte die Position mit angespanntem Bauch und Gesäß, ohne die Hüfte durchhängen zu lassen, und atme ruhig."],
  ["Para salir, caminá los pies hacia la mesa y enderezate.","To come out, walk your feet toward the table and straighten up.","Para sair, caminhe com os pés em direção à mesa e endireite-se.","Pour sortir, avance les pieds vers la table et redresse-toi.","Per uscire, cammina con i piedi verso il tavolo e raddrizzati.","Zum Beenden geh mit den Füßen zum Tisch und richte dich auf."],
  ["Usar una mesa liviana o plegable que puede moverse.","Using a light or folding table that can move.","Usar uma mesa leve ou dobrável que pode se mover.","Utiliser une table légère ou pliante qui peut bouger.","Usare un tavolo leggero o pieghevole che può muoversi.","Einen leichten oder klappbaren Tisch nutzen, der sich bewegen kann."],
  ["Elevar la cadera en pico.","Piking your hips up.","Elevar o quadril em pico.","Monter les hanches en pointe.","Sollevare le anche a punta.","Die Hüfte spitz nach oben schieben."],
  ["Al estar inclinado, cargás menos peso que en el suelo, por eso es más fácil; la mesa firme da un apoyo que no se desliza.","Since you are inclined, you carry less weight than on the floor, which makes it easier; the sturdy table gives support that doesn’t slide.","Como você fica inclinado, carrega menos peso que no chão, por isso é mais fácil; a mesa firme dá um apoio que não desliza.","En étant incliné, tu portes moins de poids qu’au sol, c’est pourquoi c’est plus facile ; la table solide offre un appui qui ne glisse pas.","Stando inclinato carichi meno peso che a terra, per questo è più facile; il tavolo stabile dà un appoggio che non scivola.","In der Schräglage trägst du weniger Gewicht als am Boden, deshalb ist es leichter; der stabile Tisch gibt Halt, der nicht rutscht."],
  ["Cuanto más baja la superficie, más difícil.","The lower the surface, the harder it gets.","Quanto mais baixa a superfície, mais difícil.","Plus la surface est basse, plus c’est difficile.","Più bassa è la superficie, più è difficile.","Je niedriger die Fläche, desto schwerer."],
  ["Terminá cuando ya no puedas mantener la alineación.","Stop when you can no longer keep the alignment.","Termine quando já não conseguir manter o alinhamento.","Arrête quand tu ne peux plus garder l’alignement.","Termina quando non riesci più a mantenere l’allineamento.","Hör auf, wenn du die Linie nicht mehr halten kannst."],
  ["Glúteos, cuádriceps, serrato anterior y hombros","Glutes, quadriceps, serratus anterior and shoulders","Glúteos, quadríceps, serrátil anterior e ombros","Fessiers, quadriceps, dentelé antérieur et épaules","Glutei, quadricipiti, dentato anteriore e spalle","Gesäß, Quadrizeps, vorderer Sägemuskel und Schultern"],
  ["Ponete en posición de flexión de brazos con las manos bajo los hombros, brazos extendidos y piernas estiradas.","Get into push-up position with your hands under your shoulders, arms extended and legs straight.","Fique em posição de flexão com as mãos sob os ombros, braços estendidos e pernas esticadas.","Mets-toi en position de pompe, mains sous les épaules, bras tendus et jambes allongées.","Mettiti in posizione di piegamento con le mani sotto le spalle, braccia distese e gambe tese.","Geh in die Liegestützposition, Hände unter den Schultern, Arme und Beine gestreckt."],
  ["Apoyá las manos bajo los hombros con los dedos abiertos y extendé las piernas.","Place your hands under your shoulders with your fingers spread and extend your legs.","Apoie as mãos sob os ombros com os dedos abertos e estenda as pernas.","Pose les mains sous les épaules, doigts écartés, et tends les jambes.","Appoggia le mani sotto le spalle con le dita aperte e distendi le gambe.","Setz die Hände mit gespreizten Fingern unter die Schultern und streck die Beine."],
  ["Alineá talones, cadera y cabeza apretando abdomen y glúteos.","Align your heels, hips and head by tightening your abs and glutes.","Alinhe calcanhares, quadril e cabeça contraindo abdômen e glúteos.","Aligne talons, hanches et tête en serrant abdos et fessiers.","Allinea talloni, anche e testa contraendo addome e glutei.","Bring Fersen, Hüfte und Kopf in eine Linie und spann Bauch und Gesäß an."],
  ["Sostené la posición empujando el suelo, sin hundir la cadera, mientras respirás con calma.","Hold the position by pushing the floor away, without letting your hips sag, while breathing calmly.","Sustente a posição empurrando o chão, sem afundar o quadril, enquanto respira com calma.","Tiens la position en poussant le sol, sans laisser les hanches s’affaisser, tout en respirant calmement.","Mantieni la posizione spingendo il pavimento, senza far cedere le anche, mentre respiri con calma.","Halte die Position, drück dich vom Boden weg, ohne die Hüfte durchhängen zu lassen, und atme ruhig."],
  ["Para terminar, apoyá las rodillas en el suelo con control.","To finish, lower your knees to the floor with control.","Para terminar, apoie os joelhos no chão com controle.","Pour finir, pose les genoux au sol en contrôle.","Per finire, appoggia le ginocchia a terra con controllo.","Setz zum Abschluss die Knie kontrolliert auf den Boden."],
  ["Dejar que los hombros se hundan entre las escápulas.","Letting your shoulders sink between your shoulder blades.","Deixar os ombros afundarem entre as escápulas.","Laisser les épaules s’enfoncer entre les omoplates.","Lasciare che le spalle sprofondino tra le scapole.","Die Schultern zwischen die Schulterblätter sinken lassen."],
  ["Bloquear los codos con fuerza.","Forcefully locking your elbows.","Travar os cotovelos com força.","Verrouiller les coudes en force.","Bloccare i gomiti con forza.","Die Ellbogen kräftig durchdrücken."],
  ["Empujar el suelo con las manos estabiliza los hombros.","Pushing the floor away with your hands stabilizes your shoulders.","Empurrar o chão com as mãos estabiliza os ombros.","Pousser le sol avec les mains stabilise les épaules.","Spingere il pavimento con le mani stabilizza le spalle.","Wenn du dich mit den Händen vom Boden wegdrückst, stabilisierst du die Schultern."],
  ["Si las muñecas molestan, apoyá los puños o hacé la plancha sobre antebrazos.","If your wrists bother you, rest on your fists or do the plank on your forearms.","Se os punhos incomodarem, apoie os punhos fechados ou faça a prancha sobre os antebraços.","Si tes poignets te gênent, appuie-toi sur les poings ou fais la planche sur les avant-bras.","Se i polsi danno fastidio, appoggia i pugni o fai il plank sugli avambracci.","Wenn die Handgelenke zwicken, stütz dich auf die Fäuste oder mach den Unterarmstütz."],
  ["Transverso del abdomen y recto abdominal","Transversus abdominis and rectus abdominis","Transverso do abdômen e reto abdominal","Transverse de l’abdomen et grand droit","Trasverso dell’addome e retto addominale","Querer und gerader Bauchmuskel"],
  ["Acostate boca arriba con los brazos extendidos hacia el techo y las rodillas flexionadas a 90 grados sobre la cadera.","Lie on your back with your arms extended toward the ceiling and your knees bent at 90 degrees over your hips.","Deite-se de barriga para cima com os braços estendidos em direção ao teto e os joelhos flexionados a 90 graus sobre o quadril.","Allonge-toi sur le dos, bras tendus vers le plafond et genoux fléchis à 90 degrés au-dessus des hanches.","Sdraiati a pancia in su con le braccia distese verso il soffitto e le ginocchia piegate a 90 gradi sopra le anche.","Leg dich auf den Rücken, Arme zur Decke gestreckt, Knie im 90-Grad-Winkel über der Hüfte."],
  ["Exhalá al bajar el talón e inhalá al volver.","Exhale as you lower your heel and inhale as you return.","Expire ao abaixar o calcanhar e inspire ao voltar.","Expire en descendant le talon et inspire en revenant.","Espira abbassando il tallone e inspira tornando.","Atme beim Absenken der Ferse aus und beim Zurückführen ein."],
  ["Apoyá la zona lumbar en el suelo de forma suave y afirmá el abdomen.","Rest your lower back gently on the floor and brace your abs.","Apoie a lombar no chão de forma suave e firme o abdômen.","Pose doucement le bas du dos au sol et gaine les abdos.","Appoggia delicatamente la zona lombare a terra e contrai l’addome.","Leg den unteren Rücken sanft ab und spann den Bauch an."],
  ["Bajá un pie manteniendo la rodilla flexionada hasta tocar el suelo con el talón.","Lower one foot, keeping your knee bent, until your heel touches the floor.","Abaixe um pé mantendo o joelho flexionado até tocar o chão com o calcanhar.","Descends un pied en gardant le genou fléchi jusqu’à toucher le sol avec le talon.","Abbassa un piede mantenendo il ginocchio piegato fino a toccare terra con il tallone.","Senk einen Fuß mit gebeugtem Knie ab, bis die Ferse den Boden berührt."],
  ["Volvé la pierna a la posición inicial sin que la espalda se arquee.","Bring your leg back to the starting position without your back arching.","Volte a perna à posição inicial sem que as costas arqueiem.","Ramène la jambe à la position de départ sans que le dos se cambre.","Riporta la gamba alla posizione iniziale senza che la schiena si inarchi.","Bring das Bein zurück in die Ausgangsposition, ohne dass der Rücken ins Hohlkreuz geht."],
  ["Despegar la zona lumbar del suelo.","Lifting your lower back off the floor.","Descolar a lombar do chão.","Décoller le bas du dos du sol.","Staccare la zona lombare da terra.","Den unteren Rücken vom Boden lösen."],
  ["Mover las piernas rápido.","Moving your legs fast.","Mover as pernas rápido.","Bouger les jambes vite.","Muovere le gambe veloce.","Die Beine schnell bewegen."],
  ["Tocar el suelo con el talón y la rodilla flexionada es más fácil que extender toda la pierna.","Touching the floor with your heel and knee bent is easier than extending the whole leg.","Tocar o chão com o calcanhar e o joelho flexionado é mais fácil que estender a perna inteira.","Toucher le sol avec le talon, genou fléchi, est plus facile que tendre toute la jambe.","Toccare terra con il tallone e il ginocchio piegato è più facile che distendere tutta la gamba.","Mit gebeugtem Knie die Ferse abzusetzen ist leichter, als das ganze Bein zu strecken."],
  ["Si la espalda se arquea, bajá menos el pie.","If your back arches, lower your foot less.","Se as costas arquearem, abaixe menos o pé.","Si ton dos se cambre, descends moins le pied.","Se la schiena si inarca, abbassa meno il piede.","Wenn der Rücken ins Hohlkreuz geht, senk den Fuß weniger tief."],
  ["Mantené los brazos quietos apuntando al techo.","Keep your arms still, pointing at the ceiling.","Mantenha os braços parados apontando para o teto.","Garde les bras immobiles, pointés vers le plafond.","Mantieni le braccia ferme rivolte verso il soffitto.","Halte die Arme ruhig zur Decke gerichtet."],
  ["Flexores de cadera, oblicuos y hombros","Hip flexors, obliques and shoulders","Flexores do quadril, oblíquos e ombros","Fléchisseurs de hanche, obliques et épaules","Flessori dell’anca, obliqui e spalle","Hüftbeuger, schräge Bauchmuskeln und Schultern"],
  ["Banco, mesa firme o escalón estable para apoyar las manos","Bench, sturdy table or stable step to rest your hands on","Banco, mesa firme ou degrau estável para apoiar as mãos","Banc, table solide ou marche stable pour poser les mains","Panca, tavolo stabile o gradino fermo per appoggiare le mani","Bank, stabiler Tisch oder feste Stufe zum Abstützen der Hände"],
  ["Apoyá las manos sobre una superficie firme y elevada, con los brazos extendidos y el cuerpo en línea recta de cabeza a talones.","Place your hands on a sturdy, raised surface with your arms extended and your body in a straight line from head to heels.","Apoie as mãos sobre uma superfície firme e elevada, com os braços estendidos e o corpo em linha reta da cabeça aos calcanhares.","Pose les mains sur une surface solide et surélevée, bras tendus et corps aligné de la tête aux talons.","Appoggia le mani su una superficie stabile e rialzata, con le braccia distese e il corpo in linea retta dalla testa ai talloni.","Stütz die Hände auf eine stabile, erhöhte Fläche, Arme gestreckt, Körper in einer geraden Linie vom Kopf bis zu den Fersen."],
  ["Verificá que la superficie no pueda deslizarse y colocá las manos bajo los hombros.","Check that the surface can’t slide and place your hands under your shoulders.","Verifique que a superfície não possa deslizar e coloque as mãos sob os ombros.","Vérifie que la surface ne peut pas glisser et place les mains sous les épaules.","Verifica che la superficie non possa scivolare e metti le mani sotto le spalle.","Prüf, dass die Fläche nicht rutschen kann, und setz die Hände unter die Schultern."],
  ["Devolvé el pie atrás con control.","Return your foot back with control.","Volte o pé para trás com controle.","Ramène le pied en arrière en contrôle.","Riporta il piede indietro con controllo.","Setz den Fuß kontrolliert zurück."],
  ["Alterná con la otra pierna a un ritmo lento y constante.","Alternate with the other leg at a slow, steady pace.","Alterne com a outra perna em um ritmo lento e constante.","Alterne avec l’autre jambe à un rythme lent et régulier.","Alterna con l’altra gamba a un ritmo lento e costante.","Wechsle in langsamem, gleichmäßigem Tempo zum anderen Bein."],
  ["Apoyarse en una superficie que se mueve.","Leaning on a surface that moves.","Apoiar-se em uma superfície que se move.","S’appuyer sur une surface qui bouge.","Appoggiarsi a una superficie che si muove.","Sich auf eine Fläche stützen, die sich bewegt."],
  ["Elevar la cadera en pico al traer la rodilla.","Piking your hips up as you bring your knee in.","Elevar o quadril em pico ao trazer o joelho.","Monter les hanches en pointe en ramenant le genou.","Sollevare le anche a punta portando il ginocchio.","Beim Heranziehen des Knies die Hüfte spitz nach oben schieben."],
  ["Acelerar y perder la alineación.","Speeding up and losing alignment.","Acelerar e perder o alinhamento.","Accélérer et perdre l’alignement.","Accelerare e perdere l’allineamento.","Schneller werden und die Linie verlieren."],
  ["Las manos elevadas reducen la carga sobre hombros y abdomen, por eso es más fácil que en el suelo.","Raised hands reduce the load on your shoulders and abs, which is why it is easier than on the floor.","As mãos elevadas reduzem a carga sobre ombros e abdômen, por isso é mais fácil que no chão.","Les mains surélevées réduisent la charge sur les épaules et les abdos, c’est pourquoi c’est plus facile qu’au sol.","Le mani rialzate riducono il carico su spalle e addome, per questo è più facile che a terra.","Erhöhte Hände entlasten Schultern und Bauch; deshalb ist es leichter als am Boden."],
  ["Lento y controlado es la clave de esta variante.","Slow and controlled is the key to this variation.","Lento e controlado é a chave desta variação.","Lent et contrôlé, c’est la clé de cette variante.","Lento e controllato è la chiave di questa variante.","Langsam und kontrolliert ist das A und O dieser Variante."],
  ["Bajá la altura de la superficie para progresar.","Lower the height of the surface to progress.","Reduza a altura da superfície para progredir.","Abaisse la hauteur de la surface pour progresser.","Abbassa l’altezza della superficie per progredire.","Senk zum Steigern die Höhe der Fläche."],
  ["Oblicuos y recto abdominal","Obliques and rectus abdominis","Oblíquos e reto abdominal","Obliques et grand droit de l’abdomen","Obliqui e retto addominale","Schräge Bauchmuskeln und gerader Bauchmuskel"],
  ["Flexores de cadera","Hip flexors","Flexores do quadril","Fléchisseurs de hanche","Flessori dell’anca","Hüftbeuger"],
  ["Acostate boca arriba con las manos junto a las sienes, hombros apenas elevados y rodillas flexionadas a 90 grados sobre la cadera.","Lie on your back with your hands by your temples, shoulders slightly raised and knees bent at 90 degrees over your hips.","Deite-se de barriga para cima com as mãos junto às têmporas, ombros levemente elevados e joelhos flexionados a 90 graus sobre o quadril.","Allonge-toi sur le dos, mains près des tempes, épaules légèrement décollées et genoux fléchis à 90 degrés au-dessus des hanches.","Sdraiati a pancia in su con le mani vicino alle tempie, spalle appena sollevate e ginocchia piegate a 90 gradi sopra le anche.","Leg dich auf den Rücken, Hände an den Schläfen, Schultern leicht angehoben, Knie im 90-Grad-Winkel über der Hüfte."],
  ["Exhalá en cada giro e inhalá al volver al centro.","Exhale on each twist and inhale as you return to the center.","Expire a cada giro e inspire ao voltar ao centro.","Expire à chaque rotation et inspire en revenant au centre.","Espira a ogni torsione e inspira tornando al centro.","Atme bei jeder Drehung aus und beim Zurückkehren zur Mitte ein."],
  ["Apoyá la zona lumbar y elevá apenas los omóplatos del suelo.","Rest your lower back on the floor and lift your shoulder blades slightly.","Apoie a lombar e eleve levemente as escápulas do chão.","Pose le bas du dos au sol et décolle légèrement les omoplates.","Appoggia la zona lombare e solleva appena le scapole da terra.","Leg den unteren Rücken ab und heb die Schulterblätter leicht an."],
  ["Girá el tronco llevando el codo hacia la rodilla contraria mientras extendés la otra pierna.","Rotate your torso, bringing your elbow toward the opposite knee while extending the other leg.","Gire o tronco levando o cotovelo em direção ao joelho oposto enquanto estende a outra perna.","Fais pivoter le buste en amenant le coude vers le genou opposé tout en tendant l’autre jambe.","Ruota il busto portando il gomito verso il ginocchio opposto mentre distendi l’altra gamba.","Dreh den Oberkörper und führ den Ellbogen zum gegenüberliegenden Knie, während du das andere Bein streckst."],
  ["Volvé al centro con control.","Return to the center with control.","Volte ao centro com controle.","Reviens au centre en contrôle.","Torna al centro con controllo.","Kehr kontrolliert zur Mitte zurück."],
  ["Repetí hacia el otro lado, alternando de forma lenta.","Repeat to the other side, alternating slowly.","Repita para o outro lado, alternando de forma lenta.","Recommence de l’autre côté, en alternant lentement.","Ripeti dall’altro lato, alternando lentamente.","Wiederhol es zur anderen Seite und wechsle langsam ab."],
  ["Tirar del cuello con las manos.","Pulling on your neck with your hands.","Puxar o pescoço com as mãos.","Tirer sur la nuque avec les mains.","Tirare il collo con le mani.","Mit den Händen am Nacken ziehen."],
  ["Mover solo los codos sin girar el tronco.","Moving only your elbows without rotating your torso.","Mover só os cotovelos sem girar o tronco.","Bouger seulement les coudes sans faire pivoter le buste.","Muovere solo i gomiti senza ruotare il busto.","Nur die Ellbogen bewegen, ohne den Oberkörper zu drehen."],
  ["Hacerlo rápido y perder el control de la zona lumbar.","Doing it fast and losing control of your lower back.","Fazer rápido e perder o controle da lombar.","Le faire vite et perdre le contrôle du bas du dos.","Farlo veloce e perdere il controllo della zona lombare.","Es schnell machen und die Kontrolle über den unteren Rücken verlieren."],
  ["El giro sale del tronco: llevá el hombro hacia la rodilla.","The twist comes from your torso: bring your shoulder toward your knee.","O giro sai do tronco: leve o ombro em direção ao joelho.","La rotation vient du buste : amène l’épaule vers le genou.","La torsione parte dal busto: porta la spalla verso il ginocchio.","Die Drehung kommt aus dem Oberkörper: Bring die Schulter zum Knie."],
  ["Extender la pierna más arriba lo hace más fácil.","Extending your leg higher makes it easier.","Estender a perna mais alto deixa mais fácil.","Tendre la jambe plus haut rend l’exercice plus facile.","Distendere la gamba più in alto lo rende più facile.","Wenn du das Bein höher streckst, wird es leichter."],
  ["Una pausa breve en cada giro aumenta el trabajo de los oblicuos.","A brief pause on each twist increases the work for your obliques.","Uma pausa breve em cada giro aumenta o trabalho dos oblíquos.","Une courte pause à chaque rotation augmente le travail des obliques.","Una breve pausa a ogni torsione aumenta il lavoro degli obliqui.","Eine kurze Pause bei jeder Drehung fordert die schrägen Bauchmuskeln stärker."],
  ["Flexores de cadera y recto abdominal","Hip flexors and rectus abdominis","Flexores do quadril e reto abdominal","Fléchisseurs de hanche et grand droit de l’abdomen","Flessori dell’anca e retto addominale","Hüftbeuger und gerader Bauchmuskel"],
  ["Oblicuos y estabilizadores de la pierna de apoyo","Obliques and stabilizers of the standing leg","Oblíquos e estabilizadores da perna de apoio","Obliques et stabilisateurs de la jambe d’appui","Obliqui e stabilizzatori della gamba d’appoggio","Schräge Bauchmuskeln und Stabilisatoren des Standbeins"],
  ["Peso corporal; opcionalmente una pared o silla firme para apoyar la mano","Bodyweight; optionally a wall or sturdy chair to rest your hand on","Peso corporal; opcionalmente uma parede ou cadeira firme para apoiar a mão","Poids du corps ; éventuellement un mur ou une chaise solide pour poser la main","Corpo libero; facoltativamente una parete o una sedia stabile per appoggiare la mano","Körpergewicht; optional eine Wand oder ein stabiler Stuhl zum Abstützen der Hand"],
  ["Parate erguido con los pies al ancho de cadera, abdomen firme y una mano cerca de un apoyo si lo necesitás.","Stand tall with your feet hip-width apart, abs braced and one hand near a support if you need it.","Fique ereto com os pés na largura do quadril, abdômen firme e uma mão perto de um apoio se precisar.","Tiens-toi droit, pieds à la largeur des hanches, abdos gainés et une main près d’un appui si besoin.","Mettiti dritto con i piedi alla larghezza delle anche, addome contratto e una mano vicino a un appoggio se ti serve.","Stell dich aufrecht hin, Füße hüftbreit, Bauch angespannt, eine Hand bei Bedarf nahe an einer Stütze."],
  ["Exhalá al subir la rodilla e inhalá al bajarla.","Exhale as you raise your knee and inhale as you lower it.","Expire ao subir o joelho e inspire ao abaixá-lo.","Expire en montant le genou et inspire en l’abaissant.","Espira sollevando il ginocchio e inspira abbassandolo.","Atme beim Heben des Knies aus und beim Senken ein."],
  ["Afirmá el abdomen y mantené el tronco erguido.","Brace your abs and keep your torso upright.","Firme o abdômen e mantenha o tronco ereto.","Gaine les abdos et garde le buste droit.","Contrai l’addome e mantieni il busto eretto.","Spann den Bauch an und halte den Oberkörper aufrecht."],
  ["Elevá una rodilla hacia el pecho hasta la altura de la cadera o un poco más, enrollando apenas la pelvis.","Raise one knee toward your chest to hip height or slightly higher, curling your pelvis slightly.","Eleve um joelho em direção ao peito até a altura do quadril ou um pouco mais, enrolando levemente a pelve.","Monte un genou vers la poitrine jusqu’à hauteur de hanche ou un peu plus, en enroulant légèrement le bassin.","Solleva un ginocchio verso il petto fino all’altezza dell’anca o poco più, arrotolando appena il bacino.","Heb ein Knie bis auf Hüfthöhe oder etwas höher zur Brust und roll das Becken leicht ein."],
  ["Bajá el pie con control.","Lower your foot with control.","Abaixe o pé com controle.","Repose le pied en contrôle.","Abbassa il piede con controllo.","Setz den Fuß kontrolliert ab."],
  ["Inclinar el tronco hacia atrás para subir la rodilla.","Leaning your torso back to raise your knee.","Inclinar o tronco para trás para subir o joelho.","Pencher le buste en arrière pour monter le genou.","Inclinare il busto indietro per sollevare il ginocchio.","Den Oberkörper nach hinten lehnen, um das Knie zu heben."],
  ["Hacer el movimiento con impulso.","Doing the movement with momentum.","Fazer o movimento com impulso.","Faire le mouvement avec de l’élan.","Fare il movimento con slancio.","Die Bewegung mit Schwung ausführen."],
  ["Encorvar los hombros.","Hunching your shoulders.","Curvar os ombros.","Voûter les épaules.","Incurvare le spalle.","Die Schultern nach vorn ziehen."],
  ["Una pausa breve arriba aumenta el trabajo del abdomen.","A brief pause at the top increases the work for your abs.","Uma pausa breve em cima aumenta o trabalho do abdômen.","Une courte pause en haut augmente le travail des abdos.","Una breve pausa in alto aumenta il lavoro dell’addome.","Eine kurze Pause oben fordert den Bauch stärker."],
  ["Apoyá una mano en la pared si perdés el equilibrio.","Put a hand on the wall if you lose your balance.","Apoie uma mão na parede se perder o equilíbrio.","Pose une main sur le mur si tu perds l’équilibre.","Appoggia una mano alla parete se perdi l’equilibrio.","Stütz eine Hand an die Wand, wenn du das Gleichgewicht verlierst."],
  ["Llevá el codo contrario hacia la rodilla para sumar oblicuos.","Bring the opposite elbow toward your knee to add obliques.","Leve o cotovelo contrário em direção ao joelho para incluir os oblíquos.","Amène le coude opposé vers le genou pour solliciter les obliques.","Porta il gomito opposto verso il ginocchio per coinvolgere gli obliqui.","Führ den gegenüberliegenden Ellbogen zum Knie, um die schrägen Bauchmuskeln mitzunehmen."],
  ["Estabilizadores de tobillo, rodilla y cadera","Ankle, knee and hip stabilizers","Estabilizadores do tornozelo, joelho e quadril","Stabilisateurs de la cheville, du genou et de la hanche","Stabilizzatori di caviglia, ginocchio e anca","Stabilisatoren von Sprunggelenk, Knie und Hüfte"],
  ["Glúteo medio, pantorrillas y core","Gluteus medius, calves and core","Glúteo médio, panturrilhas e core","Moyen fessier, mollets et sangle abdominale","Medio gluteo, polpacci e core","Mittlerer Gesäßmuskel, Waden und Rumpf"],
  ["Pared, mesada o silla firme al alcance de la mano","Wall, countertop or sturdy chair within reach","Parede, bancada ou cadeira firme ao alcance da mão","Mur, plan de travail ou chaise solide à portée de main","Parete, piano di lavoro o sedia stabile a portata di mano","Wand, Arbeitsplatte oder stabiler Stuhl in Reichweite"],
  ["Parate al lado de un apoyo firme, con una mano cerca o apenas apoyada, y el peso repartido en ambos pies.","Stand next to a sturdy support, one hand close to it or lightly resting on it, with your weight spread over both feet.","Fique ao lado de um apoio firme, com uma mão perto ou levemente apoiada, e o peso distribuído nos dois pés.","Tiens-toi à côté d’un appui solide, une main proche ou à peine posée, le poids réparti sur les deux pieds.","Mettiti accanto a un appoggio stabile, con una mano vicina o appena appoggiata, e il peso distribuito su entrambi i piedi.","Stell dich neben eine feste Stütze, eine Hand nah dran oder leicht aufgelegt, das Gewicht auf beide Füße verteilt."],
  ["Respirá de forma pareja y relajada durante todo el sostén.","Breathe evenly and relaxed throughout the hold.","Respire de forma regular e relaxada durante toda a sustentação.","Respire de façon régulière et détendue pendant tout le maintien.","Respira in modo regolare e rilassato per tutta la tenuta.","Atme während des ganzen Haltens gleichmäßig und entspannt."],
  ["Sin pausa obligatoria; alterná lados","No set rest needed; alternate sides","Sem pausa obrigatória; alterne os lados","Pas de pause obligatoire ; alterne les côtés","Nessuna pausa obbligatoria; alterna i lati","Keine feste Pause nötig; Seiten abwechseln"],
  ["Pasá el peso a un pie y levantá el otro unos centímetros del suelo.","Shift your weight to one foot and lift the other a few centimeters off the floor.","Passe o peso para um pé e levante o outro alguns centímetros do chão.","Transfère le poids sur un pied et lève l’autre de quelques centimètres.","Sposta il peso su un piede e solleva l’altro di qualche centimetro da terra.","Verlager das Gewicht auf einen Fuß und heb den anderen ein paar Zentimeter vom Boden."],
  ["Sostené la posición con la rodilla de apoyo suave, la cadera nivelada y la mirada en un punto fijo, respirando con calma.","Hold the position with your standing knee soft, hips level and eyes on a fixed point, breathing calmly.","Sustente a posição com o joelho de apoio solto, o quadril nivelado e o olhar em um ponto fixo, respirando com calma.","Tiens la position, genou d’appui souple, hanches à niveau et regard sur un point fixe, en respirant calmement.","Mantieni la posizione con il ginocchio d’appoggio morbido, le anche in piano e lo sguardo su un punto fisso, respirando con calma.","Halte die Position mit weichem Standknie, waagerechter Hüfte und Blick auf einen festen Punkt und atme ruhig."],
  ["Tocá el apoyo con la mano cada vez que lo necesites.","Touch the support with your hand whenever you need to.","Toque o apoio com a mão sempre que precisar.","Touche l’appui avec la main chaque fois que tu en as besoin.","Tocca l’appoggio con la mano ogni volta che ti serve.","Berühr die Stütze mit der Hand, wann immer du sie brauchst."],
  ["Apoyá el pie libre con control para terminar y repetí del otro lado.","Set your free foot down with control to finish and repeat on the other side.","Apoie o pé livre com controle para terminar e repita do outro lado.","Repose le pied libre en contrôle pour finir et recommence de l’autre côté.","Appoggia il piede libero con controllo per finire e ripeti dall’altro lato.","Setz den freien Fuß zum Abschluss kontrolliert ab und wiederhol es auf der anderen Seite."],
  ["Alejarse del apoyo antes de tener control.","Moving away from the support before you have control.","Afastar-se do apoio antes de ter controle.","S’éloigner de l’appui avant d’avoir le contrôle.","Allontanarsi dall’appoggio prima di avere il controllo.","Sich von der Stütze entfernen, bevor du die Kontrolle hast."],
  ["Dejar caer la cadera del lado de la pierna levantada.","Letting your hip drop on the side of the raised leg.","Deixar o quadril cair do lado da perna levantada.","Laisser tomber la hanche du côté de la jambe levée.","Lasciar cadere l’anca dal lato della gamba sollevata.","Die Hüfte auf der Seite des angehobenen Beins absinken lassen."],
  ["Bloquear la rodilla de apoyo con fuerza.","Forcefully locking your standing knee.","Travar o joelho de apoio com força.","Verrouiller le genou d’appui en force.","Bloccare con forza il ginocchio d’appoggio.","Das Standknie kräftig durchdrücken."],
  ["El apoyo cercano permite practicar sin riesgo de caída; usalo sin culpa.","A nearby support lets you practice without the risk of falling; use it without guilt.","O apoio próximo permite praticar sem risco de queda; use-o sem culpa.","Un appui à proximité permet de t’entraîner sans risque de chute ; utilise-le sans culpabiliser.","L’appoggio vicino permette di esercitarti senza rischio di cadere; usalo senza sensi di colpa.","Die Stütze in der Nähe lässt dich ohne Sturzrisiko üben; nutz sie ohne schlechtes Gewissen."],
  ["Para progresar, sostené sin manos o cerrá los ojos solo si estás junto al apoyo.","To progress, hold without hands, or close your eyes only if you are next to the support.","Para progredir, sustente sem as mãos ou feche os olhos só se estiver junto ao apoio.","Pour progresser, tiens sans les mains, ou ferme les yeux seulement si tu es à côté de l’appui.","Per progredire, mantieni senza mani o chiudi gli occhi solo se sei vicino all’appoggio.","Zum Steigern halte ohne Hände oder schließ die Augen, aber nur direkt neben der Stütze."],
  ["Hacelo descalzo o con calzado plano sobre una superficie que no resbale.","Do it barefoot or in flat shoes on a non-slip surface.","Faça descalço ou com calçado baixo sobre uma superfície que não escorregue.","Fais-le pieds nus ou en chaussures plates sur une surface antidérapante.","Fallo a piedi nudi o con scarpe basse su una superficie che non scivoli.","Mach es barfuß oder in flachen Schuhen auf rutschfestem Untergrund."],
  ["Sistema cardiovascular; flexores de cadera y cuádriceps","Cardiovascular system; hip flexors and quadriceps","Sistema cardiovascular; flexores do quadril e quadríceps","Système cardiovasculaire ; fléchisseurs de hanche et quadriceps","Sistema cardiovascolare; flessori dell’anca e quadricipiti","Herz-Kreislauf-System; Hüftbeuger und Quadrizeps"],
  ["Abdominales, glúteos y pantorrillas","Abs, glutes and calves","Abdominais, glúteos e panturrilhas","Abdominaux, fessiers et mollets","Addominali, glutei e polpacci","Bauchmuskeln, Gesäß und Waden"],
  ["Parate erguido con los pies al ancho de cadera y los brazos flexionados a los costados.","Stand tall with your feet hip-width apart and your arms bent at your sides.","Fique ereto com os pés na largura do quadril e os braços flexionados ao lado do corpo.","Tiens-toi droit, pieds à la largeur des hanches et bras fléchis le long du corps.","Mettiti dritto con i piedi alla larghezza delle anche e le braccia piegate lungo i fianchi.","Stell dich aufrecht hin, Füße hüftbreit, Arme seitlich gebeugt."],
  ["Respirá de forma rítmica; si no podés decir una frase corta, bajá el ritmo.","Breathe rhythmically; if you can’t say a short sentence, slow the pace.","Respire de forma rítmica; se não conseguir dizer uma frase curta, reduza o ritmo.","Respire en rythme ; si tu ne peux pas dire une phrase courte, ralentis.","Respira in modo ritmico; se non riesci a dire una frase breve, rallenta.","Atme rhythmisch; wenn du keinen kurzen Satz sagen kannst, werde langsamer."],
  ["Empezá con una marcha suave para entrar en calor.","Start with an easy march to warm up.","Comece com uma marcha leve para aquecer.","Commence par une marche douce pour t’échauffer.","Inizia con una marcia leggera per scaldarti.","Beginne zum Aufwärmen mit lockerem Marschieren."],
  ["Elevá cada rodilla hasta la altura de la cadera, alternando, sin saltar.","Raise each knee to hip height, alternating, without jumping.","Eleve cada joelho até a altura do quadril, alternando, sem saltar.","Monte chaque genou à hauteur de hanche, en alternant, sans sauter.","Solleva ogni ginocchio fino all’altezza dell’anca, alternando, senza saltare.","Heb abwechselnd jedes Knie auf Hüfthöhe, ohne zu springen."],
  ["Acompañá con los brazos y mantené el tronco erguido a un ritmo en el que puedas hablar en frases cortas (prueba del habla).","Swing your arms along and keep your torso upright at a pace where you can talk in short sentences (talk test).","Acompanhe com os braços e mantenha o tronco ereto em um ritmo em que consiga falar frases curtas (teste da fala).","Accompagne avec les bras et garde le buste droit à un rythme où tu peux parler par phrases courtes (test de la parole).","Accompagna con le braccia e mantieni il busto eretto a un ritmo in cui riesci a parlare a frasi brevi (test del parlato).","Schwing die Arme mit und halte den Oberkörper aufrecht, in einem Tempo, bei dem du in kurzen Sätzen sprechen kannst (Sprechtest)."],
  ["Bajá la altura de las rodillas y la velocidad durante el último minuto.","Lower your knee height and speed during the last minute.","Reduza a altura dos joelhos e a velocidade durante o último minuto.","Réduis la hauteur des genoux et la vitesse pendant la dernière minute.","Riduci l’altezza delle ginocchia e la velocità durante l’ultimo minuto.","Reduzier in der letzten Minute Kniehöhe und Tempo."],
  ["Inclinar el tronco hacia atrás para subir las rodillas.","Leaning your torso back to raise your knees.","Inclinar o tronco para trás para subir os joelhos.","Pencher le buste en arrière pour monter les genoux.","Inclinare il busto indietro per sollevare le ginocchia.","Den Oberkörper nach hinten lehnen, um die Knie zu heben."],
  ["Convertirlo en un trote con saltos.","Turning it into a jog with jumps.","Transformar em uma corrida com saltos.","En faire un trot avec des sauts.","Trasformarlo in una corsetta con salti.","Einen Hüpflauf daraus machen."],
  ["Mantener siempre un pie en el suelo lo hace de bajo impacto.","Always keeping one foot on the floor makes it low impact.","Manter sempre um pé no chão torna o exercício de baixo impacto.","Garder toujours un pied au sol en fait un exercice à faible impact.","Tenere sempre un piede a terra lo rende a basso impatto.","Da immer ein Fuß am Boden bleibt, ist es gelenkschonend."],
  ["Si perdés el equilibrio, hacelo cerca de una pared.","If you lose your balance, do it near a wall.","Se perder o equilíbrio, faça perto de uma parede.","Si tu perds l’équilibre, fais-le près d’un mur.","Se perdi l’equilibrio, fallo vicino a una parete.","Wenn du das Gleichgewicht verlierst, mach es nahe an einer Wand."],
  ["Subí la intensidad con más altura de rodilla, no con saltos.","Increase the intensity with higher knees, not with jumps.","Aumente a intensidade com mais altura de joelho, não com saltos.","Augmente l’intensité en montant les genoux plus haut, pas en sautant.","Aumenta l’intensità con le ginocchia più alte, non con i salti.","Steigere die Intensität mit höheren Knien, nicht mit Sprüngen."],
  ["Sistema cardiovascular; glúteo medio y cuádriceps","Cardiovascular system; gluteus medius and quadriceps","Sistema cardiovascular; glúteo médio e quadríceps","Système cardiovasculaire ; moyen fessier et quadriceps","Sistema cardiovascolare; medio gluteo e quadricipiti","Herz-Kreislauf-System; mittlerer Gesäßmuskel und Quadrizeps"],
  ["Aductores, pantorrillas y hombros","Adductors, calves and shoulders","Adutores, panturrilhas e ombros","Adducteurs, mollets et épaules","Adduttori, polpacci e spalle","Adduktoren, Waden und Schultern"],
  ["Peso corporal y espacio despejado a los costados","Bodyweight and clear space to the sides","Peso corporal e espaço livre dos lados","Poids du corps et espace dégagé sur les côtés","Corpo libero e spazio libero ai lati","Körpergewicht und freier Platz zu beiden Seiten"],
  ["Parate con los pies juntos, rodillas suaves y brazos relajados.","Stand with your feet together, knees soft and arms relaxed.","Fique com os pés juntos, joelhos soltos e braços relaxados.","Tiens-toi pieds joints, genoux souples et bras détendus.","Mettiti con i piedi uniti, ginocchia morbide e braccia rilassate.","Stell dich mit geschlossenen Füßen hin, Knie weich, Arme locker."],
  ["Respirá de forma rítmica y continua.","Breathe rhythmically and continuously.","Respire de forma rítmica e contínua.","Respire en rythme et en continu.","Respira in modo ritmico e continuo.","Atme rhythmisch und gleichmäßig."],
  ["Dá un paso amplio hacia un costado y juntá el otro pie, sin saltar.","Take a wide step to the side and bring the other foot in, without jumping.","Dê um passo amplo para o lado e junte o outro pé, sem saltar.","Fais un grand pas sur le côté et ramène l’autre pied, sans sauter.","Fai un ampio passo di lato e avvicina l’altro piede, senza saltare.","Mach einen weiten Schritt zur Seite und zieh den anderen Fuß nach, ohne zu springen."],
  ["Repetí hacia el otro lado, sumando movimientos de brazos si te resulta cómodo.","Repeat to the other side, adding arm movements if comfortable.","Repita para o outro lado, incluindo movimentos de braços se for confortável.","Recommence de l’autre côté, en ajoutant des mouvements de bras si c’est confortable.","Ripeti dall’altro lato, aggiungendo movimenti delle braccia se ti risulta comodo.","Wiederhol es zur anderen Seite und nimm Armbewegungen dazu, wenn es sich gut anfühlt."],
  ["Ajustá el ritmo y la amplitud a un esfuerzo en el que puedas hablar en frases cortas (prueba del habla).","Adjust the pace and range to an effort where you can talk in short sentences (talk test).","Ajuste o ritmo e a amplitude a um esforço em que consiga falar frases curtas (teste da fala).","Ajuste le rythme et l’amplitude à un effort où tu peux parler par phrases courtes (test de la parole).","Regola ritmo e ampiezza su uno sforzo in cui riesci a parlare a frasi brevi (test del parlato).","Pass Tempo und Schrittweite an eine Belastung an, bei der du in kurzen Sätzen sprechen kannst (Sprechtest)."],
  ["Bajá el ritmo gradualmente al final.","Slow the pace gradually at the end.","Reduza o ritmo gradualmente no final.","Ralentis progressivement à la fin.","Rallenta gradualmente alla fine.","Werde am Ende nach und nach langsamer."],
  ["Cruzar los pies al moverse.","Crossing your feet as you move.","Cruzar os pés ao se mover.","Croiser les pieds en te déplaçant.","Incrociare i piedi mentre ti muovi.","Beim Bewegen die Füße überkreuzen."],
  ["Moverse en un espacio con obstáculos.","Moving in a space with obstacles.","Mover-se em um espaço com obstáculos.","Bouger dans un espace encombré.","Muoversi in uno spazio con ostacoli.","Sich in einem Raum mit Hindernissen bewegen."],
  ["Flexionar un poco más las rodillas aumenta el trabajo de piernas.","Bending your knees a little more increases the work for your legs.","Flexionar um pouco mais os joelhos aumenta o trabalho das pernas.","Fléchir un peu plus les genoux augmente le travail des jambes.","Piegare un po’ di più le ginocchia aumenta il lavoro delle gambe.","Wenn du die Knie etwas mehr beugst, arbeiten die Beine stärker."],
  ["Mirá al frente y mantené el pecho abierto.","Look ahead and keep your chest open.","Olhe para frente e mantenha o peito aberto.","Regarde devant toi et garde la poitrine ouverte.","Guarda avanti e mantieni il petto aperto.","Schau nach vorn und halte die Brust offen."],
  ["Despejá el espacio a ambos lados antes de empezar.","Clear the space on both sides before you start.","Libere o espaço dos dois lados antes de começar.","Dégage l’espace des deux côtés avant de commencer.","Libera lo spazio su entrambi i lati prima di iniziare.","Räum den Platz zu beiden Seiten frei, bevor du startest."],
  ["Sistema cardiovascular; hombros y piernas","Cardiovascular system; shoulders and legs","Sistema cardiovascular; ombros e pernas","Système cardiovasculaire ; épaules et jambes","Sistema cardiovascolare; spalle e gambe","Herz-Kreislauf-System; Schultern und Beine"],
  ["Parate con los pies juntos y los brazos a los costados.","Stand with your feet together and your arms at your sides.","Fique com os pés juntos e os braços ao lado do corpo.","Tiens-toi pieds joints et bras le long du corps.","Mettiti con i piedi uniti e le braccia lungo i fianchi.","Stell dich mit geschlossenen Füßen hin, Arme seitlich."],
  ["Respirá de forma rítmica; exhalá al subir los brazos si te ayuda a llevar el ritmo.","Breathe rhythmically; exhale as you raise your arms if it helps you keep the rhythm.","Respire de forma rítmica; expire ao subir os braços se isso ajudar a manter o ritmo.","Respire en rythme ; expire en levant les bras si cela t’aide à garder le rythme.","Respira in modo ritmico; espira sollevando le braccia se ti aiuta a tenere il ritmo.","Atme rhythmisch; atme beim Heben der Arme aus, wenn dir das hilft, im Takt zu bleiben."],
  ["Dá un paso hacia el costado con un pie mientras elevás los brazos por los costados hacia arriba.","Step to the side with one foot while raising your arms out to the sides and up.","Dê um passo para o lado com um pé enquanto eleva os braços pelas laterais para cima.","Fais un pas sur le côté avec un pied tout en levant les bras par les côtés vers le haut.","Fai un passo di lato con un piede mentre sollevi le braccia lateralmente verso l’alto.","Mach mit einem Fuß einen Schritt zur Seite und heb dabei die Arme seitlich nach oben."],
  ["Volvé a juntar los pies bajando los brazos, sin saltar.","Bring your feet back together while lowering your arms, without jumping.","Volte a juntar os pés abaixando os braços, sem saltar.","Ramène les pieds ensemble en baissant les bras, sans sauter.","Riunisci i piedi abbassando le braccia, senza saltare.","Schließ die Füße wieder und senk dabei die Arme, ohne zu springen."],
  ["Repetí hacia el otro lado, alternando, a un ritmo en el que puedas hablar en frases cortas (prueba del habla).","Repeat to the other side, alternating, at a pace where you can talk in short sentences (talk test).","Repita para o outro lado, alternando, em um ritmo em que consiga falar frases curtas (teste da fala).","Recommence de l’autre côté, en alternant, à un rythme où tu peux parler par phrases courtes (test de la parole).","Ripeti dall’altro lato, alternando, a un ritmo in cui riesci a parlare a frasi brevi (test del parlato).","Wiederhol es abwechselnd zur anderen Seite, in einem Tempo, bei dem du in kurzen Sätzen sprechen kannst (Sprechtest)."],
  ["Bajá la velocidad gradualmente al final.","Slow down gradually at the end.","Reduza a velocidade gradualmente no final.","Ralentis progressivement à la fin.","Rallenta gradualmente alla fine.","Werde am Ende nach und nach langsamer."],
  ["Saltar en lugar de dar pasos.","Jumping instead of stepping.","Saltar em vez de dar passos.","Sauter au lieu de faire des pas.","Saltare invece di fare passi.","Springen statt Schritte zu machen."],
  ["Encoger los hombros al subir los brazos.","Shrugging your shoulders as you raise your arms.","Encolher os ombros ao subir os braços.","Hausser les épaules en levant les bras.","Sollevare le spalle alzando le braccia.","Beim Heben der Arme die Schultern hochziehen."],
  ["Dar pasos sobre la punta del pie sin apoyar el talón.","Stepping on your toes without putting your heel down.","Dar passos na ponta do pé sem apoiar o calcanhar.","Faire les pas sur la pointe des pieds sans poser le talon.","Fare i passi sulla punta del piede senza appoggiare il tallone.","Auf den Zehenspitzen gehen, ohne die Ferse aufzusetzen."],
  ["Reemplazar el salto por un paso reduce el impacto en articulaciones.","Replacing the jump with a step reduces the impact on your joints.","Trocar o salto por um passo reduz o impacto nas articulações.","Remplacer le saut par un pas réduit l’impact sur les articulations.","Sostituire il salto con un passo riduce l’impatto sulle articolazioni.","Einen Schritt statt eines Sprungs zu machen schont die Gelenke."],
  ["Si los hombros molestan, subí los brazos solo hasta la altura de los hombros.","If your shoulders bother you, raise your arms only to shoulder height.","Se os ombros incomodarem, suba os braços só até a altura dos ombros.","Si tes épaules te gênent, lève les bras seulement jusqu’à hauteur des épaules.","Se le spalle danno fastidio, solleva le braccia solo fino all’altezza delle spalle.","Wenn die Schultern zwicken, heb die Arme nur bis auf Schulterhöhe."],
  ["Mantené las rodillas suaves y alineadas con los pies.","Keep your knees soft and aligned with your feet.","Mantenha os joelhos soltos e alinhados com os pés.","Garde les genoux souples et alignés avec les pieds.","Mantieni le ginocchia morbide e allineate con i piedi.","Halte die Knie weich und in einer Linie mit den Füßen."],
  ["Deltoides y manguito rotador","Deltoids and rotator cuff","Deltoides e manguito rotador","Deltoïdes et coiffe des rotateurs","Deltoidi e cuffia dei rotatori","Deltamuskeln und Rotatorenmanschette"],
  ["Trapecio y estabilizadores escapulares","Trapezius and scapular stabilizers","Trapézio e estabilizadores escapulares","Trapèzes et stabilisateurs de l’omoplate","Trapezio e stabilizzatori scapolari","Trapezmuskel und Schulterblattstabilisatoren"],
  ["Parate erguido con los pies al ancho de cadera y los brazos extendidos hacia los costados a la altura de los hombros.","Stand tall with your feet hip-width apart and your arms extended out to the sides at shoulder height.","Fique ereto com os pés na largura do quadril e os braços estendidos para os lados na altura dos ombros.","Tiens-toi droit, pieds à la largeur des hanches et bras tendus sur les côtés à hauteur des épaules.","Mettiti dritto con i piedi alla larghezza delle anche e le braccia distese lateralmente all’altezza delle spalle.","Stell dich aufrecht hin, Füße hüftbreit, Arme auf Schulterhöhe zur Seite gestreckt."],
  ["Respirá de forma pareja y relajada durante el movimiento.","Breathe evenly and relaxed during the movement.","Respire de forma regular e relaxada durante o movimento.","Respire de façon régulière et détendue pendant le mouvement.","Respira in modo regolare e rilassato durante il movimento.","Atme während der Bewegung gleichmäßig und entspannt."],
  ["Empezá con círculos pequeños hacia adelante, lentos y controlados.","Start with small forward circles, slow and controlled.","Comece com círculos pequenos para frente, lentos e controlados.","Commence par de petits cercles vers l’avant, lents et contrôlés.","Inizia con piccoli cerchi in avanti, lenti e controllati.","Beginne mit kleinen Kreisen nach vorn, langsam und kontrolliert."],
  ["Agrandá los círculos de a poco hasta un rango cómodo, sin dolor.","Gradually make the circles bigger to a comfortable range, without pain.","Aumente os círculos aos poucos até uma amplitude confortável, sem dor.","Agrandis progressivement les cercles jusqu’à une amplitude confortable, sans douleur.","Allarga poco a poco i cerchi fino a un’ampiezza comoda, senza dolore.","Vergrößere die Kreise nach und nach bis zu einem angenehmen Bewegungsumfang, ohne Schmerz."],
  ["Después de unos segundos, cambiá la dirección hacia atrás.","After a few seconds, switch direction to backward.","Depois de alguns segundos, mude a direção para trás.","Après quelques secondes, change de sens vers l’arrière.","Dopo qualche secondo, cambia direzione all’indietro.","Wechsle nach ein paar Sekunden die Richtung nach hinten."],
  ["Terminá bajando los brazos despacio a los costados.","Finish by slowly lowering your arms to your sides.","Termine abaixando os braços devagar ao lado do corpo.","Termine en abaissant lentement les bras le long du corps.","Termina abbassando lentamente le braccia lungo i fianchi.","Senk zum Abschluss die Arme langsam an die Seiten."],
  ["Hacer círculos grandes y rápidos de entrada.","Doing big, fast circles right away.","Fazer círculos grandes e rápidos logo de cara.","Faire de grands cercles rapides d’emblée.","Fare subito cerchi grandi e veloci.","Gleich zu Beginn große, schnelle Kreise machen."],
  ["Movimiento lento, sin rebotes ni tirones.","Slow movement, without bouncing or jerking.","Movimento lento, sem quiques nem puxões.","Mouvement lent, sans rebond ni à-coup.","Movimento lento, senza rimbalzi né strattoni.","Langsame Bewegung ohne Federn oder Reißen."],
  ["Si el hombro molesta, reducí el tamaño del círculo.","If your shoulder bothers you, make the circle smaller.","Se o ombro incomodar, reduza o tamanho do círculo.","Si ton épaule te gêne, réduis la taille du cercle.","Se la spalla dà fastidio, riduci la dimensione del cerchio.","Wenn die Schulter zwickt, mach die Kreise kleiner."],
  ["Sirve como entrada en calor antes de ejercicios de tren superior.","It works as a warm-up before upper-body exercises.","Serve como aquecimento antes de exercícios de membros superiores.","Il sert d’échauffement avant les exercices du haut du corps.","Serve come riscaldamento prima degli esercizi per la parte superiore.","Eignet sich zum Aufwärmen vor Oberkörperübungen."],
  ["Pantorrillas (gastrocnemio y sóleo) y articulación del tobillo","Calves (gastrocnemius and soleus) and ankle joint","Panturrilhas (gastrocnêmio e sóleo) e articulação do tornozelo","Mollets (gastrocnémien et soléaire) et articulation de la cheville","Polpacci (gastrocnemio e soleo) e articolazione della caviglia","Waden (Gastrocnemius und Soleus) und Sprunggelenk"],
  ["Tibial anterior y estabilizadores del pie","Tibialis anterior and foot stabilizers","Tibial anterior e estabilizadores do pé","Tibial antérieur et stabilisateurs du pied","Tibiale anteriore e stabilizzatori del piede","Vorderer Schienbeinmuskel und Fußstabilisatoren"],
  ["Parate frente a una pared en posición de paso, con el pie de adelante a unos centímetros de la pared y las manos apoyadas en ella.","Stand facing a wall in a split stance, front foot a few centimeters from the wall and hands on it.","Fique de frente para uma parede em posição de passo, com o pé da frente a alguns centímetros da parede e as mãos apoiadas nela.","Tiens-toi face à un mur en position de fente, pied avant à quelques centimètres du mur et mains posées dessus.","Mettiti di fronte a una parete in posizione di passo, con il piede anteriore a pochi centimetri dalla parete e le mani appoggiate.","Stell dich in Schrittstellung vor eine Wand, den vorderen Fuß ein paar Zentimeter davor, Hände an der Wand."],
  ["Respirá de forma pareja; exhalá al llevar la rodilla hacia la pared.","Breathe evenly; exhale as you bring your knee toward the wall.","Respire de forma regular; expire ao levar o joelho em direção à parede.","Respire régulièrement ; expire en amenant le genou vers le mur.","Respira in modo regolare; espira portando il ginocchio verso la parete.","Atme gleichmäßig; atme aus, wenn du das Knie zur Wand führst."],
  ["Apoyá todo el pie de adelante en el suelo, con el talón firme.","Place your whole front foot on the floor, heel firmly down.","Apoie o pé da frente inteiro no chão, com o calcanhar firme.","Pose tout le pied avant au sol, talon bien ancré.","Appoggia tutto il piede anteriore a terra, con il tallone ben fermo.","Setz den ganzen vorderen Fuß auf, die Ferse bleibt fest am Boden."],
  ["Llevá la rodilla hacia la pared en línea con el segundo dedo del pie, sin despegar el talón.","Bring your knee toward the wall in line with your second toe, without lifting your heel.","Leve o joelho em direção à parede alinhado com o segundo dedo do pé, sem tirar o calcanhar.","Amène le genou vers le mur dans l’axe du deuxième orteil, sans décoller le talon.","Porta il ginocchio verso la parete in linea con il secondo dito del piede, senza staccare il tallone.","Führ das Knie in Linie mit dem zweiten Zeh zur Wand, ohne die Ferse anzuheben."],
  ["Volvé despacio y repetí de forma controlada, sin rebotes ni dolor.","Return slowly and repeat with control, without bouncing or pain.","Volte devagar e repita de forma controlada, sem quiques nem dor.","Reviens lentement et répète en contrôle, sans rebond ni douleur.","Torna lentamente e ripeti in modo controllato, senza rimbalzi né dolore.","Komm langsam zurück und wiederhol es kontrolliert, ohne Federn und ohne Schmerz."],
  ["Completá las repeticiones de un lado y después cambiá de pie.","Complete the reps on one side and then switch feet.","Complete as repetições de um lado e depois troque de pé.","Termine les répétitions d’un côté puis change de pied.","Completa le ripetizioni da un lato e poi cambia piede.","Mach die Wiederholungen auf einer Seite und wechsle dann den Fuß."],
  ["Despegar el talón del suelo.","Lifting your heel off the floor.","Tirar o calcanhar do chão.","Décoller le talon du sol.","Staccare il tallone da terra.","Die Ferse vom Boden abheben."],
  ["Dejar que la rodilla se vaya hacia adentro.","Letting your knee drift inward.","Deixar o joelho ir para dentro.","Laisser le genou partir vers l’intérieur.","Lasciare che il ginocchio vada verso l’interno.","Das Knie nach innen wandern lassen."],
  ["Forzar el rango con rebotes.","Forcing the range with bounces.","Forçar a amplitude com quiques.","Forcer l’amplitude avec des rebonds.","Forzare l’ampiezza con rimbalzi.","Den Bewegungsumfang mit Federn erzwingen."],
  ["Si tocás la pared con facilidad, alejá el pie un centímetro.","If you touch the wall easily, move your foot back a centimeter.","Se tocar a parede com facilidade, afaste o pé um centímetro.","Si tu touches le mur facilement, recule le pied d’un centimètre.","Se tocchi la parete con facilità, allontana il piede di un centimetro.","Wenn du die Wand leicht berührst, setz den Fuß einen Zentimeter weiter zurück."],
  ["Compará ambos lados para ver si uno tiene menos rango.","Compare both sides to see if one has less range.","Compare os dois lados para ver se um tem menos amplitude.","Compare les deux côtés pour voir si l’un a moins d’amplitude.","Confronta i due lati per vedere se uno ha meno ampiezza.","Vergleich beide Seiten, um zu sehen, ob eine weniger beweglich ist."],
  ["Es una buena preparación antes de sentadillas o zancadas.","It is good preparation before squats or lunges.","É uma boa preparação antes de agachamentos ou passadas.","C’est une bonne préparation avant les squats ou les fentes.","È una buona preparazione prima di squat o affondi.","Eine gute Vorbereitung vor Kniebeugen oder Ausfallschritten."],
  ["Recto abdominal y transverso abdominal como parte del sistema de estabilización","Rectus abdominis and transversus abdominis as part of the stabilizing system","Reto abdominal e transverso do abdômen como parte do sistema de estabilização","Grand droit et transverse de l’abdomen dans le cadre du système de stabilisation","Retto addominale e trasverso dell’addome come parte del sistema di stabilizzazione","Gerader und querer Bauchmuskel als Teil des Stabilisierungssystems"],
  ["Oblicuos, glúteos, serrato y hombros estabilizan","Obliques, glutes, serratus and shoulders stabilize","Oblíquos, glúteos, serrátil e ombros estabilizam","Obliques, fessiers, dentelé et épaules stabilisent","Obliqui, glutei, dentato e spalle stabilizzano","Schräge Bauchmuskeln, Gesäß, Sägemuskel und Schultern stabilisieren"],
  ["Colchoneta o suelo antideslizante","Mat or non-slip floor","Colchonete ou piso antiderrapante","Tapis ou sol antidérapant","Tappetino o pavimento antiscivolo","Matte oder rutschfester Boden"],
  ["Principiante; acortá tiempo o elevá el apoyo si lo necesitás","Beginner; shorten the time or raise your support if you need to","Iniciante; reduza o tempo ou eleve o apoio se precisar","Débutant ; réduis le temps ou surélève l’appui si besoin","Principiante; accorcia il tempo o alza l’appoggio se ti serve","Anfänger; verkürz die Zeit oder erhöh die Stütze, wenn nötig"],
  ["Respirá continua y suavemente durante toda la contracción; no aguantes el aire.","Breathe continuously and gently throughout the contraction; don’t hold your breath.","Respire de forma contínua e suave durante toda a contração; não prenda o ar.","Respire en continu et doucement pendant toute la contraction ; ne bloque pas ta respiration.","Respira in modo continuo e delicato per tutta la contrazione; non trattenere il respiro.","Atme während der ganzen Anspannung ruhig und gleichmäßig; halt nicht die Luft an."],
  ["Apoyá antebrazos debajo o apenas delante de los hombros y extendé las piernas, o apoyá rodillas para una variante fácil.","Place your forearms under or slightly in front of your shoulders and extend your legs, or rest on your knees for an easier variation.","Apoie os antebraços abaixo ou um pouco à frente dos ombros e estenda as pernas, ou apoie os joelhos para uma variação fácil.","Pose les avant-bras sous les épaules ou un peu devant et tends les jambes, ou pose les genoux pour une variante facile.","Appoggia gli avambracci sotto o poco davanti alle spalle e distendi le gambe, oppure appoggia le ginocchia per una variante facile.","Setz die Unterarme unter oder knapp vor die Schultern und streck die Beine, oder setz für eine leichte Variante die Knie auf."],
  ["Alineá cabeza, tronco y pelvis; contraé suavemente abdomen y glúteos sin contener la respiración.","Align your head, torso and pelvis; gently tighten your abs and glutes without holding your breath.","Alinhe cabeça, tronco e pelve; contraia suavemente abdômen e glúteos sem prender a respiração.","Aligne tête, buste et bassin ; contracte doucement abdos et fessiers sans bloquer ta respiration.","Allinea testa, busto e bacino; contrai delicatamente addome e glutei senza trattenere il respiro.","Bring Kopf, Oberkörper und Becken in eine Linie; spann Bauch und Gesäß sanft an, ohne die Luft anzuhalten."],
  ["Mantené la posición solo mientras conserves la alineación; apoyá rodillas antes de perderla.","Hold the position only as long as you keep your alignment; drop to your knees before you lose it.","Mantenha a posição só enquanto conservar o alinhamento; apoie os joelhos antes de perdê-lo.","Tiens la position seulement tant que tu gardes l’alignement ; pose les genoux avant de le perdre.","Mantieni la posizione solo finché conservi l’allineamento; appoggia le ginocchia prima di perderlo.","Halte die Position nur, solange die Linie stimmt; setz die Knie ab, bevor du sie verlierst."],
  ["Cadera hundida o elevada en exceso.","Hips sagging or raised too high.","Quadril afundado ou elevado em excesso.","Hanches affaissées ou trop hautes.","Anche cedute o troppo sollevate.","Hüfte hängt durch oder ist zu hoch."],
  ["Aguantar la respiración.","Holding your breath.","Prender a respiração.","Retenir sa respiration.","Trattenere il respiro.","Die Luft anhalten."],
  ["Seguir pese a dolor lumbar o temblor que impide mantener posición.","Continuing despite lower-back pain or shaking that prevents you from holding the position.","Continuar mesmo com dor lombar ou tremor que impede manter a posição.","Continuer malgré une douleur lombaire ou des tremblements qui empêchent de tenir la position.","Continuare nonostante dolore lombare o tremori che impediscono di mantenere la posizione.","Trotz Schmerzen im unteren Rücken oder Zittern weitermachen, das die Position unmöglich macht."],
  ["Pensá en acercar suavemente costillas y pelvis sin redondear en exceso.","Think about gently drawing your ribs and pelvis together without rounding too much.","Pense em aproximar suavemente costelas e pelve sem arredondar em excesso.","Pense à rapprocher doucement les côtes et le bassin sans trop arrondir.","Pensa di avvicinare delicatamente costole e bacino senza arrotondare troppo.","Stell dir vor, du bringst Rippen und Becken sanft zusammen, ohne zu stark zu runden."],
  ["La duración no compensa la pérdida de postura.","Duration doesn’t make up for losing your posture.","A duração não compensa a perda de postura.","La durée ne compense pas la perte de posture.","La durata non compensa la perdita di postura.","Die Dauer gleicht eine schlechte Haltung nicht aus."],
  ["Una variante más corta y limpia es mejor que sostener con dolor.","A shorter, cleaner variation is better than holding through pain.","Uma variação mais curta e limpa é melhor que sustentar com dor.","Une variante plus courte et propre vaut mieux que tenir avec douleur.","Una variante più breve e pulita è meglio che resistere con dolore.","Eine kürzere, saubere Variante ist besser als unter Schmerzen zu halten."],
  ["Cuádriceps y glúteo mayor de ambas piernas","Quadriceps and gluteus maximus of both legs","Quadríceps e glúteo máximo das duas pernas","Quadriceps et grand fessier des deux jambes","Quadricipiti e grande gluteo di entrambe le gambe","Quadrizeps und großer Gesäßmuskel beider Beine"],
  ["Aductores, pantorrillas y estabilizadores del tronco","Adductors, calves and trunk stabilizers","Adutores, panturrilhas e estabilizadores do tronco","Adducteurs, mollets et stabilisateurs du tronc","Adduttori, polpacci e stabilizzatori del tronco","Adduktoren, Waden und Rumpfstabilisatoren"],
  ["Peso corporal; mancuernas opcionales y apoyo cercano si hace falta","Bodyweight; optional dumbbells and nearby support if needed","Peso corporal; halteres opcionais e apoio próximo se precisar","Poids du corps ; haltères en option et appui à proximité si besoin","Corpo libero; manubri facoltativi e appoggio vicino se serve","Körpergewicht; optional Kurzhanteln und bei Bedarf eine Stütze in der Nähe"],
  ["Parate con pies al ancho de caderas y cerca de una pared o soporte si necesitás equilibrio.","Stand with your feet hip-width apart, near a wall or support if you need help with balance.","Fique com os pés na largura do quadril e perto de uma parede ou apoio se precisar de equilíbrio.","Tiens-toi pieds à la largeur des hanches, près d’un mur ou d’un appui si tu as besoin d’équilibre.","Mettiti con i piedi alla larghezza delle anche e vicino a una parete o a un supporto se ti serve equilibrio.","Stell dich hüftbreit hin, nah an einer Wand oder Stütze, falls du Hilfe beim Gleichgewicht brauchst."],
  ["Llevá una pierna hacia atrás y flexioná ambas rodillas hasta un rango cómodo, manteniendo el pie delantero estable.","Step one leg back and bend both knees to a comfortable range, keeping your front foot stable.","Leve uma perna para trás e flexione os dois joelhos até uma amplitude confortável, mantendo o pé da frente estável.","Recule une jambe et fléchis les deux genoux jusqu’à une amplitude confortable, en gardant le pied avant stable.","Porta una gamba indietro e piega entrambe le ginocchia fino a un’ampiezza comoda, mantenendo stabile il piede anteriore.","Setz ein Bein nach hinten und beuge beide Knie bis zu einem angenehmen Bewegungsumfang, der vordere Fuß bleibt stabil."],
  ["Empujá con el pie delantero para volver y alterná lados sin perder equilibrio.","Push through your front foot to come back and alternate sides without losing balance.","Empurre com o pé da frente para voltar e alterne os lados sem perder o equilíbrio.","Pousse sur le pied avant pour revenir et alterne les côtés sans perdre l’équilibre.","Spingi con il piede anteriore per tornare e alterna i lati senza perdere l’equilibrio.","Drück dich über den vorderen Fuß zurück und wechsle die Seiten, ohne das Gleichgewicht zu verlieren."],
  ["Perder el apoyo del pie delantero.","Losing contact with your front foot.","Perder o apoio do pé da frente.","Perdre l’appui du pied avant.","Perdere l’appoggio del piede anteriore.","Den Halt des vorderen Fußes verlieren."],
  ["Caer bruscamente sobre la rodilla trasera.","Dropping hard onto your back knee.","Cair bruscamente sobre o joelho de trás.","Tomber brusquement sur le genou arrière.","Cadere bruscamente sul ginocchio posteriore.","Hart auf das hintere Knie fallen."],
  ["Dejar que la rodilla delantera colapse hacia adentro.","Letting your front knee collapse inward.","Deixar o joelho da frente colapsar para dentro.","Laisser le genou avant s’effondrer vers l’intérieur.","Lasciare che il ginocchio anteriore collassi verso l’interno.","Das vordere Knie nach innen einknicken lassen."],
  ["El paso puede ser más largo o corto según tu movilidad; buscá estabilidad.","Your step can be longer or shorter depending on your mobility; aim for stability.","O passo pode ser mais longo ou curto conforme sua mobilidade; busque estabilidade.","Le pas peut être plus long ou plus court selon ta mobilité ; cherche la stabilité.","Il passo può essere più lungo o più corto in base alla tua mobilità; cerca stabilità.","Der Schritt kann je nach Beweglichkeit länger oder kürzer sein; achte auf Stabilität."],
  ["No hace falta tocar la rodilla trasera contra el suelo.","Your back knee doesn’t need to touch the floor.","Não é preciso tocar o joelho de trás no chão.","Le genou arrière n’a pas besoin de toucher le sol.","Non serve toccare terra con il ginocchio posteriore.","Das hintere Knie muss den Boden nicht berühren."],
  ["Usá apoyo estable si el equilibrio limita el movimiento.","Use a stable support if balance limits the movement.","Use um apoio estável se o equilíbrio limitar o movimento.","Utilise un appui stable si l’équilibre limite le mouvement.","Usa un appoggio stabile se l’equilibrio limita il movimento.","Nutze eine stabile Stütze, wenn das Gleichgewicht die Bewegung einschränkt."]
);

